    "DELETE FROM auth_sessions WHERE account_id=$1 AND device_id=$2 AND revoked_at IS NULL";
const AUTH_CONTACT_INVITES_ISSUER_CHAT_DEVICE_REVOKE_SQL: &str =
    "UPDATE auth_contact_invites SET revoked_at=NOW() \
     WHERE revoked_at IS NULL AND expires_at > NOW() AND issuer_chat_device_id IN (\
         SELECT chat_device_id FROM auth_chat_devices \
         WHERE account_id=$1 AND client_device_id=$2 AND revoked_at IS NULL\
     )";
const AUTH_DEVICE_LOGIN_CHALLENGES_ACCOUNT_DEVICE_REVOKE_SQL: &str =
    "DELETE FROM device_login_challenges \
     WHERE account_id=$1 AND device_id=$2 AND expires_at > NOW()";
