    "UPDATE auth_chat_devices SET revoked_at=NOW() WHERE account_id=$1 AND client_device_id=$2 AND revoked_at IS NULL";
const AUTH_CHAT_DEVICES_CLIENT_DEVICE_SIBLINGS_REVOKE_SQL: &str =
    "UPDATE auth_chat_devices SET revoked_at=NOW() \
     WHERE account_id=$1 AND client_device_id=$2 AND chat_device_id <> $3 AND revoked_at IS NULL";
const AUTH_CHAT_CONTACTS_PEER_CHAT_DEVICE_REVOKE_SQL: &str =
    "UPDATE auth_chat_contacts SET revoked_at=NOW() \
     WHERE revoked_at IS NULL AND peer_chat_device_id IN (\
         SELECT chat_device_id FROM auth_chat_devices \
         WHERE account_id=$1 AND client_device_id=$2\
     )";
const AUTH_CHAT_DEVICES_ACCOUNT_ACTIVE_LAST_SEEN_LOOKUP_SQL: &str = "SELECT chat_device_id \
     FROM auth_chat_devices \
     WHERE account_id=$1 AND revoked_at IS NULL \
     ORDER BY last_seen_at DESC, id DESC \
     LIMIT 1";
const AUTH_CHAT_DEVICES_PHONE_ACTIVE_LAST_SEEN_LOOKUP_SQL: &str = "SELECT chat_device_id \
     FROM auth_chat_devices \
     WHERE phone=$1 AND revoked_at IS NULL \
     ORDER BY last_seen_at DESC, id DESC \
     LIMIT 1";
const AUTH_BIOMETRIC_LOGIN_TOKEN_LOOKUP_SQL: &str = r#"
        SELECT
          account_id,
          phone,
          (revoked_at IS NULL AND expires_at > NOW()) AS alive,
          COALESCE(token_hash = $1, FALSE) AS matched_current,
          COALESCE(next_token_hash = $1, FALSE) AS matched_next
        FROM auth_biometric_tokens
        WHERE device_id=$2 AND (token_hash=$1 OR next_token_hash=$1)
        LIMIT 1
        "#;
const AUTH_BIOMETRIC_LOGIN_ATTESTATION_TOKEN_LOOKUP_SQL: &str = r#"
        SELECT
          account_id,
          phone,
          (revoked_at IS NULL AND expires_at > NOW()) AS alive,
          COALESCE(token_hash = $1, FALSE) AS matched_current,
          COALESCE(next_token_hash = $1, FALSE) AS matched_next
        FROM auth_biometric_tokens
        WHERE device_id=$2 AND (token_hash=$1 OR next_token_hash=$1)
        LIMIT 1
        "#;
