    "SELECT account_id FROM auth_chat_devices WHERE chat_device_id=$1 AND revoked_at IS NULL LIMIT 1 FOR UPDATE";
const AUTH_CHAT_CONTACT_ACTIVE_LOOKUP_SQL: &str = "SELECT 1 FROM auth_chat_contacts c \
     JOIN auth_chat_devices d ON d.chat_device_id=c.peer_chat_device_id AND d.revoked_at IS NULL \
     WHERE c.owner_account_id=$1 AND c.peer_chat_device_id=$2 AND c.revoked_at IS NULL \
     LIMIT 1";
