const SUPPORTED_WALLET_CURRENCIES: &[&str] = &["SYP", "USD", "EUR", "SAR", "AED", "QAR", "KWD"];

fn normalize_wallet_currency(raw: Option<&str>) -> ApiResult<Option<String>> {
    let Some(currency) = raw.map(str::trim).filter(|value| !value.is_empty()) else {
        return Ok(None);
    };
    let currency = currency.to_ascii_uppercase();
    if SUPPORTED_WALLET_CURRENCIES.contains(&currency.as_str()) {
        return Ok(Some(currency));
    }
    Err(ApiError::bad_request(format!(
        "currency must be one of: {}",
        SUPPORTED_WALLET_CURRENCIES.join(", ")
    )))
}

