pub async fn auth_biometric_login_attestation_challenge(
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(body): Json<BiometricLoginAttestationChallengeIn>,
) -> ApiResult<Response> {
    let auth = require_auth_runtime(&state)?;
    let hw_providers = hardware_attestation_providers(auth);
    let enabled = auth.biometric_login_hw_attestation_enabled && !hw_providers.is_empty();
    if !enabled {
        return Ok(recorded_hardware_attestation_challenge_disabled_response());
    }

    let client_ip = rate_limit_client_ip(&state, &headers)?;
    consume_rate_limit(
        auth,
        &format!(
            "auth_biometric_login_attestation_challenge_ip:{}",
            sha256_hex(&client_ip)
        ),
        BIOMETRIC_LOGIN_ATTESTATION_CHALLENGE_WINDOW_SECS,
        BIOMETRIC_LOGIN_ATTESTATION_CHALLENGE_MAX_PER_IP,
    )
    .await?;

    let device_id = normalize_device_id(body.device_id.as_deref())
        .ok_or_else(|| ApiError::bad_request("device_id required"))?;
    let token = normalize_hex_64(body.token.as_deref().unwrap_or_default())
        .ok_or_else(|| ApiError::bad_request("invalid token"))?;
    let token_hash = sha256_hex(&format!("bio:{device_id}:{token}"));
    let token_hash_pref = token_hash_prefix(&token_hash);
    let row = sqlx::query(AUTH_BIOMETRIC_LOGIN_ATTESTATION_TOKEN_LOOKUP_SQL)
        .bind(&token_hash)
        .bind(&device_id)
        .fetch_optional(&auth.pool)
        .await
        .map_err(|e| {
            tracing::error!(
                error = %e,
                token_hash_prefix = %token_hash_pref,
                device_id_hash = %hash_prefix(&device_id),
                "biometric login attestation challenge select failed"
            );
            ApiError::internal("biometric login attestation unavailable")
        })?;
    let Some(row) = row else {
        tracing::warn!(
            security_event = "biometric_login_attestation_challenge",
            outcome = "blocked",
            reason = "unauthorized",
            token_hash_prefix = %token_hash_pref,
            device_id_hash = %hash_prefix(&device_id),
            client_ip_hash = %hash_prefix(&client_ip),
            "biometric login attestation challenge unauthorized"
        );
        audit_device_login_event(
            "biometric_login_attestation_challenge",
            "blocked",
            Some(client_ip.as_str()),
            None,
            Some(token_hash.as_str()),
            Some("unauthorized"),
        );
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    };
    let decode_bio_challenge_column = |column: &'static str, e: sqlx::Error| -> ApiError {
        tracing::error!(
            error = %e,
            token_hash_prefix = %token_hash_pref,
            device_id_hash = %hash_prefix(&device_id),
            column,
            "biometric login attestation challenge column decode failed"
        );
        ApiError::internal("biometric login attestation unavailable")
    };
    let account_id_db: Option<String> = row
        .try_get("account_id")
        .map_err(|e| decode_bio_challenge_column("account_id", e))?;
    let phone: Option<String> = row
        .try_get("phone")
        .map_err(|e| decode_bio_challenge_column("phone", e))?;
    let alive: bool = row
        .try_get("alive")
        .map_err(|e| decode_bio_challenge_column("alive", e))?;
    let matched_current: bool = row
        .try_get("matched_current")
        .map_err(|e| decode_bio_challenge_column("matched_current", e))?;
    let matched_next: bool = row
        .try_get("matched_next")
        .map_err(|e| decode_bio_challenge_column("matched_next", e))?;
    let phone_opt = phone
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToString::to_string);
    let Some(_) = biometric_token_match_kind(matched_current, matched_next) else {
        tracing::warn!(
            security_event = "biometric_login_attestation_challenge",
            outcome = "blocked",
            reason = "invalid_match_state",
            token_hash_prefix = %token_hash_pref,
            device_id_hash = %hash_prefix(&device_id),
            client_ip_hash = %hash_prefix(&client_ip),
            "biometric login attestation challenge lookup returned inconsistent token match state"
        );
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    };
    if !alive {
        tracing::warn!(
            security_event = "biometric_login_attestation_challenge",
            outcome = "blocked",
            reason = "revoked_or_expired",
            token_hash_prefix = %token_hash_pref,
            device_id_hash = %hash_prefix(&device_id),
            client_ip_hash = %hash_prefix(&client_ip),
            "biometric login attestation challenge rejected"
        );
        audit_device_login_event(
            "biometric_login_attestation_challenge",
            "blocked",
            Some(client_ip.as_str()),
            phone_opt.as_deref(),
            Some(token_hash.as_str()),
            Some("revoked_or_expired"),
        );
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }
    let Some(account_id) = resolve_biometric_login_account_id(
        auth,
        &device_id,
        &token_hash,
        &token_hash_pref,
        account_id_db.as_deref(),
        phone_opt.as_deref(),
    )
    .await?
    else {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    };
    let principal = AuthPrincipal {
        account_id: account_id.clone(),
        phone: phone_opt.clone(),
        device_id: Some(device_id.clone()),
    };
    enforce_biometric_login_attestation_challenge_rate_limit(&state, &headers, &principal).await?;

    let challenge_token = generate_token_hex_32();
    let expires_at = unix_now_secs().saturating_add(auth.biometric_login_attestation_ttl_secs);
    record_payment_mutation_attestation_challenge(
        auth,
        PaymentMutationAttestationChallengeRecord {
            account_id: &account_id,
            device_id: &device_id,
            operation: "biometric_login",
            resource_id: &token_hash,
            challenge_token: &challenge_token,
            expires_at_epoch_secs: expires_at,
            failure_detail: "biometric login attestation unavailable",
        },
    )
    .await?;

    tracing::info!(
        security_event = "biometric_login_attestation_challenge",
        outcome = "ok",
        account_hash = %hash_prefix(account_id.trim()),
        device_id_hash = %hash_prefix(&device_id),
        token_hash_prefix = %token_hash_pref,
        "issued biometric login attestation challenge"
    );

    let nonce_b64 = payment_mutation_attestation_nonce_b64(&challenge_token).unwrap_or_default();
    Ok(recorded_hardware_attestation_challenge_response(
        &challenge_token,
        expires_at,
        &nonce_b64,
        hw_providers,
    ))
}

