async fn enforce_recorded_hardware_attestation_challenge_rate_limit_inner(
    state: &AppState,
    headers: &HeaderMap,
    principal: &AuthPrincipal,
    key_prefix: &'static str,
    window_secs: i64,
    max_per_ip: i64,
    max_per_account: i64,
) -> ApiResult<()> {
    let Some(auth) = state.auth.as_ref() else {
        return Ok(());
    };
    let account_id = principal.account_id.trim();
    if account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }
    let client_ip = rate_limit_client_ip(state, headers)?;
    consume_rate_limit(
        auth,
        &format!("{key_prefix}_ip:{}", sha256_hex(&client_ip)),
        window_secs,
        max_per_ip,
    )
    .await?;
    consume_rate_limit(
        auth,
        &format!("{key_prefix}_account:{}", sha256_hex(account_id)),
        window_secs,
        max_per_account,
    )
    .await?;
    Ok(())
}

fn auth_username_pattern() -> &'static Regex {
    static PATTERN: OnceLock<Regex> = OnceLock::new();
    PATTERN.get_or_init(|| {
        Regex::new(r"^[a-z][a-z0-9._-]{2,31}$").expect("username regex must compile")
    })
}

fn normalize_auth_username(raw: Option<&str>) -> Result<String, ApiError> {
    let username = raw.unwrap_or_default().trim().to_ascii_lowercase();
    if username.len() < AUTH_USERNAME_MIN_LEN || username.len() > AUTH_USERNAME_MAX_LEN {
        return Err(ApiError::bad_request("invalid username"));
    }
    if !auth_username_pattern().is_match(&username) {
        return Err(ApiError::bad_request("invalid username"));
    }
    Ok(username)
}

fn validate_auth_password(raw: Option<&str>) -> Result<String, ApiError> {
    let password = raw.ok_or_else(|| ApiError::bad_request("password required"))?;
    let password_len = password.chars().count();
    if !(AUTH_PASSWORD_MIN_LEN..=AUTH_PASSWORD_MAX_LEN).contains(&password_len) {
        return Err(ApiError::bad_request("invalid password"));
    }
    if password.chars().any(|ch| ch.is_control()) {
        return Err(ApiError::bad_request("invalid password"));
    }
    Ok(password.to_string())
}

fn derive_auth_password_hash_bytes(password: &[u8], salt: &[u8], iterations: u32) -> [u8; 32] {
    let mut mac =
        Hmac::<Sha256>::new_from_slice(password).expect("HMAC accepts arbitrary key sizes");
    let mut block = Vec::with_capacity(salt.len() + 4);
    block.extend_from_slice(salt);
    block.extend_from_slice(&1u32.to_be_bytes());

    mac.update(&block);
    let mut u = mac.finalize_reset().into_bytes();
    let mut out = [0u8; 32];
    out.copy_from_slice(&u);

    for _ in 1..iterations {
        mac.update(&u);
        u = mac.finalize_reset().into_bytes();
        for (dst, src) in out.iter_mut().zip(u.iter()) {
            *dst ^= *src;
        }
    }

    out
}

fn hash_auth_password(password: &str) -> String {
    let mut salt = [0u8; 16];
    rand::thread_rng().fill_bytes(&mut salt);
    let derived =
        derive_auth_password_hash_bytes(password.as_bytes(), &salt, AUTH_PASSWORD_HASH_ITERATIONS);
    format!(
        "{AUTH_PASSWORD_HASH_PREFIX}${AUTH_PASSWORD_HASH_ITERATIONS}${}${}",
        STANDARD.encode(salt),
        STANDARD.encode(derived),
    )
}

fn verify_auth_password(password: &str, stored: &str) -> bool {
    let parts: Vec<&str> = stored.trim().split('$').collect();
    if parts.len() != 4 || parts[0] != AUTH_PASSWORD_HASH_PREFIX {
        return false;
    }
    let Ok(iterations) = parts[1].parse::<u32>() else {
        return false;
    };
    let Ok(salt) = STANDARD.decode(parts[2]) else {
        return false;
    };
    let Ok(expected) = STANDARD.decode(parts[3]) else {
        return false;
    };
    if salt.is_empty() || expected.len() != 32 {
        return false;
    }
    let derived = derive_auth_password_hash_bytes(password.as_bytes(), &salt, iterations);
    derived.as_slice().ct_eq(expected.as_slice()).into()
}

fn consume_dummy_auth_password_work(password: &str) {
    let _ = derive_auth_password_hash_bytes(
        password.as_bytes(),
        &[0u8; 16],
        AUTH_PASSWORD_HASH_ITERATIONS,
    );
}

struct UsernamePasswordSessionIssue<'a> {
    account_id: &'a str,
    shamell_id: &'a str,
    username: &'a str,
    phone: Option<&'a str>,
    device_id: &'a str,
    client_ip: &'a str,
    user_agent: Option<&'a str>,
    security_event: &'static str,
}

async fn issue_username_password_session(
    auth: &AuthRuntime,
    issue: &UsernamePasswordSessionIssue<'_>,
) -> ApiResult<Response> {
    let sid = generate_token_hex_16();
    let sid_hash = sha256_hex(&sid);
    let mut tx = auth.pool.begin().await.map_err(|e| {
        tracing::error!(
            error = %e,
            security_event = issue.security_event,
            "password auth tx begin failed"
        );
        ApiError::internal("failed to sign in")
    })?;

    sqlx::query(
        r#"
        INSERT INTO auth_sessions
          (sid_hash, account_id, phone, device_id, expires_at, created_at, last_seen_at, revoked_at)
        VALUES
          ($1, $2, $3, $4, NOW() + ($5::bigint * INTERVAL '1 second'), NOW(), NOW(), NULL)
        "#,
    )
    .bind(&sid_hash)
    .bind(issue.account_id)
    .bind(issue.phone)
    .bind(issue.device_id)
    .bind(auth.auth_session_ttl_secs)
    .execute(&mut *tx)
    .await
    .map_err(|e| {
        tracing::error!(
            error = %e,
            security_event = issue.security_event,
            "password auth session insert failed"
        );
        ApiError::internal("failed to sign in")
    })?;

    upsert_device_session_record(
        &mut *tx,
        issue.account_id,
        issue.phone,
        issue.device_id,
        Some(issue.client_ip),
        issue.user_agent,
    )
    .await
    .map_err(|e| {
        tracing::error!(
            error = %e,
            security_event = issue.security_event,
            "password auth device-session upsert failed"
        );
        ApiError::internal("failed to sign in")
    })?;

    tx.commit().await.map_err(|e| {
        tracing::error!(
            error = %e,
            security_event = issue.security_event,
            "password auth tx commit failed"
        );
        ApiError::internal("failed to sign in")
    })?;

    tracing::info!(
        security_event = issue.security_event,
        outcome = "ok",
        account_hash = %hash_prefix(issue.account_id),
        username_hash = %hash_prefix(issue.username),
        device_id_hash = %hash_prefix(issue.device_id),
        "password auth session issued"
    );

    let mut resp = json_no_store(json!({
        "ok": true,
        "shamell_id": issue.shamell_id,
        "username": issue.username,
    }));
    append_set_cookie(
        &mut resp,
        &session_cookie_value(&sid, auth.auth_session_ttl_secs),
    );
    append_set_cookie(&mut resp, &clear_legacy_session_cookie_value());
    Ok(resp)
}

async fn cleanup_username_password_signup_account(
    auth: &AuthRuntime,
    account_id: &str,
    username: &str,
) {
    let mut tx = match auth.pool.begin().await {
        Ok(tx) => tx,
        Err(error) => {
            tracing::error!(
                error = %error,
                security_event = "auth_signup",
                outcome = "cleanup_failed",
                account_hash = %hash_prefix(account_id),
                "password signup cleanup tx begin failed after wallet provisioning failure"
            );
            return;
        }
    };

    let mut cleanup_ok = true;
    for (label, sql) in [
        (
            "auth_sessions",
            "DELETE FROM auth_sessions WHERE account_id=$1",
        ),
        (
            "device_sessions",
            "DELETE FROM device_sessions WHERE account_id=$1",
        ),
        (
            "auth_accounts",
            "DELETE FROM auth_accounts WHERE account_id=$1 AND username=$2",
        ),
    ] {
        let result = if label == "auth_accounts" {
            sqlx::query(sql)
                .bind(account_id)
                .bind(username)
                .execute(&mut *tx)
                .await
        } else {
            sqlx::query(sql).bind(account_id).execute(&mut *tx).await
        };
        if let Err(error) = result {
            cleanup_ok = false;
            tracing::error!(
                error = %error,
                table = label,
                security_event = "auth_signup",
                outcome = "cleanup_failed",
                account_hash = %hash_prefix(account_id),
                "password signup cleanup delete failed after wallet provisioning failure"
            );
            break;
        }
    }

    if !cleanup_ok {
        let _ = tx.rollback().await;
        return;
    }

    if let Err(error) = tx.commit().await {
        tracing::error!(
            error = %error,
            security_event = "auth_signup",
            outcome = "cleanup_failed",
            account_hash = %hash_prefix(account_id),
            "password signup cleanup tx commit failed after wallet provisioning failure"
        );
    }
}

pub async fn auth_username_password_signup(
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(body): Json<UsernamePasswordSignUpIn>,
) -> ApiResult<Response> {
    let auth = require_auth_runtime(&state)?;
    if !auth.account_create_enabled {
        tracing::warn!(
            security_event = "auth_signup",
            outcome = "disabled",
            "username/password signup disabled by account creation policy"
        );
        return Err(ApiError::new(
            StatusCode::SERVICE_UNAVAILABLE,
            "account creation temporarily unavailable",
        ));
    }
    let client_ip = rate_limit_client_ip(&state, &headers)?;
    let (_, user_agent) = device_session_request_metadata(&state, &headers);
    let username = normalize_auth_username(body.username.as_deref())?;
    let password = validate_auth_password(body.password.as_deref())?;
    let wallet_currency = normalize_wallet_currency(body.currency.as_deref())?;
    let device_id = normalize_device_id(body.device_id.as_deref())
        .ok_or_else(|| ApiError::bad_request("device_id required"))?;

    consume_rate_limit(
        auth,
        &format!("auth_signup_ip:{}", sha256_hex(&client_ip)),
        AUTH_SIGNUP_WINDOW_SECS,
        AUTH_SIGNUP_MAX_PER_IP,
    )
    .await?;
    consume_rate_limit(
        auth,
        &format!("auth_signup_device:{}", sha256_hex(&device_id)),
        AUTH_SIGNUP_WINDOW_SECS,
        AUTH_SIGNUP_MAX_PER_DEVICE,
    )
    .await?;

    let password_hash = hash_auth_password(&password);
    for _ in 0..12 {
        let account_id = generate_token_hex_32();
        let shamell_id = generate_shamell_user_id();

        let mut tx = auth.pool.begin().await.map_err(|e| {
            tracing::error!(error = %e, "password signup tx begin failed");
            ApiError::internal("failed to create account")
        })?;

        let inserted = sqlx::query(
            "INSERT INTO auth_accounts (account_id, shamell_user_id, phone, username, password_hash) \
             VALUES ($1, $2, NULL, $3, $4)",
        )
        .bind(&account_id)
        .bind(&shamell_id)
        .bind(&username)
        .bind(&password_hash)
        .execute(&mut *tx)
        .await;

        match inserted {
            Ok(result) => {
                if result.rows_affected() != 1 {
                    let _ = tx.rollback().await;
                    continue;
                }
            }
            Err(error) => {
                let unique_violation = matches!(
                    &error,
                    sqlx::Error::Database(db) if db.code().as_deref() == Some("23505")
                );
                let _ = tx.rollback().await;
                if unique_violation {
                    return Err(ApiError::new(
                        StatusCode::CONFLICT,
                        "username already taken",
                    ));
                }
                tracing::error!(error = %error, "password signup insert failed");
                return Err(ApiError::internal("failed to create account"));
            }
        }

        let sid = generate_token_hex_16();
        let sid_hash = sha256_hex(&sid);
        if let Err(error) = sqlx::query(
            r#"
            INSERT INTO auth_sessions
              (sid_hash, account_id, phone, device_id, expires_at, created_at, last_seen_at, revoked_at)
            VALUES
              ($1, $2, NULL, $3, NOW() + ($4::bigint * INTERVAL '1 second'), NOW(), NOW(), NULL)
            "#,
        )
        .bind(&sid_hash)
        .bind(&account_id)
        .bind(&device_id)
        .bind(auth.auth_session_ttl_secs)
        .execute(&mut *tx)
        .await
        {
            let _ = tx.rollback().await;
            tracing::error!(error = %error, "password signup session insert failed");
            return Err(ApiError::internal("failed to create account"));
        }

        if let Err(error) = upsert_device_session_record(
            &mut *tx,
            &account_id,
            None,
            &device_id,
            Some(client_ip.as_str()),
            user_agent.as_deref(),
        )
        .await
        {
            let _ = tx.rollback().await;
            tracing::error!(error = %error, "password signup device-session upsert failed");
            return Err(ApiError::internal("failed to create account"));
        }

        tx.commit().await.map_err(|e| {
            tracing::error!(error = %e, "password signup tx commit failed");
            ApiError::internal("failed to create account")
        })?;

        seed_default_official_follow_best_effort(auth, &account_id, "password_signup").await;

        let wallet = match ensure_wallet_for_account(
            &state,
            &headers,
            &account_id,
            None,
            wallet_currency.as_deref(),
        )
        .await
        {
            Ok(wallet) => wallet,
            Err(error) => {
                cleanup_username_password_signup_account(auth, &account_id, &username).await;
                tracing::error!(
                    error = %error.detail,
                    status = error.status.as_u16(),
                    security_event = "auth_signup",
                    outcome = "wallet_provision_failed",
                    account_hash = %hash_prefix(&account_id),
                    username_hash = %hash_prefix(&username),
                    "username/password signup wallet provisioning failed"
                );
                return Err(ApiError::internal("failed to create wallet"));
            }
        };
        let wallet_id = wallet
            .as_ref()
            .and_then(wallet_id_from_payments_user)
            .map(ToString::to_string);
        let mut signup_metadata = json!({
            "wallet_currency": wallet_currency.as_deref().unwrap_or("SYP"),
        });
        if let Some(wallet_id) = wallet_id.as_deref() {
            signup_metadata["wallet_id"] = json!(wallet_id);
        }
        if let Err(error) = insert_user_activity_event(
            auth,
            UserActivityEventInsert {
                account_id: Some(account_id.clone()),
                shamell_user_id: Some(shamell_id.clone()),
                username: Some(username.clone()),
                phone: None,
                event_type: "signup".to_string(),
                module_id: None,
                action: Some("username_password_signup".to_string()),
                route: Some("/auth/signup".to_string()),
                metadata: signup_metadata,
                device_id_hash: Some(hash_prefix(&device_id)),
                client_ip_hash: Some(hash_prefix(&client_ip)),
                user_agent_hash: user_agent.as_deref().map(hash_prefix),
            },
        )
        .await
        {
            tracing::error!(
                error = %error,
                security_event = "auth_signup_audit_insert",
                outcome = "failed",
                account_hash = %hash_prefix(&account_id),
                username_hash = %hash_prefix(&username),
                "username/password signup activity insert failed"
            );
        }

        tracing::info!(
            security_event = "auth_signup",
            outcome = "ok",
            client_ip_hash = %hash_prefix(&client_ip),
            account_hash = %hash_prefix(&account_id),
            username_hash = %hash_prefix(&username),
            device_id_hash = %hash_prefix(&device_id),
            "username/password account created"
        );

        let mut response_body = json!({
            "ok": true,
            "shamell_id": shamell_id,
            "username": username,
        });
        if let Some(wallet) = wallet {
            response_body["wallet"] = wallet;
        }
        if let Some(wallet_id) = wallet_id {
            response_body["wallet_id"] = json!(wallet_id);
        }
        let mut resp = json_no_store(response_body);
        append_set_cookie(
            &mut resp,
            &session_cookie_value(&sid, auth.auth_session_ttl_secs),
        );
        append_set_cookie(&mut resp, &clear_legacy_session_cookie_value());
        return Ok(resp);
    }

    Err(ApiError::internal("failed to create account"))
}

pub async fn auth_username_password_login(
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(body): Json<UsernamePasswordLoginIn>,
) -> ApiResult<Response> {
    let auth = require_auth_runtime(&state)?;
    let client_ip = rate_limit_client_ip(&state, &headers)?;
    let (_, user_agent) = device_session_request_metadata(&state, &headers);
    let username = normalize_auth_username(body.username.as_deref())?;
    let password = validate_auth_password(body.password.as_deref())?;
    let device_id = normalize_device_id(body.device_id.as_deref())
        .ok_or_else(|| ApiError::bad_request("device_id required"))?;

    consume_rate_limit(
        auth,
        &format!("auth_login_ip:{}", sha256_hex(&client_ip)),
        AUTH_LOGIN_WINDOW_SECS,
        AUTH_LOGIN_MAX_PER_IP,
    )
    .await?;
    consume_rate_limit(
        auth,
        &format!("auth_login_username:{}", sha256_hex(&username)),
        AUTH_LOGIN_WINDOW_SECS,
        AUTH_LOGIN_MAX_PER_USERNAME,
    )
    .await?;

    let row = sqlx::query(
        "SELECT account_id, shamell_user_id, phone, password_hash \
         FROM auth_accounts WHERE username=$1 LIMIT 1",
    )
    .bind(&username)
    .fetch_optional(&auth.pool)
    .await
    .map_err(|e| {
        tracing::error!(error = %e, "password login account lookup failed");
        ApiError::internal("failed to sign in")
    })?;

    let Some(row) = row else {
        consume_dummy_auth_password_work(&password);
        return Err(ApiError::new(
            StatusCode::UNAUTHORIZED,
            "invalid username or password",
        ));
    };

    let account_id: String = require_auth_text_column(
        row.try_get("account_id"),
        "account_id",
        "auth_username_password_login",
        "failed to sign in",
    )?;
    let shamell_id: String = require_auth_text_column(
        row.try_get("shamell_user_id"),
        "shamell_user_id",
        "auth_username_password_login",
        "failed to sign in",
    )?;
    let phone = require_auth_optional_text_column(
        row.try_get("phone"),
        "phone",
        "auth_username_password_login",
        "failed to sign in",
    )?;
    let stored_hash = require_auth_optional_text_column(
        row.try_get("password_hash"),
        "password_hash",
        "auth_username_password_login",
        "failed to sign in",
    )?;

    let verified = stored_hash
        .as_deref()
        .map(|value| verify_auth_password(&password, value))
        .unwrap_or(false);
    if !verified {
        if stored_hash.is_none() {
            consume_dummy_auth_password_work(&password);
        }
        tracing::warn!(
            security_event = "auth_login",
            outcome = "invalid_credentials",
            client_ip_hash = %hash_prefix(&client_ip),
            username_hash = %hash_prefix(&username),
            "username/password login rejected"
        );
        return Err(ApiError::new(
            StatusCode::UNAUTHORIZED,
            "invalid username or password",
        ));
    }

    let session_issue = UsernamePasswordSessionIssue {
        account_id: account_id.trim(),
        shamell_id: shamell_id.trim(),
        username: &username,
        phone: phone.as_deref(),
        device_id: &device_id,
        client_ip: client_ip.as_str(),
        user_agent: user_agent.as_deref(),
        security_event: "auth_login",
    };
    issue_username_password_session(auth, &session_issue).await
}

pub async fn auth_account_create(
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(body): Json<AccountCreateIn>,
) -> ApiResult<Response> {
    let auth = require_auth_runtime(&state)?;
    if !auth.account_create_enabled {
        tracing::warn!(
            security_event = "account_create",
            outcome = "disabled",
            "account creation disabled by policy"
        );
        return Err(ApiError::new(
            StatusCode::SERVICE_UNAVAILABLE,
            "account creation temporarily unavailable",
        ));
    }
    let client_ip = rate_limit_client_ip(&state, &headers)?;
    let (_, user_agent) = device_session_request_metadata(&state, &headers);
    consume_rate_limit(
        auth,
        &format!("auth_account_create_ip:{}", sha256_hex(&client_ip)),
        auth.account_create_window_secs,
        auth.account_create_max_per_ip,
    )
    .await?;

    let device_id = normalize_device_id(body.device_id.as_deref())
        .ok_or_else(|| ApiError::bad_request("device_id required"))?;
    let rate_limit_surface = normalize_app_surface_header_value(
        header_value(&headers, SHAMELL_APP_SURFACE_HEADER).as_deref(),
    );
    consume_rate_limit(
        auth,
        &format!(
            "auth_account_create_device:{rate_limit_surface}:{}",
            sha256_hex(&device_id)
        ),
        auth.account_create_window_secs,
        auth.account_create_max_per_device,
    )
    .await?;

    let (trusted_device, _hw_providers, hw_attestation_enabled, hw_attestation_required) =
        account_create_hw_attestation_policy(auth, &device_id);

    if trusted_device {
        tracing::warn!(
            security_event = "account_create_hw_attestation",
            outcome = "trusted_device_bypass",
            client_ip_hash = %hash_prefix(&client_ip),
            device_id_hash = %hash_prefix(&device_id),
            "bypassing account-create hardware attestation for trusted device"
        );
    }

    // When either PoW or hardware attestation is enabled, require a signed challenge token so:
    // - it can be expired server-side
    // - it can be bound to hardware attestation nonces (Android Play Integrity)
    // - it cannot be forged without the HMAC secret
    let pow_required = auth.account_create_pow_enabled;
    let needs_challenge = pow_required || hw_attestation_enabled;
    let challenge_token = body
        .challenge_token
        .as_deref()
        .unwrap_or_default()
        .trim()
        .to_string();

    let mut expected_hw_nonce_b64: Option<String> = None;
    if needs_challenge {
        let Some(secret) = auth.account_create_pow_secret.as_deref() else {
            tracing::error!(
                account_create_pow_enabled = pow_required,
                hw_attestation_enabled,
                "account-create attestation enabled but missing secret"
            );
            return Err(ApiError::internal("account create unavailable"));
        };
        if challenge_token.is_empty() {
            tracing::warn!(
                security_event = "account_create_attestation",
                outcome = "missing_token",
                client_ip_hash = %hash_prefix(&client_ip),
                device_id_hash = %hash_prefix(&device_id),
                "account create missing challenge token"
            );
            return Err(ApiError::new(
                StatusCode::UNAUTHORIZED,
                "attestation required",
            ));
        }
        let now = unix_now_secs();
        let payload = decode_pow_token(secret, &challenge_token).ok_or_else(|| {
            tracing::warn!(
                security_event = "account_create_attestation",
                outcome = "invalid_token",
                client_ip_hash = %hash_prefix(&client_ip),
                device_id_hash = %hash_prefix(&device_id),
                "account create invalid challenge token"
            );
            ApiError::new(StatusCode::UNAUTHORIZED, "attestation required")
        })?;
        if payload.exp <= now || payload.device_id.trim() != device_id.trim() {
            tracing::warn!(
                security_event = "account_create_attestation",
                outcome = "expired_or_mismatch",
                client_ip_hash = %hash_prefix(&client_ip),
                device_id_hash = %hash_prefix(&device_id),
                "account create expired or mismatched challenge token"
            );
            return Err(ApiError::new(
                StatusCode::UNAUTHORIZED,
                "attestation required",
            ));
        }
        expected_hw_nonce_b64 = account_create_attestation_nonce_b64(&challenge_token);
    }

    if pow_required {
        let Some(secret) = auth.account_create_pow_secret.as_deref() else {
            tracing::error!("account-create pow enabled but missing secret");
            return Err(ApiError::internal("account create unavailable"));
        };
        let solution = body.pow_solution.as_deref().unwrap_or_default();
        if solution.trim().is_empty() {
            tracing::warn!(
                security_event = "account_create_attestation",
                outcome = "missing_pow",
                client_ip_hash = %hash_prefix(&client_ip),
                device_id_hash = %hash_prefix(&device_id),
                "account create missing PoW solution"
            );
            return Err(ApiError::new(
                StatusCode::UNAUTHORIZED,
                "attestation required",
            ));
        }
        if !verify_pow_solution(secret, &device_id, &challenge_token, solution) {
            tracing::warn!(
                security_event = "account_create_attestation",
                outcome = "invalid_pow",
                client_ip_hash = %hash_prefix(&client_ip),
                device_id_hash = %hash_prefix(&device_id),
                "account create invalid PoW solution"
            );
            return Err(ApiError::new(
                StatusCode::UNAUTHORIZED,
                "attestation required",
            ));
        }
    }

    if hw_attestation_enabled {
        let ios_tok = body
            .ios_devicecheck_token_b64
            .as_deref()
            .map(str::trim)
            .filter(|s| !s.is_empty());
        let android_tok = body
            .android_play_integrity_token
            .as_deref()
            .map(str::trim)
            .filter(|s| !s.is_empty());
        let has_any = ios_tok.is_some() || android_tok.is_some();
        if hw_attestation_required && !has_any {
            tracing::warn!(
                security_event = "account_create_hw_attestation",
                outcome = "missing",
                client_ip_hash = %hash_prefix(&client_ip),
                device_id_hash = %hash_prefix(&device_id),
                "account create missing hardware attestation"
            );
            return Err(ApiError::new(
                StatusCode::UNAUTHORIZED,
                "attestation required",
            ));
        }

        let mut ok = false;
        let mut attempted = false;

        if let Some(tok) = ios_tok {
            attempted = true;
            let Some(cfg) = auth.account_create_apple_devicecheck.as_ref() else {
                tracing::error!(
                    security_event = "account_create_hw_attestation",
                    outcome = "misconfigured",
                    provider = "apple_devicecheck",
                    "hardware attestation token provided but provider not configured"
                );
                return Err(ApiError::new(
                    StatusCode::UNAUTHORIZED,
                    "attestation required",
                ));
            };
            ok = verify_apple_devicecheck_token(&state.http, cfg, tok).await?;
            if !ok {
                tracing::warn!(
                    security_event = "account_create_hw_attestation",
                    outcome = "invalid",
                    provider = "apple_devicecheck",
                    client_ip_hash = %hash_prefix(&client_ip),
                    device_id_hash = %hash_prefix(&device_id),
                    "hardware attestation invalid"
                );
            }
        }

        if !ok {
            if let Some(tok) = android_tok {
                attempted = true;
                let Some(cfg) = auth.account_create_play_integrity.as_ref() else {
                    tracing::error!(
                        security_event = "account_create_hw_attestation",
                        outcome = "misconfigured",
                        provider = "google_play_integrity",
                        "hardware attestation token provided but provider not configured"
                    );
                    return Err(ApiError::new(
                        StatusCode::UNAUTHORIZED,
                        "attestation required",
                    ));
                };
                let Some(expected_nonce_b64) = expected_hw_nonce_b64.as_deref() else {
                    tracing::error!(
                        security_event = "account_create_hw_attestation",
                        outcome = "missing_nonce",
                        provider = "google_play_integrity",
                        "missing expected nonce"
                    );
                    return Err(ApiError::internal("account create unavailable"));
                };
                ok = verify_play_integrity_token(&state.http, cfg, tok, expected_nonce_b64).await?;
                if !ok {
                    tracing::warn!(
                        security_event = "account_create_hw_attestation",
                        outcome = "invalid",
                        provider = "google_play_integrity",
                        client_ip_hash = %hash_prefix(&client_ip),
                        device_id_hash = %hash_prefix(&device_id),
                        "hardware attestation invalid"
                    );
                }
            }
        }

        if (hw_attestation_required || attempted) && !ok {
            return Err(ApiError::new(
                StatusCode::UNAUTHORIZED,
                "attestation required",
            ));
        }
    }

    if needs_challenge {
        consume_account_create_challenge(auth, &device_id, &challenge_token, client_ip.as_str())
            .await?;
    }

    // Allocate a new account + Shamell ID, then create a fresh server session.
    // Best practice: do it in a transaction so we don't leave orphaned sessions.
    for _ in 0..12 {
        let account_id = generate_token_hex_32();
        let shamell_id = generate_shamell_user_id();
        let sid = generate_token_hex_16();
        let sid_hash = sha256_hex(&sid);

        let mut tx = auth.pool.begin().await.map_err(|e| {
            tracing::error!(error = %e, "account_create tx begin failed");
            ApiError::internal("account create unavailable")
        })?;

        let inserted = sqlx::query(
            "INSERT INTO auth_accounts (account_id, shamell_user_id, phone) VALUES ($1, $2, NULL)",
        )
        .bind(&account_id)
        .bind(&shamell_id)
        .execute(&mut *tx)
        .await;

        match inserted {
            Ok(r) => {
                if r.rows_affected() != 1 {
                    let _ = tx.rollback().await;
                    continue;
                }
            }
            Err(e) => {
                let unique_violation = match &e {
                    sqlx::Error::Database(db) => db.code().as_deref() == Some("23505"),
                    _ => false,
                };
                let _ = tx.rollback().await;
                if unique_violation {
                    continue;
                }
                tracing::error!(error = %e, "auth_accounts insert failed for account_create");
                return Err(ApiError::internal("failed to create account"));
            }
        }

        if let Err(e) = sqlx::query(
            r#"
            INSERT INTO auth_sessions
              (sid_hash, account_id, phone, device_id, expires_at, created_at, last_seen_at, revoked_at)
            VALUES
              ($1, $2, NULL, $3, NOW() + ($4::bigint * INTERVAL '1 second'), NOW(), NOW(), NULL)
            "#,
        )
        .bind(&sid_hash)
        .bind(&account_id)
        .bind(&device_id)
        .bind(auth.auth_session_ttl_secs)
        .execute(&mut *tx)
        .await
        {
            let _ = tx.rollback().await;
            tracing::error!(error = %e, "auth_sessions insert failed for account_create");
            return Err(ApiError::internal("failed to create session"));
        }
        if let Err(e) = upsert_device_session_record(
            &mut *tx,
            &account_id,
            None,
            &device_id,
            Some(client_ip.as_str()),
            user_agent.as_deref(),
        )
        .await
        {
            let _ = tx.rollback().await;
            tracing::error!(error = %e, "device_sessions upsert failed for account_create");
            return Err(ApiError::internal("failed to create session"));
        }

        tx.commit().await.map_err(|e| {
            tracing::error!(error = %e, "account_create tx commit failed");
            ApiError::internal("account create unavailable")
        })?;

        tracing::info!(
            security_event = "account_create",
            outcome = "ok",
            client_ip_hash = %hash_prefix(&client_ip),
            account_hash = %hash_prefix(&account_id),
            device_id_hash = %hash_prefix(&device_id),
            "new account created"
        );

        seed_default_official_follow_best_effort(auth, &account_id, "account_create").await;

        let mut resp = Json(json!({"ok": true, "shamell_id": shamell_id})).into_response();
        append_set_cookie(
            &mut resp,
            &session_cookie_value(&sid, auth.auth_session_ttl_secs),
        );
        append_set_cookie(&mut resp, &clear_legacy_session_cookie_value());
        append_no_store(&mut resp);
        return Ok(resp);
    }

    Err(ApiError::internal("failed to allocate account"))
}

pub async fn auth_logout(State(state): State<AppState>, headers: HeaderMap) -> ApiResult<Response> {
    if let Some(auth) = state.auth.as_ref() {
        if let Some(sid) = extract_session_token(&headers, state.accept_legacy_session_cookie) {
            let sid_hash = sha256_hex(&sid);
            if let Err(e) = sqlx::query("DELETE FROM auth_sessions WHERE sid_hash=$1")
                .bind(&sid_hash)
                .execute(&auth.pool)
                .await
            {
                tracing::error!(error = %e, "auth_logout session revoke failed");
                return Ok(logout_response(
                    StatusCode::INTERNAL_SERVER_ERROR,
                    json!({"detail": "failed to revoke session"}),
                ));
            }
        }
    }
    Ok(logout_response(StatusCode::OK, json!({"ok": true})))
}

fn logout_response(status: StatusCode, body: Value) -> Response {
    let mut resp = Json(body).into_response();
    *resp.status_mut() = status;
    append_set_cookie(&mut resp, &clear_session_cookie_value());
    append_set_cookie(&mut resp, &clear_legacy_session_cookie_value());
    append_no_store(&mut resp);
    resp
}

pub async fn auth_device_login_start(
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(body): Json<DeviceLoginStartIn>,
) -> ApiResult<Response> {
    ensure_device_login_web_enabled(&state)?;
    let auth = require_auth_runtime(&state)?;
    let client_ip = rate_limit_client_ip(&state, &headers)?;
    consume_rate_limit(
        auth,
        &format!("auth_device_start_ip:{}", sha256_hex(&client_ip)),
        auth.device_login_window_secs,
        auth.device_login_start_max_per_ip,
    )
    .await?;

    let token = generate_token_hex_16();
    let token_hash = sha256_hex(&token);
    let browser_binding = resolved_device_login_binding(&headers);
    let browser_binding_hash = sha256_hex(&browser_binding);
    let label = normalize_device_login_label(body.label.as_deref(), 64).unwrap_or_default();
    let device_id = normalize_device_id(body.device_id.as_deref());

    sqlx::query(
        r#"
        INSERT INTO device_login_challenges
          (token_hash, browser_binding_hash, label, status, phone, device_id, created_at, expires_at, approved_at)
        VALUES
          ($1, $2, $3, 'pending', NULL, $4, NOW(), NOW() + ($5::bigint * INTERVAL '1 second'), NULL)
        "#,
    )
    .bind(&token_hash)
    .bind(&browser_binding_hash)
    .bind(if label.is_empty() {
        None::<String>
    } else {
        Some(label.clone())
    })
    .bind(device_id.as_deref())
    .bind(auth.device_login_ttl_secs)
    .execute(&auth.pool)
    .await
    .map_err(|e| {
        tracing::error!(error = %e, "device_login start insert failed");
        ApiError::internal("failed to start device login")
    })?;
    audit_device_login_event(
        "device_login_start",
        "issued",
        Some(client_ip.as_str()),
        None,
        Some(token_hash.as_str()),
        None,
    );

    Ok(device_login_start_response(
        &token,
        &browser_binding,
        auth.device_login_ttl_secs,
    ))
}

pub async fn auth_device_login_approve(
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(body): Json<DeviceLoginTokenIn>,
) -> ApiResult<Response> {
    ensure_device_login_web_enabled(&state)?;
    let auth = require_auth_runtime(&state)?;
    let client_ip = client_ip_from_headers(&state, &headers);
    let principal = require_session_principal(&state, &headers).await?;
    let account_id = principal.account_id.trim().to_string();
    let phone = principal
        .phone
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty());
    consume_rate_limit(
        auth,
        &format!("auth_device_approve_account:{}", hash_prefix(&account_id)),
        auth.device_login_window_secs,
        auth.device_login_approve_max_per_phone,
    )
    .await?;
    let token = normalize_hex_32(&body.token.unwrap_or_default())
        .ok_or_else(|| ApiError::bad_request("token required"))?;
    let token_hash = sha256_hex(&token);
    consume_rate_limit(
        auth,
        &format!("auth_device_approve_token:{token_hash}"),
        auth.device_login_window_secs,
        auth.device_login_approve_max_per_token,
    )
    .await?;

    let mut tx = auth.pool.begin().await.map_err(|e| {
        tracing::error!(error = %e, "device_login approve begin tx failed");
        ApiError::internal("failed to approve device login")
    })?;
    let row = sqlx::query(
        "SELECT id, status, account_id, phone, (expires_at > NOW()) AS alive FROM device_login_challenges WHERE token_hash=$1 LIMIT 1 FOR UPDATE",
    )
    .bind(&token_hash)
    .fetch_optional(&mut *tx)
    .await
    .map_err(|e| {
        tracing::error!(error = %e, "device_login approve select failed");
        ApiError::internal("device login lookup failed")
    })?;

    let Some(row) = row else {
        let _ = tx.rollback().await;
        audit_device_login_event(
            "device_login_approve",
            "blocked",
            client_ip.as_deref(),
            phone,
            Some(token_hash.as_str()),
            Some("challenge_not_found"),
        );
        return Err(ApiError::new(StatusCode::NOT_FOUND, "challenge not found"));
    };

    let id: i64 = row.try_get("id").map_err(|e| {
        tracing::error!(
            error = %e,
            token_hash = %token_hash_prefix(&token_hash),
            column = "id",
            "device_login approve column decode failed"
        );
        ApiError::internal("device login lookup failed")
    })?;
    let status_raw: String = row.try_get("status").map_err(|e| {
        tracing::error!(
            error = %e,
            token_hash = %token_hash_prefix(&token_hash),
            column = "status",
            "device_login approve column decode failed"
        );
        ApiError::internal("device login lookup failed")
    })?;
    let status_l = normalize_device_login_challenge_status(&status_raw).ok_or_else(|| {
        tracing::error!(
            token_hash = %token_hash_prefix(&token_hash),
            status = status_raw.trim(),
            "device_login approve invalid challenge status"
        );
        ApiError::internal("device login lookup failed")
    })?;
    let bound_account_id: Option<String> = row.try_get("account_id").map_err(|e| {
        tracing::error!(
            error = %e,
            token_hash = %token_hash_prefix(&token_hash),
            column = "account_id",
            "device_login approve column decode failed"
        );
        ApiError::internal("device login lookup failed")
    })?;
    let bound_phone: Option<String> = row.try_get("phone").map_err(|e| {
        tracing::error!(
            error = %e,
            token_hash = %token_hash_prefix(&token_hash),
            column = "phone",
            "device_login approve column decode failed"
        );
        ApiError::internal("device login lookup failed")
    })?;
    let alive: bool = row.try_get("alive").map_err(|e| {
        tracing::error!(
            error = %e,
            token_hash = %token_hash_prefix(&token_hash),
            column = "alive",
            "device_login approve column decode failed"
        );
        ApiError::internal("device login lookup failed")
    })?;
    if !alive {
        let _ = sqlx::query("DELETE FROM device_login_challenges WHERE id=$1")
            .bind(id)
            .execute(&mut *tx)
            .await;
        let _ = tx.commit().await;
        audit_device_login_event(
            "device_login_approve",
            "blocked",
            client_ip.as_deref(),
            phone,
            Some(token_hash.as_str()),
            Some("challenge_expired"),
        );
        return Err(ApiError::bad_request("challenge expired"));
    }

    if device_login_approve_allows_idempotent_replay(status_l) {
        if let Some(reason) = approved_device_login_conflict_reason(
            bound_account_id.as_deref(),
            bound_phone.as_deref(),
            &account_id,
            phone,
        ) {
            let _ = tx.rollback().await;
            audit_device_login_event(
                "device_login_approve",
                "blocked",
                client_ip.as_deref(),
                phone,
                Some(token_hash.as_str()),
                Some(reason),
            );
            return Err(ApiError::new(
                StatusCode::CONFLICT,
                "challenge already approved",
            ));
        }

        // Best-effort migration: attach account_id when legacy approve only stored phone.
        if bound_account_id.as_deref().unwrap_or("").trim().is_empty() {
            sqlx::query(
                "UPDATE device_login_challenges SET account_id=$1 WHERE id=$2 AND account_id IS NULL",
            )
            .bind(&account_id)
            .bind(id)
            .execute(&mut *tx)
            .await
            .map_err(|_| {
                device_login_challenge_account_backfill_failed(
                    id,
                    "failed to approve device login",
                    ApiError::internal("device_login challenge account backfill failed"),
                )
            })?;
        }
        tx.commit().await.map_err(|e| {
            tracing::error!(error = %e, "device_login approve commit failed");
            ApiError::internal("failed to approve device login")
        })?;

        audit_device_login_event(
            "device_login_approve",
            if status_l == "redeemed" {
                "already_redeemed"
            } else {
                "already_approved"
            },
            client_ip.as_deref(),
            phone,
            Some(token_hash.as_str()),
            None,
        );
        return Ok(device_login_approve_response());
    }
    if status_l != "pending" {
        let _ = tx.rollback().await;
        audit_device_login_event(
            "device_login_approve",
            "blocked",
            client_ip.as_deref(),
            phone,
            Some(token_hash.as_str()),
            Some("challenge_not_pending"),
        );
        return Err(ApiError::bad_request("challenge not pending"));
    }

    let updated = sqlx::query(
        "UPDATE device_login_challenges SET status='approved', account_id=$1, phone=$2, approved_at=NOW() WHERE id=$3 AND status='pending'",
    )
    .bind(&account_id)
    .bind(phone)
    .bind(id)
    .execute(&mut *tx)
    .await
    .map_err(|e| {
        tracing::error!(error = %e, "device_login approve update failed");
        ApiError::internal("failed to approve device login")
    })?
    .rows_affected();
    if updated == 0 {
        let _ = tx.rollback().await;
        audit_device_login_event(
            "device_login_approve",
            "blocked",
            client_ip.as_deref(),
            phone,
            Some(token_hash.as_str()),
            Some("challenge_not_pending"),
        );
        return Err(ApiError::bad_request("challenge not pending"));
    }
    tx.commit().await.map_err(|e| {
        tracing::error!(error = %e, "device_login approve commit failed");
        ApiError::internal("failed to approve device login")
    })?;
    audit_device_login_event(
        "device_login_approve",
        "approved",
        client_ip.as_deref(),
        phone,
        Some(token_hash.as_str()),
        None,
    );

    Ok(device_login_approve_response())
}

pub async fn auth_device_login_redeem(
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(body): Json<DeviceLoginTokenIn>,
) -> ApiResult<Response> {
    ensure_device_login_web_enabled(&state)?;
    let auth = require_auth_runtime(&state)?;
    let client_ip = rate_limit_client_ip(&state, &headers)?;
    consume_rate_limit(
        auth,
        &format!("auth_device_redeem_ip:{}", sha256_hex(&client_ip)),
        auth.device_login_window_secs,
        auth.device_login_redeem_max_per_ip,
    )
    .await?;

    let token = normalize_hex_32(&body.token.unwrap_or_default())
        .ok_or_else(|| ApiError::bad_request("token required"))?;
    let token_hash = sha256_hex(&token);
    consume_rate_limit(
        auth,
        &format!("auth_device_redeem_token:{token_hash}"),
        auth.device_login_window_secs,
        auth.device_login_redeem_max_per_token,
    )
    .await?;
    let device_id_req = normalize_device_id(body.device_id.as_deref());
    let (redeem_client_ip_hash, redeem_user_agent_hash) =
        device_login_redeem_fingerprint_hashes(&state, &headers, &client_ip);

    let sid = generate_token_hex_16();
    let sid_hash = sha256_hex(&sid);
    let mut tx = auth.pool.begin().await.map_err(|e| {
        tracing::error!(error = %e, "device_login redeem begin tx failed");
        ApiError::internal("failed to redeem device login")
    })?;
    let row = sqlx::query(
        "SELECT id, status, account_id, phone, device_id, browser_binding_hash, redeemed_client_ip_hash, redeemed_user_agent_hash, (expires_at > NOW()) AS alive \
         FROM device_login_challenges WHERE token_hash=$1 LIMIT 1 FOR UPDATE",
    )
    .bind(&token_hash)
    .fetch_optional(&mut *tx)
    .await
    .map_err(|e| {
        tracing::error!(error = %e, "device_login redeem select failed");
        ApiError::internal("device login lookup failed")
    })?;
    let Some(row) = row else {
        let _ = tx.rollback().await;
        audit_device_login_event(
            "device_login_redeem",
            "blocked",
            Some(client_ip.as_str()),
            None,
            Some(token_hash.as_str()),
            Some("challenge_not_found"),
        );
        return Err(ApiError::new(StatusCode::NOT_FOUND, "challenge not found"));
    };

    let id: i64 = row.try_get("id").map_err(|e| {
        tracing::error!(
            error = %e,
            token_hash = %token_hash_prefix(&token_hash),
            column = "id",
            "device_login redeem column decode failed"
        );
        ApiError::internal("device login lookup failed")
    })?;
    let status_raw: String = row.try_get("status").map_err(|e| {
        tracing::error!(
            error = %e,
            token_hash = %token_hash_prefix(&token_hash),
            column = "status",
            "device_login redeem column decode failed"
        );
        ApiError::internal("device login lookup failed")
    })?;
    let status_l = normalize_device_login_challenge_status(&status_raw).ok_or_else(|| {
        tracing::error!(
            token_hash = %token_hash_prefix(&token_hash),
            status = status_raw.trim(),
            "device_login redeem invalid challenge status"
        );
        ApiError::internal("device login lookup failed")
    })?;
    let account_id_db: Option<String> = row.try_get("account_id").map_err(|e| {
        tracing::error!(
            error = %e,
            token_hash = %token_hash_prefix(&token_hash),
            column = "account_id",
            "device_login redeem column decode failed"
        );
        ApiError::internal("device login lookup failed")
    })?;
    let phone: Option<String> = row.try_get("phone").map_err(|e| {
        tracing::error!(
            error = %e,
            token_hash = %token_hash_prefix(&token_hash),
            column = "phone",
            "device_login redeem column decode failed"
        );
        ApiError::internal("device login lookup failed")
    })?;
    let device_id_db: Option<String> = row.try_get("device_id").map_err(|e| {
        tracing::error!(
            error = %e,
            token_hash = %token_hash_prefix(&token_hash),
            column = "device_id",
            "device_login redeem column decode failed"
        );
        ApiError::internal("device login lookup failed")
    })?;
    let browser_binding_hash_db: Option<String> =
        row.try_get("browser_binding_hash").map_err(|e| {
            tracing::error!(
                error = %e,
                token_hash = %token_hash_prefix(&token_hash),
                column = "browser_binding_hash",
                "device_login redeem column decode failed"
            );
            ApiError::internal("device login lookup failed")
        })?;
    let redeemed_client_ip_hash_db: Option<String> =
        row.try_get("redeemed_client_ip_hash").map_err(|e| {
            tracing::error!(
                error = %e,
                token_hash = %token_hash_prefix(&token_hash),
                column = "redeemed_client_ip_hash",
                "device_login redeem column decode failed"
            );
            ApiError::internal("device login lookup failed")
        })?;
    let redeemed_user_agent_hash_db: Option<String> =
        row.try_get("redeemed_user_agent_hash").map_err(|e| {
            tracing::error!(
                error = %e,
                token_hash = %token_hash_prefix(&token_hash),
                column = "redeemed_user_agent_hash",
                "device_login redeem column decode failed"
            );
            ApiError::internal("device login lookup failed")
        })?;
    let alive: bool = row.try_get("alive").map_err(|e| {
        tracing::error!(
            error = %e,
            token_hash = %token_hash_prefix(&token_hash),
            column = "alive",
            "device_login redeem column decode failed"
        );
        ApiError::internal("device login lookup failed")
    })?;

    if !device_login_browser_binding_matches(&headers, browser_binding_hash_db.as_deref()) {
        let _ = tx.rollback().await;
        audit_device_login_event(
            "device_login_redeem",
            "blocked",
            Some(client_ip.as_str()),
            None,
            Some(token_hash.as_str()),
            Some("browser_binding_mismatch"),
        );
        return Err(ApiError::new(StatusCode::NOT_FOUND, "challenge not found"));
    }

    if !alive {
        let _ = tx.rollback().await;
        let _ = sqlx::query("DELETE FROM device_login_challenges WHERE id=$1")
            .bind(id)
            .execute(&auth.pool)
            .await;
        audit_device_login_event(
            "device_login_redeem",
            "blocked",
            Some(client_ip.as_str()),
            None,
            Some(token_hash.as_str()),
            Some("challenge_expired"),
        );
        return Err(ApiError::bad_request("challenge expired"));
    }
    let phone = phone
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty());
    let account_id = account_id_db
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(ToString::to_string);
    let account_id = if let Some(account_id) = account_id {
        account_id
    } else if let Some(phone) = phone.as_deref() {
        // Legacy device-login approvals may still be bound by phone only.
        let acct_id = ensure_account_id_for_phone(auth, phone).await?;
        sqlx::query(
            "UPDATE device_login_challenges SET account_id=$1 WHERE id=$2 AND account_id IS NULL",
        )
        .bind(&acct_id)
        .bind(id)
        .execute(&mut *tx)
        .await
        .map_err(|_| {
            device_login_challenge_account_backfill_failed(
                id,
                "device login lookup failed",
                ApiError::internal("device_login challenge account backfill failed"),
            )
        })?;
        acct_id
    } else {
        let _ = tx.rollback().await;
        audit_device_login_event(
            "device_login_redeem",
            "blocked",
            Some(client_ip.as_str()),
            None,
            Some(token_hash.as_str()),
            Some("challenge_not_bound_to_user"),
        );
        return Err(ApiError::bad_request("challenge not bound to user"));
    };

    // If the challenge is bound to a device_id (e.g. new-device onboarding),
    // require the redeemer to present the same device_id to prevent token theft
    // races (best practice, backwards-compatible with web flows that omit it).
    let device_id_db = normalize_device_id(device_id_db.as_deref());
    if let Some(dbid) = device_id_db.as_deref() {
        let req = device_id_req.as_deref().unwrap_or("");
        if req.is_empty() {
            let _ = tx.rollback().await;
            audit_device_login_event(
                "device_login_redeem",
                "blocked",
                Some(client_ip.as_str()),
                phone.as_deref(),
                Some(token_hash.as_str()),
                Some("device_id_required"),
            );
            return Err(ApiError::bad_request("device_id required"));
        }
        if req != dbid {
            let _ = tx.rollback().await;
            audit_device_login_event(
                "device_login_redeem",
                "blocked",
                Some(client_ip.as_str()),
                phone.as_deref(),
                Some(token_hash.as_str()),
                Some("device_id_mismatch"),
            );
            return Err(ApiError::bad_request("device_id mismatch"));
        }
    }
    let device_id = device_id_db.or(device_id_req);
    match status_l {
        "approved" => {}
        "redeemed" => {
            if !device_login_redeem_replay_allowed(
                redeemed_client_ip_hash_db.as_deref(),
                redeemed_user_agent_hash_db.as_deref(),
                &redeem_client_ip_hash,
                &redeem_user_agent_hash,
            ) {
                let _ = tx.rollback().await;
                audit_device_login_event(
                    "device_login_redeem",
                    "blocked",
                    Some(client_ip.as_str()),
                    phone.as_deref(),
                    Some(token_hash.as_str()),
                    Some("challenge_already_redeemed"),
                );
                return Err(ApiError::new(
                    StatusCode::CONFLICT,
                    "challenge already redeemed",
                ));
            }
        }
        _ => {
            let _ = tx.rollback().await;
            audit_device_login_event(
                "device_login_redeem",
                "blocked",
                Some(client_ip.as_str()),
                None,
                Some(token_hash.as_str()),
                Some("challenge_not_approved"),
            );
            return Err(ApiError::bad_request("challenge not approved"));
        }
    }
    let (last_ip, user_agent) = device_session_request_metadata(&state, &headers);

    sqlx::query(
        r#"
        INSERT INTO auth_sessions
          (sid_hash, account_id, phone, device_id, expires_at, created_at, last_seen_at, revoked_at)
        VALUES
          ($1, $2, $3, $4, NOW() + ($5::bigint * INTERVAL '1 second'), NOW(), NOW(), NULL)
        "#,
    )
    .bind(&sid_hash)
    .bind(&account_id)
    .bind(phone.as_deref())
    .bind(device_id.as_deref())
    .bind(auth.auth_session_ttl_secs)
    .execute(&mut *tx)
    .await
    .map_err(|e| {
        tracing::error!(error = %e, "device_login redeem insert session failed");
        ApiError::internal("failed to redeem device login")
    })?;
    if let Some(device_id) = device_id.as_deref() {
        upsert_device_session_record(
            &mut *tx,
            &account_id,
            phone.as_deref(),
            device_id,
            last_ip.as_deref(),
            user_agent.as_deref(),
        )
        .await
        .map_err(|e| {
            tracing::error!(error = %e, "device_login redeem device-session upsert failed");
            ApiError::internal("failed to redeem device login")
        })?;
    }
    if status_l == "approved" {
        sqlx::query(
            "UPDATE device_login_challenges \
             SET status='redeemed', redeemed_at=NOW(), redeemed_client_ip_hash=$1, redeemed_user_agent_hash=$2 \
             WHERE id=$3",
        )
        .bind(&redeem_client_ip_hash)
        .bind(&redeem_user_agent_hash)
        .bind(id)
        .execute(&mut *tx)
        .await
        .map_err(|e| {
            tracing::error!(error = %e, "device_login redeem challenge finalize failed");
            ApiError::internal("failed to redeem device login")
        })?;
    }
    tx.commit().await.map_err(|e| {
        tracing::error!(error = %e, "device_login redeem commit failed");
        ApiError::internal("failed to redeem device login")
    })?;

    seed_default_official_follow_best_effort(auth, &account_id, "device_login_redeem").await;

    let mut resp = device_login_redeem_response();
    append_set_cookie(
        &mut resp,
        &session_cookie_value(&sid, auth.auth_session_ttl_secs),
    );
    append_set_cookie(&mut resp, &clear_legacy_session_cookie_value());
    append_no_store(&mut resp);
    audit_device_login_event(
        "device_login_redeem",
        if status_l == "redeemed" {
            "replayed"
        } else {
            "redeemed"
        },
        Some(client_ip.as_str()),
        phone.as_deref(),
        Some(token_hash.as_str()),
        None,
    );
    Ok(resp)
}

pub async fn auth_devices_register(
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(body): Json<DeviceRegisterIn>,
) -> ApiResult<Response> {
    let auth = require_auth_runtime(&state)?;
    let principal = require_session_principal(&state, &headers).await?;
    let account_id = principal.account_id.trim().to_string();
    let phone = principal
        .phone
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty());
    let device_id = normalize_device_id(body.device_id.as_deref())
        .ok_or_else(|| ApiError::bad_request("device_id required"))?;
    enforce_bound_session_device_id(&principal, &device_id, "devices_register")?;
    let device_type = normalize_device_login_label(body.device_type.as_deref(), 32);
    let device_name = normalize_device_login_label(body.device_name.as_deref(), 128);
    let platform = normalize_device_login_label(body.platform.as_deref(), 32);
    let app_version = normalize_small(body.app_version.as_deref(), 32);
    let last_ip = client_ip_from_headers(&state, &headers);
    let user_agent = normalize_small(header_value(&headers, "user-agent").as_deref(), 255);
    let sid =
        extract_session_token(&headers, state.accept_legacy_session_cookie).ok_or_else(|| {
            device_register_session_binding_failed(
                &account_id,
                &device_id,
                ApiError::internal("session token missing during device register"),
            )
        })?;
    let sid_hash = sha256_hex(&sid);
    let mut tx = auth.pool.begin().await.map_err(|e| {
        tracing::error!(error = %e, "device register begin tx failed");
        ApiError::internal("failed to register device")
    })?;

    let row = sqlx::query(
        r#"
        INSERT INTO device_sessions
          (account_id, phone, device_id, device_type, device_name, platform, app_version, last_ip, user_agent, created_at, last_seen_at)
        VALUES
          ($1, $2, $3, $4, $5, $6, $7, $8, $9, NOW(), NOW())
        ON CONFLICT (account_id, device_id)
        DO UPDATE SET
          device_type = COALESCE(EXCLUDED.device_type, device_sessions.device_type),
          device_name = COALESCE(EXCLUDED.device_name, device_sessions.device_name),
          platform = COALESCE(EXCLUDED.platform, device_sessions.platform),
          app_version = COALESCE(EXCLUDED.app_version, device_sessions.app_version),
          last_ip = COALESCE(EXCLUDED.last_ip, device_sessions.last_ip),
          user_agent = COALESCE(EXCLUDED.user_agent, device_sessions.user_agent),
          last_seen_at = NOW()
        RETURNING
          id, account_id, phone, device_id, device_type, device_name, platform, app_version, last_ip, user_agent,
          created_at::text AS created_at, last_seen_at::text AS last_seen_at
        "#,
    )
    .bind(&account_id)
    .bind(phone)
    .bind(&device_id)
    .bind(device_type.as_deref())
    .bind(device_name.as_deref())
    .bind(platform.as_deref())
    .bind(app_version.as_deref())
    .bind(last_ip.as_deref())
    .bind(user_agent.as_deref())
    .fetch_one(&mut *tx)
    .await
    .map_err(|e| {
        tracing::error!(error = %e, "device register upsert failed");
        ApiError::internal("failed to register device")
    })?;

    let session_binding = sqlx::query(
        "UPDATE auth_sessions SET device_id=$1, last_seen_at=NOW() WHERE sid_hash=$2 AND account_id=$3 AND revoked_at IS NULL AND expires_at > NOW()",
    )
    .bind(&device_id)
    .bind(&sid_hash)
    .bind(&account_id)
    .execute(&mut *tx)
    .await
    .map_err(|_| {
        device_register_session_binding_failed(
            &account_id,
            &device_id,
            ApiError::internal("auth_sessions device_id binding failed"),
        )
    })?
    .rows_affected();
    require_device_register_session_binding(session_binding, &account_id, &device_id)?;

    tx.commit().await.map_err(|e| {
        tracing::error!(error = %e, "device register commit failed");
        ApiError::internal("failed to register device")
    })?;

    let registered_device_id = require_auth_text_column(
        row.try_get("device_id"),
        "device_id",
        "auth_device_register_upsert",
        "failed to register device",
    )?;
    let registered_device_id = registered_device_id.trim().to_string();
    if registered_device_id.is_empty() {
        tracing::error!(
            account_hash = %hash_prefix(&account_id),
            device_id_hash = %hash_prefix(&device_id),
            "device register upsert returned empty device_id"
        );
        return Err(ApiError::internal("failed to register device"));
    }
    Ok(auth_device_register_response(&registered_device_id))
}

pub async fn auth_devices_list(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<AuthDevicesQuery>,
) -> ApiResult<Response> {
    let auth = require_auth_runtime(&state)?;
    let account_id = require_session_account_id(&state, &headers).await?;
    let limit = normalize_auth_devices_limit(q.limit);
    let before_cursor = normalize_before_cursor(q.before_last_seen_at.as_deref(), q.before_id);
    let rows = if let Some((before_last_seen_at, before_id)) = before_cursor.as_ref() {
        sqlx::query(auth_devices_list_sql(true))
            .bind(&account_id)
            .bind(before_last_seen_at)
            .bind(*before_id)
            .bind(limit)
            .fetch_all(&auth.pool)
            .await
    } else {
        sqlx::query(auth_devices_list_sql(false))
            .bind(&account_id)
            .bind(limit)
            .fetch_all(&auth.pool)
            .await
    }
    .map_err(|e| {
        tracing::error!(error = %e, "device list failed");
        ApiError::internal("failed to list devices")
    })?;

    let devices: Vec<Value> = rows
        .iter()
        .map(row_to_device_json)
        .collect::<ApiResult<Vec<Value>>>()?;
    Ok(auth_devices_list_response(devices))
}

pub async fn auth_devices_delete(
    Path(device_id): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
) -> ApiResult<Response> {
    let auth = require_auth_runtime(&state)?;
    let principal = require_session_principal(&state, &headers).await?;
    let account_id = principal.account_id.trim().to_string();
    let device_id = normalize_device_id(Some(&device_id))
        .ok_or_else(|| ApiError::bad_request("device_id required"))?;
    let clear_current_session = principal.device_id.as_deref() == Some(device_id.as_str());

    let mut tx = auth.pool.begin().await.map_err(|e| {
        tracing::error!(error = %e, "device delete begin tx failed");
        ApiError::internal("failed to remove device")
    })?;

    let deleted_device_record =
        sqlx::query("DELETE FROM device_sessions WHERE account_id=$1 AND device_id=$2")
            .bind(&account_id)
            .bind(&device_id)
            .execute(&mut *tx)
            .await
            .map_err(|e| {
                tracing::error!(error = %e, "device delete failed");
                ApiError::internal("failed to remove device")
            })?
            .rows_affected();

    let revoked = sqlx::query(AUTH_SESSIONS_DEVICE_REVOKE_SQL)
        .bind(&account_id)
        .bind(&device_id)
        .execute(&mut *tx)
        .await
        .map_err(|e| {
            tracing::error!(error = %e, "session revocation on device delete failed");
            ApiError::internal("failed to remove device")
        })?
        .rows_affected();

    // Best practice: revoking a device should also revoke its biometric re-login token.
    let revoked_biometric_tokens = sqlx::query(
        "UPDATE auth_biometric_tokens SET revoked_at=NOW() WHERE account_id=$1 AND device_id=$2 AND revoked_at IS NULL",
    )
    .bind(&account_id)
    .bind(&device_id)
    .execute(&mut *tx)
    .await
    .map_err(|e| {
        tracing::error!(error = %e, "biometric token revocation on device delete failed");
        ApiError::internal("failed to remove device")
    })?
    .rows_affected();

    // Any outstanding contact-invite tokens issued from chat devices registered
    // on this client device must be revoked as well; otherwise a deleted device
    // can continue minting valid first-contact links until invite expiry.
    let revoked_contact_invites = sqlx::query(AUTH_CONTACT_INVITES_ISSUER_CHAT_DEVICE_REVOKE_SQL)
        .bind(&account_id)
        .bind(&device_id)
        .execute(&mut *tx)
        .await
        .map_err(|e| {
            tracing::error!(
                error = %e,
                "contact invite revocation on device delete failed"
            );
            ApiError::internal("failed to remove device")
        })?
        .rows_affected();

    // Revoking a remembered device must also invalidate any already approved or
    // redeemed browser device-login challenges bound to this device id.
    // Otherwise the same browser can replay an old challenge and silently mint
    // a fresh session for a device the user just removed.
    let revoked_device_login_challenges =
        sqlx::query(AUTH_DEVICE_LOGIN_CHALLENGES_ACCOUNT_DEVICE_REVOKE_SQL)
            .bind(&account_id)
            .bind(&device_id)
            .execute(&mut *tx)
            .await
            .map_err(|e| {
                tracing::error!(
                    error = %e,
                    "device-login challenge revocation on device delete failed"
                );
                ApiError::internal("failed to remove device")
            })?
            .rows_affected();

    // Best practice: forgetting a device should also revoke any chat device(s)
    // that were registered from it (prevents stale directory mappings).
    let revoked_chat_devices = sqlx::query(AUTH_CHAT_DEVICES_CLIENT_DEVICE_REVOKE_SQL)
        .bind(&account_id)
        .bind(&device_id)
        .execute(&mut *tx)
        .await
        .map_err(|e| {
            tracing::error!(error = %e, "chat device revocation on device delete failed");
            ApiError::internal("failed to remove device")
        })?
        .rows_affected();

    let revoked_chat_contacts = sqlx::query(AUTH_CHAT_CONTACTS_PEER_CHAT_DEVICE_REVOKE_SQL)
        .bind(&account_id)
        .bind(&device_id)
        .execute(&mut *tx)
        .await
        .map_err(|e| {
            tracing::error!(error = %e, "chat contact revocation on device delete failed");
            ApiError::internal("failed to remove device")
        })?
        .rows_affected();

    tx.commit().await.map_err(|e| {
        tracing::error!(error = %e, "device delete commit failed");
        ApiError::internal("failed to remove device")
    })?;

    if device_delete_is_ignored(
        deleted_device_record,
        revoked,
        revoked_biometric_tokens,
        revoked_contact_invites,
        revoked_device_login_challenges,
        revoked_chat_devices,
        revoked_chat_contacts,
    ) {
        return Ok(auth_device_delete_response(
            AuthDeviceDeleteResponsePayload {
                status: "ignored",
                deleted_device_record: 0,
                revoked_sessions: 0,
                revoked_biometric_tokens: 0,
                revoked_contact_invites: 0,
                revoked_device_login_challenges: 0,
                revoked_chat_devices: 0,
                revoked_chat_contacts: 0,
                clear_current_session,
            },
        ));
    }

    let client_ip =
        client_ip_from_headers(&state, &headers).unwrap_or_else(|| "unknown".to_string());
    tracing::info!(
        security_event = "device_removed",
        outcome = "ok",
        client_ip_hash = %hash_prefix(&client_ip),
        account_hash = %hash_prefix(&account_id),
        device_id_hash = %hash_prefix(&device_id),
        deleted_device_record,
        revoked_sessions = revoked,
        revoked_biometric_tokens,
        revoked_contact_invites,
        revoked_device_login_challenges,
        revoked_chat_devices,
        revoked_chat_contacts,
        "device removed"
    );

    Ok(auth_device_delete_response(
        AuthDeviceDeleteResponsePayload {
            status: "ok",
            deleted_device_record,
            revoked_sessions: revoked,
            revoked_biometric_tokens,
            revoked_contact_invites,
            revoked_device_login_challenges,
            revoked_chat_devices,
            revoked_chat_contacts,
            clear_current_session,
        },
    ))
}

fn device_delete_is_ignored(
    deleted_device_record: u64,
    revoked_sessions: u64,
    revoked_biometric_tokens: u64,
    revoked_contact_invites: u64,
    revoked_device_login_challenges: u64,
    revoked_chat_devices: u64,
    revoked_chat_contacts: u64,
) -> bool {
    deleted_device_record == 0
        && revoked_sessions == 0
        && revoked_biometric_tokens == 0
        && revoked_contact_invites == 0
        && revoked_device_login_challenges == 0
        && revoked_chat_devices == 0
        && revoked_chat_contacts == 0
}

fn approved_device_login_conflict_reason(
    bound_account_id: Option<&str>,
    bound_phone: Option<&str>,
    account_id: &str,
    phone: Option<&str>,
) -> Option<&'static str> {
    if let Some(bound) = bound_account_id.map(str::trim).filter(|s| !s.is_empty()) {
        if bound != account_id {
            return Some("challenge_already_bound_to_other_account");
        }
    }
    if let Some(bound) = bound_phone.map(str::trim).filter(|s| !s.is_empty()) {
        let Some(phone) = phone.map(str::trim).filter(|s| !s.is_empty()) else {
            return Some("challenge_already_bound_to_other_phone");
        };
        if bound != phone {
            return Some("challenge_already_bound_to_other_phone");
        }
    }
    None
}

