struct MeAccessSubject {
    shamell_id: String,
    roles: Vec<String>,
    operator_ids: Vec<String>,
}

#[derive(Debug, Clone)]
struct DerivedAccessSnapshot {
    permissions: Vec<String>,
    products: Vec<String>,
    official_account_ids: Vec<String>,
    official_account_wildcard: bool,
    has_platform_scope: bool,
    is_admin: bool,
    is_superadmin: bool,
}

async fn load_me_access_subject(
    state: &AppState,
    headers: &HeaderMap,
) -> ApiResult<MeAccessSubject> {
    let auth = require_auth_runtime(state)?;
    let principal = require_session_principal(state, headers).await?;
    let shamell_id = ensure_shamell_user_id_for_account(auth, &principal.account_id).await?;
    let operator_ids =
        coach_operator_ids_for_account_best_effort(state, &principal.account_id).await;
    let roles = match fetch_roles_for_account(state, headers, &principal.account_id).await {
        Ok(roles) => roles,
        Err(err) => {
            tracing::warn!(
                account_id_hash = %hash_prefix(&principal.account_id),
                upstream_status = err.status.as_u16(),
                detail = %err.detail,
                "me access roles unavailable"
            );
            Vec::new()
        }
    };
    Ok(MeAccessSubject {
        shamell_id,
        roles,
        operator_ids,
    })
}

fn grant_permission(
    permissions: &mut BTreeSet<String>,
    products: &mut BTreeSet<String>,
    permission: &str,
) {
    permissions.insert(permission.to_string());
    if let Some(product) = product_for_permission(permission) {
        products.insert(product.to_string());
    }
}

fn product_for_permission(permission: &str) -> Option<&'static str> {
    if permission.starts_with("access.") {
        Some("access")
    } else if permission.starts_with("audit.") {
        Some("audit")
    } else if permission.starts_with("cash.") {
        Some("wallet")
    } else if permission.starts_with("coach.") {
        Some("coach")
    } else if permission.starts_with("control.") {
        Some("control")
    } else if permission.starts_with("official.") {
        Some("official_accounts")
    } else if permission.starts_with("rides.") {
        Some("rides")
    } else if permission.starts_with("wallet.") {
        Some("wallet")
    } else {
        None
    }
}

fn derive_access_snapshot(roles: &[String], _operator_ids: &[String]) -> DerivedAccessSnapshot {
    let mut permissions = BTreeSet::new();
    let mut products = BTreeSet::new();
    let is_superadmin = roles.iter().any(|role| role == "superadmin");
    let is_admin = is_superadmin || roles.iter().any(|role| role == "admin");
    let (official_account_wildcard, official_account_ids) = official_role_scopes(roles);
    let has_platform_scope = roles_allow_from_allowlist(roles, PLATFORM_SCOPE_ALLOWED_ROLES);

    if roles_allow_from_allowlist(roles, ACCESS_ASSIGNMENT_ALLOWED_ROLES) {
        grant_permission(&mut permissions, &mut products, "access.assignment.read");
        grant_permission(&mut permissions, &mut products, "access.assignment.write");
    }
    if has_platform_scope {
        grant_permission(&mut permissions, &mut products, "control.dashboard.read");
    }
    if roles_allow_from_allowlist(roles, COACH_ADMIN_ALLOWED_ROLES) {
        grant_permission(&mut permissions, &mut products, "coach.admin.read");
        grant_permission(&mut permissions, &mut products, "coach.admin.write");
    }
    if roles_allow_from_allowlist(roles, COACH_OPS_ALLOWED_ROLES) {
        grant_permission(&mut permissions, &mut products, "coach.catalog.read");
        grant_permission(&mut permissions, &mut products, "coach.operator.read");
    }
    if roles_allow_from_allowlist(roles, COACH_CATALOG_WRITE_ALLOWED_ROLES) {
        grant_permission(
            &mut permissions,
            &mut products,
            "coach.operator.config.write",
        );
    }
    if roles_allow_from_allowlist(roles, COACH_SETTLEMENT_READ_ALLOWED_ROLES) {
        grant_permission(&mut permissions, &mut products, "coach.settlement.read");
    }
    if roles_allow_from_allowlist(roles, COACH_SETTLEMENT_WRITE_ALLOWED_ROLES) {
        grant_permission(&mut permissions, &mut products, "coach.settlement.write");
    }
    if roles_allow_from_allowlist(roles, COACH_BOARDING_ALLOWED_ROLES) {
        grant_permission(&mut permissions, &mut products, "coach.manifest.read");
        grant_permission(&mut permissions, &mut products, "coach.boarding.scan.write");
    }
    if roles_contain_value(roles, "coach.operator_admin")
        || roles_contain_value(roles, "coach.operator_staff")
        || roles_contain_value(roles, "legacy.coach_operator_scope")
    {
        grant_permission(&mut permissions, &mut products, "coach.catalog.read");
        grant_permission(&mut permissions, &mut products, "coach.operator.read");
    }
    if roles_contain_value(roles, "coach.operator_admin") {
        grant_permission(
            &mut permissions,
            &mut products,
            "coach.operator.config.write",
        );
        grant_permission(&mut permissions, &mut products, "coach.settlement.read");
    }
    if roles_contain_value(roles, "coach.boarding_agent") {
        grant_permission(&mut permissions, &mut products, "coach.manifest.read");
        grant_permission(&mut permissions, &mut products, "coach.boarding.scan.write");
    }
    if roles_contain_value(roles, "coach.settlement_readonly") {
        grant_permission(&mut permissions, &mut products, "coach.settlement.read");
    }
    if official_account_wildcard || !official_account_ids.is_empty() {
        grant_permission(&mut permissions, &mut products, "official.dashboard.read");
        grant_permission(&mut permissions, &mut products, "official.dashboard.write");
    }
    if roles_allow_ride_dispatch(roles) {
        grant_permission(&mut permissions, &mut products, "rides.dispatch.read");
    }
    if roles_allow_ride_driver(roles) {
        grant_permission(&mut permissions, &mut products, "rides.driver.read");
    }
    if roles_allow_ride_operator(roles) {
        grant_permission(&mut permissions, &mut products, "rides.operator.read");
    }
    if roles_allow_ride_support(roles) {
        grant_permission(&mut permissions, &mut products, "rides.support.read");
    }
    if roles_allow_ride_support_sensitive_details(roles) {
        grant_permission(
            &mut permissions,
            &mut products,
            "rides.support.sensitive.read",
        );
    }
    if roles_allow_ride_finance(roles) {
        grant_permission(&mut permissions, &mut products, "rides.finance.read");
    }
    if roles_allow_ride_finance_sensitive_details(roles) {
        grant_permission(
            &mut permissions,
            &mut products,
            "rides.finance.sensitive.read",
        );
    }
    if roles_allow_ride_admin(roles) {
        grant_permission(&mut permissions, &mut products, "rides.admin.read");
        grant_permission(&mut permissions, &mut products, "rides.admin.write");
    }
    if roles_allow_ride_compliance(roles) {
        grant_permission(&mut permissions, &mut products, "rides.compliance.read");
    }
    if roles_allow_ride_document_sensitive_details(roles) {
        grant_permission(
            &mut permissions,
            &mut products,
            "rides.document.sensitive.read",
        );
    }
    if roles_allow_ride_case_sensitive_details(roles) {
        grant_permission(&mut permissions, &mut products, "rides.case.sensitive.read");
    }
    if roles_allow_ride_pricing(roles) {
        grant_permission(&mut permissions, &mut products, "rides.pricing.write");
    }
    if roles_allow_wallet_operator(roles) {
        grant_permission(&mut permissions, &mut products, "wallet.operator.read");
    }
    if roles_allow_cash_agent(roles) {
        grant_permission(&mut permissions, &mut products, "cash.agent.read");
        grant_permission(&mut permissions, &mut products, "cash.agent.redeem.write");
    }
    if roles_allow_wallet_admin(roles) {
        grant_permission(&mut permissions, &mut products, "wallet.admin.read");
    }
    if roles_allow_wallet_finance(roles) {
        grant_permission(&mut permissions, &mut products, "wallet.finance.read");
    }
    if roles_allow_wallet_credit(roles) {
        grant_permission(&mut permissions, &mut products, "wallet.credit.write");
    }
    if roles_allow_wallet_guardrails(roles) {
        grant_permission(&mut permissions, &mut products, "wallet.admin.write");
        grant_permission(&mut permissions, &mut products, "wallet.finance.write");
        grant_permission(&mut permissions, &mut products, "wallet.guardrails.write");
    }
    if roles_allow_from_allowlist(roles, AUDIT_EXPORT_ALLOWED_ROLES) {
        grant_permission(&mut permissions, &mut products, "audit.export.read");
    }
    let mut official_account_ids = official_account_ids.into_iter().collect::<Vec<_>>();
    official_account_ids.sort();

    DerivedAccessSnapshot {
        permissions: permissions.into_iter().collect(),
        products: products.into_iter().collect(),
        official_account_ids,
        official_account_wildcard,
        has_platform_scope,
        is_admin,
        is_superadmin,
    }
}

#[derive(Debug, Clone)]
pub(crate) struct ResolvedAccessAssignment {
    pub(crate) role_id: String,
    pub(crate) legacy_role: String,
    pub(crate) scope: AccessAssignmentScopeOut,
}

fn access_assignment_scope(
    platform: bool,
    operator_id: Option<String>,
    official_account_id: Option<String>,
) -> AccessAssignmentScopeOut {
    AccessAssignmentScopeOut {
        platform,
        operator_id,
        official_account_id,
    }
}

fn normalize_access_assignment_role_id(raw: &str) -> ApiResult<String> {
    let normalized = raw.trim().to_ascii_lowercase();
    if normalized.is_empty() || normalized.len() > 96 {
        return Err(ApiError::bad_request("role_id required"));
    }
    if !normalized
        .chars()
        .all(|ch| ch.is_ascii_lowercase() || ch.is_ascii_digit() || matches!(ch, '.' | '_' | '-'))
    {
        return Err(ApiError::bad_request("invalid role_id"));
    }
    Ok(normalized)
}

fn supported_legacy_access_assignment_role(raw: &str) -> bool {
    matches!(
        raw,
        "merchant"
            | "qr_seller"
            | "seller"
            | "cashout_operator"
            | "driver"
            | "ride_driver"
            | "driver_ops"
            | "city_manager"
            | "support_l1"
            | "support_l2"
            | "finance"
            | "compliance_risk"
            | "marketing"
            | "bi_audit_read_only"
            | "admin"
            | "superadmin"
            | "ops"
    )
}

fn normalize_access_assignment_operator_scope(raw: Option<&str>) -> ApiResult<Option<String>> {
    let Some(raw) = raw.map(str::trim).filter(|value| !value.is_empty()) else {
        return Ok(None);
    };
    let normalized = normalize_coach_operator_ids([raw.to_string()]);
    normalized
        .into_iter()
        .next()
        .map(Some)
        .ok_or_else(|| ApiError::bad_request("invalid operator_id"))
}

fn normalize_access_assignment_official_scope(raw: Option<&str>) -> ApiResult<Option<String>> {
    let Some(raw) = raw.map(str::trim).filter(|value| !value.is_empty()) else {
        return Ok(None);
    };
    if raw == "*" {
        return Ok(Some("*".to_string()));
    }
    Ok(Some(normalize_official_account_id(raw)?))
}

fn normalize_access_assignment_subject(
    account_id_raw: Option<&str>,
    phone_raw: Option<&str>,
) -> ApiResult<(Option<String>, Option<String>)> {
    let account_id = normalize_session_account_id(account_id_raw);
    let phone = normalize_owner_phone(phone_raw)?;
    if account_id.is_none() && phone.is_none() {
        return Err(ApiError::bad_request("account_id or phone required"));
    }
    Ok((account_id, phone))
}

fn normalize_access_assignment_limit(raw: Option<i64>) -> i64 {
    raw.unwrap_or(200).clamp(1, 500)
}

#[allow(dead_code)]
pub(crate) fn resolved_access_assignment_from_legacy_role(
    raw: &str,
) -> Option<ResolvedAccessAssignment> {
    let legacy_role = raw.trim().to_ascii_lowercase();
    if legacy_role.is_empty() {
        return None;
    }
    let resolved = match legacy_role.as_str() {
        "superadmin" => ResolvedAccessAssignment {
            role_id: "owner.daily_admin".to_string(),
            legacy_role,
            scope: access_assignment_scope(true, None, None),
        },
        "admin" => ResolvedAccessAssignment {
            role_id: "platform.admin".to_string(),
            legacy_role,
            scope: access_assignment_scope(true, None, None),
        },
        "ops" => ResolvedAccessAssignment {
            role_id: "platform.ops_manager".to_string(),
            legacy_role,
            scope: access_assignment_scope(true, None, None),
        },
        "support_l1" => ResolvedAccessAssignment {
            role_id: "platform.support_l1".to_string(),
            legacy_role,
            scope: access_assignment_scope(true, None, None),
        },
        "support_l2" => ResolvedAccessAssignment {
            role_id: "platform.support_l2".to_string(),
            legacy_role,
            scope: access_assignment_scope(true, None, None),
        },
        "finance" => ResolvedAccessAssignment {
            role_id: "platform.finance_admin".to_string(),
            legacy_role,
            scope: access_assignment_scope(true, None, None),
        },
        "compliance_risk" => ResolvedAccessAssignment {
            role_id: "platform.compliance_admin".to_string(),
            legacy_role,
            scope: access_assignment_scope(true, None, None),
        },
        "bi_audit_read_only" => ResolvedAccessAssignment {
            role_id: "audit.readonly".to_string(),
            legacy_role,
            scope: access_assignment_scope(true, None, None),
        },
        "driver" | "ride_driver" => ResolvedAccessAssignment {
            role_id: "rides.driver".to_string(),
            legacy_role,
            scope: access_assignment_scope(false, None, None),
        },
        "driver_ops" => ResolvedAccessAssignment {
            role_id: "rides.driver_ops".to_string(),
            legacy_role,
            scope: access_assignment_scope(false, None, None),
        },
        "city_manager" => ResolvedAccessAssignment {
            role_id: "rides.city_manager".to_string(),
            legacy_role,
            scope: access_assignment_scope(false, None, None),
        },
        "merchant" | "qr_seller" => ResolvedAccessAssignment {
            role_id: "wallet.operator".to_string(),
            legacy_role,
            scope: access_assignment_scope(false, None, None),
        },
        "cashout_operator" => ResolvedAccessAssignment {
            role_id: "wallet.cash_agent".to_string(),
            legacy_role,
            scope: access_assignment_scope(false, None, None),
        },
        "seller" => ResolvedAccessAssignment {
            role_id: "legacy.seller".to_string(),
            legacy_role,
            scope: access_assignment_scope(true, None, None),
        },
        "marketing" => ResolvedAccessAssignment {
            role_id: "legacy.marketing".to_string(),
            legacy_role,
            scope: access_assignment_scope(false, None, None),
        },
        _ => {
            if let Some(operator_id) = legacy_role.strip_prefix("operator_") {
                let operator_id = normalize_coach_operator_ids([operator_id.to_string()])
                    .into_iter()
                    .next()?;
                ResolvedAccessAssignment {
                    role_id: "legacy.coach_operator_scope".to_string(),
                    legacy_role,
                    scope: access_assignment_scope(false, Some(operator_id), None),
                }
            } else if let Some(official_account_id) = legacy_role.strip_prefix("official_owner:") {
                let official_account_id = if official_account_id == "*" {
                    "*".to_string()
                } else {
                    normalize_official_account_id(official_account_id).ok()?
                };
                ResolvedAccessAssignment {
                    role_id: "official.account_owner".to_string(),
                    legacy_role,
                    scope: access_assignment_scope(false, None, Some(official_account_id)),
                }
            } else {
                ResolvedAccessAssignment {
                    role_id: format!("legacy.{legacy_role}"),
                    legacy_role,
                    scope: access_assignment_scope(false, None, None),
                }
            }
        }
    };
    Some(resolved)
}

fn resolved_access_assignment_from_role_id(
    raw_role_id: &str,
    scope: Option<&crate::models::AccessAssignmentScopeIn>,
) -> ApiResult<ResolvedAccessAssignment> {
    let role_id = normalize_access_assignment_role_id(raw_role_id)?;
    let scope_platform = scope.and_then(|value| value.platform).unwrap_or(false);
    let operator_id = normalize_access_assignment_operator_scope(
        scope.and_then(|value| value.operator_id.as_deref()),
    )?;
    let official_account_id = normalize_access_assignment_official_scope(
        scope.and_then(|value| value.official_account_id.as_deref()),
    )?;

    let platform_role =
        |legacy_role: &str, role_id: String| -> ApiResult<ResolvedAccessAssignment> {
            if operator_id.is_some()
                || official_account_id.is_some()
                || (scope.is_some() && !scope_platform)
            {
                return Err(ApiError::bad_request("scope does not match role_id"));
            }
            Ok(ResolvedAccessAssignment {
                role_id,
                legacy_role: legacy_role.to_string(),
                scope: access_assignment_scope(true, None, None),
            })
        };
    let unscoped_role =
        |legacy_role: &str, role_id: String| -> ApiResult<ResolvedAccessAssignment> {
            if operator_id.is_some() || official_account_id.is_some() {
                return Err(ApiError::bad_request("scope does not match role_id"));
            }
            Ok(ResolvedAccessAssignment {
                role_id,
                legacy_role: legacy_role.to_string(),
                scope: access_assignment_scope(false, None, None),
            })
        };

    match role_id.as_str() {
        "owner.daily_admin" => platform_role("superadmin", role_id),
        "platform.admin" => platform_role("admin", role_id),
        "platform.ops_manager" => platform_role("ops", role_id),
        "platform.support_l1" => platform_role("support_l1", role_id),
        "platform.support_l2" => platform_role("support_l2", role_id),
        "platform.finance_admin" => platform_role("finance", role_id),
        "platform.compliance_admin" => platform_role("compliance_risk", role_id),
        "audit.readonly" => platform_role("bi_audit_read_only", role_id),
        "rides.driver" => unscoped_role("ride_driver", role_id),
        "rides.driver_ops" => unscoped_role("driver_ops", role_id),
        "rides.city_manager" => unscoped_role("city_manager", role_id),
        "wallet.operator" => unscoped_role("merchant", role_id),
        "wallet.cash_agent" => unscoped_role("cashout_operator", role_id),
        "legacy.seller" => platform_role("seller", role_id),
        "legacy.marketing" => unscoped_role("marketing", role_id),
        "official.account_owner" => {
            if operator_id.is_some() || (scope.is_some() && scope_platform) {
                return Err(ApiError::bad_request("scope does not match role_id"));
            }
            let Some(official_account_id) = official_account_id else {
                return Err(ApiError::bad_request("official_account_id required"));
            };
            Ok(ResolvedAccessAssignment {
                role_id,
                legacy_role: format!("official_owner:{official_account_id}"),
                scope: access_assignment_scope(false, None, Some(official_account_id)),
            })
        }
        "coach.operator_admin"
        | "coach.operator_staff"
        | "coach.boarding_agent"
        | "coach.settlement_readonly"
        | "legacy.coach_operator_scope" => {
            if official_account_id.is_some() || (scope.is_some() && scope_platform) {
                return Err(ApiError::bad_request("scope does not match role_id"));
            }
            let Some(operator_id) = operator_id else {
                return Err(ApiError::bad_request("operator_id required"));
            };
            Ok(ResolvedAccessAssignment {
                role_id,
                legacy_role: format!("operator_{operator_id}"),
                scope: access_assignment_scope(false, Some(operator_id), None),
            })
        }
        _ if role_id.starts_with("legacy.") => {
            let Some(suffix) = role_id.strip_prefix("legacy.") else {
                return Err(ApiError::bad_request("unsupported role_id"));
            };
            let legacy_role = suffix.to_string();
            if suffix == "coach_operator_scope" {
                return Err(ApiError::bad_request("operator_id required"));
            }
            if !supported_legacy_access_assignment_role(suffix) {
                return Err(ApiError::bad_request("unsupported role_id"));
            }
            if operator_id.is_some() || official_account_id.is_some() {
                return Err(ApiError::bad_request("scope does not match role_id"));
            }
            Ok(ResolvedAccessAssignment {
                role_id,
                legacy_role,
                scope: access_assignment_scope(false, None, None),
            })
        }
        _ => Err(ApiError::bad_request("unsupported role_id")),
    }
}

fn legacy_role_for_access_assignment(
    role_id: &str,
    scope: &AccessAssignmentScopeOut,
) -> ApiResult<String> {
    match role_id {
        "owner.daily_admin" => Ok("superadmin".to_string()),
        "platform.admin" => Ok("admin".to_string()),
        "platform.ops_manager" => Ok("ops".to_string()),
        "platform.support_l1" => Ok("support_l1".to_string()),
        "platform.support_l2" => Ok("support_l2".to_string()),
        "platform.finance_admin" => Ok("finance".to_string()),
        "platform.compliance_admin" => Ok("compliance_risk".to_string()),
        "audit.readonly" => Ok("bi_audit_read_only".to_string()),
        "rides.driver" => Ok("ride_driver".to_string()),
        "rides.driver_ops" => Ok("driver_ops".to_string()),
        "rides.city_manager" => Ok("city_manager".to_string()),
        "wallet.operator" => Ok("merchant".to_string()),
        "wallet.cash_agent" => Ok("cashout_operator".to_string()),
        "legacy.seller" => Ok("seller".to_string()),
        "legacy.marketing" => Ok("marketing".to_string()),
        "official.account_owner" => {
            let Some(official_account_id) = scope.official_account_id.as_deref() else {
                return Err(ApiError::internal(
                    "failed to materialize official access assignment",
                ));
            };
            Ok(format!("official_owner:{official_account_id}"))
        }
        "coach.operator_admin"
        | "coach.operator_staff"
        | "coach.boarding_agent"
        | "coach.settlement_readonly"
        | "legacy.coach_operator_scope" => {
            let Some(operator_id) = scope.operator_id.as_deref() else {
                return Err(ApiError::internal(
                    "failed to materialize coach access assignment",
                ));
            };
            Ok(format!("operator_{operator_id}"))
        }
        _ if role_id.starts_with("legacy.") => {
            let Some(suffix) = role_id.strip_prefix("legacy.") else {
                return Err(ApiError::internal(
                    "failed to materialize access assignment",
                ));
            };
            if suffix == "coach_operator_scope" {
                return Err(ApiError::internal(
                    "failed to materialize access assignment",
                ));
            }
            if !supported_legacy_access_assignment_role(suffix) {
                return Err(ApiError::internal(
                    "failed to materialize access assignment",
                ));
            }
            Ok(suffix.to_string())
        }
        _ => Err(ApiError::internal(
            "failed to materialize access assignment",
        )),
    }
}

fn account_role_alias_for_access_assignment(
    role_id: &str,
    scope: &AccessAssignmentScopeOut,
) -> ApiResult<Option<String>> {
    if matches!(
        role_id,
        "coach.operator_admin"
            | "coach.operator_staff"
            | "coach.boarding_agent"
            | "coach.settlement_readonly"
            | "legacy.coach_operator_scope"
    ) {
        return Ok(None);
    }
    Ok(Some(legacy_role_for_access_assignment(role_id, scope)?))
}

#[derive(Debug)]
struct StoredAccessAssignmentRow {
    cursor_id: i64,
    account_id: Option<String>,
    phone: Option<String>,
    role_id: String,
    created_at: Option<String>,
    scope: AccessAssignmentScopeOut,
}

fn access_assignment_out_from_stored_row(
    row: StoredAccessAssignmentRow,
) -> ApiResult<Option<AccessAssignmentOut>> {
    if row.account_id.is_none() && row.phone.is_none() {
        return Ok(None);
    }
    let legacy_role = legacy_role_for_access_assignment(&row.role_id, &row.scope)?;
    Ok(Some(AccessAssignmentOut {
        cursor_id: Some(row.cursor_id),
        account_id: row.account_id,
        phone: row.phone,
        role_id: row.role_id,
        legacy_role,
        created_at: row.created_at,
        scope: row.scope,
    }))
}

async fn load_stored_access_assignment_rows<'e, E>(
    executor: E,
    account_id: Option<&str>,
    phone: Option<&str>,
    role_id: Option<&str>,
    limit: i64,
    before_created_at: Option<&str>,
    before_id: Option<i64>,
) -> Result<Vec<StoredAccessAssignmentRow>, sqlx::Error>
where
    E: sqlx::Executor<'e, Database = Postgres>,
{
    let rows = sqlx::query(
        r#"
        SELECT
          ra.id AS cursor_id,
          ra.subject_account_id AS account_id,
          ra.subject_phone AS phone,
          ra.role_id AS role_id,
          ra.created_at::text AS created_at,
          COALESCE(BOOL_OR(sa.scope_kind = 'platform'), FALSE) AS scope_platform,
          MAX(CASE WHEN sa.scope_kind = 'operator' THEN sa.scope_value END) AS operator_id,
          MAX(CASE WHEN sa.scope_kind = 'official_account' THEN sa.scope_value END) AS official_account_id
        FROM auth_role_assignments ra
        LEFT JOIN auth_scope_assignments sa
          ON sa.role_assignment_id = ra.id
        WHERE ra.revoked_at IS NULL
          AND (
            (($1::text IS NULL AND $2::text IS NULL))
            OR ($1::text IS NOT NULL AND ra.subject_account_id = $1)
            OR ($2::text IS NOT NULL AND ra.subject_phone = $2)
          )
          AND ($3::text IS NULL OR ra.role_id = $3)
          AND (
            $4::timestamptz IS NULL
            OR $5::bigint IS NULL
            OR ra.created_at < $4::timestamptz
            OR (ra.created_at = $4::timestamptz AND ra.id < $5::bigint)
          )
        GROUP BY ra.id, ra.subject_account_id, ra.subject_phone, ra.role_id, ra.created_at
        ORDER BY ra.created_at DESC, ra.id DESC
        LIMIT $6
        "#,
    )
    .bind(account_id)
    .bind(phone)
    .bind(role_id)
    .bind(before_created_at)
    .bind(before_id)
    .bind(limit)
    .fetch_all(executor)
    .await?;

    let mut out = Vec::with_capacity(rows.len());
    for row in rows {
        let cursor_id = row.try_get::<i64, _>("cursor_id")?;
        let account_id = row
            .try_get::<Option<String>, _>("account_id")?
            .map(|value| value.trim().to_string())
            .filter(|value| !value.is_empty());
        let phone = row
            .try_get::<Option<String>, _>("phone")?
            .map(|value| value.trim().to_string())
            .filter(|value| !value.is_empty());
        let role_id = row
            .try_get::<String, _>("role_id")?
            .trim()
            .to_ascii_lowercase();
        let created_at = row
            .try_get::<Option<String>, _>("created_at")?
            .map(|value| value.trim().to_string())
            .filter(|value| !value.is_empty());
        let scope = access_assignment_scope(
            row.try_get::<bool, _>("scope_platform")?,
            row.try_get::<Option<String>, _>("operator_id")?
                .map(|value| value.trim().to_string())
                .filter(|value| !value.is_empty()),
            row.try_get::<Option<String>, _>("official_account_id")?
                .map(|value| value.trim().to_string())
                .filter(|value| !value.is_empty()),
        );
        out.push(StoredAccessAssignmentRow {
            cursor_id,
            account_id,
            phone,
            role_id,
            created_at,
            scope,
        });
    }
    Ok(out)
}

pub(crate) async fn list_access_assignments_from_auth_store(
    auth: &AuthRuntime,
    account_id: Option<&str>,
    phone: Option<&str>,
    role_id: Option<&str>,
    limit: i64,
    before_created_at: Option<&str>,
    before_id: Option<i64>,
) -> ApiResult<Vec<AccessAssignmentOut>> {
    let rows = load_stored_access_assignment_rows(
        &auth.pool,
        account_id,
        phone,
        role_id,
        limit,
        before_created_at,
        before_id,
    )
    .await
    .map_err(|e| {
        tracing::error!(error = %e, "access assignment list query failed");
        ApiError::internal("failed to load access assignments")
    })?;
    let mut out = Vec::new();
    for row in rows {
        if let Some(assignment) = access_assignment_out_from_stored_row(row)? {
            out.push(assignment);
        }
    }
    Ok(out)
}

async fn account_phone_for_account(
    auth: &AuthRuntime,
    account_id: &str,
) -> ApiResult<Option<String>> {
    let phone = sqlx::query("SELECT phone FROM auth_accounts WHERE account_id=$1 LIMIT 1")
        .bind(account_id)
        .fetch_optional(&auth.pool)
        .await
        .map_err(|e| {
            tracing::error!(error = %e, account_id_hash = %hash_prefix(account_id), "account phone lookup failed");
            ApiError::internal("failed to resolve access assignment subject")
        })?
        .and_then(|row| row.try_get::<Option<String>, _>("phone").ok().flatten())
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());
    Ok(phone)
}

async fn best_effort_account_id_for_subject_phone(
    auth: &AuthRuntime,
    phone: Option<&str>,
) -> Option<String> {
    let phone = phone.map(str::trim).filter(|value| !value.is_empty())?;
    sqlx::query("SELECT account_id FROM auth_accounts WHERE phone=$1 LIMIT 1")
        .bind(phone)
        .fetch_optional(&auth.pool)
        .await
        .ok()
        .flatten()
        .and_then(|row| {
            row.try_get::<Option<String>, _>("account_id")
                .ok()
                .flatten()
        })
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
}

async fn resolve_access_assignment_subject_for_storage(
    auth: &AuthRuntime,
    account_id: Option<String>,
    phone: Option<String>,
) -> ApiResult<(Option<String>, Option<String>)> {
    let mut resolved_account_id = account_id;
    let mut resolved_phone = phone;
    if resolved_phone.is_none() {
        if let Some(account_id) = resolved_account_id.as_deref() {
            resolved_phone = account_phone_for_account(auth, account_id).await?;
        }
    }
    if resolved_account_id.is_none() {
        resolved_account_id =
            best_effort_account_id_for_subject_phone(auth, resolved_phone.as_deref()).await;
    }
    Ok((resolved_account_id, resolved_phone))
}

fn access_assignment_scope_matches(
    left: &AccessAssignmentScopeOut,
    right: &AccessAssignmentScopeOut,
) -> bool {
    left.platform == right.platform
        && left.operator_id == right.operator_id
        && left.official_account_id == right.official_account_id
}

#[derive(Clone, Debug)]
pub(crate) struct AccessAssignmentActor {
    account_id: Option<String>,
    service_id: Option<String>,
}

impl AccessAssignmentActor {
    pub(crate) fn session(account_id: &str) -> Self {
        let account_id = account_id.trim();
        Self {
            account_id: (!account_id.is_empty()).then(|| account_id.to_string()),
            service_id: None,
        }
    }

    pub(crate) fn internal(service_id: &str) -> Self {
        let service_id = service_id.trim().to_ascii_lowercase();
        Self {
            account_id: None,
            service_id: (!service_id.is_empty()).then_some(service_id),
        }
    }

    fn account_id(&self) -> Option<&str> {
        self.account_id.as_deref()
    }

    fn service_id(&self) -> Option<&str> {
        self.service_id.as_deref()
    }
}

fn access_assignment_actor_metadata(actor: &AccessAssignmentActor, field: &'static str) -> String {
    actor
        .service_id()
        .map(|service_id| json!({ field: service_id }).to_string())
        .unwrap_or_else(|| "{}".to_string())
}

pub(crate) async fn grant_access_assignment_in_auth_store(
    auth: &AuthRuntime,
    actor: &AccessAssignmentActor,
    account_id: Option<String>,
    phone: Option<String>,
    resolved: &ResolvedAccessAssignment,
) -> ApiResult<AccessAssignmentOut> {
    let (account_id, phone) =
        resolve_access_assignment_subject_for_storage(auth, account_id, phone).await?;
    let mut tx = auth.pool.begin().await.map_err(|e| {
        tracing::error!(error = %e, "access assignment transaction begin failed");
        ApiError::internal("failed to write access assignment")
    })?;

    let lock_key = format!(
        "access_assignment_grant:{}:{}:{}:{}",
        account_id.as_deref().unwrap_or(""),
        phone.as_deref().unwrap_or(""),
        resolved.role_id,
        resolved.legacy_role
    );
    sqlx::query("SELECT pg_advisory_xact_lock(hashtext($1))")
        .bind(&lock_key)
        .execute(&mut *tx)
        .await
        .map_err(|e| {
            tracing::error!(error = %e, "access assignment lock failed");
            ApiError::internal("failed to write access assignment")
        })?;

    let existing = load_stored_access_assignment_rows(
        &mut *tx,
        account_id.as_deref(),
        phone.as_deref(),
        Some(resolved.role_id.as_str()),
        100,
        None,
        None,
    )
    .await
    .map_err(|e| {
        tracing::error!(error = %e, "access assignment existing lookup failed");
        ApiError::internal("failed to write access assignment")
    })?;
    for row in existing {
        if access_assignment_scope_matches(&row.scope, &resolved.scope) {
            tx.commit().await.map_err(|e| {
                tracing::error!(error = %e, "access assignment transaction commit failed");
                ApiError::internal("failed to write access assignment")
            })?;
            return access_assignment_out_from_stored_row(row)?
                .ok_or_else(|| ApiError::internal("failed to write access assignment"));
        }
    }

    let inserted = sqlx::query(
        r#"
        INSERT INTO auth_role_assignments
          (subject_account_id, subject_phone, role_id, created_by_account_id, created_at, revoked_by_account_id, revoked_at, revoke_reason, metadata)
        VALUES
          ($1, $2, $3, $4, NOW(), NULL, NULL, NULL, $5::jsonb)
        RETURNING id AS cursor_id, created_at::text AS created_at
        "#,
    )
    .bind(account_id.as_deref())
    .bind(phone.as_deref())
    .bind(resolved.role_id.as_str())
    .bind(actor.account_id())
    .bind(access_assignment_actor_metadata(actor, "created_by_service_id"))
    .fetch_one(&mut *tx)
    .await
    .map_err(|e| {
        tracing::error!(error = %e, "access assignment insert failed");
        ApiError::internal("failed to write access assignment")
    })?;
    let cursor_id = inserted.try_get::<i64, _>("cursor_id").map_err(|e| {
        tracing::error!(error = %e, "access assignment insert missing cursor id");
        ApiError::internal("failed to write access assignment")
    })?;
    let created_at = inserted
        .try_get::<Option<String>, _>("created_at")
        .map_err(|e| {
            tracing::error!(error = %e, "access assignment insert missing created_at");
            ApiError::internal("failed to write access assignment")
        })?
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty());

    if resolved.scope.platform {
        sqlx::query(
            "INSERT INTO auth_scope_assignments (role_assignment_id, scope_kind, scope_value, created_at) VALUES ($1, 'platform', NULL, NOW()) ON CONFLICT DO NOTHING",
        )
        .bind(cursor_id)
        .execute(&mut *tx)
        .await
        .map_err(|e| {
            tracing::error!(error = %e, "platform scope insert failed");
            ApiError::internal("failed to write access assignment")
        })?;
    }
    if let Some(operator_id) = resolved.scope.operator_id.as_deref() {
        sqlx::query(
            "INSERT INTO auth_scope_assignments (role_assignment_id, scope_kind, scope_value, created_at) VALUES ($1, 'operator', $2, NOW()) ON CONFLICT DO NOTHING",
        )
        .bind(cursor_id)
        .bind(operator_id)
        .execute(&mut *tx)
        .await
        .map_err(|e| {
            tracing::error!(error = %e, "operator scope insert failed");
            ApiError::internal("failed to write access assignment")
        })?;
    }
    if let Some(official_account_id) = resolved.scope.official_account_id.as_deref() {
        sqlx::query(
            "INSERT INTO auth_scope_assignments (role_assignment_id, scope_kind, scope_value, created_at) VALUES ($1, 'official_account', $2, NOW()) ON CONFLICT DO NOTHING",
        )
        .bind(cursor_id)
        .bind(official_account_id)
        .execute(&mut *tx)
        .await
        .map_err(|e| {
            tracing::error!(error = %e, "official scope insert failed");
            ApiError::internal("failed to write access assignment")
        })?;
    }

    tx.commit().await.map_err(|e| {
        tracing::error!(error = %e, "access assignment transaction commit failed");
        ApiError::internal("failed to write access assignment")
    })?;

    Ok(AccessAssignmentOut {
        cursor_id: Some(cursor_id),
        account_id,
        phone,
        role_id: resolved.role_id.clone(),
        legacy_role: resolved.legacy_role.clone(),
        created_at,
        scope: resolved.scope.clone(),
    })
}

pub(crate) async fn revoke_access_assignment_in_auth_store(
    auth: &AuthRuntime,
    actor: &AccessAssignmentActor,
    account_id: Option<String>,
    phone: Option<String>,
    resolved: &ResolvedAccessAssignment,
) -> ApiResult<AccessAssignmentOut> {
    let (account_id, phone) =
        resolve_access_assignment_subject_for_storage(auth, account_id, phone).await?;
    let mut tx = auth.pool.begin().await.map_err(|e| {
        tracing::error!(error = %e, "access assignment transaction begin failed");
        ApiError::internal("failed to remove access assignment")
    })?;

    let lock_key = format!(
        "access_assignment_revoke:{}:{}:{}:{}",
        account_id.as_deref().unwrap_or(""),
        phone.as_deref().unwrap_or(""),
        resolved.role_id,
        resolved.legacy_role
    );
    sqlx::query("SELECT pg_advisory_xact_lock(hashtext($1))")
        .bind(&lock_key)
        .execute(&mut *tx)
        .await
        .map_err(|e| {
            tracing::error!(error = %e, "access assignment lock failed");
            ApiError::internal("failed to remove access assignment")
        })?;

    let existing = load_stored_access_assignment_rows(
        &mut *tx,
        account_id.as_deref(),
        phone.as_deref(),
        Some(resolved.role_id.as_str()),
        100,
        None,
        None,
    )
    .await
    .map_err(|e| {
        tracing::error!(error = %e, "access assignment revoke lookup failed");
        ApiError::internal("failed to remove access assignment")
    })?;

    let mut revoked_assignment = None;
    for row in existing {
        if !access_assignment_scope_matches(&row.scope, &resolved.scope) {
            continue;
        }
        sqlx::query(
            "UPDATE auth_role_assignments \
             SET revoked_at=NOW(), \
                 revoked_by_account_id=$2, \
                 revoke_reason='access_assignment_remove', \
                 metadata=COALESCE(metadata, '{}'::jsonb) || $3::jsonb \
             WHERE id=$1 AND revoked_at IS NULL",
        )
        .bind(row.cursor_id)
        .bind(actor.account_id())
        .bind(access_assignment_actor_metadata(
            actor,
            "revoked_by_service_id",
        ))
        .execute(&mut *tx)
        .await
        .map_err(|e| {
            tracing::error!(error = %e, "access assignment revoke update failed");
            ApiError::internal("failed to remove access assignment")
        })?;
        revoked_assignment = access_assignment_out_from_stored_row(row)?;
        break;
    }

    tx.commit().await.map_err(|e| {
        tracing::error!(error = %e, "access assignment transaction commit failed");
        ApiError::internal("failed to remove access assignment")
    })?;

    Ok(revoked_assignment.unwrap_or(AccessAssignmentOut {
        cursor_id: None,
        account_id,
        phone,
        role_id: resolved.role_id.clone(),
        legacy_role: resolved.legacy_role.clone(),
        created_at: None,
        scope: resolved.scope.clone(),
    }))
}

async fn assignment_cache_account_ids(
    auth: &AuthRuntime,
    account_id: Option<&str>,
    phone: Option<&str>,
) -> Vec<String> {
    let mut out = Vec::new();
    if let Some(account_id) = account_id
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToString::to_string)
    {
        out.push(account_id);
    }
    if let Some(cache_account_id) = best_effort_account_id_for_subject_phone(auth, phone).await {
        if !out.iter().any(|value| value == &cache_account_id) {
            out.push(cache_account_id);
        }
    }
    out
}

async fn load_role_strings_for_account_from_auth_store(
    auth: &AuthRuntime,
    account_id: &str,
) -> ApiResult<Vec<String>> {
    let phone = account_phone_for_account(auth, account_id).await?;
    let assignments = list_access_assignments_from_auth_store(
        auth,
        Some(account_id),
        phone.as_deref(),
        None,
        500,
        None,
        None,
    )
    .await?;
    let mut out = Vec::new();
    for assignment in assignments {
        if !out.iter().any(|value| value == &assignment.role_id) {
            out.push(assignment.role_id.clone());
        }
        if let Some(alias) =
            account_role_alias_for_access_assignment(&assignment.role_id, &assignment.scope)?
        {
            if !out.iter().any(|value| value == &alias) {
                out.push(alias);
            }
        }
    }
    Ok(out)
}

async fn load_access_assignment_operator_ids_for_account(
    auth: &AuthRuntime,
    account_id: &str,
) -> ApiResult<Vec<String>> {
    let phone = account_phone_for_account(auth, account_id).await?;
    let assignments = list_access_assignments_from_auth_store(
        auth,
        Some(account_id),
        phone.as_deref(),
        None,
        500,
        None,
        None,
    )
    .await?;
    let mut operator_ids = Vec::new();
    for assignment in assignments {
        let Some(operator_id) = assignment.scope.operator_id.as_deref() else {
            continue;
        };
        if !operator_ids.iter().any(|value| value == operator_id) {
            operator_ids.push(operator_id.to_string());
        }
    }
    Ok(operator_ids)
}

fn access_assignment_matches_filters(
    assignment: &AccessAssignmentOut,
    role_id_filter: Option<&str>,
    operator_id_filter: Option<&str>,
    official_account_id_filter: Option<&str>,
) -> bool {
    if let Some(role_id_filter) = role_id_filter {
        if assignment.role_id != role_id_filter {
            return false;
        }
    }
    if let Some(operator_id_filter) = operator_id_filter {
        if assignment.scope.operator_id.as_deref() != Some(operator_id_filter) {
            return false;
        }
    }
    if let Some(official_account_id_filter) = official_account_id_filter {
        if assignment.scope.official_account_id.as_deref() != Some(official_account_id_filter) {
            return false;
        }
    }
    true
}

async fn require_access_assignment_snapshot(
    state: &AppState,
    headers: &HeaderMap,
    required_permission: &'static str,
    forbidden_detail: &'static str,
) -> ApiResult<(
    AuthPrincipal,
    Vec<String>,
    Vec<String>,
    DerivedAccessSnapshot,
)> {
    if auth_test_overrides_enabled(state) {
        if let Some(principal) = test_override_principal(headers) {
            let roles = test_override_roles(headers).unwrap_or_default();
            let derived = derive_access_snapshot(&roles, &[]);
            if derived
                .permissions
                .iter()
                .any(|value| value == required_permission)
            {
                return Ok((principal, roles, Vec::new(), derived));
            }
            return Err(ApiError::new(StatusCode::FORBIDDEN, forbidden_detail));
        }
    }

    let principal = require_session_principal(state, headers).await?;
    let roles = fetch_roles_for_account(state, headers, &principal.account_id).await?;
    let operator_ids =
        coach_operator_ids_for_account_best_effort(state, &principal.account_id).await;
    let derived = derive_access_snapshot(&roles, &operator_ids);
    if !derived
        .permissions
        .iter()
        .any(|value| value == required_permission)
    {
        return Err(ApiError::new(StatusCode::FORBIDDEN, forbidden_detail));
    }
    Ok((principal, roles, operator_ids, derived))
}

fn canonical_access_assignment_idempotency_key(raw: Option<&str>) -> ApiResult<String> {
    let value = raw
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| ApiError::bad_request("Idempotency-Key required"))?;
    if value.len() > 128 {
        return Err(ApiError::bad_request("invalid Idempotency-Key"));
    }
    if !value
        .chars()
        .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '.' | '_' | ':' | '-'))
    {
        return Err(ApiError::bad_request("invalid Idempotency-Key"));
    }
    Ok(value.to_string())
}

fn access_assignment_headers_with_idempotency(headers: &HeaderMap) -> ApiResult<HeaderMap> {
    let mut out = headers.clone();
    let raw = headers
        .get("Idempotency-Key")
        .or_else(|| headers.get("idempotency-key"))
        .map(|value| {
            value
                .to_str()
                .map_err(|_| ApiError::bad_request("invalid Idempotency-Key"))
        })
        .transpose()?;
    let canonical = canonical_access_assignment_idempotency_key(raw)?;
    out.insert(
        "Idempotency-Key",
        HeaderValue::from_str(canonical.as_str())
            .map_err(|_| ApiError::bad_request("invalid Idempotency-Key"))?,
    );
    Ok(out)
}

pub async fn admin_access_assignments_list(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<AccessAssignmentsListQuery>,
) -> ApiResult<Response> {
    let (principal, _roles, _operator_ids, _derived) = require_access_assignment_snapshot(
        &state,
        &headers,
        "access.assignment.read",
        "access assignment read required",
    )
    .await?;
    let (account_id, phone) =
        normalize_access_assignment_subject(q.account_id.as_deref(), q.phone.as_deref())?;
    let role_id_filter = q
        .role_id
        .as_deref()
        .map(normalize_access_assignment_role_id)
        .transpose()?;
    let operator_id_filter = normalize_access_assignment_operator_scope(q.operator_id.as_deref())?;
    let official_account_id_filter =
        normalize_access_assignment_official_scope(q.official_account_id.as_deref())?;
    enforce_admin_role_read_rate_limit(&state, &headers, &principal, "access_assignment_list")
        .await?;
    let auth = require_auth_runtime(&state)?;
    let before_cursor = normalize_before_cursor(q.before_created_at.as_deref(), q.before_id);
    let mut assignments = list_access_assignments_from_auth_store(
        auth,
        account_id.as_deref(),
        phone.as_deref(),
        None,
        normalize_access_assignment_limit(q.limit),
        before_cursor
            .as_ref()
            .map(|(created_at, _)| created_at.as_str()),
        before_cursor.as_ref().map(|(_, before_id)| *before_id),
    )
    .await?;
    assignments.retain(|assignment| {
        access_assignment_matches_filters(
            assignment,
            role_id_filter.as_deref(),
            operator_id_filter.as_deref(),
            official_account_id_filter.as_deref(),
        )
    });

    audit_admin_role_read_event(
        "access_assignment_list",
        "applied",
        Some(&principal),
        role_id_filter.as_deref(),
        account_id.as_deref(),
        phone.as_deref(),
        None,
    );
    Ok(json_no_store_payload(AccessAssignmentsListOut {
        assignments,
    }))
}

async fn mutate_access_assignment(
    state: &AppState,
    headers: &HeaderMap,
    method: Method,
    body: AccessAssignmentMutationIn,
) -> ApiResult<Response> {
    let operation = match method {
        Method::POST => "access_assignment_add",
        Method::DELETE => "access_assignment_remove",
        _ => "access_assignment_mutate",
    };
    let (principal, _roles, _operator_ids, _derived) = require_access_assignment_snapshot(
        state,
        headers,
        "access.assignment.write",
        "access assignment write required",
    )
    .await?;
    enforce_admin_role_mutation_rate_limit(state, headers, &principal, operation).await?;
    let (account_id, phone) =
        normalize_access_assignment_subject(body.account_id.as_deref(), body.phone.as_deref())?;
    let resolved = resolved_access_assignment_from_role_id(&body.role_id, body.scope.as_ref())?;
    let _ = access_assignment_headers_with_idempotency(headers)?;
    let auth = require_auth_runtime(state)?;
    let assignment = match method {
        Method::POST => {
            grant_access_assignment_in_auth_store(
                auth,
                &AccessAssignmentActor::session(&principal.account_id),
                account_id.clone(),
                phone.clone(),
                &resolved,
            )
            .await?
        }
        Method::DELETE => {
            revoke_access_assignment_in_auth_store(
                auth,
                &AccessAssignmentActor::session(&principal.account_id),
                account_id.clone(),
                phone.clone(),
                &resolved,
            )
            .await?
        }
        _ => {
            return Err(ApiError::bad_request(
                "unsupported access assignment mutation",
            ))
        }
    };

    for cache_account_id in
        assignment_cache_account_ids(auth, account_id.as_deref(), phone.as_deref()).await
    {
        state.forget_roles_for_account(&cache_account_id).await;
    }

    audit_admin_role_mutation_event(
        operation,
        "applied",
        Some(&principal),
        Some(assignment.legacy_role.as_str()),
        account_id.as_deref(),
        phone.as_deref(),
        None,
    );
    Ok(json_no_store_payload(AccessAssignmentMutationOut {
        ok: true,
        assignment,
    }))
}

fn require_internal_access_assignment_service_id(headers: &HeaderMap) -> ApiResult<String> {
    let service_id = headers
        .get(INTERNAL_SERVICE_ID_HEADER)
        .and_then(|value| value.to_str().ok())
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(|value| value.to_ascii_lowercase())
        .ok_or_else(|| ApiError::new(StatusCode::UNAUTHORIZED, "internal identity required"))?;
    Ok(service_id)
}

fn audit_internal_access_assignment_event(
    operation: &'static str,
    outcome: &'static str,
    service_id: &str,
    role_id: Option<&str>,
    account_id: Option<&str>,
    phone: Option<&str>,
    reason: Option<&str>,
) {
    let target_role = role_id.unwrap_or("").trim().to_ascii_lowercase();
    let target_account_hash = account_id
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(hash_prefix)
        .unwrap_or_default();
    let target_phone_hash = phone
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(hash_prefix)
        .unwrap_or_default();
    let reason = reason.unwrap_or("");
    if matches!(outcome, "blocked" | "failed") {
        tracing::warn!(
            security_event = "internal_access_assignment",
            operation,
            outcome,
            reason,
            service_id,
            target_role,
            target_account_hash,
            target_phone_hash,
            "internal access assignment security event"
        );
    } else {
        tracing::info!(
            security_event = "internal_access_assignment",
            operation,
            outcome,
            service_id,
            target_role,
            target_account_hash,
            target_phone_hash,
            "internal access assignment security event"
        );
    }
}

