fn normalize_coach_operator_ids(values: impl IntoIterator<Item = String>) -> Vec<String> {
    let mut out = Vec::new();
    for raw in values {
        let normalized = raw.trim().to_ascii_lowercase();
        if normalized.is_empty() || normalized.len() > 128 {
            continue;
        }
        if !normalized.chars().all(|ch| {
            ch.is_ascii_lowercase() || ch.is_ascii_digit() || matches!(ch, '_' | '-' | '.')
        }) {
            continue;
        }
        if !out.iter().any(|entry| entry == &normalized) {
            out.push(normalized);
        }
    }
    out.sort();
    out
}

async fn load_coach_operator_ids_for_account(
    state: &AppState,
    account_id: &str,
) -> ApiResult<Vec<String>> {
    let auth = require_auth_runtime(state)?;
    let account_id = account_id.trim();
    if account_id.is_empty() {
        return Ok(Vec::new());
    }

    let operator_ids: Vec<String> = sqlx::query_scalar(
        "WITH operator_sources AS ( \
            SELECT jsonb_array_elements_text(operator_ids) AS operator_id \
            FROM auth_coach_catalog_source_artifacts \
            WHERE created_by_account_id = $1 \
            UNION ALL \
            SELECT jsonb_array_elements_text(operator_ids) AS operator_id \
            FROM auth_coach_catalog_import_run_saved_views \
            WHERE account_id = $1 \
            UNION ALL \
            SELECT jsonb_array_elements_text(operator_ids) AS operator_id \
            FROM auth_coach_catalog_import_run_issue_saved_views \
            WHERE account_id = $1 \
            UNION ALL \
            SELECT jsonb_array_elements_text(COALESCE(artifact.operator_ids, latest_run.operator_ids, '[]'::jsonb)) AS operator_id \
            FROM auth_coach_catalog_import_configs config \
            LEFT JOIN auth_coach_catalog_source_artifacts artifact \
                ON artifact.artifact_id = config.source_artifact_id \
            LEFT JOIN LATERAL ( \
                SELECT import_run.operator_ids \
                FROM auth_coach_catalog_import_runs import_run \
                WHERE import_run.feed_kind = config.feed_kind \
                  AND import_run.source_kind = config.source_kind \
                  AND import_run.feed_locator = config.feed_locator \
                ORDER BY import_run.started_at DESC, import_run.import_run_id DESC \
                LIMIT 1 \
            ) latest_run ON TRUE \
            WHERE config.updated_by_account_id = $1 \
        ) \
        SELECT operator_id \
        FROM operator_sources \
        WHERE operator_id IS NOT NULL AND LENGTH(BTRIM(operator_id)) > 0",
    )
    .bind(account_id)
    .fetch_all(auth.pool())
    .await
    .map_err(|error| {
        tracing::error!(
            error = %error,
            account_id_hash = %hash_prefix(account_id),
            "coach operator scope lookup failed"
        );
        ApiError::internal("coach operator scope unavailable")
    })?;

    Ok(normalize_coach_operator_ids(operator_ids))
}

pub(crate) async fn coach_operator_ids_for_account_best_effort(
    state: &AppState,
    account_id: &str,
) -> Vec<String> {
    let mut operator_ids = Vec::new();
    if let Some(auth) = state.auth.as_ref() {
        match load_access_assignment_operator_ids_for_account(auth, account_id).await {
            Ok(ids) => operator_ids.extend(ids),
            Err(err) => {
                tracing::warn!(
                    account_id_hash = %hash_prefix(account_id),
                    detail = %err.detail,
                    "access assignment operator scope unavailable; continuing without auth operator_ids"
                );
            }
        }
    }
    match load_coach_operator_ids_for_account(state, account_id).await {
        Ok(ids) => {
            operator_ids.extend(ids);
            normalize_coach_operator_ids(operator_ids)
        }
        Err(err) => {
            if operator_ids.is_empty() {
                tracing::warn!(
                    account_id_hash = %hash_prefix(account_id),
                    detail = %err.detail,
                    "coach operator scope unavailable; continuing without operator_ids"
                );
            }
            normalize_coach_operator_ids(operator_ids)
        }
    }
}

