fn normalize_official_service_session_status(
    raw: &str,
    context: &'static str,
    failure_detail: &'static str,
) -> ApiResult<String> {
    let normalized = raw.trim().to_ascii_lowercase();
    if matches!(normalized.as_str(), "open" | "closed") {
        return Ok(normalized);
    }
    tracing::error!(
        status = raw.trim(),
        context,
        "invalid official service session status"
    );
    Err(ApiError::internal(failure_detail))
}

