const OFFICIAL_NOTIFICATION_IDS_MAX: usize = 100;
const USER_ACTIVITY_METADATA_MAX_BYTES: usize = 4096;
const PLATFORM_FEATURE_METADATA_MAX_BYTES: usize = 4096;

