pub async fn admin_official_account_owners_list(
    Path(account_id_raw): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<OfficialOwnersQuery>,
) -> ApiResult<Response> {
    let official_id = normalize_official_account_id(&account_id_raw)?;
    let role = official_owner_role_for(&official_id);
    let test_principal_override_active = auth_test_principal_override_active(&state, &headers);
    if !test_principal_override_active {
        let _ = require_auth_runtime(&state)?;
    }
    let principal = match require_official_scope_principal(&state, &headers, &official_id).await {
        Ok(principal) => principal,
        Err(err) => {
            audit_admin_role_read_event(
                "official_owner_list",
                "blocked",
                None,
                Some(&role),
                None,
                None,
                Some(err.detail.as_str()),
            );
            return Err(err);
        }
    };
    if let Err(err) =
        enforce_admin_role_read_rate_limit(&state, &headers, &principal, "official_owner_list")
            .await
    {
        audit_admin_role_read_event(
            "official_owner_list",
            "blocked",
            Some(&principal),
            Some(&role),
            None,
            None,
            Some(err.detail.as_str()),
        );
        return Err(err);
    }

    let official_exists_override = auth_test_official_exists_override(&state, &headers);
    if let Some(exists) = official_exists_override {
        if !exists {
            let err = ApiError::new(StatusCode::NOT_FOUND, "official account not found");
            audit_admin_role_read_event(
                "official_owner_list",
                "failed",
                Some(&principal),
                Some(&role),
                None,
                None,
                Some(err.detail.as_str()),
            );
            return Err(err);
        }
    } else {
        let auth = require_auth_runtime(&state)?;
        if !official_account_exists(auth, &official_id)
            .await
            .map_err(|e| {
                tracing::error!(
                    error = %e,
                    official_id_hash = %hash_prefix(&official_id),
                    "official account exists lookup failed"
                );
                ApiError::internal("failed to load official owners")
            })?
        {
            let err = ApiError::new(StatusCode::NOT_FOUND, "official account not found");
            audit_admin_role_read_event(
                "official_owner_list",
                "failed",
                Some(&principal),
                Some(&role),
                None,
                None,
                Some(err.detail.as_str()),
            );
            return Err(err);
        }
    }

    let limit = normalize_official_owner_limit(q.limit);
    let before_cursor = normalize_before_cursor(q.before_created_at.as_deref(), q.before_id);
    let assignments = match list_official_owner_assignments(
        &state,
        &headers,
        Some("official.account_owner"),
        limit,
        before_cursor
            .as_ref()
            .map(|(created_at, _)| created_at.as_str()),
        before_cursor.as_ref().map(|(_, before_id)| *before_id),
    )
    .await
    {
        Ok(assignments) => assignments,
        Err(err) => {
            audit_admin_role_read_event(
                "official_owner_list",
                "failed",
                Some(&principal),
                Some(&role),
                None,
                None,
                Some(err.detail.as_str()),
            );
            return Err(err);
        }
    };
    let owners = assignments
        .iter()
        .filter_map(|assignment| official_owner_entry_from_assignment(assignment, &official_id))
        .collect();

    audit_admin_role_read_event(
        "official_owner_list",
        "applied",
        Some(&principal),
        Some(&role),
        None,
        None,
        None,
    );
    Ok(json_no_store(official_owner_list_value(owners)))
}

pub async fn admin_official_account_owners_add(
    Path(account_id_raw): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(body): Json<OfficialOwnerUpsertIn>,
) -> ApiResult<Response> {
    let official_id = normalize_official_account_id(&account_id_raw)?;
    let role = official_owner_role_for(&official_id);
    let test_principal_override_active = auth_test_principal_override_active(&state, &headers);
    if !test_principal_override_active {
        let _ = require_auth_runtime(&state)?;
    }
    let principal = match require_official_scope_principal(&state, &headers, &official_id).await {
        Ok(principal) => principal,
        Err(err) => {
            audit_admin_role_mutation_event(
                "official_owner_add",
                "blocked",
                None,
                Some(&role),
                body.account_id.as_deref(),
                body.phone.as_deref(),
                Some(err.detail.as_str()),
            );
            return Err(err);
        }
    };
    if let Err(err) =
        enforce_admin_role_mutation_rate_limit(&state, &headers, &principal, "official_owner_add")
            .await
    {
        audit_admin_role_mutation_event(
            "official_owner_add",
            "blocked",
            Some(&principal),
            Some(&role),
            body.account_id.as_deref(),
            body.phone.as_deref(),
            Some(err.detail.as_str()),
        );
        return Err(err);
    }

    let official_exists_override = auth_test_official_exists_override(&state, &headers);
    if let Some(exists) = official_exists_override {
        if !exists {
            let err = ApiError::new(StatusCode::NOT_FOUND, "official account not found");
            audit_admin_role_mutation_event(
                "official_owner_add",
                "failed",
                Some(&principal),
                Some(&role),
                body.account_id.as_deref(),
                body.phone.as_deref(),
                Some(err.detail.as_str()),
            );
            return Err(err);
        }
    } else {
        let auth = require_auth_runtime(&state)?;
        ensure_seed_official_catalog(auth).await.map_err(|e| {
            tracing::error!(
                error = %e,
                official_id_hash = %hash_prefix(&official_id),
                "official catalog seed failed"
            );
            ApiError::internal("failed to add official owner")
        })?;
        if !official_account_exists(auth, &official_id)
            .await
            .map_err(|e| {
                tracing::error!(
                    error = %e,
                    official_id_hash = %hash_prefix(&official_id),
                    "official account exists lookup failed"
                );
                ApiError::internal("failed to add official owner")
            })?
        {
            let err = ApiError::new(StatusCode::NOT_FOUND, "official account not found");
            audit_admin_role_mutation_event(
                "official_owner_add",
                "failed",
                Some(&principal),
                Some(&role),
                body.account_id.as_deref(),
                body.phone.as_deref(),
                Some(err.detail.as_str()),
            );
            return Err(err);
        }
    }

    let account_id = normalize_owner_account_id(body.account_id.as_deref())?;
    let phone = normalize_owner_phone(body.phone.as_deref())?;
    if account_id.is_none() && phone.is_none() {
        let err = ApiError::bad_request("account_id or phone required");
        audit_admin_role_mutation_event(
            "official_owner_add",
            "blocked",
            Some(&principal),
            Some(&role),
            body.account_id.as_deref(),
            body.phone.as_deref(),
            Some(err.detail.as_str()),
        );
        return Err(err);
    }
    let (idempotency_key, idempotency_mode) = official_owner_mutation_idempotency_key(
        &headers,
        &principal,
        &official_id,
        "add",
        &role,
        account_id.as_deref(),
        phone.as_deref(),
    )?;
    let _ = canonical_access_assignment_idempotency_key(Some(&idempotency_key))
        .map_err(|_| ApiError::internal("failed to add official owner"))?;
    let resolved = resolved_access_assignment_from_role_id(
        "official.account_owner",
        Some(&crate::models::AccessAssignmentScopeIn {
            platform: Some(false),
            operator_id: None,
            official_account_id: Some(official_id.clone()),
        }),
    )?;
    let auth = require_auth_runtime(&state)?;
    if let Err(err) = grant_access_assignment_in_auth_store(
        auth,
        &AccessAssignmentActor::session(&principal.account_id),
        account_id.clone(),
        phone.clone(),
        &resolved,
    )
    .await
    {
        let reason = format!("{idempotency_mode}: {}", err.detail);
        audit_admin_role_mutation_event(
            "official_owner_add",
            "failed",
            Some(&principal),
            Some(&role),
            account_id.as_deref(),
            phone.as_deref(),
            Some(reason.as_str()),
        );
        return Err(err);
    }

    audit_admin_role_mutation_event(
        "official_owner_add",
        "applied",
        Some(&principal),
        Some(&role),
        account_id.as_deref(),
        phone.as_deref(),
        None,
    );
    for cache_account_id in
        assignment_cache_account_ids(auth, account_id.as_deref(), phone.as_deref()).await
    {
        state.forget_roles_for_account(&cache_account_id).await;
    }
    Ok(json_no_store(official_admin_mutation_value()))
}

pub async fn admin_official_account_owners_remove(
    Path(account_id_raw): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(body): Json<OfficialOwnerUpsertIn>,
) -> ApiResult<Response> {
    let official_id = normalize_official_account_id(&account_id_raw)?;
    let role = official_owner_role_for(&official_id);
    let test_principal_override_active = auth_test_principal_override_active(&state, &headers);
    if !test_principal_override_active {
        let _ = require_auth_runtime(&state)?;
    }
    let principal = match require_official_scope_principal(&state, &headers, &official_id).await {
        Ok(principal) => principal,
        Err(err) => {
            audit_admin_role_mutation_event(
                "official_owner_remove",
                "blocked",
                None,
                Some(&role),
                body.account_id.as_deref(),
                body.phone.as_deref(),
                Some(err.detail.as_str()),
            );
            return Err(err);
        }
    };
    if let Err(err) = enforce_admin_role_mutation_rate_limit(
        &state,
        &headers,
        &principal,
        "official_owner_remove",
    )
    .await
    {
        audit_admin_role_mutation_event(
            "official_owner_remove",
            "blocked",
            Some(&principal),
            Some(&role),
            body.account_id.as_deref(),
            body.phone.as_deref(),
            Some(err.detail.as_str()),
        );
        return Err(err);
    }

    let official_exists_override = auth_test_official_exists_override(&state, &headers);
    if let Some(exists) = official_exists_override {
        if !exists {
            let err = ApiError::new(StatusCode::NOT_FOUND, "official account not found");
            audit_admin_role_mutation_event(
                "official_owner_remove",
                "failed",
                Some(&principal),
                Some(&role),
                body.account_id.as_deref(),
                body.phone.as_deref(),
                Some(err.detail.as_str()),
            );
            return Err(err);
        }
    } else {
        let auth = require_auth_runtime(&state)?;
        ensure_seed_official_catalog(auth).await.map_err(|e| {
            tracing::error!(
                error = %e,
                official_id_hash = %hash_prefix(&official_id),
                "official catalog seed failed"
            );
            ApiError::internal("failed to remove official owner")
        })?;
        if !official_account_exists(auth, &official_id)
            .await
            .map_err(|e| {
                tracing::error!(
                    error = %e,
                    official_id_hash = %hash_prefix(&official_id),
                    "official account exists lookup failed"
                );
                ApiError::internal("failed to remove official owner")
            })?
        {
            let err = ApiError::new(StatusCode::NOT_FOUND, "official account not found");
            audit_admin_role_mutation_event(
                "official_owner_remove",
                "failed",
                Some(&principal),
                Some(&role),
                body.account_id.as_deref(),
                body.phone.as_deref(),
                Some(err.detail.as_str()),
            );
            return Err(err);
        }
    }

    let account_id = normalize_owner_account_id(body.account_id.as_deref())?;
    let phone = normalize_owner_phone(body.phone.as_deref())?;
    if account_id.is_none() && phone.is_none() {
        let err = ApiError::bad_request("account_id or phone required");
        audit_admin_role_mutation_event(
            "official_owner_remove",
            "blocked",
            Some(&principal),
            Some(&role),
            body.account_id.as_deref(),
            body.phone.as_deref(),
            Some(err.detail.as_str()),
        );
        return Err(err);
    }
    let (idempotency_key, idempotency_mode) = official_owner_mutation_idempotency_key(
        &headers,
        &principal,
        &official_id,
        "remove",
        &role,
        account_id.as_deref(),
        phone.as_deref(),
    )?;
    let _ = canonical_access_assignment_idempotency_key(Some(&idempotency_key))
        .map_err(|_| ApiError::internal("failed to remove official owner"))?;
    let resolved = resolved_access_assignment_from_role_id(
        "official.account_owner",
        Some(&crate::models::AccessAssignmentScopeIn {
            platform: Some(false),
            operator_id: None,
            official_account_id: Some(official_id.clone()),
        }),
    )?;
    let auth = require_auth_runtime(&state)?;
    if let Err(err) = revoke_access_assignment_in_auth_store(
        auth,
        &AccessAssignmentActor::session(&principal.account_id),
        account_id.clone(),
        phone.clone(),
        &resolved,
    )
    .await
    {
        let reason = format!("{idempotency_mode}: {}", err.detail);
        audit_admin_role_mutation_event(
            "official_owner_remove",
            "failed",
            Some(&principal),
            Some(&role),
            account_id.as_deref(),
            phone.as_deref(),
            Some(reason.as_str()),
        );
        return Err(err);
    }

    audit_admin_role_mutation_event(
        "official_owner_remove",
        "applied",
        Some(&principal),
        Some(&role),
        account_id.as_deref(),
        phone.as_deref(),
        None,
    );
    for cache_account_id in
        assignment_cache_account_ids(auth, account_id.as_deref(), phone.as_deref()).await
    {
        state.forget_roles_for_account(&cache_account_id).await;
    }
    Ok(json_no_store(official_admin_mutation_value()))
}

pub async fn admin_official_account_auto_replies_create(
    Path(account_id_raw): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(body): Json<OfficialAutoReplyCreateIn>,
) -> ApiResult<Response> {
    let official_id = normalize_official_account_id(&account_id_raw)?;
    let kind = normalize_official_auto_reply_kind(body.kind.as_deref())?;
    let mut keyword = normalize_official_auto_reply_keyword(body.keyword.as_deref());
    let text = normalize_official_auto_reply_text(body.text.as_deref())?;
    let enabled = body.enabled.unwrap_or(true);
    if kind == "keyword" && keyword.is_none() {
        return Err(ApiError::bad_request("keyword required for keyword rule"));
    }
    if kind != "keyword" {
        keyword = None;
    }

    let test_principal_override_active = auth_test_principal_override_active(&state, &headers);
    if !test_principal_override_active {
        let _ = require_auth_runtime(&state)?;
    }
    let principal = require_official_scope_principal(&state, &headers, &official_id).await?;
    let account_id = principal.account_id.trim();
    if account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }
    enforce_admin_role_mutation_rate_limit(
        &state,
        &headers,
        &principal,
        "official_auto_reply_create",
    )
    .await?;
    let _ = account_id;

    let official_exists_override = auth_test_official_exists_override(&state, &headers);
    if let Some(exists) = official_exists_override {
        if !exists {
            return Err(ApiError::new(
                StatusCode::NOT_FOUND,
                "official account not found",
            ));
        }
    } else {
        let auth = require_auth_runtime(&state)?;
        ensure_seed_official_catalog(auth).await.map_err(|e| {
            tracing::error!(
                error = %e,
                official_id_hash = %hash_prefix(&official_id),
                "official catalog seed failed"
            );
            ApiError::internal("failed to create auto reply")
        })?;
        if !official_account_exists(auth, &official_id)
            .await
            .map_err(|e| {
                tracing::error!(
                    error = %e,
                    official_id_hash = %hash_prefix(&official_id),
                    "official account exists lookup failed"
                );
                ApiError::internal("failed to create auto reply")
            })?
        {
            return Err(ApiError::new(
                StatusCode::NOT_FOUND,
                "official account not found",
            ));
        }
    }
    let auth = require_auth_runtime(&state)?;
    let (replay_limit_key, replay_window_secs, replay_mode) =
        official_auto_reply_mutation_replay_guard_key(
            &headers,
            &principal,
            OfficialAutoReplyMutationReplayPayload {
                official_id: &official_id,
                operation: "create",
                rule_id: None,
                kind: &kind,
                keyword: keyword.as_deref(),
                text: &text,
                enabled,
            },
        )?;

    let mut tx = auth.pool.begin().await.map_err(|e| {
        tracing::error!(
            error = %e,
            official_id_hash = %hash_prefix(&official_id),
            "official auto reply create tx begin failed"
        );
        ApiError::internal("failed to create auto reply")
    })?;
    if consume_rate_limit_once_in_tx(&mut tx, &replay_limit_key, replay_window_secs).await?
        == MutationReplayDecision::Replay
    {
        tracing::warn!(
            security_event = "admin_role_mutation_replay",
            operation = "official_auto_reply_create",
            mode = replay_mode,
            actor_account_hash = %hash_prefix(principal.account_id.trim()),
            official_id_hash = %hash_prefix(&official_id),
            kind = kind.as_str(),
            "blocked replayed official auto reply mutation"
        );
        return Ok(json_no_store(official_admin_mutation_value()));
    }

    let rows_affected = sqlx::query(
        "INSERT INTO auth_official_auto_replies (account_id,kind,keyword,text,enabled,created_at,updated_at) VALUES ($1,$2,$3,$4,$5,NOW(),NOW())",
    )
    .bind(&official_id)
    .bind(&kind)
    .bind(keyword.clone())
    .bind(&text)
    .bind(enabled)
    .execute(&mut *tx)
    .await
    .map_err(|e| {
        tracing::error!(
            error = %e,
            official_id_hash = %hash_prefix(&official_id),
            kind,
            "official auto reply create failed"
        );
        ApiError::internal("failed to create auto reply")
    })?
    .rows_affected();
    if rows_affected != 1 {
        return Err(ApiError::internal("failed to create auto reply"));
    }
    tx.commit().await.map_err(|e| {
        tracing::error!(
            error = %e,
            official_id_hash = %hash_prefix(&official_id),
            "official auto reply create tx commit failed"
        );
        ApiError::internal("failed to create auto reply")
    })?;

    Ok(json_no_store(official_admin_mutation_value()))
}

pub async fn admin_official_auto_reply_patch(
    Path(rule_id_raw): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(body): Json<OfficialAutoReplyPatchIn>,
) -> ApiResult<Response> {
    let rule_id = parse_positive_i64(&rule_id_raw, "rule id")?;
    let test_principal_override_active = auth_test_principal_override_active(&state, &headers);
    if !test_principal_override_active {
        let _ = require_auth_runtime(&state)?;
    }
    let (principal, roles) = require_official_roles_principal(&state, &headers).await?;
    let account_id = principal.account_id.trim();
    if account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }
    enforce_admin_role_mutation_rate_limit(
        &state,
        &headers,
        &principal,
        "official_auto_reply_patch",
    )
    .await?;
    let _ = account_id;

    if let Some(exists) = auth_test_auto_reply_exists_override(&state, &headers) {
        if !exists {
            return Err(ApiError::new(StatusCode::NOT_FOUND, "auto reply not found"));
        }
        let account_id_existing = test_override_auto_reply_account_id(&headers)?
            .unwrap_or_else(|| "shamell_pay".to_string());
        if !roles_can_manage_official(&roles, &account_id_existing) {
            return Err(ApiError::new(
                StatusCode::FORBIDDEN,
                "official owner scope required",
            ));
        }
        let existing_kind = "welcome".to_string();
        let existing_keyword: Option<String> = None;
        let kind = if body.kind.is_some() {
            normalize_official_auto_reply_kind(body.kind.as_deref())?
        } else {
            existing_kind
        };
        let keyword = if body.keyword.is_some() {
            normalize_official_auto_reply_keyword(body.keyword.as_deref())
        } else {
            existing_keyword
        };
        if kind == "keyword" && keyword.is_none() {
            return Err(ApiError::bad_request("keyword required for keyword rule"));
        }
        if body.text.is_some() {
            let _ = normalize_official_auto_reply_text(body.text.as_deref())?;
        }
        return Ok(json_no_store(json!({
            "ok": true,
        })));
    }

    let auth = require_auth_runtime(&state)?;
    let mut tx = auth.pool.begin().await.map_err(|e| {
        tracing::error!(
            error = %e,
            rule_id_hash = %hash_i64_prefix(rule_id),
            "official auto reply patch tx begin failed"
        );
        ApiError::internal("failed to update auto reply")
    })?;

    let existing = sqlx::query(
        "SELECT account_id,kind,keyword,text,enabled FROM auth_official_auto_replies WHERE id=$1 FOR UPDATE",
    )
    .bind(rule_id)
    .fetch_optional(&mut *tx)
    .await
    .map_err(|e| {
        tracing::error!(
            error = %e,
            rule_id_hash = %hash_i64_prefix(rule_id),
            "official auto reply lookup failed"
        );
        ApiError::internal("failed to update auto reply")
    })?
    .ok_or_else(|| ApiError::new(StatusCode::NOT_FOUND, "auto reply not found"))?;

    let account_id_existing: String = require_auth_text_column(
        existing.try_get("account_id"),
        "account_id",
        "admin_official_auto_reply_patch_existing_row",
        "failed to update auto reply",
    )?;
    if !roles_can_manage_official(&roles, &account_id_existing) {
        return Err(ApiError::new(
            StatusCode::FORBIDDEN,
            "official owner scope required",
        ));
    }
    let existing_kind: String = require_auth_optional_text_column(
        existing.try_get("kind"),
        "kind",
        "admin_official_auto_reply_patch_existing_row",
        "failed to update auto reply",
    )?
    .unwrap_or_else(|| "welcome".to_string());
    let existing_keyword: Option<String> = require_auth_optional_text_column(
        existing.try_get("keyword"),
        "keyword",
        "admin_official_auto_reply_patch_existing_row",
        "failed to update auto reply",
    )?;
    let existing_text: String = require_auth_text_column(
        existing.try_get("text"),
        "text",
        "admin_official_auto_reply_patch_existing_row",
        "failed to update auto reply",
    )?;
    let existing_enabled: bool = require_auth_db_column(
        existing.try_get("enabled"),
        "enabled",
        "admin_official_auto_reply_patch_existing_row",
        "failed to update auto reply",
    )?;

    let kind = if body.kind.is_some() {
        normalize_official_auto_reply_kind(body.kind.as_deref())?
    } else {
        existing_kind
    };
    let mut keyword = if body.keyword.is_some() {
        normalize_official_auto_reply_keyword(body.keyword.as_deref())
    } else {
        existing_keyword
    };
    if kind == "keyword" && keyword.is_none() {
        return Err(ApiError::bad_request("keyword required for keyword rule"));
    }
    if kind != "keyword" {
        keyword = None;
    }
    let text = if body.text.is_some() {
        normalize_official_auto_reply_text(body.text.as_deref())?
    } else {
        existing_text
    };
    let enabled = body.enabled.unwrap_or(existing_enabled);
    let (replay_limit_key, replay_window_secs, replay_mode) =
        official_auto_reply_mutation_replay_guard_key(
            &headers,
            &principal,
            OfficialAutoReplyMutationReplayPayload {
                official_id: &account_id_existing,
                operation: "patch",
                rule_id: Some(rule_id),
                kind: &kind,
                keyword: keyword.as_deref(),
                text: &text,
                enabled,
            },
        )?;
    if consume_rate_limit_once_in_tx(&mut tx, &replay_limit_key, replay_window_secs).await?
        == MutationReplayDecision::Replay
    {
        tracing::warn!(
            security_event = "admin_role_mutation_replay",
            operation = "official_auto_reply_patch",
            mode = replay_mode,
            actor_account_hash = %hash_prefix(principal.account_id.trim()),
            official_id_hash = %hash_prefix(&account_id_existing),
            rule_id_hash = %hash_i64_prefix(rule_id),
            kind = kind.as_str(),
            "blocked replayed official auto reply mutation"
        );
        return Ok(json_no_store(official_admin_mutation_value()));
    }

    let rows_affected = sqlx::query(
        "UPDATE auth_official_auto_replies SET kind=$2, keyword=$3, text=$4, enabled=$5, updated_at=NOW() WHERE id=$1",
    )
    .bind(rule_id)
    .bind(&kind)
    .bind(keyword.clone())
    .bind(&text)
    .bind(enabled)
    .execute(&mut *tx)
    .await
    .map_err(|e| {
        tracing::error!(
            error = %e,
            rule_id_hash = %hash_i64_prefix(rule_id),
            "official auto reply update failed"
        );
        ApiError::internal("failed to update auto reply")
    })?
    .rows_affected();
    if rows_affected != 1 {
        return Err(ApiError::internal("failed to update auto reply"));
    }
    tx.commit().await.map_err(|e| {
        tracing::error!(
            error = %e,
            rule_id_hash = %hash_i64_prefix(rule_id),
            "official auto reply patch tx commit failed"
        );
        ApiError::internal("failed to update auto reply")
    })?;

    Ok(json_no_store(official_admin_mutation_value()))
}

pub async fn admin_official_feeds_list(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<OfficialAdminFeedsQuery>,
) -> ApiResult<Response> {
    let auth = require_auth_runtime(&state)?;
    let (principal, roles) = require_official_roles_principal(&state, &headers).await?;
    let account_id = principal.account_id.trim();
    if account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }
    enforce_admin_role_read_rate_limit(&state, &headers, &principal, "official_feeds_list").await?;
    let _ = account_id;
    let (scope_all, scope_owned) = official_role_scopes(&roles);

    let account_filter = q
        .account_id
        .as_deref()
        .map(normalize_official_account_id)
        .transpose()?;
    if let Some(official_id) = account_filter.as_deref() {
        if !scope_all && !scope_owned.contains(official_id) {
            return Err(ApiError::new(
                StatusCode::FORBIDDEN,
                "official owner scope required",
            ));
        }
    }
    if let Some(official_id) = account_filter.as_deref() {
        if !official_account_exists(auth, official_id)
            .await
            .map_err(|e| {
                tracing::error!(
                    error = %e,
                    official_id_hash = %hash_prefix(official_id),
                    "official account exists lookup failed"
                );
                ApiError::internal("failed to load official feed")
            })?
        {
            return Err(ApiError::new(
                StatusCode::NOT_FOUND,
                "official account not found",
            ));
        }
    }

    let limit = normalize_official_feed_limit(q.limit);
    let before_cursor = normalize_before_cursor(q.before_ts.as_deref(), q.before_id);
    let rows = if let Some(official_id) = account_filter.as_deref() {
        if let Some((before_ts, before_id)) = before_cursor.as_ref() {
            sqlx::query(official_admin_feeds_sql(
                OfficialAdminFeedsScope::Account,
                true,
            ))
            .bind(official_id)
            .bind(before_ts)
            .bind(*before_id)
            .bind(limit)
            .fetch_all(&auth.pool)
            .await
        } else {
            sqlx::query(official_admin_feeds_sql(
                OfficialAdminFeedsScope::Account,
                false,
            ))
            .bind(official_id)
            .bind(limit)
            .fetch_all(&auth.pool)
            .await
        }
    } else if scope_all {
        if let Some((before_ts, before_id)) = before_cursor.as_ref() {
            sqlx::query(official_admin_feeds_sql(OfficialAdminFeedsScope::All, true))
                .bind(before_ts)
                .bind(*before_id)
                .bind(limit)
                .fetch_all(&auth.pool)
                .await
        } else {
            sqlx::query(official_admin_feeds_sql(
                OfficialAdminFeedsScope::All,
                false,
            ))
            .bind(limit)
            .fetch_all(&auth.pool)
            .await
        }
    } else {
        let mut owned: Vec<String> = scope_owned.into_iter().collect();
        if owned.is_empty() {
            return Ok(json_no_store(json!({ "items": [] })));
        }
        owned.sort();
        if let Some((before_ts, before_id)) = before_cursor.as_ref() {
            sqlx::query(official_admin_feeds_sql(
                OfficialAdminFeedsScope::OwnedSubset,
                true,
            ))
            .bind(&owned)
            .bind(before_ts)
            .bind(*before_id)
            .bind(limit)
            .fetch_all(&auth.pool)
            .await
        } else {
            sqlx::query(official_admin_feeds_sql(
                OfficialAdminFeedsScope::OwnedSubset,
                false,
            ))
            .bind(&owned)
            .bind(limit)
            .fetch_all(&auth.pool)
            .await
        }
    }
    .map_err(|e| {
        tracing::error!(error = %e, "official admin feeds lookup failed");
        ApiError::internal("failed to load official feed")
    })?;

    let include_account_id = account_filter.is_none();
    let mut items = Vec::with_capacity(rows.len());
    for row in rows {
        let id: i64 = require_auth_db_column(
            row.try_get("id"),
            "id",
            "admin_official_feeds_list_row_decode",
            "failed to load official feed",
        )?;
        let item_id: String = require_auth_text_column(
            row.try_get("item_id"),
            "item_id",
            "admin_official_feeds_list_row_decode",
            "failed to load official feed",
        )?;
        let account_id: Option<String> = if include_account_id {
            Some(require_auth_text_column(
                row.try_get("account_id"),
                "account_id",
                "admin_official_feeds_list_row_decode",
                "failed to load official feed",
            )?)
        } else {
            None
        };
        let title: String = require_auth_text_column(
            row.try_get("title"),
            "title",
            "admin_official_feeds_list_row_decode",
            "failed to load official feed",
        )?;
        let snippet: Option<String> = require_auth_optional_text_column(
            row.try_get("snippet"),
            "snippet",
            "admin_official_feeds_list_row_decode",
            "failed to load official feed",
        )?;
        let thumb_url: Option<String> = require_auth_optional_text_column(
            row.try_get("thumb_url"),
            "thumb_url",
            "admin_official_feeds_list_row_decode",
            "failed to load official feed",
        )?;
        let ts: Option<String> = require_auth_optional_text_column(
            row.try_get("ts"),
            "ts",
            "admin_official_feeds_list_row_decode",
            "failed to load official feed",
        )?;
        items.push(official_admin_feed_item_value(
            id,
            item_id,
            account_id,
            title,
            snippet,
            scrub_remote_media_url(thumb_url.as_deref()),
            ts,
        ));
    }

    Ok(json_no_store(json!({ "items": items })))
}

pub async fn admin_official_feeds_create(
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(body): Json<OfficialAdminFeedCreateIn>,
) -> ApiResult<Response> {
    let official_id = normalize_official_account_id(
        body.account_id
            .as_deref()
            .ok_or_else(|| ApiError::bad_request("account_id required"))?,
    )?;
    let item_id = normalize_official_feed_item_id(body.id.as_deref().or(body.item_id.as_deref()))?;
    let item_type =
        trim_to_non_empty(body.r#type.as_deref()).unwrap_or_else(|| "promo".to_string());
    let title = trim_to_non_empty(body.title.as_deref());
    let snippet = trim_to_non_empty(body.snippet.as_deref());
    if title.is_none() && snippet.is_none() {
        return Err(ApiError::bad_request("title or snippet required"));
    }
    let title = title.or_else(|| snippet.clone()).unwrap_or_default();
    if title.len() > 220 {
        return Err(ApiError::bad_request("title too long"));
    }
    let snippet = snippet.map(|v| {
        if v.len() > 4000 {
            v.chars().take(4000).collect()
        } else {
            v
        }
    });
    let thumb_url = normalize_remote_media_url(body.thumb_url.as_deref(), "thumb_url")?;

    let auth = require_auth_runtime(&state)?;
    let principal = require_official_scope_principal(&state, &headers, &official_id).await?;
    let account_id = principal.account_id.trim();
    if account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }
    enforce_admin_role_mutation_rate_limit(&state, &headers, &principal, "official_feed_create")
        .await?;
    let _ = account_id;

    ensure_seed_official_catalog(auth).await.map_err(|e| {
        tracing::error!(
            error = %e,
            official_id_hash = %hash_prefix(&official_id),
            "official catalog seed failed"
        );
        ApiError::internal("failed to create feed item")
    })?;
    if !official_account_exists(auth, &official_id)
        .await
        .map_err(|e| {
            tracing::error!(
                error = %e,
                official_id_hash = %hash_prefix(&official_id),
                "official account exists lookup failed"
            );
            ApiError::internal("failed to create feed item")
        })?
    {
        return Err(ApiError::new(
            StatusCode::NOT_FOUND,
            "official account not found",
        ));
    }

    let (replay_limit_key, replay_window_secs, replay_mode) =
        official_feed_create_replay_guard_key(
            &headers,
            &principal,
            &official_id,
            &item_id,
            &title,
            snippet.as_deref(),
            thumb_url.as_deref(),
        )?;
    let mut tx = auth.pool.begin().await.map_err(|e| {
        tracing::error!(
            error = %e,
            official_id_hash = %hash_prefix(&official_id),
            item_id_hash = %hash_prefix(&item_id),
            "official feed create tx begin failed"
        );
        ApiError::internal("failed to create feed item")
    })?;
    if consume_rate_limit_once_in_tx(&mut tx, &replay_limit_key, replay_window_secs).await?
        == MutationReplayDecision::Replay
    {
        tracing::warn!(
            security_event = "admin_role_mutation_replay",
            operation = "official_feed_create",
            mode = replay_mode,
            actor_account_hash = %hash_prefix(principal.account_id.trim()),
            official_id_hash = %hash_prefix(&official_id),
            item_id_hash = %hash_prefix(&item_id),
            "blocked replayed official feed create mutation"
        );
        return Ok(json_no_store(official_admin_mutation_value()));
    }

    let rows_affected = sqlx::query(official_admin_feed_upsert_sql())
        .bind(&official_id)
        .bind(&item_id)
        .bind(&title)
        .bind(snippet.clone())
        .bind(thumb_url.clone())
        .execute(&mut *tx)
        .await
        .map_err(|e| {
            tracing::error!(
                error = %e,
                official_id_hash = %hash_prefix(&official_id),
                item_id_hash = %hash_prefix(&item_id),
                "official feed create failed"
            );
            ApiError::internal("failed to create feed item")
        })?
        .rows_affected();
    if rows_affected == 0 {
        tracing::warn!(
            security_event = "official_feed_item_conflict",
            outcome = "blocked",
            official_id_hash = %hash_prefix(&official_id),
            item_id_hash = %hash_prefix(&item_id),
            "official feed item id already exists for another account"
        );
        return Err(ApiError::new(
            StatusCode::CONFLICT,
            "feed item id already exists",
        ));
    }
    if rows_affected != 1 {
        return Err(ApiError::internal("failed to create feed item"));
    }
    tx.commit().await.map_err(|e| {
        tracing::error!(
            error = %e,
            official_id_hash = %hash_prefix(&official_id),
            item_id_hash = %hash_prefix(&item_id),
            "official feed create tx commit failed"
        );
        ApiError::internal("failed to create feed item")
    })?;

    let _ = item_type;
    Ok(json_no_store(official_admin_mutation_value()))
}

pub async fn admin_official_service_inbox_list(
    Path(account_id_raw): Path<String>,
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<OfficialServiceInboxQuery>,
) -> ApiResult<Response> {
    let official_id = normalize_official_account_id(&account_id_raw)?;
    let test_principal_override_active = auth_test_principal_override_active(&state, &headers);
    if !test_principal_override_active {
        let _ = require_auth_runtime(&state)?;
    }
    let principal = require_official_scope_principal(&state, &headers, &official_id).await?;
    let account_id = principal.account_id.trim();
    if account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }
    enforce_admin_role_read_rate_limit(&state, &headers, &principal, "official_service_inbox_list")
        .await?;

    let official_exists_override = auth_test_official_exists_override(&state, &headers);
    if let Some(exists) = official_exists_override {
        if !exists {
            return Err(ApiError::new(
                StatusCode::NOT_FOUND,
                "official account not found",
            ));
        }
        return Ok(json_no_store(json!({ "sessions": [] })));
    }

    let auth = require_auth_runtime(&state)?;
    if !official_account_exists(auth, &official_id)
        .await
        .map_err(|e| {
            tracing::error!(
                error = %e,
                official_id_hash = %hash_prefix(&official_id),
                "official account exists lookup failed"
            );
            ApiError::internal("failed to load service inbox")
        })?
    {
        return Err(ApiError::new(
            StatusCode::NOT_FOUND,
            "official account not found",
        ));
    }

    let limit = normalize_official_service_inbox_limit(q.limit);
    let before_cursor = normalize_before_cursor(q.before_ts.as_deref(), q.before_id);
    let rows = if let Some((before_ts, before_id)) = before_cursor.as_ref() {
        sqlx::query(official_service_inbox_sql(true))
            .bind(&official_id)
            .bind(before_ts)
            .bind(*before_id)
            .bind(limit)
            .fetch_all(&auth.pool)
            .await
    } else {
        sqlx::query(official_service_inbox_sql(false))
            .bind(&official_id)
            .bind(limit)
            .fetch_all(&auth.pool)
            .await
    }
    .map_err(|e| {
        tracing::error!(
            error = %e,
            official_id_hash = %hash_prefix(&official_id),
            "official service inbox lookup failed"
        );
        ApiError::internal("failed to load service inbox")
    })?;

    let mut sessions = Vec::with_capacity(rows.len());
    for row in rows {
        let id: i64 = require_auth_db_column(
            row.try_get("id"),
            "id",
            "official_service_inbox_row_decode",
            "failed to load service inbox",
        )?;
        let customer_phone = require_auth_optional_text_column(
            row.try_get("customer_phone"),
            "customer_phone",
            "official_service_inbox_row_decode",
            "failed to load service inbox",
        )?
        .unwrap_or_default();
        let chat_peer_id = require_auth_optional_text_column(
            row.try_get("chat_peer_id"),
            "chat_peer_id",
            "official_service_inbox_row_decode",
            "failed to load service inbox",
        )?;
        let status = normalize_official_service_session_status(
            &require_auth_text_column(
                row.try_get("status"),
                "status",
                "official_service_inbox_row_decode",
                "failed to load service inbox",
            )?,
            "official_service_inbox_row_decode",
            "failed to load service inbox",
        )?;
        let last_message_ts = require_auth_optional_text_column(
            row.try_get("last_message_ts"),
            "last_message_ts",
            "official_service_inbox_row_decode",
            "failed to load service inbox",
        )?;
        let cursor_ts = require_auth_optional_text_column(
            row.try_get("cursor_ts"),
            "cursor_ts",
            "official_service_inbox_row_decode",
            "failed to load service inbox",
        )?;
        let unread_by_operator: bool = require_auth_db_column(
            row.try_get("unread_by_operator"),
            "unread_by_operator",
            "official_service_inbox_row_decode",
            "failed to load service inbox",
        )?;
        sessions.push(official_service_session_value(
            id,
            customer_phone,
            chat_peer_id,
            status,
            last_message_ts,
            cursor_ts,
            unread_by_operator,
        ));
    }

    Ok(json_no_store(json!({ "sessions": sessions })))
}

fn official_service_inbox_sql(paged: bool) -> &'static str {
    if paged {
        "SELECT id,account_id,customer_phone,chat_peer_id,status,last_message_ts::text AS last_message_ts,COALESCE(last_message_ts, created_at)::text AS cursor_ts,unread_by_operator \
         FROM auth_official_service_sessions \
         WHERE account_id=$1 \
           AND (COALESCE(last_message_ts, created_at) < $2::timestamptz OR (COALESCE(last_message_ts, created_at) = $2::timestamptz AND id < $3)) \
         ORDER BY COALESCE(last_message_ts, created_at) DESC, id DESC \
         LIMIT $4"
    } else {
        "SELECT id,account_id,customer_phone,chat_peer_id,status,last_message_ts::text AS last_message_ts,COALESCE(last_message_ts, created_at)::text AS cursor_ts,unread_by_operator \
         FROM auth_official_service_sessions \
         WHERE account_id=$1 \
         ORDER BY COALESCE(last_message_ts, created_at) DESC, id DESC \
         LIMIT $2"
    }
}

fn official_service_session_value(
    id: i64,
    customer_phone: String,
    chat_peer_id: Option<String>,
    status: String,
    last_message_ts: Option<String>,
    cursor_ts: Option<String>,
    unread_by_operator: bool,
) -> Value {
    json!({
        "id": id,
        "customer_phone": customer_phone,
        "chat_peer_id": chat_peer_id,
        "status": status,
        "last_message_ts": last_message_ts,
        "cursor_ts": cursor_ts,
        "unread_by_operator": unread_by_operator,
    })
}

pub async fn admin_official_service_inbox_mark_read(
    Path((account_id_raw, session_id_raw)): Path<(String, String)>,
    State(state): State<AppState>,
    headers: HeaderMap,
) -> ApiResult<Response> {
    let official_id = normalize_official_account_id(&account_id_raw)?;
    let session_id = parse_positive_i64(&session_id_raw, "session id")?;
    let test_principal_override_active = auth_test_principal_override_active(&state, &headers);
    if !test_principal_override_active {
        let _ = require_auth_runtime(&state)?;
    }
    let principal = require_official_scope_principal(&state, &headers, &official_id).await?;
    let account_id = principal.account_id.trim();
    if account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }
    enforce_admin_role_mutation_rate_limit(
        &state,
        &headers,
        &principal,
        "official_service_inbox_mark_read",
    )
    .await?;
    let _ = account_id;

    let official_exists_override = auth_test_official_exists_override(&state, &headers);
    if let Some(exists) = official_exists_override {
        if !exists {
            return Err(ApiError::new(
                StatusCode::NOT_FOUND,
                "official account not found",
            ));
        }
    }

    let auth = require_auth_runtime(&state)?;
    let (replay_limit_key, replay_window_secs, replay_mode) =
        official_service_session_mutation_replay_guard_key(
            &headers,
            &principal,
            &official_id,
            session_id,
            "mark_read",
        )?;
    let mut tx = auth.pool.begin().await.map_err(|e| {
        tracing::error!(
            error = %e,
            official_id_hash = %hash_prefix(&official_id),
            session_id_hash = %hash_i64_prefix(session_id),
            "official service inbox mark-read tx begin failed"
        );
        ApiError::internal("failed to update session")
    })?;
    if consume_rate_limit_once_in_tx(&mut tx, &replay_limit_key, replay_window_secs).await?
        == MutationReplayDecision::Replay
    {
        tracing::warn!(
            security_event = "admin_role_mutation_replay",
            operation = "official_service_inbox_mark_read",
            mode = replay_mode,
            actor_account_hash = %hash_prefix(principal.account_id.trim()),
            official_id_hash = %hash_prefix(&official_id),
            session_id_hash = %hash_i64_prefix(session_id),
            "blocked replayed official service session mutation"
        );
        return Ok(json_no_store(json!({ "ok": true })));
    }

    let updated = sqlx::query(
        "UPDATE auth_official_service_sessions SET unread_by_operator=FALSE, updated_at=NOW() WHERE id=$1 AND account_id=$2",
    )
    .bind(session_id)
    .bind(&official_id)
    .execute(&mut *tx)
    .await
    .map_err(|e| {
        tracing::error!(
            error = %e,
            official_id_hash = %hash_prefix(&official_id),
            session_id_hash = %hash_i64_prefix(session_id),
            "official service inbox mark-read failed"
        );
        ApiError::internal("failed to update session")
    })?
    .rows_affected();
    if updated == 0 {
        return Err(ApiError::new(StatusCode::NOT_FOUND, "session not found"));
    }
    tx.commit().await.map_err(|e| {
        tracing::error!(
            error = %e,
            official_id_hash = %hash_prefix(&official_id),
            session_id_hash = %hash_i64_prefix(session_id),
            "official service inbox mark-read tx commit failed"
        );
        ApiError::internal("failed to update session")
    })?;

    Ok(json_no_store(json!({ "ok": true })))
}

