pub async fn admin_user_activity(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<AdminUserActivityQuery>,
) -> ApiResult<Response> {
    let auth = require_auth_runtime(&state)?;
    let principal = require_session_principal(&state, &headers).await?;
    let roles = fetch_roles_for_account(&state, &headers, &principal.account_id).await?;
    let operator_ids =
        coach_operator_ids_for_account_best_effort(&state, &principal.account_id).await;
    let derived = derive_access_snapshot(&roles, &operator_ids);
    if !derived.is_superadmin {
        return Err(ApiError::new(
            StatusCode::FORBIDDEN,
            "superadmin role required",
        ));
    }

    let account_id_filter = match q.account_id.as_deref().map(str::trim) {
        Some(value) if !value.is_empty() => Some(
            normalize_session_account_id(Some(value))
                .ok_or_else(|| ApiError::bad_request("invalid account_id"))?,
        ),
        _ => None,
    };
    let username_filter = q
        .username
        .as_deref()
        .map(|value| normalize_auth_username(Some(value)))
        .transpose()?;
    let event_type_filter = q
        .event_type
        .as_deref()
        .map(|value| normalize_user_activity_event_type(Some(value), "app_action"))
        .transpose()?;
    let limit = normalize_user_activity_limit(q.limit);
    let before_cursor = normalize_before_cursor(q.before_created_at.as_deref(), q.before_id);
    let before_created_at = before_cursor
        .as_ref()
        .map(|(created_at, _)| created_at.as_str());
    let before_id = before_cursor.as_ref().map(|(_, id)| *id);

    let rows = sqlx::query(
        r#"
        SELECT
          id,
          account_id,
          shamell_user_id,
          username,
          phone,
          event_type,
          module_id,
          action,
          route,
          metadata::text AS metadata_json,
          to_char(created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') AS created_at
        FROM auth_user_activity_events
        WHERE ($1::text IS NULL OR account_id=$1)
          AND ($2::text IS NULL OR username=$2)
          AND ($3::text IS NULL OR event_type=$3)
          AND ($4::timestamptz IS NULL OR (created_at, id) < ($4::timestamptz, COALESCE($5::bigint, 0)))
        ORDER BY created_at DESC, id DESC
        LIMIT $6
        "#,
    )
    .bind(account_id_filter.as_deref())
    .bind(username_filter.as_deref())
    .bind(event_type_filter.as_deref())
    .bind(before_created_at)
    .bind(before_id)
    .bind(limit)
    .fetch_all(&auth.pool)
    .await
    .map_err(|error| {
        tracing::error!(
            error = %error,
            actor_account_hash = %hash_prefix(&principal.account_id),
            "admin user activity lookup failed"
        );
        ApiError::internal("failed to load user activity")
    })?;

    let mut items = Vec::with_capacity(rows.len());
    for row in rows {
        items.push(user_activity_row_value(row)?);
    }
    let next_before_id = items
        .last()
        .and_then(|item| item.get("id"))
        .and_then(Value::as_i64);
    let next_before_created_at = items
        .last()
        .and_then(|item| item.get("created_at"))
        .and_then(Value::as_str)
        .map(ToString::to_string);

    Ok(json_no_store(json!({
        "items": items,
        "next_before_created_at": next_before_created_at,
        "next_before_id": next_before_id,
    })))
}

pub async fn me_platform_feature_event_record(
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(body): Json<PlatformFeatureEventRecordIn>,
) -> ApiResult<Response> {
    let auth = require_auth_runtime(&state)?;
    let principal = require_session_principal(&state, &headers).await?;
    let identity = load_user_activity_identity(auth, &principal.account_id).await?;
    let module_id = normalize_platform_feature_key(body.module_id.as_deref(), 64, "module_id")?;
    let action = normalize_platform_feature_key(body.action.as_deref(), 128, "action")?;
    let feature_key =
        normalize_platform_feature_key(body.feature_key.as_deref(), 128, "feature_key")?;
    let mini_program_id = normalize_platform_feature_optional_key(
        body.mini_program_id.as_deref(),
        128,
        "mini_program_id",
    )?;
    let role_context = normalize_platform_feature_role_context(body.role_context.as_deref());
    let metadata = normalize_platform_feature_metadata(body.metadata)?;
    let client_ip_hash = client_ip_from_headers(&state, &headers)
        .as_deref()
        .map(hash_prefix);
    let (_, user_agent) = device_session_request_metadata(&state, &headers);
    let device_id_hash = principal.device_id.as_deref().map(hash_prefix);
    let account_id = Some(principal.account_id.clone());

    let created = insert_platform_feature_event(
        auth,
        PlatformFeatureEventInsert {
            account_id: account_id.clone(),
            shamell_user_id: identity.shamell_user_id.clone(),
            username: identity.username.clone(),
            phone: identity.phone.clone(),
            module_id: module_id.clone(),
            action: action.clone(),
            feature_key: feature_key.clone(),
            mini_program_id: mini_program_id.clone(),
            role_context: role_context.clone(),
            metadata: metadata.clone(),
            device_id_hash: device_id_hash.clone(),
            client_ip_hash: client_ip_hash.clone(),
            user_agent_hash: user_agent.as_deref().map(hash_prefix),
        },
    )
    .await
    .map_err(|error| {
        tracing::error!(
            error = %error,
            account_hash = %hash_prefix(&principal.account_id),
            "platform feature event insert failed"
        );
        ApiError::internal("failed to record platform feature")
    })?;

    let activity_metadata = json!({
        "feature_key": feature_key,
        "mini_program_id": mini_program_id,
        "role_context": role_context,
        "platform_metadata": metadata,
    });
    if let Err(error) = insert_user_activity_event(
        auth,
        UserActivityEventInsert {
            account_id,
            shamell_user_id: identity.shamell_user_id,
            username: identity.username,
            phone: identity.phone,
            event_type: "platform_feature".to_string(),
            module_id: Some(module_id),
            action: Some(action),
            route: Some("shamell_platform_features".to_string()),
            metadata: activity_metadata,
            device_id_hash,
            client_ip_hash,
            user_agent_hash: user_agent.as_deref().map(hash_prefix),
        },
    )
    .await
    {
        tracing::warn!(
            error = %error,
            account_hash = %hash_prefix(&principal.account_id),
            "platform feature activity mirror insert failed"
        );
    }

    Ok(json_no_store(json!({
        "ok": true,
        "event_id": created.id,
        "created_at": created.created_at,
    })))
}

pub async fn admin_platform_feature_summary(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(q): Query<AdminPlatformFeatureSummaryQuery>,
) -> ApiResult<Response> {
    let auth = require_auth_runtime(&state)?;
    let principal = require_session_principal(&state, &headers).await?;
    let roles = fetch_roles_for_account(&state, &headers, &principal.account_id).await?;
    let operator_ids =
        coach_operator_ids_for_account_best_effort(&state, &principal.account_id).await;
    let derived = derive_access_snapshot(&roles, &operator_ids);
    if !derived.is_superadmin {
        return Err(ApiError::new(
            StatusCode::FORBIDDEN,
            "superadmin role required",
        ));
    }

    let module_filter =
        normalize_platform_feature_optional_key(q.module_id.as_deref(), 64, "module_id")?;
    let feature_filter =
        normalize_platform_feature_optional_key(q.feature_key.as_deref(), 128, "feature_key")?;
    let mini_program_filter = normalize_platform_feature_optional_key(
        q.mini_program_id.as_deref(),
        128,
        "mini_program_id",
    )?;
    let limit = normalize_user_activity_limit(q.limit);
    let before_cursor = normalize_before_cursor(q.before_created_at.as_deref(), q.before_id);
    let before_created_at = before_cursor
        .as_ref()
        .map(|(created_at, _)| created_at.as_str());
    let before_id = before_cursor.as_ref().map(|(_, id)| *id);

    let summary_row = sqlx::query(
        r#"
        SELECT
          COUNT(*)::bigint AS total_events,
          COUNT(DISTINCT account_id)::bigint AS active_users,
          COUNT(*) FILTER (WHERE mini_program_id IS NOT NULL)::bigint AS mini_program_events
        FROM auth_platform_feature_events
        WHERE ($1::text IS NULL OR module_id=$1)
          AND ($2::text IS NULL OR feature_key=$2)
          AND ($3::text IS NULL OR mini_program_id=$3)
        "#,
    )
    .bind(module_filter.as_deref())
    .bind(feature_filter.as_deref())
    .bind(mini_program_filter.as_deref())
    .fetch_one(&auth.pool)
    .await
    .map_err(|error| {
        tracing::error!(
            error = %error,
            actor_account_hash = %hash_prefix(&principal.account_id),
            "admin platform feature summary lookup failed"
        );
        ApiError::internal("failed to load platform feature summary")
    })?;

    let module_rows = sqlx::query(
        r#"
        SELECT module_id, COUNT(*)::bigint AS event_count
        FROM auth_platform_feature_events
        WHERE ($1::text IS NULL OR module_id=$1)
          AND ($2::text IS NULL OR feature_key=$2)
          AND ($3::text IS NULL OR mini_program_id=$3)
        GROUP BY module_id
        ORDER BY event_count DESC, module_id ASC
        LIMIT 12
        "#,
    )
    .bind(module_filter.as_deref())
    .bind(feature_filter.as_deref())
    .bind(mini_program_filter.as_deref())
    .fetch_all(&auth.pool)
    .await
    .map_err(|error| {
        tracing::error!(
            error = %error,
            actor_account_hash = %hash_prefix(&principal.account_id),
            "admin platform feature module summary lookup failed"
        );
        ApiError::internal("failed to load platform feature summary")
    })?;

    let feature_rows = sqlx::query(
        r#"
        SELECT feature_key, module_id, COUNT(*)::bigint AS event_count
        FROM auth_platform_feature_events
        WHERE ($1::text IS NULL OR module_id=$1)
          AND ($2::text IS NULL OR feature_key=$2)
          AND ($3::text IS NULL OR mini_program_id=$3)
        GROUP BY feature_key, module_id
        ORDER BY event_count DESC, feature_key ASC
        LIMIT 12
        "#,
    )
    .bind(module_filter.as_deref())
    .bind(feature_filter.as_deref())
    .bind(mini_program_filter.as_deref())
    .fetch_all(&auth.pool)
    .await
    .map_err(|error| {
        tracing::error!(
            error = %error,
            actor_account_hash = %hash_prefix(&principal.account_id),
            "admin platform feature key summary lookup failed"
        );
        ApiError::internal("failed to load platform feature summary")
    })?;

    let mini_program_rows = sqlx::query(
        r#"
        SELECT mini_program_id, COUNT(*)::bigint AS event_count
        FROM auth_platform_feature_events
        WHERE mini_program_id IS NOT NULL
          AND ($1::text IS NULL OR module_id=$1)
          AND ($2::text IS NULL OR feature_key=$2)
          AND ($3::text IS NULL OR mini_program_id=$3)
        GROUP BY mini_program_id
        ORDER BY event_count DESC, mini_program_id ASC
        LIMIT 12
        "#,
    )
    .bind(module_filter.as_deref())
    .bind(feature_filter.as_deref())
    .bind(mini_program_filter.as_deref())
    .fetch_all(&auth.pool)
    .await
    .map_err(|error| {
        tracing::error!(
            error = %error,
            actor_account_hash = %hash_prefix(&principal.account_id),
            "admin platform mini program summary lookup failed"
        );
        ApiError::internal("failed to load platform feature summary")
    })?;

    let recent_rows = sqlx::query(
        r#"
        SELECT
          id,
          account_id,
          shamell_user_id,
          username,
          phone,
          module_id,
          action,
          feature_key,
          mini_program_id,
          role_context,
          metadata::text AS metadata_json,
          to_char(created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') AS created_at
        FROM auth_platform_feature_events
        WHERE ($1::text IS NULL OR module_id=$1)
          AND ($2::text IS NULL OR feature_key=$2)
          AND ($3::text IS NULL OR mini_program_id=$3)
          AND ($4::timestamptz IS NULL OR (created_at, id) < ($4::timestamptz, COALESCE($5::bigint, 0)))
        ORDER BY created_at DESC, id DESC
        LIMIT $6
        "#,
    )
    .bind(module_filter.as_deref())
    .bind(feature_filter.as_deref())
    .bind(mini_program_filter.as_deref())
    .bind(before_created_at)
    .bind(before_id)
    .bind(limit)
    .fetch_all(&auth.pool)
    .await
    .map_err(|error| {
        tracing::error!(
            error = %error,
            actor_account_hash = %hash_prefix(&principal.account_id),
            "admin platform feature recent events lookup failed"
        );
        ApiError::internal("failed to load platform feature summary")
    })?;

    let mut recent_events = Vec::with_capacity(recent_rows.len());
    for row in recent_rows {
        recent_events.push(platform_feature_event_row_value(row)?);
    }
    let next_before_id = recent_events
        .last()
        .and_then(|item| item.get("id"))
        .and_then(Value::as_i64);
    let next_before_created_at = recent_events
        .last()
        .and_then(|item| item.get("created_at"))
        .and_then(Value::as_str)
        .map(ToString::to_string);
    let total_events: i64 = require_auth_db_column(
        summary_row.try_get("total_events"),
        "total_events",
        "platform_feature_summary_decode",
        "failed to load platform feature summary",
    )?;
    let active_users: i64 = require_auth_db_column(
        summary_row.try_get("active_users"),
        "active_users",
        "platform_feature_summary_decode",
        "failed to load platform feature summary",
    )?;
    let mini_program_events: i64 = require_auth_db_column(
        summary_row.try_get("mini_program_events"),
        "mini_program_events",
        "platform_feature_summary_decode",
        "failed to load platform feature summary",
    )?;

    Ok(json_no_store(json!({
        "total_events": total_events,
        "active_users": active_users,
        "mini_program_events": mini_program_events,
        "modules": platform_feature_count_rows(module_rows, "module_id")?,
        "features": platform_feature_feature_rows(feature_rows)?,
        "mini_programs": platform_feature_count_rows(mini_program_rows, "mini_program_id")?,
        "recent_events": recent_events,
        "next_before_created_at": next_before_created_at,
        "next_before_id": next_before_id,
    })))
}

fn user_activity_row_value(row: PgRow) -> ApiResult<Value> {
    let id: i64 = require_auth_db_column(
        row.try_get("id"),
        "id",
        "user_activity_row_decode",
        "failed to load user activity",
    )?;
    let metadata_json: String = require_auth_text_column(
        row.try_get("metadata_json"),
        "metadata_json",
        "user_activity_row_decode",
        "failed to load user activity",
    )?;
    let metadata = serde_json::from_str::<Value>(&metadata_json).unwrap_or_else(|_| json!({}));
    Ok(json!({
        "id": id,
        "account_id": require_auth_optional_text_column(row.try_get("account_id"), "account_id", "user_activity_row_decode", "failed to load user activity")?,
        "shamell_user_id": require_auth_optional_text_column(row.try_get("shamell_user_id"), "shamell_user_id", "user_activity_row_decode", "failed to load user activity")?,
        "username": require_auth_optional_text_column(row.try_get("username"), "username", "user_activity_row_decode", "failed to load user activity")?,
        "phone": require_auth_optional_text_column(row.try_get("phone"), "phone", "user_activity_row_decode", "failed to load user activity")?,
        "event_type": require_auth_text_column(row.try_get("event_type"), "event_type", "user_activity_row_decode", "failed to load user activity")?,
        "module_id": require_auth_optional_text_column(row.try_get("module_id"), "module_id", "user_activity_row_decode", "failed to load user activity")?,
        "action": require_auth_optional_text_column(row.try_get("action"), "action", "user_activity_row_decode", "failed to load user activity")?,
        "route": require_auth_optional_text_column(row.try_get("route"), "route", "user_activity_row_decode", "failed to load user activity")?,
        "metadata": metadata,
        "created_at": require_auth_text_column(row.try_get("created_at"), "created_at", "user_activity_row_decode", "failed to load user activity")?,
    }))
}

fn platform_feature_count_rows(rows: Vec<PgRow>, key: &'static str) -> ApiResult<Vec<Value>> {
    let mut out = Vec::with_capacity(rows.len());
    for row in rows {
        let event_count: i64 = require_auth_db_column(
            row.try_get("event_count"),
            "event_count",
            "platform_feature_count_decode",
            "failed to load platform feature summary",
        )?;
        out.push(json!({
            key: require_auth_text_column(row.try_get(key), key, "platform_feature_count_decode", "failed to load platform feature summary")?,
            "event_count": event_count,
        }));
    }
    Ok(out)
}

fn platform_feature_feature_rows(rows: Vec<PgRow>) -> ApiResult<Vec<Value>> {
    let mut out = Vec::with_capacity(rows.len());
    for row in rows {
        let event_count: i64 = require_auth_db_column(
            row.try_get("event_count"),
            "event_count",
            "platform_feature_key_count_decode",
            "failed to load platform feature summary",
        )?;
        out.push(json!({
            "feature_key": require_auth_text_column(row.try_get("feature_key"), "feature_key", "platform_feature_key_count_decode", "failed to load platform feature summary")?,
            "module_id": require_auth_text_column(row.try_get("module_id"), "module_id", "platform_feature_key_count_decode", "failed to load platform feature summary")?,
            "event_count": event_count,
        }));
    }
    Ok(out)
}

fn platform_feature_event_row_value(row: PgRow) -> ApiResult<Value> {
    let id: i64 = require_auth_db_column(
        row.try_get("id"),
        "id",
        "platform_feature_event_row_decode",
        "failed to load platform feature summary",
    )?;
    let metadata_json: String = require_auth_text_column(
        row.try_get("metadata_json"),
        "metadata_json",
        "platform_feature_event_row_decode",
        "failed to load platform feature summary",
    )?;
    let metadata = serde_json::from_str::<Value>(&metadata_json).unwrap_or_else(|_| json!({}));
    Ok(json!({
        "id": id,
        "account_id": require_auth_optional_text_column(row.try_get("account_id"), "account_id", "platform_feature_event_row_decode", "failed to load platform feature summary")?,
        "shamell_user_id": require_auth_optional_text_column(row.try_get("shamell_user_id"), "shamell_user_id", "platform_feature_event_row_decode", "failed to load platform feature summary")?,
        "username": require_auth_optional_text_column(row.try_get("username"), "username", "platform_feature_event_row_decode", "failed to load platform feature summary")?,
        "phone": require_auth_optional_text_column(row.try_get("phone"), "phone", "platform_feature_event_row_decode", "failed to load platform feature summary")?,
        "module_id": require_auth_text_column(row.try_get("module_id"), "module_id", "platform_feature_event_row_decode", "failed to load platform feature summary")?,
        "action": require_auth_text_column(row.try_get("action"), "action", "platform_feature_event_row_decode", "failed to load platform feature summary")?,
        "feature_key": require_auth_text_column(row.try_get("feature_key"), "feature_key", "platform_feature_event_row_decode", "failed to load platform feature summary")?,
        "mini_program_id": require_auth_optional_text_column(row.try_get("mini_program_id"), "mini_program_id", "platform_feature_event_row_decode", "failed to load platform feature summary")?,
        "role_context": require_auth_optional_text_column(row.try_get("role_context"), "role_context", "platform_feature_event_row_decode", "failed to load platform feature summary")?,
        "metadata": metadata,
        "created_at": require_auth_text_column(row.try_get("created_at"), "created_at", "platform_feature_event_row_decode", "failed to load platform feature summary")?,
    }))
}

fn wallet_for_home_snapshot(
    account_id: &str,
    wallet_result: ApiResult<Option<Value>>,
) -> Option<Value> {
    match wallet_result {
        Ok(wallet) => wallet,
        Err(err) => {
            tracing::warn!(
                security_event = "me_home_snapshot_wallet_unavailable",
                outcome = "degraded",
                account_hash = %hash_prefix(account_id),
                upstream_status = err.status.as_u16(),
                upstream_detail = %err.detail,
                "wallet resolution failed during home snapshot; returning identity-only snapshot"
            );
            None
        }
    }
}

fn wallet_id_from_payments_user(body: &Value) -> Option<&str> {
    body.get("wallet_id")
        .or_else(|| body.get("id"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
}

async fn ensure_wallet_for_account(
    state: &AppState,
    headers: &HeaderMap,
    account_id: &str,
    phone: Option<&str>,
    currency: Option<&str>,
) -> ApiResult<Option<Value>> {
    let normalized_phone = normalize_wallet_owner_phone(phone);
    if phone
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .is_some()
        && normalized_phone.is_none()
    {
        tracing::warn!(
            security_event = "payments_wallet_owner_phone_invalid",
            outcome = "degraded",
            account_hash = %hash_prefix(account_id),
            "invalid session phone ignored for wallet lookup/create"
        );
    }

    let wallet_currency = normalize_wallet_currency(currency)?;
    if let Some(existing) = lookup_existing_wallet_for_account(
        state,
        headers,
        account_id,
        normalized_phone.as_deref(),
        wallet_currency.as_deref(),
    )
    .await?
    {
        remember_wallet_id_from_payments_user(state, account_id, &existing).await;
        return Ok(Some(existing));
    }

    let mut wallet_provision_headers = headers.clone();
    if header_value(&wallet_provision_headers, "idempotency-key").is_none() {
        let generated_idempotency =
            wallet_create_user_idempotency_key(account_id, wallet_currency.as_deref());
        if let Ok(value) = HeaderValue::from_str(&generated_idempotency) {
            wallet_provision_headers.insert("Idempotency-Key", value);
        }
    }

    let mut payload = serde_json::Map::new();
    payload.insert("account_id".to_string(), json!(account_id));
    if let Some(p) = normalized_phone.as_deref() {
        payload.insert("phone".to_string(), json!(p));
    }
    if let Some(currency) = wallet_currency.as_deref() {
        payload.insert("currency".to_string(), json!(currency));
    }
    let create_with_payload = |payload: Value| async {
        call_upstream_json(
            state,
            Upstream::Payments,
            Method::POST,
            "/users",
            Vec::new(),
            Some(payload),
            &wallet_provision_headers,
        )
        .await
    };

    let out = create_with_payload(Value::Object(payload)).await;
    let out = match out {
        Ok(value) => value,
        Err(err)
            if normalized_phone.is_some() && wallet_phone_retry_without_phone_allowed(&err) =>
        {
            tracing::warn!(
                security_event = "payments_wallet_create_retry_without_phone",
                outcome = "retry",
                account_hash = %hash_prefix(account_id),
                upstream_status = err.status.as_u16(),
                upstream_detail = %err.detail,
                "payments /users create failed with phone; retrying without phone"
            );
            if let Some(existing) = lookup_existing_wallet_for_account(
                state,
                headers,
                account_id,
                None,
                wallet_currency.as_deref(),
            )
            .await?
            {
                remember_wallet_id_from_payments_user(state, account_id, &existing).await;
                return Ok(Some(existing));
            }
            let mut retry_payload = serde_json::Map::new();
            retry_payload.insert("account_id".to_string(), json!(account_id));
            if let Some(currency) = wallet_currency.as_deref() {
                retry_payload.insert("currency".to_string(), json!(currency));
            }
            create_with_payload(Value::Object(retry_payload)).await?
        }
        Err(err) => {
            if matches!(err.status, StatusCode::CONFLICT | StatusCode::BAD_REQUEST) {
                if let Some(existing) = lookup_existing_wallet_for_account(
                    state,
                    headers,
                    account_id,
                    None,
                    wallet_currency.as_deref(),
                )
                .await?
                {
                    remember_wallet_id_from_payments_user(state, account_id, &existing).await;
                    return Ok(Some(existing));
                }
            }
            return Err(err);
        }
    };
    remember_wallet_id_from_payments_user(state, account_id, &out).await;
    Ok(Some(out))
}

fn wallet_create_user_idempotency_key(account_id: &str, currency: Option<&str>) -> String {
    match currency.map(str::trim).filter(|value| !value.is_empty()) {
        Some(currency) => format!(
            "wallet_create_user:{}:{}",
            hash_prefix(account_id),
            currency.to_ascii_lowercase()
        ),
        None => format!("wallet_create_user:{}", hash_prefix(account_id)),
    }
}

fn normalize_wallet_owner_phone(phone: Option<&str>) -> Option<String> {
    let phone = phone
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .filter(|value| valid_e164(value))?;
    Some(phone.to_string())
}

fn wallet_phone_retry_without_phone_allowed(err: &ApiError) -> bool {
    if !(err.status == StatusCode::BAD_REQUEST || err.status == StatusCode::CONFLICT) {
        return false;
    }
    let detail = err.detail.to_ascii_lowercase();
    detail.contains("phone")
        || detail.contains("account_id does not match phone owner")
        || detail.contains("invalid phone format")
}

async fn lookup_existing_wallet_for_account(
    state: &AppState,
    headers: &HeaderMap,
    account_id: &str,
    phone: Option<&str>,
    currency: Option<&str>,
) -> ApiResult<Option<Value>> {
    let lookup_with_phone = phone.map(str::trim).filter(|value| !value.is_empty());
    let lookup_currency = currency.map(str::trim).filter(|value| !value.is_empty());
    let lookup_user = |query: Vec<(String, String)>| async {
        match call_upstream_json(
            state,
            Upstream::Payments,
            Method::GET,
            "/users",
            query,
            None,
            headers,
        )
        .await
        {
            Ok(out) => Ok(Some(out)),
            Err(err) if err.status == StatusCode::NOT_FOUND => Ok(None),
            Err(err) => Err(err),
        }
    };

    let mut query = vec![("account_id".to_string(), account_id.to_string())];
    if let Some(phone) = lookup_with_phone {
        query.push(("phone".to_string(), phone.to_string()));
    }
    if let Some(currency) = lookup_currency {
        query.push(("currency".to_string(), currency.to_string()));
    }

    match lookup_user(query).await {
        Ok(out) => Ok(out),
        Err(err)
            if lookup_with_phone.is_some() && wallet_phone_retry_without_phone_allowed(&err) =>
        {
            tracing::warn!(
                security_event = "payments_wallet_lookup_retry_without_phone",
                outcome = "retry",
                account_hash = %hash_prefix(account_id),
                upstream_status = err.status.as_u16(),
                upstream_detail = %err.detail,
                "payments /users lookup failed with phone; retrying without phone"
            );
            let mut retry_query = vec![("account_id".to_string(), account_id.to_string())];
            if let Some(currency) = lookup_currency {
                retry_query.push(("currency".to_string(), currency.to_string()));
            }
            lookup_user(retry_query).await
        }
        Err(err) => Err(err),
    }
}

async fn remember_wallet_id_from_payments_user(state: &AppState, account_id: &str, body: &Value) {
    if let Some(wallet_id) = wallet_id_from_payments_user(body) {
        state
            .remember_wallet_id_for_account(account_id, wallet_id)
            .await;
    }
}

pub(crate) async fn fetch_roles_for_account(
    state: &AppState,
    headers: &HeaderMap,
    account_id: &str,
) -> ApiResult<Vec<String>> {
    if let Some(cached) = state.cached_roles_for_account(account_id).await {
        return Ok(cached);
    }
    let out = if let Some(auth) = state.auth.as_ref() {
        load_role_strings_for_account_from_auth_store(auth, account_id).await?
    } else {
        let v = call_upstream_json(
            state,
            Upstream::Payments,
            Method::GET,
            "/admin/roles",
            vec![
                ("account_id".to_string(), account_id.to_string()),
                ("limit".to_string(), "200".to_string()),
            ],
            None,
            headers,
        )
        .await?;
        let mut out: Vec<String> = Vec::new();
        if let Value::Array(items) = v {
            for it in items {
                if let Some(role) = it.get("role").and_then(|r| r.as_str()) {
                    let role = role.trim().to_ascii_lowercase();
                    if !role.is_empty() && !out.iter().any(|r| r == &role) {
                        out.push(role);
                    }
                }
            }
        }
        out
    };
    if state.auth.is_some() && out.is_empty() {
        tracing::debug!(
            account_id_hash = %hash_prefix(account_id),
            "no locally assigned roles resolved for account"
        );
    }
    state.remember_roles_for_account(account_id, &out).await;
    Ok(out)
}

#[derive(Clone, Copy)]
enum Upstream {
    Payments,
}

async fn call_upstream_json(
    state: &AppState,
    upstream: Upstream,
    method: Method,
    path: &str,
    query: Vec<(String, String)>,
    body: Option<Value>,
    headers: &HeaderMap,
) -> ApiResult<Value> {
    let (base_url, internal_secret, upstream_name) = match upstream {
        Upstream::Payments => (
            state.payments_base_url.as_str(),
            state.payments_internal_secret.as_deref(),
            "payments",
        ),
    };
    let path_hash = hash_prefix(path);
    let (url, path_and_query) = state
        .build_upstream_url(base_url, path, &query)
        .map_err(|e| {
            tracing::error!(
                error = %e,
                upstream = upstream_name,
                path_hash,
                "invalid upstream url"
            );
            ApiError::internal(format!("{upstream_name} upstream unavailable"))
        })?;
    let body_bytes = body
        .map(|b| serde_json::to_vec(&b))
        .transpose()
        .map_err(|e| {
            tracing::error!(
                error = %e,
                upstream = upstream_name,
                path_hash,
                "encode upstream body"
            );
            ApiError::internal(format!("{upstream_name} upstream unavailable"))
        })?;
    let mut req = state
        .http
        .request(method.clone(), url)
        .timeout(std::time::Duration::from_secs(
            state.upstream_timeout_secs.max(1),
        ));
    if state.should_send_legacy_internal_secret() {
        if let Some(secret) = internal_secret.map(str::trim).filter(|s| !s.is_empty()) {
            req = req.header("X-Internal-Secret", secret);
        }
    }
    req = state
        .apply_internal_identity_headers(
            req,
            &method,
            "payments",
            &path_and_query,
            body_bytes.as_deref().unwrap_or(&[]),
        )
        .map_err(|e| {
            tracing::error!(
                error = %e,
                upstream = upstream_name,
                path_hash,
                "sign upstream request"
            );
            ApiError::internal(format!("{upstream_name} upstream unavailable"))
        })?;
    if header_value(headers, TRUSTED_CLIENT_IP_ATTESTED_HEADER).as_deref() == Some("1") {
        if let Some(client_ip) =
            header_value(headers, TRUSTED_CLIENT_IP_HEADER).and_then(|value| parse_ip(&value))
        {
            req = req.header(TRUSTED_CLIENT_IP_HEADER, client_ip);
            req = req.header(TRUSTED_CLIENT_IP_ATTESTED_HEADER, "1");
        }
    }
    if let Some(rid) = header_value(headers, "x-request-id") {
        req = req.header("X-Request-ID", rid);
    }
    if let Some(idempotency_key) = header_value(headers, "idempotency-key") {
        req = req.header("Idempotency-Key", idempotency_key);
    }
    if let Some(body_bytes) = body_bytes {
        req = req
            .header(header::CONTENT_TYPE, "application/json")
            .body(body_bytes);
    }
    let resp = req.send().await.map_err(|e| {
        let status = if e.is_timeout() {
            StatusCode::GATEWAY_TIMEOUT
        } else {
            StatusCode::BAD_GATEWAY
        };
        tracing::error!(
            error = %e,
            timeout = e.is_timeout(),
            upstream = upstream_name,
            path_hash,
            "upstream call failed"
        );
        ApiError::upstream(status, format!("{upstream_name} upstream unavailable"))
    })?;
    let status = StatusCode::from_u16(resp.status().as_u16()).unwrap_or(StatusCode::BAD_GATEWAY);
    let body_bytes =
        read_upstream_json_body_limited(resp, state.max_upstream_body_bytes, upstream_name, path)
            .await?;
    let text = String::from_utf8_lossy(&body_bytes).to_string();
    let parsed: Value =
        serde_json::from_slice(&body_bytes).unwrap_or_else(|_| json!({"detail": text.clone()}));
    if status.is_success() {
        return Ok(parsed);
    }
    let detail = parsed
        .get("detail")
        .and_then(|v| v.as_str())
        .map(ToString::to_string)
        .unwrap_or_else(|| {
            if text.trim().is_empty() {
                format!("{upstream_name} upstream error")
            } else {
                text
            }
        });
    let detail = redact_sensitive_upstream_error_detail(&detail);
    if !state.expose_upstream_errors && (status.is_client_error() || status.is_server_error()) {
        return Err(ApiError::new(
            status,
            format!("{upstream_name} upstream error"),
        ));
    }
    Err(ApiError::new(status, detail))
}

async fn read_upstream_json_body_limited(
    resp: reqwest::Response,
    max_bytes: usize,
    upstream_name: &str,
    path: &str,
) -> ApiResult<Vec<u8>> {
    let path_hash = hash_prefix(path);
    if let Some(cl) = resp.content_length() {
        if cl as usize > max_bytes {
            tracing::warn!(
                upstream = upstream_name,
                path_hash,
                content_length = cl,
                max_bytes,
                "upstream response exceeds configured limit"
            );
            return Err(ApiError::upstream(
                StatusCode::BAD_GATEWAY,
                format!("{upstream_name} upstream response too large"),
            ));
        }
    }

    let mut out: Vec<u8> = Vec::new();
    let mut total = 0usize;
    let mut stream = resp.bytes_stream();
    while let Some(next) = stream.next().await {
        let chunk = next.map_err(|e| {
            tracing::error!(
                error = %e,
                path_hash,
                upstream = upstream_name,
                "upstream body read failed"
            );
            ApiError::internal(format!("{upstream_name} upstream body read failed"))
        })?;
        total += chunk.len();
        if total > max_bytes {
            tracing::warn!(
                upstream = upstream_name,
                path_hash,
                total_bytes = total,
                max_bytes,
                "upstream response exceeded configured limit while streaming"
            );
            return Err(ApiError::upstream(
                StatusCode::BAD_GATEWAY,
                format!("{upstream_name} upstream response too large"),
            ));
        }
        out.extend_from_slice(&chunk);
    }
    Ok(out)
}

fn require_auth_runtime(state: &AppState) -> ApiResult<&AuthRuntime> {
    state
        .auth
        .as_ref()
        .ok_or_else(|| ApiError::new(StatusCode::SERVICE_UNAVAILABLE, "auth not configured"))
}

fn parse_scoped_official_owner_role(raw: &str) -> Option<String> {
    let role = raw.trim().to_ascii_lowercase();
    let scope = role.strip_prefix("official_owner:")?.trim();
    if scope == "*" {
        return Some("*".to_string());
    }
    normalize_official_account_id(scope).ok()
}

fn official_role_scopes(roles: &[String]) -> (bool, HashSet<String>) {
    let mut wildcard = false;
    let mut owned = HashSet::new();
    for role in roles {
        match role.as_str() {
            "admin" | "superadmin" => {
                wildcard = true;
                break;
            }
            _ => {
                if let Some(scope) = parse_scoped_official_owner_role(role) {
                    if scope == "*" {
                        wildcard = true;
                        break;
                    }
                    owned.insert(scope);
                }
            }
        }
    }
    (wildcard, owned)
}

fn roles_can_manage_official(roles: &[String], official_id: &str) -> bool {
    let (wildcard, owned) = official_role_scopes(roles);
    wildcard || owned.contains(official_id)
}

fn official_owner_role_for(official_id: &str) -> String {
    format!("official_owner:{official_id}")
}

fn official_owner_entry_from_assignment(
    assignment: &AccessAssignmentOut,
    expected_official_id: &str,
) -> Option<Value> {
    if assignment.role_id != "official.account_owner" {
        return None;
    }
    if assignment.scope.official_account_id.as_deref() != Some(expected_official_id) {
        return None;
    }
    let account_id = assignment.account_id.clone();
    let phone = assignment.phone.clone();
    if account_id.is_none() && phone.is_none() {
        return None;
    }
    let created_at = assignment.created_at.clone();
    let cursor_id = assignment.cursor_id.filter(|value| *value > 0);
    Some(json!({
        "cursor_id": cursor_id,
        "account_id": account_id,
        "phone": phone,
        "created_at": created_at,
    }))
}

async fn list_official_owner_assignments(
    state: &AppState,
    headers: &HeaderMap,
    role_id: Option<&str>,
    limit: i64,
    before_created_at: Option<&str>,
    before_id: Option<i64>,
) -> ApiResult<Vec<AccessAssignmentOut>> {
    if let Some(auth) = state.auth.as_ref() {
        return list_access_assignments_from_auth_store(
            auth,
            None,
            None,
            role_id,
            limit,
            before_created_at,
            before_id,
        )
        .await;
    }

    let v = call_upstream_json(
        state,
        Upstream::Payments,
        Method::GET,
        "/admin/roles",
        vec![("limit".to_string(), limit.to_string())],
        None,
        headers,
    )
    .await?;

    let items = v.as_array().cloned().unwrap_or_default();
    let mut assignments = Vec::new();
    for item in items {
        let Some(role) = item
            .get("role")
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
        else {
            continue;
        };
        let Some(resolved) = resolved_access_assignment_from_legacy_role(role) else {
            continue;
        };
        if let Some(expected_role_id) = role_id {
            if resolved.role_id != expected_role_id {
                continue;
            }
        }
        let account_id = item
            .get("account_id")
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(ToString::to_string);
        let phone = item
            .get("phone")
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(ToString::to_string);
        let created_at = item
            .get("created_at")
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(ToString::to_string);
        assignments.push(AccessAssignmentOut {
            cursor_id: None,
            account_id,
            phone,
            role_id: resolved.role_id,
            legacy_role: resolved.legacy_role,
            created_at,
            scope: resolved.scope,
        });
    }
    Ok(assignments)
}

async fn require_official_roles_principal(
    state: &AppState,
    headers: &HeaderMap,
) -> ApiResult<(AuthPrincipal, Vec<String>)> {
    if auth_test_overrides_enabled(state) {
        if let Some(principal) = test_override_principal(headers) {
            let roles = test_override_roles(headers).unwrap_or_default();
            return Ok((principal, roles));
        }
    }

    let principal = require_session_principal(state, headers).await?;
    let account_id = principal.account_id.trim();
    if account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }

    let roles = fetch_roles_for_account(state, headers, account_id).await?;
    Ok((principal, roles))
}

