fn roles_contain_value(roles: &[String], expected: &str) -> bool {
    roles
        .iter()
        .any(|role| role.trim().eq_ignore_ascii_case(expected))
}

fn roles_allow_from_allowlist(roles: &[String], allowlist: &[&str]) -> bool {
    roles.iter().any(|role| {
        let normalized = role.trim().to_ascii_lowercase();
        !normalized.is_empty() && allowlist.contains(&normalized.as_str())
    })
}

pub(crate) fn roles_allow_wallet_operator(roles: &[String]) -> bool {
    roles_allow_from_allowlist(roles, WALLET_OPERATOR_ALLOWED_ROLES)
        || roles.iter().any(|role| {
            let normalized = role.trim().to_ascii_lowercase();
            normalized.starts_with("operator_")
        })
}

