fn is_contact_enforcement_schema_missing(error: &sqlx::Error) -> bool {
    if let Some(db_err) = error.as_database_error() {
        if db_err.code().as_deref() == Some("42P01") {
            return true;
        }
        let msg = db_err.message().to_ascii_lowercase();
        if msg.contains("auth_chat_contacts")
            && (msg.contains("does not exist") || msg.contains("undefined table"))
        {
            return true;
        }
    }
    let msg = error.to_string().to_ascii_lowercase();
    msg.contains("auth_chat_contacts")
        && (msg.contains("does not exist")
            || msg.contains("undefined table")
            || msg.contains("no such table"))
}

fn contact_enforcement_lookup_failed(
    error: &sqlx::Error,
    account_id: &str,
    recipient_device_id: &str,
) -> ApiError {
    if is_contact_enforcement_schema_missing(error) {
        tracing::error!(
            error = %error,
            account_hash = %hash_prefix(account_id),
            recipient_device_id_hash = %hash_prefix(recipient_device_id),
            "contact enforcement schema missing; blocking direct send"
        );
    } else {
        tracing::error!(
            error = %error,
            account_hash = %hash_prefix(account_id),
            recipient_device_id_hash = %hash_prefix(recipient_device_id),
            "auth_chat_contacts lookup failed for contact enforcement"
        );
    }
    ApiError::internal("contact enforcement unavailable")
}

#[derive(Debug, Clone)]
pub(crate) struct AuthPrincipal {
    pub account_id: String,
    pub phone: Option<String>,
    pub device_id: Option<String>,
}

async fn require_auth_principal(state: &AppState, headers: &HeaderMap) -> ApiResult<AuthPrincipal> {
    auth_principal_from_headers(state, headers)
        .await?
        .ok_or_else(|| ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"))
}

pub(crate) async fn require_session_principal(
    state: &AppState,
    headers: &HeaderMap,
) -> ApiResult<AuthPrincipal> {
    require_auth_principal(state, headers).await
}

pub(crate) async fn require_session_account_id(
    state: &AppState,
    headers: &HeaderMap,
) -> ApiResult<String> {
    Ok(require_auth_principal(state, headers).await?.account_id)
}

pub(crate) fn enforce_session_device_binding(
    principal: &AuthPrincipal,
    requested_device_id: &str,
    operation: &'static str,
) -> ApiResult<()> {
    enforce_bound_session_device_id(principal, requested_device_id, operation)
}

pub(crate) async fn enforce_payment_mutation_attestation(
    state: &AppState,
    headers: &HeaderMap,
    principal: &AuthPrincipal,
    operation: &'static str,
    resource_id: &str,
) -> ApiResult<()> {
    let requested_device_id = normalize_device_id(header_value(headers, "x-device-id").as_deref())
        .ok_or_else(|| ApiError::bad_request("device_id required"))?;
    let enabled = state
        .auth
        .as_ref()
        .map(|auth| auth.payment_mutation_hw_attestation_enabled)
        .unwrap_or(false);
    enforce_recorded_hardware_attestation_inner(
        state,
        headers,
        principal,
        RecordedHardwareAttestationSpec {
            attestation_enabled: enabled,
            requested_device_id: &requested_device_id,
            operation,
            resource_id,
            challenge_header_name: PAYMENT_ATTESTATION_CHALLENGE_HEADER,
            play_integrity_header_name: PAYMENT_ATTESTATION_PLAY_INTEGRITY_HEADER,
            apple_devicecheck_header_name: PAYMENT_ATTESTATION_APPLE_DEVICECHECK_HEADER,
            security_event: "payment_mutation_attestation",
            failure_detail: "payment attestation unavailable",
            verification_override: None,
        },
    )
    .await
}

async fn enforce_biometric_enroll_attestation(
    state: &AppState,
    headers: &HeaderMap,
    principal: &AuthPrincipal,
    device_id: &str,
) -> ApiResult<()> {
    let enabled = state
        .auth
        .as_ref()
        .map(|auth| auth.biometric_enroll_hw_attestation_enabled)
        .unwrap_or(false);
    enforce_recorded_hardware_attestation_inner(
        state,
        headers,
        principal,
        RecordedHardwareAttestationSpec {
            attestation_enabled: enabled,
            requested_device_id: device_id,
            operation: "biometric_enroll",
            resource_id: device_id,
            challenge_header_name: BIOMETRIC_ENROLL_ATTESTATION_CHALLENGE_HEADER,
            play_integrity_header_name: BIOMETRIC_ENROLL_ATTESTATION_PLAY_INTEGRITY_HEADER,
            apple_devicecheck_header_name: BIOMETRIC_ENROLL_ATTESTATION_APPLE_DEVICECHECK_HEADER,
            security_event: "biometric_enroll_attestation",
            failure_detail: "biometric attestation unavailable",
            verification_override: None,
        },
    )
    .await
}

async fn enforce_biometric_login_attestation(
    state: &AppState,
    headers: &HeaderMap,
    account_id: &str,
    device_id: &str,
    token_hash: &str,
) -> ApiResult<()> {
    enforce_biometric_login_attestation_inner(
        state, headers, account_id, device_id, token_hash, None,
    )
    .await
}

async fn enforce_biometric_login_attestation_inner(
    state: &AppState,
    headers: &HeaderMap,
    account_id: &str,
    device_id: &str,
    token_hash: &str,
    verification_override: Option<bool>,
) -> ApiResult<()> {
    let enabled = state
        .auth
        .as_ref()
        .map(|auth| auth.biometric_login_hw_attestation_enabled)
        .unwrap_or(false);
    let principal = AuthPrincipal {
        account_id: account_id.to_string(),
        phone: None,
        device_id: Some(device_id.to_string()),
    };
    let result = enforce_recorded_hardware_attestation_inner(
        state,
        headers,
        &principal,
        RecordedHardwareAttestationSpec {
            attestation_enabled: enabled,
            requested_device_id: device_id,
            operation: "biometric_login",
            resource_id: token_hash,
            challenge_header_name: BIOMETRIC_LOGIN_ATTESTATION_CHALLENGE_HEADER,
            play_integrity_header_name: BIOMETRIC_LOGIN_ATTESTATION_PLAY_INTEGRITY_HEADER,
            apple_devicecheck_header_name: BIOMETRIC_LOGIN_ATTESTATION_APPLE_DEVICECHECK_HEADER,
            security_event: "biometric_login_attestation",
            failure_detail: "biometric login attestation unavailable",
            verification_override,
        },
    )
    .await;
    let Some(auth) = state.auth.as_ref() else {
        return result;
    };
    match result {
        Ok(()) => {
            clear_biometric_login_attestation_failure_tracking(auth, token_hash).await;
            Ok(())
        }
        Err(err)
            if err.status == StatusCode::UNAUTHORIZED
                && err
                    .detail
                    .trim()
                    .eq_ignore_ascii_case("attestation required") =>
        {
            let client_ip = rate_limit_client_ip(state, headers).ok();
            record_biometric_login_attestation_failure(
                auth,
                account_id,
                device_id,
                token_hash,
                client_ip.as_deref(),
            )
            .await;
            Err(err)
        }
        Err(err) => Err(err),
    }
}

async fn enforce_recorded_hardware_attestation_inner(
    state: &AppState,
    headers: &HeaderMap,
    principal: &AuthPrincipal,
    spec: RecordedHardwareAttestationSpec<'_>,
) -> ApiResult<()> {
    enforce_payment_mutation_attestation_inner(state, headers, principal, spec).await
}

struct RecordedHardwareAttestationSpec<'a> {
    attestation_enabled: bool,
    requested_device_id: &'a str,
    operation: &'static str,
    resource_id: &'a str,
    challenge_header_name: &'static str,
    play_integrity_header_name: &'static str,
    apple_devicecheck_header_name: &'static str,
    security_event: &'static str,
    failure_detail: &'static str,
    verification_override: Option<bool>,
}

async fn enforce_payment_mutation_attestation_inner(
    state: &AppState,
    headers: &HeaderMap,
    principal: &AuthPrincipal,
    spec: RecordedHardwareAttestationSpec<'_>,
) -> ApiResult<()> {
    let RecordedHardwareAttestationSpec {
        attestation_enabled,
        requested_device_id,
        operation,
        resource_id,
        challenge_header_name,
        play_integrity_header_name,
        apple_devicecheck_header_name,
        security_event,
        failure_detail,
        verification_override,
    } = spec;
    let Some(auth) = state.auth.as_ref() else {
        return Ok(());
    };
    let hw_providers = hardware_attestation_providers(auth);
    if !attestation_enabled || hw_providers.is_empty() {
        return Ok(());
    }
    if auth
        .payment_mutation_attestation_emergency_bypass_operations
        .contains(operation)
    {
        tracing::warn!(
            security_event,
            outcome = "emergency_bypass",
            operation,
            account_hash = %hash_prefix(principal.account_id.trim()),
            device_id_hash = %hash_prefix(requested_device_id),
            resource_id_hash = %hash_prefix(resource_id),
            "payment mutation hardware attestation bypassed by emergency operation policy"
        );
        return Ok(());
    }

    let challenge_token = header_value(headers, challenge_header_name)
        .ok_or_else(|| ApiError::new(StatusCode::UNAUTHORIZED, "attestation required"))?;
    let ios_tok = header_value(headers, apple_devicecheck_header_name);
    let android_tok = header_value(headers, play_integrity_header_name);
    if ios_tok.is_none() && android_tok.is_none() {
        tracing::warn!(
            security_event,
            outcome = "missing_token",
            operation,
            account_hash = %hash_prefix(principal.account_id.trim()),
            device_id_hash = %hash_prefix(requested_device_id),
            resource_id_hash = %hash_prefix(resource_id),
            "recorded hardware attestation missing token"
        );
        return Err(ApiError::new(
            StatusCode::UNAUTHORIZED,
            "attestation required",
        ));
    }

    let token_hash = payment_mutation_attestation_challenge_token_hash(&challenge_token);
    let mut tx = auth.pool.begin().await.map_err(|e| {
        tracing::error!(
            error = %e,
            operation,
            security_event,
            "recorded hardware attestation begin tx failed"
        );
        ApiError::internal(failure_detail)
    })?;
    let row = sqlx::query(
        "SELECT id, account_id, device_id, operation, resource_id, consumed_at IS NULL AS fresh, (expires_at > NOW()) AS alive \
         FROM auth_payment_attestation_challenges WHERE token_hash=$1 LIMIT 1 FOR UPDATE",
    )
    .bind(&token_hash)
    .fetch_optional(&mut *tx)
    .await
    .map_err(|e| {
        tracing::error!(error = %e, operation, security_event, "recorded hardware attestation lookup failed");
        ApiError::internal(failure_detail)
    })?;
    let Some(row) = row else {
        let _ = tx.rollback().await;
        tracing::warn!(
            security_event,
            outcome = "unknown_challenge",
            operation,
            account_hash = %hash_prefix(principal.account_id.trim()),
            device_id_hash = %hash_prefix(requested_device_id),
            challenge_hash = %token_hash_prefix(&token_hash),
            resource_id_hash = %hash_prefix(resource_id),
            "recorded hardware attestation challenge not found"
        );
        return Err(ApiError::new(
            StatusCode::UNAUTHORIZED,
            "attestation required",
        ));
    };
    let decode_attestation_column = |column: &'static str, e: sqlx::Error| -> ApiError {
        tracing::error!(
            error = %e,
            operation,
            security_event,
            challenge_hash = %token_hash_prefix(&token_hash),
            column,
            "recorded hardware attestation challenge decode failed"
        );
        ApiError::internal(failure_detail)
    };
    let id: i64 = row
        .try_get("id")
        .map_err(|e| decode_attestation_column("id", e))?;
    let account_id_db: String = row
        .try_get("account_id")
        .map_err(|e| decode_attestation_column("account_id", e))?;
    let device_id_db: String = row
        .try_get("device_id")
        .map_err(|e| decode_attestation_column("device_id", e))?;
    let operation_db: String = row
        .try_get("operation")
        .map_err(|e| decode_attestation_column("operation", e))?;
    let resource_id_db: String = row
        .try_get("resource_id")
        .map_err(|e| decode_attestation_column("resource_id", e))?;
    let fresh: bool = row
        .try_get("fresh")
        .map_err(|e| decode_attestation_column("fresh", e))?;
    let alive: bool = row
        .try_get("alive")
        .map_err(|e| decode_attestation_column("alive", e))?;
    if !fresh
        || !alive
        || account_id_db.trim() != principal.account_id.trim()
        || device_id_db.trim() != requested_device_id
        || operation_db.trim() != operation
        || resource_id_db.trim() != resource_id
    {
        let _ = tx.rollback().await;
        tracing::warn!(
            security_event,
            outcome = "replayed_or_mismatch",
            operation,
            account_hash = %hash_prefix(principal.account_id.trim()),
            device_id_hash = %hash_prefix(requested_device_id),
            challenge_hash = %token_hash_prefix(&token_hash),
            resource_id_hash = %hash_prefix(resource_id),
            "recorded hardware attestation challenge replayed or mismatched"
        );
        return Err(ApiError::new(
            StatusCode::UNAUTHORIZED,
            "attestation required",
        ));
    }

    let (attempted, ok) = if let Some(forced_verdict) = verification_override {
        (true, forced_verdict)
    } else {
        let mut ok = false;
        let mut attempted = false;
        if let Some(tok) = ios_tok.as_deref() {
            attempted = true;
            let Some(cfg) = auth.account_create_apple_devicecheck.as_ref() else {
                let _ = tx.rollback().await;
                tracing::error!(
                    security_event,
                    outcome = "misconfigured",
                    provider = "apple_devicecheck",
                    operation,
                    "hardware attestation token provided but Apple DeviceCheck is not configured"
                );
                return Err(ApiError::new(
                    StatusCode::UNAUTHORIZED,
                    "attestation required",
                ));
            };
            ok = verify_apple_devicecheck_token(&state.http, cfg, tok).await?;
        }
        if !ok {
            if let Some(tok) = android_tok.as_deref() {
                attempted = true;
                let Some(cfg) = auth.account_create_play_integrity.as_ref() else {
                    let _ = tx.rollback().await;
                    tracing::error!(
                        security_event,
                        outcome = "misconfigured",
                        provider = "google_play_integrity",
                        operation,
                        "hardware attestation token provided but Play Integrity is not configured"
                    );
                    return Err(ApiError::new(
                        StatusCode::UNAUTHORIZED,
                        "attestation required",
                    ));
                };
                let Some(expected_nonce_b64) =
                    payment_mutation_attestation_nonce_b64(&challenge_token)
                else {
                    let _ = tx.rollback().await;
                    tracing::error!(
                        security_event,
                        outcome = "missing_nonce",
                        provider = "google_play_integrity",
                        operation,
                        "hardware attestation missing expected nonce"
                    );
                    return Err(ApiError::internal(failure_detail));
                };
                ok =
                    verify_play_integrity_token(&state.http, cfg, tok, &expected_nonce_b64).await?;
            }
        }
        (attempted, ok)
    };
    if !attempted || !ok {
        let _ = tx.rollback().await;
        tracing::warn!(
            security_event,
            outcome = "invalid",
            operation,
            account_hash = %hash_prefix(principal.account_id.trim()),
            device_id_hash = %hash_prefix(requested_device_id),
            challenge_hash = %token_hash_prefix(&token_hash),
            resource_id_hash = %hash_prefix(resource_id),
            "recorded hardware attestation invalid"
        );
        return Err(ApiError::new(
            StatusCode::UNAUTHORIZED,
            "attestation required",
        ));
    }

    let consumed = sqlx::query(
        "UPDATE auth_payment_attestation_challenges \
         SET consumed_at=NOW() \
         WHERE id=$1 AND consumed_at IS NULL AND expires_at > NOW()",
    )
    .bind(id)
    .execute(&mut *tx)
    .await
    .map_err(|e| {
        tracing::error!(error = %e, operation, security_event, "recorded hardware attestation consume failed");
        ApiError::internal(failure_detail)
    })?
    .rows_affected();
    if consumed != 1 {
        let _ = tx.rollback().await;
        tracing::warn!(
            security_event,
            outcome = "consume_race",
            operation,
            account_hash = %hash_prefix(principal.account_id.trim()),
            device_id_hash = %hash_prefix(requested_device_id),
            challenge_hash = %token_hash_prefix(&token_hash),
            resource_id_hash = %hash_prefix(resource_id),
            "recorded hardware attestation consume raced or expired"
        );
        return Err(ApiError::new(
            StatusCode::UNAUTHORIZED,
            "attestation required",
        ));
    }

    tx.commit().await.map_err(|e| {
        tracing::error!(error = %e, operation, security_event, "recorded hardware attestation commit failed");
        ApiError::internal(failure_detail)
    })?;
    tracing::info!(
        security_event,
        outcome = "ok",
        operation,
        account_hash = %hash_prefix(principal.account_id.trim()),
        device_id_hash = %hash_prefix(requested_device_id),
        challenge_hash = %token_hash_prefix(&token_hash),
        resource_id_hash = %hash_prefix(resource_id),
        "recorded hardware attestation accepted"
    );
    Ok(())
}

