fn enforce_bound_session_device_id(
    principal: &AuthPrincipal,
    requested_device_id: &str,
    operation: &'static str,
) -> ApiResult<()> {
    let Some(bound_device_id) = principal.device_id.as_deref() else {
        return Ok(());
    };
    if bound_device_id == requested_device_id {
        return Ok(());
    }
    tracing::warn!(
        security_event = "session_device_binding_mismatch",
        outcome = "blocked",
        operation,
        account_hash = %hash_prefix(principal.account_id.trim()),
        session_device_id_hash = %hash_prefix(bound_device_id),
        requested_device_id_hash = %hash_prefix(requested_device_id),
        "requested device id does not match the active session binding"
    );
    Err(ApiError::bad_request("device_id mismatch"))
}

fn require_prebound_session_device_id(
    principal: &AuthPrincipal,
    requested_device_id: &str,
    operation: &'static str,
) -> ApiResult<()> {
    let Some(bound_device_id) = principal.device_id.as_deref() else {
        tracing::warn!(
            security_event = "session_device_binding_required",
            outcome = "blocked",
            operation,
            account_hash = %hash_prefix(principal.account_id.trim()),
            requested_device_id_hash = %hash_prefix(requested_device_id),
            "requested operation requires an already device-bound session"
        );
        return Err(ApiError::new(
            StatusCode::UNAUTHORIZED,
            "auth session required",
        ));
    };
    if bound_device_id == requested_device_id {
        return Ok(());
    }
    enforce_bound_session_device_id(principal, requested_device_id, operation)
}

fn normalize_bound_client_device_id(
    principal: &AuthPrincipal,
    raw_client_device_id: Option<&str>,
) -> ApiResult<Option<String>> {
    let requested_client_device_id = normalize_device_id(raw_client_device_id);
    let Some(bound_device_id) = principal.device_id.as_deref() else {
        return Ok(requested_client_device_id);
    };
    if let Some(requested_client_device_id) = requested_client_device_id.as_deref() {
        if requested_client_device_id != bound_device_id {
            tracing::warn!(
                security_event = "chat_client_device_binding_mismatch",
                outcome = "blocked",
                account_hash = %hash_prefix(principal.account_id.trim()),
                session_device_id_hash = %hash_prefix(bound_device_id),
                requested_client_device_id_hash = %hash_prefix(requested_client_device_id),
                "client_device_id does not match the active session binding"
            );
            return Err(ApiError::bad_request("client_device_id mismatch"));
        }
    }
    Ok(Some(bound_device_id.to_string()))
}

fn chat_device_bind_conflict_reason(
    existing_account_id: Option<&str>,
    existing_phone: Option<&str>,
    existing_client_device_id: Option<&str>,
    account_id: &str,
    phone: Option<&str>,
    client_device_id: Option<&str>,
) -> Option<&'static str> {
    let existing_client_device_id = existing_client_device_id
        .map(str::trim)
        .filter(|s| !s.is_empty());
    let client_device_id = client_device_id.map(str::trim).filter(|s| !s.is_empty());
    if existing_client_device_id.is_some() && existing_client_device_id == client_device_id {
        return None;
    }

    if let Some(existing_account_id) = existing_account_id.map(str::trim).filter(|s| !s.is_empty())
    {
        if existing_account_id != account_id {
            return Some("device_id already in use");
        }
        return None;
    }

    let existing_phone = existing_phone.map(str::trim).filter(|s| !s.is_empty());
    let phone = phone.map(str::trim).filter(|s| !s.is_empty());
    if existing_phone.is_some() && existing_phone == phone {
        return None;
    }
    if existing_phone.is_some() {
        return Some("device_id already in use");
    }
    None
}

pub(crate) async fn ensure_chat_device_binding_allowed(
    state: &AppState,
    principal: &AuthPrincipal,
    raw_chat_device_id: &str,
    raw_client_device_id: Option<&str>,
) -> ApiResult<()> {
    let Some(auth) = state.auth.as_ref() else {
        return Ok(());
    };
    let account_id = principal.account_id.trim();
    if account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }
    let phone = principal
        .phone
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty());
    let chat_device_id = normalize_device_id(Some(raw_chat_device_id))
        .ok_or_else(|| ApiError::bad_request("chat device_id required"))?;
    let client_device_id = normalize_bound_client_device_id(principal, raw_client_device_id)?;

    let row = sqlx::query(
        "SELECT account_id, phone, client_device_id FROM auth_chat_devices WHERE chat_device_id=$1 AND revoked_at IS NULL LIMIT 1",
    )
    .bind(&chat_device_id)
    .fetch_optional(&auth.pool)
    .await
    .map_err(|e| {
        tracing::error!(
            error = %e,
            account_hash = %hash_prefix(account_id),
            chat_device_id_hash = %hash_prefix(&chat_device_id),
            "chat device bind precheck failed"
        );
        ApiError::internal("failed to register chat device")
    })?;

    let Some(row) = row else {
        return Ok(());
    };
    let existing_account_id: Option<String> = require_auth_optional_text_column(
        row.try_get("account_id"),
        "account_id",
        "chat_device_bind_precheck",
        "failed to register chat device",
    )?;
    let existing_phone: Option<String> = require_auth_optional_text_column(
        row.try_get("phone"),
        "phone",
        "chat_device_bind_precheck",
        "failed to register chat device",
    )?;
    let existing_client_device_id: Option<String> = require_auth_optional_text_column(
        row.try_get("client_device_id"),
        "client_device_id",
        "chat_device_bind_precheck",
        "failed to register chat device",
    )?;
    if let Some(reason) = chat_device_bind_conflict_reason(
        existing_account_id.as_deref(),
        existing_phone.as_deref(),
        existing_client_device_id.as_deref(),
        account_id,
        phone,
        client_device_id.as_deref(),
    ) {
        tracing::warn!(
            security_event = "chat_device_bind_precheck_rejected",
            outcome = "blocked",
            account_hash = %hash_prefix(account_id),
            chat_device_id_hash = %hash_prefix(&chat_device_id),
            reason,
            "chat device registration rejected before proxy side effects"
        );
        return Err(ApiError::new(StatusCode::FORBIDDEN, reason));
    }
    Ok(())
}

pub(crate) async fn require_chat_device_owned_by_principal(
    state: &AppState,
    principal: &AuthPrincipal,
    raw_device_id: &str,
) -> ApiResult<String> {
    let auth = state
        .auth
        .as_ref()
        .ok_or_else(|| ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"))?;
    let device_id = normalize_device_id(Some(raw_device_id))
        .ok_or_else(|| ApiError::bad_request("chat device_id required"))?;
    let account_id = principal.account_id.trim();
    if account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }

    let found_by_account = sqlx::query(
        "SELECT 1 FROM auth_chat_devices WHERE account_id=$1 AND chat_device_id=$2 AND revoked_at IS NULL LIMIT 1",
    )
    .bind(account_id)
    .bind(&device_id)
    .fetch_optional(&auth.pool)
        .await
        .map_err(|e| {
            tracing::error!(
                error = %e,
                account_hash = %hash_prefix(account_id),
                device_id_hash = %hash_prefix(&device_id),
                "chat device ownership lookup failed"
            );
            ApiError::internal("device ownership lookup failed")
        })?
    .is_some();
    if found_by_account {
        return Ok(device_id);
    }

    // Backwards-compatible fallback: legacy rows may still be bound by phone only.
    if let Some(phone) = principal
        .phone
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty())
    {
        let found_by_phone = sqlx::query(
            "SELECT 1 FROM auth_chat_devices WHERE phone=$1 AND chat_device_id=$2 AND revoked_at IS NULL LIMIT 1",
        )
        .bind(phone)
        .bind(&device_id)
        .fetch_optional(&auth.pool)
            .await
            .map_err(|e| {
                tracing::error!(
                    error = %e,
                    account_hash = %hash_prefix(account_id),
                    phone_hash = %hash_prefix(phone),
                    device_id_hash = %hash_prefix(&device_id),
                    "legacy chat device ownership fallback lookup failed"
                );
                ApiError::internal("device ownership lookup failed")
            })?
        .is_some();
        if found_by_phone {
            sqlx::query(
                "UPDATE auth_chat_devices SET account_id=$1 WHERE phone=$2 AND chat_device_id=$3 AND account_id IS NULL",
            )
            .bind(account_id)
            .bind(phone)
            .bind(&device_id)
            .execute(&auth.pool)
            .await
            .map_err(|e| {
                tracing::error!(
                    error = %e,
                    account_hash = %hash_prefix(account_id),
                    phone_hash = %hash_prefix(phone),
                    device_id_hash = %hash_prefix(&device_id),
                    "legacy chat device ownership account backfill failed"
                );
                legacy_chat_device_account_claim_failed(phone, ApiError::internal("device ownership lookup failed"))
            })?;
            return Ok(device_id);
        }
    }

    tracing::warn!(
        account_hash = %hash_prefix(account_id),
        device_id_hash = %hash_prefix(&device_id),
        "blocked chat request for non-owned or unregistered device"
    );
    Err(ApiError::new(
        StatusCode::FORBIDDEN,
        "device not registered for authenticated user",
    ))
}

fn legacy_chat_device_account_claim_failed(phone: &str, err: ApiError) -> ApiError {
    tracing::error!(
        error = ?err,
        phone_hash = %hash_prefix(phone),
        "legacy chat device ownership account claim failed"
    );
    err
}

fn resolve_redeem_contact_invite_issuer_account(
    invite_issuer_account_id: Option<&str>,
    active_chat_device_account_id: Option<&str>,
    issuer_chat_device_id: &str,
) -> ApiResult<Option<String>> {
    let invite_issuer_account_id = invite_issuer_account_id
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(ToString::to_string);
    let active_chat_device_account_id = active_chat_device_account_id
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(ToString::to_string);
    if let (Some(invite_account_id), Some(active_account_id)) = (
        invite_issuer_account_id.as_deref(),
        active_chat_device_account_id.as_deref(),
    ) {
        if invite_account_id != active_account_id {
            tracing::warn!(
                security_event = "contact_invite_redeem_issuer_mismatch",
                outcome = "blocked",
                issuer_chat_device_hash = %hash_prefix(issuer_chat_device_id),
                invite_account_hash = %hash_prefix(invite_account_id),
                active_account_hash = %hash_prefix(active_account_id),
                "contact invite issuer account drift detected"
            );
            return Err(ApiError::new(StatusCode::NOT_FOUND, "not found"));
        }
    }
    Ok(active_chat_device_account_id.or(invite_issuer_account_id))
}

fn requested_contact_invite_chat_device_id(headers: &HeaderMap) -> ApiResult<Option<String>> {
    let Some(raw_header_value) = headers.get("x-chat-device-id") else {
        return Ok(None);
    };
    let raw_device_id = raw_header_value
        .to_str()
        .map_err(|_| ApiError::bad_request("chat device_id required"))?;
    let Some(device_id) = normalize_device_id(Some(raw_device_id)) else {
        return Err(ApiError::bad_request("chat device_id required"));
    };
    Ok(Some(device_id))
}

fn normalize_device_login_challenge_status(raw: &str) -> Option<&'static str> {
    match raw.trim().to_ascii_lowercase().as_str() {
        "pending" => Some("pending"),
        "approved" => Some("approved"),
        "redeemed" => Some("redeemed"),
        _ => None,
    }
}

fn device_login_approve_allows_idempotent_replay(status: &str) -> bool {
    matches!(
        status.trim().to_ascii_lowercase().as_str(),
        "approved" | "redeemed"
    )
}

