fn device_login_redeem_replay_allowed(
    stored_client_ip_hash: Option<&str>,
    stored_user_agent_hash: Option<&str>,
    current_client_ip_hash: &str,
    current_user_agent_hash: &str,
) -> bool {
    let stored_client_ip_hash = stored_client_ip_hash
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let stored_user_agent_hash = stored_user_agent_hash
        .map(str::trim)
        .filter(|value| !value.is_empty());
    matches!(
        (stored_client_ip_hash, stored_user_agent_hash),
        (Some(ip_hash), Some(user_agent_hash))
            if ip_hash == current_client_ip_hash && user_agent_hash == current_user_agent_hash
    )
}

