fn biometric_login_attestation_failure_limit_key(token_hash: &str) -> String {
    format!("bio_login_attestation_fail:{token_hash}")
}

async fn clear_biometric_login_attestation_failure_tracking(auth: &AuthRuntime, token_hash: &str) {
    let key = biometric_login_attestation_failure_limit_key(token_hash);
    if let Err(e) = sqlx::query("DELETE FROM auth_rate_limits WHERE limit_key=$1")
        .bind(&key)
        .execute(&auth.pool)
        .await
    {
        tracing::error!(
            error = %e,
            limit_key_hash = hash_prefix(&key),
            token_hash_prefix = %token_hash_prefix(token_hash),
            "biometric login attestation failure counter cleanup failed"
        );
    }
}

async fn revoke_biometric_login_token_after_invalid_attestation(
    auth: &AuthRuntime,
    account_id: &str,
    device_id: &str,
    token_hash: &str,
    client_ip: Option<&str>,
) {
    match sqlx::query(
        "UPDATE auth_biometric_tokens \
         SET revoked_at=NOW(), next_token_hash=NULL \
         WHERE account_id=$1 AND device_id=$2 AND (token_hash=$3 OR next_token_hash=$3) AND revoked_at IS NULL",
    )
    .bind(account_id)
    .bind(device_id)
    .bind(token_hash)
    .execute(&auth.pool)
    .await
    {
        Ok(result) if result.rows_affected() >= 1 => {
            tracing::warn!(
                security_event = "biometric_login_attestation",
                outcome = "revoked",
                reason = "repeated_invalid_attestation",
                account_hash = %hash_prefix(account_id),
                device_id_hash = %hash_prefix(device_id),
                token_hash_prefix = %token_hash_prefix(token_hash),
                client_ip_hash = %client_ip.map(hash_prefix).unwrap_or_default(),
                failure_window_secs = BIOMETRIC_LOGIN_ATTESTATION_FAILURE_WINDOW_SECS,
                revoke_threshold = BIOMETRIC_LOGIN_ATTESTATION_FAILURE_REVOKE_THRESHOLD,
                "biometric login token revoked after repeated invalid attestation"
            );
            audit_device_login_event(
                "biometric_login_attestation",
                "revoked",
                client_ip,
                None,
                Some(token_hash),
                Some("repeated_invalid_attestation"),
            );
            clear_biometric_login_attestation_failure_tracking(auth, token_hash).await;
        }
        Ok(_) => {}
        Err(e) => {
            tracing::error!(
                error = %e,
                account_hash = %hash_prefix(account_id),
                device_id_hash = %hash_prefix(device_id),
                token_hash_prefix = %token_hash_prefix(token_hash),
                "biometric login token revoke after repeated invalid attestation failed"
            );
        }
    }
}

async fn record_biometric_login_attestation_failure(
    auth: &AuthRuntime,
    account_id: &str,
    device_id: &str,
    token_hash: &str,
    client_ip: Option<&str>,
) {
    let key = biometric_login_attestation_failure_limit_key(token_hash);
    match consume_rate_limit(
        auth,
        &key,
        BIOMETRIC_LOGIN_ATTESTATION_FAILURE_WINDOW_SECS,
        BIOMETRIC_LOGIN_ATTESTATION_FAILURE_REVOKE_THRESHOLD,
    )
    .await
    {
        Ok(()) => {
            let key = biometric_login_attestation_failure_limit_key(token_hash);
            match sqlx::query("SELECT request_count FROM auth_rate_limits WHERE limit_key=$1")
                .bind(&key)
                .fetch_optional(&auth.pool)
                .await
            {
                Ok(Some(row)) => {
                    let request_count = match row.try_get::<i64, _>("request_count") {
                        Ok(value) => value,
                        Err(e) => {
                            tracing::error!(
                                error = %e,
                                limit_key_hash = hash_prefix(&key),
                                account_hash = %hash_prefix(account_id),
                                device_id_hash = %hash_prefix(device_id),
                                token_hash_prefix = %token_hash_prefix(token_hash),
                                "biometric login attestation failure counter decode failed"
                            );
                            return;
                        }
                    };
                    if request_count >= BIOMETRIC_LOGIN_ATTESTATION_FAILURE_REVOKE_THRESHOLD {
                        revoke_biometric_login_token_after_invalid_attestation(
                            auth, account_id, device_id, token_hash, client_ip,
                        )
                        .await;
                    }
                }
                Ok(None) => {}
                Err(e) => {
                    tracing::error!(
                        error = %e,
                        limit_key_hash = hash_prefix(&key),
                        account_hash = %hash_prefix(account_id),
                        device_id_hash = %hash_prefix(device_id),
                        token_hash_prefix = %token_hash_prefix(token_hash),
                        "biometric login attestation failure counter read failed"
                    );
                }
            }
        }
        Err(err) if err.status == StatusCode::TOO_MANY_REQUESTS => {
            revoke_biometric_login_token_after_invalid_attestation(
                auth, account_id, device_id, token_hash, client_ip,
            )
            .await
        }
        Err(err) => {
            tracing::error!(
                error = ?err,
                limit_key_hash = hash_prefix(&key),
                account_hash = %hash_prefix(account_id),
                device_id_hash = %hash_prefix(device_id),
                token_hash_prefix = %token_hash_prefix(token_hash),
                "biometric login attestation failure counter update failed"
            );
        }
    }
}

async fn resolve_biometric_login_account_id(
    auth: &AuthRuntime,
    device_id: &str,
    token_hash: &str,
    token_hash_pref: &str,
    account_id_db: Option<&str>,
    phone_opt: Option<&str>,
) -> ApiResult<Option<String>> {
    let account_id = account_id_db
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToString::to_string);
    if account_id.is_some() {
        return Ok(account_id);
    }
    let Some(phone) = phone_opt.map(str::trim).filter(|value| !value.is_empty()) else {
        return Ok(None);
    };
    let account_id = ensure_account_id_for_phone(auth, phone).await?;
    sqlx::query(
        "UPDATE auth_biometric_tokens SET account_id=$1 WHERE device_id=$2 AND account_id IS NULL AND (token_hash=$3 OR next_token_hash=$3)",
    )
    .bind(&account_id)
    .bind(device_id)
    .bind(token_hash)
    .execute(&auth.pool)
    .await
    .map_err(|_| {
        biometric_token_account_backfill_failed(
            device_id,
            ApiError::internal("auth_biometric_tokens account backfill failed"),
        )
    })?;
    tracing::info!(
        security_event = "biometric_login",
        outcome = "account_backfilled",
        token_hash_prefix = token_hash_pref,
        device_id_hash = %hash_prefix(device_id),
        account_hash = %hash_prefix(&account_id),
        "backfilled legacy biometric token account binding from phone"
    );
    Ok(Some(account_id))
}

fn derive_rotated_biometric_login_token(device_id: &str, current_token: &str) -> String {
    let next = sha256_hex(&format!("bio-rotate:v1:{device_id}:{current_token}"));
    if next != current_token {
        return next;
    }
    sha256_hex(&format!("bio-rotate:v1b:{device_id}:{current_token}"))
}

fn biometric_token_match_kind(
    matched_current: bool,
    matched_next: bool,
) -> Option<BiometricTokenMatchKind> {
    match (matched_current, matched_next) {
        (true, false) => Some(BiometricTokenMatchKind::Current),
        (false, true) => Some(BiometricTokenMatchKind::PendingNext),
        _ => None,
    }
}

