pub(crate) async fn require_chat_contact_allowed_for_direct_send(
    state: &AppState,
    principal: &AuthPrincipal,
    raw_recipient_device_id: &str,
) -> ApiResult<()> {
    let auth = require_auth_runtime(state)?;
    let account_id = principal.account_id.trim();
    if account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }
    let recipient_device_id = normalize_device_id(Some(raw_recipient_device_id))
        .ok_or_else(|| ApiError::bad_request("invalid recipient_id"))?;

    // Always allow sends to self-owned devices (multi-device sync / web login flows).
    let self_owned = match sqlx::query(
        "SELECT 1 FROM auth_chat_devices WHERE account_id=$1 AND chat_device_id=$2 AND revoked_at IS NULL LIMIT 1",
    )
    .bind(account_id)
    .bind(&recipient_device_id)
    .fetch_optional(&auth.pool)
    .await
    {
        Ok(row) => row.is_some(),
        Err(e) => {
            return Err(contact_enforcement_lookup_failed(
                &e,
                account_id,
                &recipient_device_id,
            ));
        }
    };
    if self_owned {
        return Ok(());
    }

    let allowed = match sqlx::query(AUTH_CHAT_CONTACT_ACTIVE_LOOKUP_SQL)
        .bind(account_id)
        .bind(&recipient_device_id)
        .fetch_optional(&auth.pool)
        .await
    {
        Ok(row) => row.is_some(),
        Err(e) => {
            return Err(contact_enforcement_lookup_failed(
                &e,
                account_id,
                &recipient_device_id,
            ));
        }
    };
    if !allowed {
        // Fail closed: avoid revealing whether the recipient exists.
        return Err(ApiError::new(StatusCode::NOT_FOUND, "not found"));
    }
    Ok(())
}

pub(crate) async fn bind_chat_device_to_principal(
    state: &AppState,
    principal: &AuthPrincipal,
    raw_chat_device_id: &str,
    raw_client_device_id: Option<&str>,
) -> ApiResult<()> {
    let Some(auth) = state.auth.as_ref() else {
        return Ok(());
    };
    let account_id = principal.account_id.trim();
    if account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }
    let phone = principal
        .phone
        .as_deref()
        .map(str::trim)
        .filter(|s| !s.is_empty());
    let chat_device_id = normalize_device_id(Some(raw_chat_device_id))
        .ok_or_else(|| ApiError::bad_request("chat device_id required"))?;
    let client_device_id = normalize_bound_client_device_id(principal, raw_client_device_id)?;

    let r = sqlx::query(
        r#"
        INSERT INTO auth_chat_devices
          (account_id, phone, chat_device_id, client_device_id, created_at, last_seen_at, revoked_at)
        VALUES
          ($1, $2, $3, $4, NOW(), NOW(), NULL)
        ON CONFLICT (chat_device_id)
        DO UPDATE SET
          account_id = CASE
            WHEN auth_chat_devices.account_id IS NULL THEN EXCLUDED.account_id
            WHEN auth_chat_devices.account_id = EXCLUDED.account_id THEN auth_chat_devices.account_id
            WHEN auth_chat_devices.client_device_id IS NOT NULL
                 AND EXCLUDED.client_device_id IS NOT NULL
                 AND auth_chat_devices.client_device_id = EXCLUDED.client_device_id
              THEN EXCLUDED.account_id
            ELSE auth_chat_devices.account_id
          END,
          phone = CASE
            WHEN auth_chat_devices.account_id IS NULL
                 OR auth_chat_devices.account_id = EXCLUDED.account_id
                 OR (
                   auth_chat_devices.client_device_id IS NOT NULL
                   AND EXCLUDED.client_device_id IS NOT NULL
                   AND auth_chat_devices.client_device_id = EXCLUDED.client_device_id
                 )
              THEN COALESCE(EXCLUDED.phone, auth_chat_devices.phone)
            ELSE auth_chat_devices.phone
          END,
          client_device_id = COALESCE(EXCLUDED.client_device_id, auth_chat_devices.client_device_id),
          last_seen_at = NOW(),
          revoked_at = NULL
        WHERE
          (auth_chat_devices.account_id IS NOT NULL AND auth_chat_devices.account_id = EXCLUDED.account_id)
          OR
          (auth_chat_devices.account_id IS NULL AND auth_chat_devices.phone IS NOT NULL AND auth_chat_devices.phone = EXCLUDED.phone)
          OR
          (
            auth_chat_devices.client_device_id IS NOT NULL
            AND EXCLUDED.client_device_id IS NOT NULL
            AND auth_chat_devices.client_device_id = EXCLUDED.client_device_id
          )
        "#,
    )
    .bind(account_id)
    .bind(phone)
    .bind(&chat_device_id)
    .bind(client_device_id.as_deref())
    .execute(&auth.pool)
    .await
    .map_err(|e| {
        tracing::error!(
            error = %e,
            account_hash = %hash_prefix(account_id),
            chat_device_id_hash = %hash_prefix(&chat_device_id),
            "chat device bind failed"
        );
        ApiError::internal("failed to register chat device")
    })?;

    if r.rows_affected() == 0 {
        tracing::warn!(
            security_event = "chat_device_bind_rejected",
            outcome = "blocked",
            account_hash = %hash_prefix(account_id),
            chat_device_id_hash = %hash_prefix(&chat_device_id),
            "chat device id already bound to a different user"
        );
        return Err(ApiError::new(
            StatusCode::FORBIDDEN,
            "device id already in use",
        ));
    }
    if let Some(client_device_id) = client_device_id.as_deref() {
        sqlx::query(AUTH_CHAT_DEVICES_CLIENT_DEVICE_SIBLINGS_REVOKE_SQL)
            .bind(account_id)
            .bind(client_device_id)
            .bind(&chat_device_id)
            .execute(&auth.pool)
            .await
            .map_err(|e| {
                tracing::error!(
                    error = %e,
                    account_hash = %hash_prefix(account_id),
                    client_device_id_hash = %hash_prefix(client_device_id),
                    chat_device_id_hash = %hash_prefix(&chat_device_id),
                    "chat device sibling revoke failed"
                );
                ApiError::internal("failed to register chat device")
            })?;
    }
    Ok(())
}

pub(crate) async fn enforce_chat_register_rate_limit(
    state: &AppState,
    headers: &HeaderMap,
    device_id: Option<&str>,
) -> ApiResult<()> {
    let Some(auth) = state.auth.as_ref() else {
        return Ok(());
    };
    let client_ip = rate_limit_client_ip(state, headers)?;
    consume_rate_limit(
        auth,
        &format!("chat_register_ip:{}", sha256_hex(&client_ip)),
        auth.chat_register_window_secs,
        auth.chat_register_max_per_ip,
    )
    .await?;
    if let Some(device_id) = normalize_device_id(device_id) {
        consume_rate_limit(
            auth,
            &format!("chat_register_device:{}", sha256_hex(&device_id)),
            auth.chat_register_window_secs,
            auth.chat_register_max_per_device,
        )
        .await?;
    }
    Ok(())
}

pub(crate) async fn enforce_chat_get_device_rate_limit(
    state: &AppState,
    headers: &HeaderMap,
    _device_id: &str,
) -> ApiResult<()> {
    let Some(auth) = state.auth.as_ref() else {
        return Ok(());
    };
    let client_ip = rate_limit_client_ip(state, headers)?;
    consume_rate_limit(
        auth,
        &format!("chat_get_device_ip:{}", sha256_hex(&client_ip)),
        auth.chat_get_device_window_secs,
        auth.chat_get_device_max_per_ip,
    )
    .await?;
    if let Some(device_id) = chat_request_rate_limit_device_id(headers) {
        consume_rate_limit(
            auth,
            &format!("chat_get_device_device:{}", sha256_hex(&device_id)),
            auth.chat_get_device_window_secs,
            auth.chat_get_device_max_per_device,
        )
        .await?;
    }
    Ok(())
}

