fn is_official_public_mutation_rate_limit_operation(operation: &str) -> bool {
    matches!(
        operation,
        "official_accounts_follow"
            | "official_accounts_unfollow"
            | "official_accounts_set_notification_mode"
    )
}

pub(crate) async fn enforce_official_public_mutation_rate_limit(
    state: &AppState,
    headers: &HeaderMap,
    principal: &AuthPrincipal,
    operation: &'static str,
) -> ApiResult<()> {
    let Some(auth) = state.auth.as_ref() else {
        return Ok(());
    };
    if !is_official_public_mutation_rate_limit_operation(operation) {
        tracing::error!(
            operation,
            "official public mutation rate-limit invoked with unsupported operation"
        );
        return Err(ApiError::internal("rate-limit unavailable"));
    }
    let account_id = principal.account_id.trim();
    if account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }
    let client_ip = rate_limit_client_ip(state, headers)?;
    consume_rate_limit(
        auth,
        &format!(
            "official_public_mutation_ip:{operation}:{}",
            sha256_hex(&client_ip)
        ),
        OFFICIAL_PUBLIC_MUTATION_WINDOW_SECS,
        OFFICIAL_PUBLIC_MUTATION_MAX_PER_IP,
    )
    .await?;
    consume_rate_limit(
        auth,
        &format!(
            "official_public_mutation_account:{operation}:{}",
            sha256_hex(account_id)
        ),
        OFFICIAL_PUBLIC_MUTATION_WINDOW_SECS,
        OFFICIAL_PUBLIC_MUTATION_MAX_PER_ACCOUNT,
    )
    .await?;
    Ok(())
}

fn is_payment_mutation_rate_limit_operation(operation: &str) -> bool {
    matches!(
        operation,
        "payments_create_user"
            | "payments_transfer"
            | "payments_topup"
            | "payments_favorites_create"
            | "payments_favorites_delete"
            | "payments_requests_create"
            | "payments_requests_accept"
            | "payments_requests_cancel"
    )
}

