pub(crate) async fn create_contact_invite(
    state: &AppState,
    headers: &HeaderMap,
    principal: &AuthPrincipal,
    requested_max_uses: i64,
) -> ApiResult<(String, String, i64)> {
    let auth = require_auth_runtime(state)?;
    let account_id = principal.account_id.trim();
    if account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }

    let requested_chat_device_id =
        requested_contact_invite_chat_device_id(headers).map_err(|err| {
            tracing::warn!(
                account_hash = %hash_prefix(account_id),
                error = ?err,
                "contact invite create rejected malformed requested chat device id"
            );
            err
        })?;
    if requested_chat_device_id.is_none() && !state.allow_legacy_contact_invite_chat_device_fallback
    {
        log_contact_invite_create_chat_device_header_missing(account_id);
        return Err(ApiError::bad_request("chat device_id required"));
    }

    enforce_contact_invite_create_rate_limit(state, headers, principal).await?;

    let issuer_chat_device_id = match requested_chat_device_id {
        Some(requested_chat_device_id) => {
            require_chat_device_owned_by_principal(state, principal, &requested_chat_device_id)
                .await?
        }
        None => {
            // Backward-compatible fallback for older clients that do not yet
            // send the active chat device explicitly.
            let mut row = sqlx::query(AUTH_CHAT_DEVICES_ACCOUNT_ACTIVE_LAST_SEEN_LOOKUP_SQL)
                .bind(account_id)
                .fetch_optional(&auth.pool)
                .await
                .map_err(|e| {
                    tracing::error!(
                        error = %e,
                        account_hash = %hash_prefix(account_id),
                        "auth_chat_devices lookup failed for contact invite"
                    );
                    ApiError::internal("failed to create invite")
                })?;
            if row.is_none() {
                if let Some(p) = principal
                    .phone
                    .as_deref()
                    .map(str::trim)
                    .filter(|s| !s.is_empty())
                {
                    row = sqlx::query(AUTH_CHAT_DEVICES_PHONE_ACTIVE_LAST_SEEN_LOOKUP_SQL)
                        .bind(p)
                        .fetch_optional(&auth.pool)
                        .await
                        .map_err(|e| {
                            tracing::error!(
                                error = %e,
                                account_hash = %hash_prefix(account_id),
                                phone_hash = %hash_prefix(p),
                                "legacy auth_chat_devices lookup failed for contact invite"
                            );
                            ApiError::internal("failed to create invite")
                        })?;
                }
            }
            let Some(row) = row else {
                return Err(ApiError::new(
                    StatusCode::CONFLICT,
                    "chat device not registered",
                ));
            };
            let issuer_chat_device_id: String = require_auth_text_column(
                row.try_get("chat_device_id"),
                "chat_device_id",
                "contact_invite_create_legacy_chat_device_lookup",
                "failed to create invite",
            )?;
            let issuer_chat_device_id = issuer_chat_device_id.trim().to_string();
            if issuer_chat_device_id.is_empty() {
                return Err(ApiError::new(
                    StatusCode::CONFLICT,
                    "chat device not registered",
                ));
            }
            log_contact_invite_create_legacy_chat_device_fallback(
                account_id,
                &issuer_chat_device_id,
            );
            issuer_chat_device_id
        }
    };

    // High-entropy capability token: never store plaintext, only its hash.
    let token = generate_token_hex_32();
    let token_hash = sha256_hex(&token);
    let max_uses = requested_max_uses.clamp(1, 20);

    let inserted = sqlx::query(
        r#"
        INSERT INTO auth_contact_invites
          (token_hash, issuer_account_id, issuer_phone, issuer_chat_device_id, max_uses, use_count, created_at, last_redeemed_at, expires_at, revoked_at)
        VALUES
          ($1, $2, NULL, $3, $4, 0, NOW(), NULL, NOW() + ($5::bigint * INTERVAL '1 second'), NULL)
        RETURNING expires_at::text as expires_at
        "#,
    )
    .bind(&token_hash)
    .bind(account_id)
    .bind(&issuer_chat_device_id)
    .bind(max_uses as i32)
    .bind(auth.contact_invite_ttl_secs)
    .fetch_one(&auth.pool)
    .await
    .map_err(|e| {
        tracing::error!(
            error = %e,
            account_hash = %hash_prefix(account_id),
            token_hash = %token_hash_prefix(&token_hash),
            "auth_contact_invites insert failed"
        );
        ApiError::internal("failed to create invite")
    })?;

    let expires_at: String = require_auth_text_column(
        inserted.try_get("expires_at"),
        "expires_at",
        "contact_invite_create_insert",
        "failed to create invite",
    )?;
    let expires_at = expires_at.trim().to_string();
    if expires_at.is_empty() {
        tracing::error!(
            account_hash = %hash_prefix(account_id),
            token_hash = %token_hash_prefix(&token_hash),
            "contact invite insert returned empty expires_at"
        );
        return Err(ApiError::internal("failed to create invite"));
    }
    Ok((token, expires_at, max_uses))
}

pub(crate) async fn resolve_account_id_by_shamell_id(
    state: &AppState,
    raw_shamell_id: &str,
) -> ApiResult<(String, String)> {
    let auth = require_auth_runtime(state)?;
    let shamell_user_id = normalize_shamell_user_id(raw_shamell_id)
        .ok_or_else(|| ApiError::bad_request("invalid shamell_id"))?;
    let row = sqlx::query("SELECT account_id FROM auth_accounts WHERE shamell_user_id=$1 LIMIT 1")
        .bind(&shamell_user_id)
        .fetch_optional(&auth.pool)
        .await
        .map_err(|e| {
            tracing::error!(
                error = %e,
                shamell_id_hash = %hash_prefix(&shamell_user_id),
                "auth_accounts shamell_id account resolve lookup failed"
            );
            ApiError::internal("failed to resolve Shamell ID")
        })?
        .ok_or_else(|| ApiError::new(StatusCode::NOT_FOUND, "shamell_id not found"))?;
    let account_id: String = require_auth_text_column(
        row.try_get("account_id"),
        "account_id",
        "resolve_account_id_by_shamell_id",
        "failed to resolve Shamell ID",
    )?;
    let account_id = account_id.trim().to_string();
    if account_id.is_empty() {
        return Err(ApiError::new(StatusCode::NOT_FOUND, "shamell_id not found"));
    }
    Ok((account_id, shamell_user_id))
}

pub(crate) async fn resolve_contact_by_shamell_id(
    state: &AppState,
    headers: &HeaderMap,
    principal: &AuthPrincipal,
    raw_shamell_id: &str,
) -> ApiResult<String> {
    let auth = require_auth_runtime(state)?;
    let account_id = principal.account_id.trim();
    if account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }
    enforce_contact_resolve_rate_limit(state, headers, principal).await?;
    let shamell_user_id = normalize_shamell_user_id(raw_shamell_id)
        .ok_or_else(|| ApiError::bad_request("invalid shamell_id"))?;

    let peer_account_row =
        sqlx::query("SELECT account_id FROM auth_accounts WHERE shamell_user_id=$1 LIMIT 1")
            .bind(&shamell_user_id)
            .fetch_optional(&auth.pool)
            .await
            .map_err(|e| {
                tracing::error!(
                    error = %e,
                    shamell_id_hash = %hash_prefix(&shamell_user_id),
                    "auth_accounts shamell_id resolve lookup failed"
                );
                ApiError::internal("contact resolve unavailable")
            })?;
    let Some(peer_account_row) = peer_account_row else {
        return Err(ApiError::new(StatusCode::NOT_FOUND, "not found"));
    };
    let peer_account_id: String = require_auth_text_column(
        peer_account_row.try_get("account_id"),
        "account_id",
        "contact_resolve_by_shamell_id_account_lookup",
        "contact resolve unavailable",
    )?;
    let peer_account_id = peer_account_id.trim().to_string();
    if peer_account_id.is_empty() {
        return Err(ApiError::new(StatusCode::NOT_FOUND, "not found"));
    }
    if peer_account_id == account_id {
        return Err(ApiError::bad_request("cannot add own shamell id"));
    }

    let requester_chat_device_id = header_value(headers, "x-chat-device-id")
        .and_then(|v| normalize_device_id(Some(&v)))
        .ok_or_else(|| ApiError::new(StatusCode::CONFLICT, "chat device not registered"))?;
    let requester_chat_device_id =
        require_chat_device_owned_by_principal(state, principal, &requester_chat_device_id).await?;

    let peer_device_row = sqlx::query(AUTH_CHAT_DEVICES_ACCOUNT_ACTIVE_LAST_SEEN_LOOKUP_SQL)
        .bind(&peer_account_id)
        .fetch_optional(&auth.pool)
        .await
        .map_err(|e| {
            tracing::error!(
                error = %e,
                shamell_id_hash = %hash_prefix(&shamell_user_id),
                peer_account_hash = %hash_prefix(&peer_account_id),
                "auth_chat_devices active lookup failed for shamell-id resolve"
            );
            ApiError::internal("contact resolve unavailable")
        })?;
    let Some(peer_device_row) = peer_device_row else {
        return Err(ApiError::new(StatusCode::NOT_FOUND, "not found"));
    };
    let peer_chat_device_id: String = require_auth_text_column(
        peer_device_row.try_get("chat_device_id"),
        "chat_device_id",
        "contact_resolve_by_shamell_id_peer_device_lookup",
        "contact resolve unavailable",
    )?;
    let peer_chat_device_id = peer_chat_device_id.trim().to_string();
    if peer_chat_device_id.is_empty() {
        return Err(ApiError::new(StatusCode::NOT_FOUND, "not found"));
    }

    let mut tx = auth.pool.begin().await.map_err(|e| {
        tracing::error!(
            error = %e,
            account_hash = %hash_prefix(account_id),
            shamell_id_hash = %hash_prefix(&shamell_user_id),
            "contact resolve tx begin failed"
        );
        ApiError::internal("contact resolve unavailable")
    })?;

    let _ = sqlx::query(
        r#"
        INSERT INTO auth_chat_contacts
          (owner_account_id, peer_chat_device_id, created_at, last_used_at, revoked_at)
        VALUES
          ($1, $2, NOW(), NOW(), NULL)
        ON CONFLICT (owner_account_id, peer_chat_device_id)
        DO UPDATE SET
          last_used_at = NOW(),
          revoked_at = NULL
        "#,
    )
    .bind(account_id)
    .bind(&peer_chat_device_id)
    .execute(&mut *tx)
    .await
    .map_err(|e| {
        tracing::error!(
            error = %e,
            account_hash = %hash_prefix(account_id),
            peer_chat_device_hash = %hash_prefix(&peer_chat_device_id),
            "auth_chat_contacts upsert failed (resolver->peer)"
        );
        ApiError::internal("contact resolve unavailable")
    })?;

    let _ = sqlx::query(
        r#"
        INSERT INTO auth_chat_contacts
          (owner_account_id, peer_chat_device_id, created_at, last_used_at, revoked_at)
        VALUES
          ($1, $2, NOW(), NOW(), NULL)
        ON CONFLICT (owner_account_id, peer_chat_device_id)
        DO UPDATE SET
          last_used_at = NOW(),
          revoked_at = NULL
        "#,
    )
    .bind(&peer_account_id)
    .bind(&requester_chat_device_id)
    .execute(&mut *tx)
    .await
    .map_err(|e| {
        tracing::error!(
            error = %e,
            peer_account_hash = %hash_prefix(&peer_account_id),
            requester_chat_device_hash = %hash_prefix(&requester_chat_device_id),
            "auth_chat_contacts upsert failed (peer->resolver)"
        );
        ApiError::internal("contact resolve unavailable")
    })?;

    tx.commit().await.map_err(|e| {
        tracing::error!(
            error = %e,
            account_hash = %hash_prefix(account_id),
            shamell_id_hash = %hash_prefix(&shamell_user_id),
            "contact resolve tx commit failed"
        );
        ApiError::internal("contact resolve unavailable")
    })?;

    Ok(peer_chat_device_id)
}

pub(crate) async fn redeem_contact_invite(
    state: &AppState,
    headers: &HeaderMap,
    principal: &AuthPrincipal,
    raw_token: &str,
) -> ApiResult<String> {
    let auth = require_auth_runtime(state)?;
    let account_id = principal.account_id.trim();
    if account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }

    let token =
        normalize_hex_64(raw_token).ok_or_else(|| ApiError::bad_request("invalid token"))?;
    // Validate the active redeemer chat device before burning redeem rate limits.
    let redeemer_chat_device_id = header_value(headers, "x-chat-device-id")
        .and_then(|value| normalize_device_id(Some(&value)))
        .ok_or_else(|| ApiError::new(StatusCode::CONFLICT, "chat device not registered"))?;
    let redeemer_chat_device_id =
        require_chat_device_owned_by_principal(state, principal, &redeemer_chat_device_id).await?;
    enforce_contact_invite_redeem_identity_rate_limit(state, headers, principal).await?;

    let token_hash = sha256_hex(&token);
    let mut tx = auth.pool.begin().await.map_err(|e| {
        tracing::error!(
            error = %e,
            token_hash = %token_hash_prefix(&token_hash),
            "contact invite redeem tx begin failed"
        );
        ApiError::internal("invite redeem unavailable")
    })?;

    let row = sqlx::query(
        r#"
        SELECT
          id,
          issuer_account_id,
          issuer_phone,
          issuer_chat_device_id,
          use_count,
          max_uses,
          (revoked_at IS NOT NULL) AS revoked,
          (expires_at > NOW()) AS alive
        FROM auth_contact_invites
        WHERE token_hash=$1
        LIMIT 1
        FOR UPDATE
        "#,
    )
    .bind(&token_hash)
    .fetch_optional(&mut *tx)
    .await
    .map_err(|e| {
        tracing::error!(
            error = %e,
            token_hash = %token_hash_prefix(&token_hash),
            "contact invite redeem select failed"
        );
        ApiError::internal("invite redeem unavailable")
    })?;

    let Some(row) = row else {
        // Fail closed: do not reveal whether the token ever existed.
        let _ = tx.rollback().await;
        return Err(ApiError::new(StatusCode::NOT_FOUND, "not found"));
    };

    let id = require_contact_invite_redeem_i64_column(
        &row,
        &token_hash,
        "id",
        "invite redeem unavailable",
    )?;
    let issuer_account_id: Option<String> = row.try_get("issuer_account_id").map_err(|e| {
        tracing::error!(
            error = %e,
            token_hash = %token_hash_prefix(&token_hash),
            column = "issuer_account_id",
            "contact invite redeem column decode failed"
        );
        ApiError::internal("invite redeem unavailable")
    })?;
    let issuer_phone: Option<String> = row.try_get("issuer_phone").map_err(|e| {
        tracing::error!(
            error = %e,
            token_hash = %token_hash_prefix(&token_hash),
            column = "issuer_phone",
            "contact invite redeem column decode failed"
        );
        ApiError::internal("invite redeem unavailable")
    })?;
    let issuer_chat_device_id: String = row.try_get("issuer_chat_device_id").map_err(|e| {
        tracing::error!(
            error = %e,
            token_hash = %token_hash_prefix(&token_hash),
            column = "issuer_chat_device_id",
            "contact invite redeem column decode failed"
        );
        ApiError::internal("invite redeem unavailable")
    })?;
    let use_count = require_contact_invite_redeem_i64_column(
        &row,
        &token_hash,
        "use_count",
        "invite redeem unavailable",
    )?;
    let max_uses = require_contact_invite_redeem_i64_column(
        &row,
        &token_hash,
        "max_uses",
        "invite redeem unavailable",
    )?;
    let revoked: bool = row.try_get("revoked").map_err(|e| {
        tracing::error!(
            error = %e,
            token_hash = %token_hash_prefix(&token_hash),
            column = "revoked",
            "contact invite redeem column decode failed"
        );
        ApiError::internal("invite redeem unavailable")
    })?;
    let alive: bool = row.try_get("alive").map_err(|e| {
        tracing::error!(
            error = %e,
            token_hash = %token_hash_prefix(&token_hash),
            column = "alive",
            "contact invite redeem column decode failed"
        );
        ApiError::internal("invite redeem unavailable")
    })?;
    if contact_invite_redeemer_matches_issuer(
        issuer_account_id.as_deref(),
        issuer_phone.as_deref(),
        account_id,
        principal.phone.as_deref(),
    ) {
        let _ = tx.rollback().await;
        return Err(ApiError::bad_request("cannot redeem own invite"));
    }

    let issuer_chat_device_id = issuer_chat_device_id.trim().to_string();
    if issuer_chat_device_id.is_empty() {
        let _ = tx.rollback().await;
        return Err(ApiError::new(StatusCode::NOT_FOUND, "not found"));
    }
    let active_issuer_chat_device_row = sqlx::query(AUTH_CHAT_DEVICE_ACTIVE_OWNER_FOR_UPDATE_SQL)
        .bind(&issuer_chat_device_id)
        .fetch_optional(&mut *tx)
        .await
        .map_err(|e| {
            tracing::error!(
                error = %e,
                token_hash = %token_hash_prefix(&token_hash),
                issuer_chat_device_hash = %hash_prefix(&issuer_chat_device_id),
                "auth_chat_devices active issuer lookup failed for contact invite redeem"
            );
            ApiError::internal("invite redeem unavailable")
        })?;
    let Some(active_issuer_chat_device_row) = active_issuer_chat_device_row else {
        let _ = tx.rollback().await;
        return Err(ApiError::new(StatusCode::NOT_FOUND, "not found"));
    };
    let active_issuer_account_id: Option<String> = active_issuer_chat_device_row
        .try_get::<Option<String>, _>("account_id")
        .map_err(|e| {
            tracing::error!(
                error = %e,
                token_hash = %token_hash_prefix(&token_hash),
                column = "account_id",
                "contact invite redeem issuer-account decode failed"
            );
            ApiError::internal("invite redeem unavailable")
        })?;
    let redeemer_already_has_contact = sqlx::query(AUTH_CHAT_CONTACT_ACTIVE_LOOKUP_SQL)
        .bind(account_id)
        .bind(&issuer_chat_device_id)
        .fetch_optional(&mut *tx)
        .await
        .map_err(|e| {
            tracing::error!(
                error = %e,
                token_hash = %token_hash_prefix(&token_hash),
                account_hash = %hash_prefix(account_id),
                issuer_chat_device_hash = %hash_prefix(&issuer_chat_device_id),
                "contact invite redeem active-contact lookup failed"
            );
            ApiError::internal("invite redeem unavailable")
        })?
        .is_some();

    if revoked || !alive || use_count >= max_uses {
        if redeemer_already_has_contact {
            let _ = tx.rollback().await;
            tracing::info!(
                security_event = "contact_invite_redeem",
                outcome = "already_redeemed",
                account_hash = %hash_prefix(account_id),
                issuer_chat_device_hash = %hash_prefix(&issuer_chat_device_id),
                token_hash = %token_hash_prefix(&token_hash),
                "contact invite redeem returned existing active contact edge"
            );
            return Ok(issuer_chat_device_id);
        }
        let _ = tx.rollback().await;
        return Err(ApiError::new(StatusCode::NOT_FOUND, "not found"));
    }
    if redeemer_already_has_contact {
        let _ = tx.rollback().await;
        tracing::info!(
            security_event = "contact_invite_redeem",
            outcome = "already_redeemed",
            account_hash = %hash_prefix(account_id),
            issuer_chat_device_hash = %hash_prefix(&issuer_chat_device_id),
            token_hash = %token_hash_prefix(&token_hash),
            "contact invite redeem skipped duplicate active contact edge"
        );
        return Ok(issuer_chat_device_id);
    }

    enforce_contact_invite_redeem_token_rate_limit(state, &token).await?;

    let _ = sqlx::query(
        r#"
        UPDATE auth_contact_invites
        SET
          use_count = use_count + 1,
          last_redeemed_at = NOW(),
          revoked_at = CASE WHEN use_count + 1 >= max_uses THEN NOW() ELSE revoked_at END
        WHERE id=$1
        "#,
    )
    .bind(id)
    .execute(&mut *tx)
    .await
    .map_err(|e| {
        tracing::error!(
            error = %e,
            token_hash = %token_hash_prefix(&token_hash),
            "contact invite redeem update failed"
        );
        ApiError::internal("invite redeem unavailable")
    })?;

    // Create/refresh contact edges for both sides (account-level).
    // This enables strict "invite-only first contact" enforcement on direct sends.
    let _ = sqlx::query(
        r#"
        INSERT INTO auth_chat_contacts
          (owner_account_id, peer_chat_device_id, created_at, last_used_at, revoked_at)
        VALUES
          ($1, $2, NOW(), NOW(), NULL)
        ON CONFLICT (owner_account_id, peer_chat_device_id)
        DO UPDATE SET
          last_used_at = NOW(),
          revoked_at = NULL
        "#,
    )
    .bind(account_id)
    .bind(&issuer_chat_device_id)
    .execute(&mut *tx)
    .await
    .map_err(|e| {
        tracing::error!(
            error = %e,
            token_hash = %token_hash_prefix(&token_hash),
            account_hash = %hash_prefix(account_id),
            "auth_chat_contacts upsert failed (redeemer->issuer)"
        );
        ApiError::internal("invite redeem unavailable")
    })?;

    // Resolve issuer account id (prefer invite row, fall back to chat-device mapping).
    let issuer_account_id_opt = resolve_redeem_contact_invite_issuer_account(
        issuer_account_id.as_deref(),
        active_issuer_account_id.as_deref(),
        &issuer_chat_device_id,
    )?;
    if let Some(issuer_acc) = issuer_account_id_opt.as_deref() {
        if issuer_acc != account_id {
            let _ = sqlx::query(
                r#"
                INSERT INTO auth_chat_contacts
                  (owner_account_id, peer_chat_device_id, created_at, last_used_at, revoked_at)
                VALUES
                  ($1, $2, NOW(), NOW(), NULL)
                ON CONFLICT (owner_account_id, peer_chat_device_id)
                DO UPDATE SET
                  last_used_at = NOW(),
                  revoked_at = NULL
                "#,
            )
            .bind(issuer_acc)
            .bind(&redeemer_chat_device_id)
            .execute(&mut *tx)
            .await
            .map_err(|e| {
                tracing::error!(
                    error = %e,
                    token_hash = %token_hash_prefix(&token_hash),
                    issuer_account_hash = %hash_prefix(issuer_acc),
                    "auth_chat_contacts upsert failed (issuer->redeemer)"
                );
                ApiError::internal("invite redeem unavailable")
            })?;
        }
    }

    tx.commit().await.map_err(|e| {
        tracing::error!(
            error = %e,
            token_hash = %token_hash_prefix(&token_hash),
            "contact invite redeem tx commit failed"
        );
        ApiError::internal("invite redeem unavailable")
    })?;

    Ok(issuer_chat_device_id)
}

fn require_contact_invite_redeem_i64_column(
    row: &sqlx::postgres::PgRow,
    token_hash: &str,
    column: &'static str,
    failure_detail: &'static str,
) -> ApiResult<i64> {
    match row.try_get::<i64, _>(column) {
        Ok(value) => Ok(value),
        Err(err_i64) => match row.try_get::<i32, _>(column) {
            Ok(value) => Ok(i64::from(value)),
            Err(err_i32) => {
                tracing::error!(
                    error = %err_i64,
                    fallback_error = %err_i32,
                    token_hash = %token_hash_prefix(token_hash),
                    column,
                    "contact invite redeem column decode failed"
                );
                Err(ApiError::internal(failure_detail))
            }
        },
    }
}

fn normalize_non_empty_identity_value(value: Option<&str>) -> Option<&str> {
    value.map(str::trim).filter(|v| !v.is_empty())
}

fn is_official_public_read_rate_limit_operation(operation: &str) -> bool {
    matches!(
        operation,
        "official_accounts_list"
            | "official_accounts_notifications"
            | "official_account_auto_replies"
    )
}

pub(crate) async fn enforce_official_public_read_rate_limit(
    state: &AppState,
    headers: &HeaderMap,
    principal: &AuthPrincipal,
    operation: &'static str,
) -> ApiResult<()> {
    let Some(auth) = state.auth.as_ref() else {
        return Ok(());
    };
    if !is_official_public_read_rate_limit_operation(operation) {
        tracing::error!(
            operation,
            "official public read rate-limit invoked with unsupported operation"
        );
        return Err(ApiError::internal("rate-limit unavailable"));
    }
    let account_id = principal.account_id.trim();
    if account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }
    let client_ip = rate_limit_client_ip(state, headers)?;
    consume_rate_limit(
        auth,
        &format!(
            "official_public_read_ip:{operation}:{}",
            sha256_hex(&client_ip)
        ),
        OFFICIAL_PUBLIC_READ_WINDOW_SECS,
        OFFICIAL_PUBLIC_READ_MAX_PER_IP,
    )
    .await?;
    consume_rate_limit(
        auth,
        &format!(
            "official_public_read_account:{operation}:{}",
            sha256_hex(account_id)
        ),
        OFFICIAL_PUBLIC_READ_WINDOW_SECS,
        OFFICIAL_PUBLIC_READ_MAX_PER_ACCOUNT,
    )
    .await?;
    Ok(())
}

fn contact_invite_redeemer_matches_issuer(
    issuer_account_id: Option<&str>,
    issuer_phone: Option<&str>,
    redeemer_account_id: &str,
    redeemer_phone: Option<&str>,
) -> bool {
    let issuer_account_id = normalize_non_empty_identity_value(issuer_account_id);
    if issuer_account_id.is_some_and(|issuer| issuer == redeemer_account_id.trim()) {
        return true;
    }
    if issuer_account_id.is_some() {
        return false;
    }
    let issuer_phone = normalize_non_empty_identity_value(issuer_phone);
    let redeemer_phone = normalize_non_empty_identity_value(redeemer_phone);
    match (issuer_phone, redeemer_phone) {
        (Some(issuer), Some(redeemer)) => issuer == redeemer,
        _ => false,
    }
}

pub(crate) async fn enforce_chat_mailbox_write_rate_limit(
    state: &AppState,
    headers: &HeaderMap,
    sender_device_id: Option<&str>,
    mailbox_token: Option<&str>,
) -> ApiResult<()> {
    let Some(auth) = state.auth.as_ref() else {
        return Ok(());
    };
    let client_ip = rate_limit_client_ip(state, headers)?;
    consume_rate_limit(
        auth,
        &format!("chat_mailbox_write_ip:{}", sha256_hex(&client_ip)),
        auth.chat_mailbox_write_window_secs,
        auth.chat_mailbox_write_max_per_ip,
    )
    .await?;
    if let Some(device_id) = normalize_device_id(sender_device_id) {
        consume_rate_limit(
            auth,
            &format!("chat_mailbox_write_device:{}", sha256_hex(&device_id)),
            auth.chat_mailbox_write_window_secs,
            auth.chat_mailbox_write_max_per_device,
        )
        .await?;
    }
    if let Some(tok) = mailbox_token.map(str::trim).filter(|s| !s.is_empty()) {
        // Never store raw mailbox tokens in rate-limit keys.
        let tok_hash = sha256_hex(tok);
        consume_rate_limit(
            auth,
            &format!("chat_mailbox_write_mailbox:{tok_hash}"),
            auth.chat_mailbox_write_window_secs,
            auth.chat_mailbox_write_max_per_mailbox,
        )
        .await?;
    }
    Ok(())
}

