async fn auth_principal_from_headers(
    state: &AppState,
    headers: &HeaderMap,
) -> ApiResult<Option<AuthPrincipal>> {
    let Some(auth) = state.auth.as_ref() else {
        return Ok(None);
    };
    let Some(sid) = extract_session_token(headers, state.accept_legacy_session_cookie) else {
        return direct_web_access_principal_from_headers(state, headers).await;
    };
    let sid_hash = sha256_hex(&sid);
    let row = sqlx::query(
        "SELECT account_id, phone, device_id FROM auth_sessions WHERE sid_hash=$1 AND revoked_at IS NULL AND expires_at > NOW() AND last_seen_at > NOW() - ($2::bigint * INTERVAL '1 second') LIMIT 1",
    )
    .bind(&sid_hash)
    .bind(auth.auth_session_idle_ttl_secs)
    .fetch_optional(&auth.pool)
    .await
    .map_err(|e| {
        tracing::error!(error = %e, "auth principal session lookup failed");
        ApiError::internal("failed to load session")
    })?;
    let Some(row) = row else {
        return Ok(None);
    };
    let refresh_secs = session_last_seen_refresh_secs(auth.auth_session_idle_ttl_secs);
    sqlx::query(
        "UPDATE auth_sessions SET last_seen_at=NOW() \
         WHERE sid_hash=$1 \
           AND revoked_at IS NULL \
           AND expires_at > NOW() \
           AND last_seen_at > NOW() - ($2::bigint * INTERVAL '1 second') \
           AND last_seen_at < NOW() - ($3::bigint * INTERVAL '1 second')",
    )
    .bind(&sid_hash)
    .bind(auth.auth_session_idle_ttl_secs)
    .bind(refresh_secs)
    .execute(&auth.pool)
    .await
    .map_err(|e| {
        tracing::error!(error = %e, "auth principal session refresh failed");
        ApiError::internal("failed to load session")
    })?;

    let account_id_raw = require_auth_optional_text_column(
        row.try_get("account_id"),
        "account_id",
        "auth_principal_from_headers",
        "failed to load session",
    )?
    .map(|value| value.trim().to_string())
    .filter(|value| !value.is_empty());
    let account_id = normalize_session_account_id(account_id_raw.as_deref());
    if account_id_raw.is_some() && account_id.is_none() {
        tracing::warn!(
            security_event = "auth_session_principal_invalid_account_id",
            sid_hash = %hash_prefix(&sid_hash),
            "session account_id was malformed; falling back to phone mapping only"
        );
    }

    let phone_opt = require_auth_optional_text_column(
        row.try_get("phone"),
        "phone",
        "auth_principal_from_headers",
        "failed to load session",
    )?
    .map(|value| value.trim().to_string())
    .filter(|value| !value.is_empty());
    let device_id: Option<String> = require_auth_optional_text_column(
        row.try_get("device_id"),
        "device_id",
        "auth_principal_from_headers",
        "failed to load session",
    )?
    .map(|s| s.trim().to_string())
    .filter(|s| !s.is_empty());

    let account_id = if let Some(account_id) = account_id {
        account_id
    } else if let Some(phone) = phone_opt.as_deref() {
        // Backwards-compatible migration: legacy sessions may only have phone.
        let id = resolve_phone_only_session_account_id(auth, phone).await?;
        sqlx::query(
            "UPDATE auth_sessions SET account_id=$1 \
             WHERE sid_hash=$2 \
               AND (account_id IS NULL OR btrim(account_id)='' OR account_id=$3)",
        )
        .bind(&id)
        .bind(&sid_hash)
        .bind(account_id_raw.as_deref().unwrap_or(""))
        .execute(&auth.pool)
        .await
        .map_err(|e| {
            tracing::error!(error = %e, "auth principal session account migration failed");
            ApiError::internal("failed to load session")
        })?;
        id
    } else {
        return Ok(None);
    };

    if let Some(device_id) = device_id.as_deref() {
        let (last_ip, user_agent) = device_session_request_metadata(state, headers);
        let _ = upsert_device_session_record(
            &auth.pool,
            &account_id,
            phone_opt.as_deref(),
            device_id,
            last_ip.as_deref(),
            user_agent.as_deref(),
        )
        .await;
    }

    Ok(Some(AuthPrincipal {
        account_id,
        phone: phone_opt,
        device_id,
    }))
}

async fn direct_web_access_principal_from_headers(
    state: &AppState,
    headers: &HeaderMap,
) -> ApiResult<Option<AuthPrincipal>> {
    let Some(config) = state.direct_web_access.as_ref() else {
        return Ok(None);
    };
    let Some(auth) = state.auth.as_ref() else {
        return Ok(None);
    };
    if !direct_web_access_origin_allowed(headers, &config.allowed_origins) {
        return Ok(None);
    }
    let Some(client_ip) = trusted_client_ip_from_headers(headers) else {
        return Ok(None);
    };
    if !config
        .allowed_client_cidrs
        .iter()
        .any(|cidr| cidr.contains(&client_ip))
    {
        return Ok(None);
    }

    let account_id = if let Some(account_id) = config.account_id.as_deref() {
        account_id.to_string()
    } else if let Some(account_id) =
        best_effort_account_id_for_subject_phone(auth, config.phone.as_deref()).await
    {
        account_id
    } else {
        return Ok(None);
    };
    let phone = if let Some(phone) = config.phone.as_deref() {
        Some(phone.to_string())
    } else {
        account_phone_for_account(auth, &account_id).await?
    };
    tracing::info!(
        security_event = "web_direct_access",
        outcome = "applied",
        account_id_hash = %hash_prefix(&account_id),
        client_ip_hash = %hash_prefix(&client_ip.to_string()),
        "web direct access principal applied"
    );

    Ok(Some(AuthPrincipal {
        account_id,
        phone,
        device_id: config.device_id.clone(),
    }))
}

fn trusted_client_ip_from_headers(headers: &HeaderMap) -> Option<IpAddr> {
    let ip_attested =
        header_value(headers, TRUSTED_CLIENT_IP_ATTESTED_HEADER).as_deref() == Some("1");
    if !ip_attested {
        return None;
    }
    header_value(headers, TRUSTED_CLIENT_IP_HEADER)
        .and_then(|value| parse_ip(&value))
        .and_then(|value| value.parse::<IpAddr>().ok())
}

fn direct_web_access_origin_allowed(headers: &HeaderMap, allowed_origins: &[String]) -> bool {
    for header_name in [header::ORIGIN.as_str(), header::REFERER.as_str()] {
        let Some(origin) = header_value(headers, header_name)
            .as_deref()
            .and_then(normalize_browser_origin)
        else {
            continue;
        };
        if allowed_origins.iter().any(|allowed| {
            normalize_browser_origin(allowed.as_str()).as_deref() == Some(origin.as_str())
        }) {
            return true;
        }
    }
    false
}

fn normalize_browser_origin(raw: &str) -> Option<String> {
    let trimmed = raw.trim();
    if trimmed.is_empty() || trimmed.eq_ignore_ascii_case("null") {
        return None;
    }
    let url = reqwest::Url::parse(trimmed).ok()?;
    let scheme = url.scheme().to_ascii_lowercase();
    if !matches!(scheme.as_str(), "http" | "https") {
        return None;
    }
    let host = url.host_str()?.trim().to_ascii_lowercase();
    if host.is_empty() {
        return None;
    }
    let port = url.port();
    Some(match port {
        Some(port) => format!("{scheme}://{host}:{port}"),
        None => format!("{scheme}://{host}"),
    })
}

fn extract_session_token(
    headers: &HeaderMap,
    accept_legacy_session_cookie: bool,
) -> Option<String> {
    header_value(headers, "cookie")
        .as_deref()
        .and_then(|raw| parse_session_cookie_header(raw, accept_legacy_session_cookie))
}

fn extract_device_login_binding(headers: &HeaderMap) -> Option<String> {
    header_value(headers, "cookie")
        .as_deref()
        .and_then(|raw| parse_named_cookie_token(raw, DEVICE_LOGIN_BINDING_COOKIE_NAME))
}

fn resolved_device_login_binding(headers: &HeaderMap) -> String {
    extract_device_login_binding(headers)
        .as_deref()
        .and_then(normalize_hex_32)
        .unwrap_or_else(generate_token_hex_16)
}

fn device_login_browser_binding_matches(
    headers: &HeaderMap,
    expected_binding_hash: Option<&str>,
) -> bool {
    let Some(expected_binding_hash) = expected_binding_hash
        .map(str::trim)
        .filter(|value| !value.is_empty())
    else {
        return true;
    };
    let Some(binding) = extract_device_login_binding(headers) else {
        return false;
    };
    let actual_binding_hash = sha256_hex(&binding);
    expected_binding_hash
        .as_bytes()
        .ct_eq(actual_binding_hash.as_bytes())
        .into()
}

fn parse_session_cookie_header(raw: &str, accept_legacy_session_cookie: bool) -> Option<String> {
    parse_named_cookie_token(raw, SESSION_COOKIE_NAME).or_else(|| {
        if accept_legacy_session_cookie {
            parse_named_cookie_token(raw, LEGACY_SESSION_COOKIE_NAME)
        } else {
            None
        }
    })
}

fn parse_named_cookie_token(raw: &str, cookie_name: &str) -> Option<String> {
    for part in raw.split(';') {
        let part = part.trim();
        if let Some(rest) = part
            .strip_prefix(cookie_name)
            .and_then(|tail| tail.strip_prefix('='))
        {
            if let Some(tok) = normalize_hex_32(rest) {
                return Some(tok);
            }
        }
    }
    None
}

fn generate_token_hex_16() -> String {
    let mut buf = [0u8; 16];
    rand::thread_rng().fill_bytes(&mut buf);
    buf.iter().map(|b| format!("{b:02x}")).collect::<String>()
}

fn generate_token_hex_32() -> String {
    let mut buf = [0u8; 32];
    rand::thread_rng().fill_bytes(&mut buf);
    buf.iter().map(|b| format!("{b:02x}")).collect::<String>()
}

fn unix_now_secs() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0)
}

fn generate_shamell_user_id() -> String {
    // Base32-ish alphabet excluding ambiguous chars: I, O, 0, 1.
    const ALPHABET: &[u8] = b"ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
    let mut rng = rand::thread_rng();
    let mut out = String::with_capacity(8);
    for _ in 0..8 {
        let idx = rng.gen_range(0..ALPHABET.len());
        out.push(ALPHABET[idx] as char);
    }
    out
}

fn normalize_shamell_user_id(raw: &str) -> Option<String> {
    let normalized = raw.trim().to_ascii_uppercase();
    if normalized.len() != 8 {
        return None;
    }
    if !normalized
        .chars()
        .all(|ch| matches!(ch, 'A'..='H' | 'J'..='N' | 'P'..='Z' | '2'..='9'))
    {
        return None;
    }
    Some(normalized)
}

#[derive(Debug, Deserialize, serde::Serialize)]
struct AccountCreatePowPayload {
    v: u8,
    device_id: String,
    nonce: String,
    difficulty: u8,
    exp: i64,
}

fn encode_pow_token(secret: &str, payload: &AccountCreatePowPayload) -> Option<String> {
    let payload_bytes = serde_json::to_vec(payload).ok()?;
    let mut mac = Hmac::<Sha256>::new_from_slice(secret.as_bytes()).ok()?;
    mac.update(&payload_bytes);
    let sig = mac.finalize().into_bytes();

    let payload_b64 = URL_SAFE_NO_PAD.encode(&payload_bytes);
    let sig_b64 = URL_SAFE_NO_PAD.encode(sig.as_slice());
    Some(format!("v1.{payload_b64}.{sig_b64}"))
}

fn decode_pow_token(secret: &str, raw: &str) -> Option<AccountCreatePowPayload> {
    let token = raw.trim();
    if token.is_empty() || token.len() > 2048 {
        return None;
    }
    let mut parts = token.split('.');
    let ver = parts.next()?;
    let payload_b64 = parts.next()?;
    let sig_b64 = parts.next()?;
    if parts.next().is_some() {
        return None;
    }
    if ver != "v1" {
        return None;
    }

    let payload_bytes = URL_SAFE_NO_PAD.decode(payload_b64).ok()?;
    if payload_bytes.is_empty() || payload_bytes.len() > 1024 {
        return None;
    }
    let sig = URL_SAFE_NO_PAD.decode(sig_b64).ok()?;
    if sig.len() != 32 {
        return None;
    }

    let mut mac = Hmac::<Sha256>::new_from_slice(secret.as_bytes()).ok()?;
    mac.update(&payload_bytes);
    let expected = mac.finalize().into_bytes();
    if expected.as_slice().ct_eq(sig.as_slice()).unwrap_u8() != 1 {
        return None;
    }

    let payload: AccountCreatePowPayload = serde_json::from_slice(&payload_bytes).ok()?;
    if payload.v != 1 {
        return None;
    }
    let did = payload.device_id.trim();
    if did.is_empty() || did.len() > 128 {
        return None;
    }
    if payload.nonce.trim().is_empty() || payload.nonce.len() > 128 {
        return None;
    }
    if payload.difficulty > 30 {
        return None;
    }
    Some(payload)
}

fn has_leading_zero_bits(bytes: &[u8], bits: u8) -> bool {
    if bits == 0 {
        return true;
    }
    let full = (bits / 8) as usize;
    let rem = (bits % 8) as usize;
    if full > bytes.len() {
        return false;
    }
    for b in bytes.iter().take(full) {
        if *b != 0 {
            return false;
        }
    }
    if rem == 0 {
        return true;
    }
    if full >= bytes.len() {
        return false;
    }
    // Require the most significant `rem` bits of the next byte to be zero.
    (bytes[full] >> (8 - rem)) == 0
}

fn verify_pow_solution(secret: &str, device_id: &str, token: &str, raw_solution: &str) -> bool {
    let now = unix_now_secs();
    let Some(payload) = decode_pow_token(secret, token) else {
        return false;
    };
    if payload.exp <= now {
        return false;
    }
    if payload.device_id.trim() != device_id.trim() {
        return false;
    }

    let sol = raw_solution.trim();
    if sol.is_empty() || sol.len() > 32 {
        return false;
    }
    if !sol.chars().all(|c| c.is_ascii_digit()) {
        return false;
    }
    let Ok(nonce) = sol.parse::<u64>() else {
        return false;
    };

    let msg = format!("{}:{}:{}", payload.nonce.trim(), device_id.trim(), nonce);
    let digest = Sha256::digest(msg.as_bytes());
    has_leading_zero_bits(digest.as_slice(), payload.difficulty)
}

fn unix_now_millis() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_millis() as i64)
        .unwrap_or(0)
}

fn account_create_attestation_nonce_b64(challenge_token: &str) -> Option<String> {
    let tok = challenge_token.trim();
    if tok.is_empty() || tok.len() > 2048 {
        return None;
    }
    let digest = Sha256::digest(tok.as_bytes());
    Some(URL_SAFE_NO_PAD.encode(digest.as_slice()))
}

fn payment_mutation_attestation_nonce_b64(challenge_token: &str) -> Option<String> {
    account_create_attestation_nonce_b64(challenge_token)
}

fn hardware_attestation_providers(auth: &AuthRuntime) -> Vec<&'static str> {
    let mut out = Vec::new();
    if auth.account_create_apple_devicecheck.is_some() {
        out.push("apple_devicecheck");
    }
    if auth.account_create_play_integrity.is_some() {
        out.push("google_play_integrity");
    }
    out
}

fn normalize_payment_mutation_attestation_operation(raw: Option<&str>) -> Option<&'static str> {
    match raw.unwrap_or_default().trim() {
        "payments_create_user" => Some("payments_create_user"),
        "payments_transfer" => Some("payments_transfer"),
        "payments_topup" => Some("payments_topup"),
        "payments_favorites_create" => Some("payments_favorites_create"),
        "payments_favorites_delete" => Some("payments_favorites_delete"),
        "payments_requests_create" => Some("payments_requests_create"),
        "payments_requests_accept" => Some("payments_requests_accept"),
        "payments_requests_cancel" => Some("payments_requests_cancel"),
        "biometric_enroll" => Some("biometric_enroll"),
        "biometric_login" => Some("biometric_login"),
        _ => None,
    }
}

fn parse_payment_mutation_attestation_emergency_bypass_operations(
    raw: &str,
) -> Result<HashSet<String>, String> {
    let mut out = HashSet::new();
    for token in raw.split(',') {
        let normalized = token.trim();
        if normalized.is_empty() {
            continue;
        }
        let Some(operation) = normalize_payment_mutation_attestation_operation(Some(normalized))
        else {
            return Err(
                "AUTH_PAYMENT_MUTATION_ATTESTATION_EMERGENCY_BYPASS_OPERATIONS contains unsupported operation"
                    .to_string(),
            );
        };
        out.insert(operation.to_string());
    }
    Ok(out)
}

fn default_account_create_trusted_device_ids(env_name: &str) -> HashSet<String> {
    if secret_policy::is_production_like(env_name) {
        return HashSet::new();
    }
    DEV_ACCOUNT_CREATE_TRUSTED_DEVICE_IDS
        .iter()
        .map(|device_id| device_id.to_string())
        .collect()
}

fn parse_account_create_trusted_device_ids(raw: &str) -> Result<HashSet<String>, String> {
    let mut out = HashSet::new();
    for token in raw.split(',') {
        let normalized = token.trim();
        if normalized.is_empty() {
            continue;
        }
        let Some(device_id) = normalize_device_id(Some(normalized)) else {
            return Err(
                "AUTH_ACCOUNT_CREATE_TRUSTED_DEVICE_IDS contains invalid device_id".to_string(),
            );
        };
        out.insert(device_id);
    }
    Ok(out)
}

fn account_create_device_is_trusted(auth: &AuthRuntime, device_id: &str) -> bool {
    auth.account_create_trusted_device_ids
        .contains(device_id.trim())
}

fn account_create_hw_attestation_providers(auth: &AuthRuntime) -> Vec<&'static str> {
    let mut out = Vec::new();
    if auth.account_create_apple_devicecheck.is_some() {
        out.push("apple_devicecheck");
    }
    if auth.account_create_play_integrity.is_some() {
        out.push("google_play_integrity");
    }
    out
}

fn account_create_hw_attestation_policy(
    auth: &AuthRuntime,
    device_id: &str,
) -> (bool, Vec<&'static str>, bool, bool) {
    let trusted_device = account_create_device_is_trusted(auth, device_id);
    let hw_providers = account_create_hw_attestation_providers(auth);
    let hw_attestation_enabled =
        auth.account_create_hw_attestation_enabled && !hw_providers.is_empty() && !trusted_device;
    let hw_attestation_required =
        hw_attestation_enabled && auth.account_create_hw_attestation_required;
    (
        trusted_device,
        hw_providers,
        hw_attestation_enabled,
        hw_attestation_required,
    )
}

fn normalize_payment_mutation_attestation_resource_id(raw: Option<&str>) -> Option<String> {
    let s = raw.unwrap_or_default().trim();
    if s.is_empty() || s.len() > 255 {
        return None;
    }
    if s.chars().any(|c| c.is_control()) {
        return None;
    }
    Some(s.to_string())
}

#[derive(serde::Serialize)]
struct AppleDeviceCheckJwtClaims<'a> {
    iss: &'a str,
    iat: usize,
    exp: usize,
}

async fn verify_apple_devicecheck_token(
    http: &reqwest::Client,
    cfg: &AppleDeviceCheckConfig,
    device_token_b64: &str,
) -> ApiResult<bool> {
    let Some(tok) = normalize_apple_devicecheck_token_b64(device_token_b64) else {
        return Ok(false);
    };

    // Apple DeviceCheck: https://api.devicecheck.apple.com/v1/validate_device_token
    let now = unix_now_secs().max(0) as usize;
    let mut header = Header::new(Algorithm::ES256);
    header.kid = Some(cfg.key_id.clone());
    let claims = AppleDeviceCheckJwtClaims {
        iss: cfg.team_id.as_str(),
        iat: now,
        exp: now.saturating_add(20 * 60),
    };
    let jwt = jsonwebtoken::encode(
        &header,
        &claims,
        &EncodingKey::from_ec_pem(cfg.private_key_p8.as_slice())
            .map_err(|_| ApiError::internal("apple devicecheck key misconfigured"))?,
    )
    .map_err(|_| ApiError::internal("apple devicecheck key misconfigured"))?;

    #[derive(serde::Serialize)]
    struct DcValidateReq<'a> {
        device_token: &'a str,
        timestamp: i64,
        transaction_id: &'a str,
    }

    let txid = generate_token_hex_16();
    let req = DcValidateReq {
        device_token: tok.as_str(),
        timestamp: unix_now_millis(),
        transaction_id: txid.as_str(),
    };

    let resp = http
        .post("https://api.devicecheck.apple.com/v1/validate_device_token")
        .timeout(std::time::Duration::from_secs(6))
        .bearer_auth(jwt)
        .json(&req)
        .send()
        .await
        .map_err(|_| ApiError::new(StatusCode::SERVICE_UNAVAILABLE, "attestation unavailable"))?;

    if resp.status() == StatusCode::OK {
        return Ok(true);
    }
    if resp.status().is_client_error() {
        return Ok(false);
    }
    Err(ApiError::new(
        StatusCode::SERVICE_UNAVAILABLE,
        "attestation unavailable",
    ))
}

#[derive(Deserialize)]
struct GoogleOauthTokenResponse {
    access_token: String,
}

#[derive(serde::Serialize)]
struct GoogleServiceAccountJwtClaims<'a> {
    iss: &'a str,
    sub: &'a str,
    aud: &'a str,
    iat: usize,
    exp: usize,
    scope: &'a str,
}

async fn google_service_account_access_token(
    http: &reqwest::Client,
    cfg: &PlayIntegrityConfig,
) -> ApiResult<String> {
    let now = unix_now_secs().max(0) as usize;
    let header = Header::new(Algorithm::RS256);
    let claims = GoogleServiceAccountJwtClaims {
        iss: cfg.service_account_email.as_str(),
        sub: cfg.service_account_email.as_str(),
        aud: cfg.token_uri.as_str(),
        iat: now,
        exp: now.saturating_add(55 * 60),
        scope: "https://www.googleapis.com/auth/playintegrity",
    };
    let jwt = jsonwebtoken::encode(
        &header,
        &claims,
        &EncodingKey::from_rsa_pem(cfg.service_account_private_key_pem.as_slice())
            .map_err(|_| ApiError::internal("play integrity key misconfigured"))?,
    )
    .map_err(|_| ApiError::internal("play integrity key misconfigured"))?;

    let resp = http
        .post(cfg.token_uri.as_str())
        .timeout(std::time::Duration::from_secs(6))
        .form(&[
            ("grant_type", "urn:ietf:params:oauth:grant-type:jwt-bearer"),
            ("assertion", jwt.as_str()),
        ])
        .send()
        .await
        .map_err(|_| ApiError::new(StatusCode::SERVICE_UNAVAILABLE, "attestation unavailable"))?;

    if !resp.status().is_success() {
        if resp.status().is_client_error() {
            tracing::warn!(
                status = %resp.status(),
                "play integrity oauth rejected service-account request"
            );
        }
        return Err(ApiError::new(
            StatusCode::SERVICE_UNAVAILABLE,
            "attestation unavailable",
        ));
    }
    let parsed: GoogleOauthTokenResponse = resp
        .json()
        .await
        .map_err(|_| ApiError::internal("play integrity oauth parse failed"))?;
    let tok = parsed.access_token.trim().to_string();
    if tok.is_empty() {
        return Err(ApiError::internal("play integrity oauth failed"));
    }
    Ok(tok)
}

#[derive(Deserialize)]
struct PlayIntegrityDecodeResponse {
    #[serde(rename = "tokenPayloadExternal")]
    token_payload_external: Option<PlayIntegrityTokenPayloadExternal>,
}

#[derive(Deserialize)]
struct PlayIntegrityTokenPayloadExternal {
    #[serde(rename = "requestDetails")]
    request_details: Option<PlayIntegrityRequestDetails>,
    #[serde(rename = "appIntegrity")]
    app_integrity: Option<PlayIntegrityAppIntegrity>,
    #[serde(rename = "deviceIntegrity")]
    device_integrity: Option<PlayIntegrityDeviceIntegrity>,
    #[serde(rename = "accountDetails")]
    account_details: Option<PlayIntegrityAccountDetails>,
}

#[derive(Deserialize)]
struct PlayIntegrityRequestDetails {
    #[serde(rename = "requestPackageName")]
    request_package_name: Option<String>,
    nonce: Option<String>,
}

#[derive(Deserialize)]
struct PlayIntegrityAppIntegrity {
    #[serde(rename = "appRecognitionVerdict")]
    app_recognition_verdict: Option<String>,
}

#[derive(Deserialize)]
struct PlayIntegrityDeviceIntegrity {
    #[serde(rename = "deviceRecognitionVerdict")]
    device_recognition_verdict: Option<Vec<String>>,
}

#[derive(Deserialize)]
struct PlayIntegrityAccountDetails {
    #[serde(rename = "appLicensingVerdict")]
    app_licensing_verdict: Option<String>,
}

async fn verify_play_integrity_token(
    http: &reqwest::Client,
    cfg: &PlayIntegrityConfig,
    integrity_token: &str,
    expected_nonce_b64: &str,
) -> ApiResult<bool> {
    let tok = integrity_token.trim();
    if tok.is_empty() || tok.len() > 32_768 {
        return Ok(false);
    }
    let expected_nonce = expected_nonce_b64.trim();
    if expected_nonce.is_empty() || expected_nonce.len() > 512 {
        return Ok(false);
    }

    let access_token = google_service_account_access_token(http, cfg).await?;

    #[derive(serde::Serialize)]
    struct DecodeReq<'a> {
        integrity_token: &'a str,
    }

    for pkg in cfg.allowed_package_names.iter() {
        let url = format!(
            "https://playintegrity.googleapis.com/v1/{}:decodeIntegrityToken",
            pkg
        );
        let resp = http
            .post(url)
            .timeout(std::time::Duration::from_secs(8))
            .bearer_auth(access_token.as_str())
            .json(&DecodeReq {
                integrity_token: tok,
            })
            .send()
            .await
            .map_err(|_| {
                ApiError::new(StatusCode::SERVICE_UNAVAILABLE, "attestation unavailable")
            })?;

        if resp.status() == StatusCode::UNAUTHORIZED || resp.status() == StatusCode::FORBIDDEN {
            // Access token / IAM misconfig.
            return Err(ApiError::internal("play integrity unauthorized"));
        }
        if !resp.status().is_success() {
            // Try next package (token might belong to another allowed package).
            continue;
        }

        let decoded: PlayIntegrityDecodeResponse = resp
            .json()
            .await
            .map_err(|_| ApiError::internal("play integrity decode parse failed"))?;
        let Some(payload) = decoded.token_payload_external else {
            return Ok(false);
        };
        let Some(req) = payload.request_details else {
            return Ok(false);
        };

        let Ok(req_pkg) = normalize_play_integrity_package_name(
            req.request_package_name.as_deref().unwrap_or(""),
        ) else {
            return Ok(false);
        };
        if !cfg.allowed_package_names.iter().any(|p| p == &req_pkg) {
            return Ok(false);
        }
        let nonce = req.nonce.unwrap_or_default();
        if nonce.trim() != expected_nonce {
            return Ok(false);
        }

        if cfg.require_play_recognized {
            let verdict = payload
                .app_integrity
                .as_ref()
                .and_then(|v| v.app_recognition_verdict.as_deref())
                .unwrap_or("")
                .trim()
                .to_string();
            if verdict != "PLAY_RECOGNIZED" {
                return Ok(false);
            }
        }

        let verdicts = payload
            .device_integrity
            .as_ref()
            .and_then(|v| v.device_recognition_verdict.as_ref())
            .cloned()
            .unwrap_or_default();
        if cfg.require_strong_integrity {
            if !verdicts.iter().any(|v| v == "MEETS_STRONG_INTEGRITY") {
                return Ok(false);
            }
        } else if !verdicts
            .iter()
            .any(|v| v == "MEETS_DEVICE_INTEGRITY" || v == "MEETS_STRONG_INTEGRITY")
        {
            return Ok(false);
        }

        if cfg.require_licensed {
            let verdict = payload
                .account_details
                .as_ref()
                .and_then(|v| v.app_licensing_verdict.as_deref())
                .unwrap_or("")
                .trim()
                .to_string();
            if verdict != "LICENSED" {
                return Ok(false);
            }
        }

        return Ok(true);
    }

    Ok(false)
}

async fn ensure_account_id_for_phone(auth: &AuthRuntime, phone: &str) -> ApiResult<String> {
    let phone = phone.trim();
    if phone.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }

    // Fast path: already mapped.
    if let Some(row) = sqlx::query("SELECT account_id FROM auth_accounts WHERE phone=$1 LIMIT 1")
        .bind(phone)
        .fetch_optional(&auth.pool)
        .await
        .map_err(|e| {
            tracing::error!(error = %e, "auth_accounts select failed");
            ApiError::internal("failed to load account")
        })?
    {
        let id: String = require_auth_text_column(
            row.try_get("account_id"),
            "account_id",
            "ensure_account_id_for_phone_select",
            "failed to load account",
        )?;
        let id = id.trim().to_string();
        if !id.is_empty() {
            return Ok(id);
        }
    }

    // Preserve any legacy Shamell ID mapping if present.
    let legacy_shamell_id = if let Some(row) =
        sqlx::query("SELECT shamell_user_id FROM auth_user_ids WHERE phone=$1 LIMIT 1")
            .bind(phone)
            .fetch_optional(&auth.pool)
            .await
            .map_err(|e| {
                tracing::error!(error = %e, "auth_user_ids legacy shamell_id lookup failed");
                ApiError::internal("failed to load account")
            })? {
        require_auth_optional_text_column(
            row.try_get("shamell_user_id"),
            "shamell_user_id",
            "ensure_account_id_for_phone_legacy_shamell_id_lookup",
            "failed to load account",
        )?
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty())
    } else {
        None
    };

    for _ in 0..12 {
        let account_id = generate_token_hex_32();
        let shamell_id = legacy_shamell_id
            .clone()
            .unwrap_or_else(generate_shamell_user_id);
        let inserted = sqlx::query(
            "INSERT INTO auth_accounts (account_id, shamell_user_id, phone) VALUES ($1, $2, $3) ON CONFLICT (phone) DO NOTHING",
        )
        .bind(&account_id)
        .bind(&shamell_id)
        .bind(phone)
        .execute(&auth.pool)
        .await;

        match inserted {
            Ok(r) => {
                if r.rows_affected() == 1 {
                    return Ok(account_id);
                }
                // Another request won the race: load and return.
                if let Some(row) =
                    sqlx::query("SELECT account_id FROM auth_accounts WHERE phone=$1 LIMIT 1")
                        .bind(phone)
                        .fetch_optional(&auth.pool)
                        .await
                        .map_err(|e| {
                            tracing::error!(error = %e, "auth_accounts re-select failed");
                            ApiError::internal("failed to load account")
                        })?
                {
                    let id: String = require_auth_text_column(
                        row.try_get("account_id"),
                        "account_id",
                        "ensure_account_id_for_phone_reselect",
                        "failed to load account",
                    )?;
                    let id = id.trim().to_string();
                    if !id.is_empty() {
                        return Ok(id);
                    }
                }
            }
            Err(e) => {
                let unique_violation = match &e {
                    sqlx::Error::Database(db) => db.code().as_deref() == Some("23505"),
                    _ => false,
                };
                if unique_violation {
                    continue;
                }
                tracing::error!(error = %e, "auth_accounts insert failed");
                return Err(ApiError::internal("failed to allocate account"));
            }
        }
    }
    Err(ApiError::internal("failed to allocate account"))
}

async fn resolve_phone_only_session_account_id(
    auth: &AuthRuntime,
    phone: &str,
) -> ApiResult<String> {
    map_phone_only_session_account_id_result(phone, ensure_account_id_for_phone(auth, phone).await)
}

fn map_phone_only_session_account_id_result(
    phone: &str,
    result: ApiResult<String>,
) -> ApiResult<String> {
    match result {
        Ok(id) => Ok(id),
        Err(err) => {
            tracing::error!(
                error = ?err,
                phone_hash = %hash_prefix(phone),
                "failed to ensure account mapping for phone session"
            );
            if err.status == StatusCode::UNAUTHORIZED {
                Err(err)
            } else {
                Err(ApiError::internal("failed to load session"))
            }
        }
    }
}

async fn ensure_shamell_user_id_for_account(
    auth: &AuthRuntime,
    account_id: &str,
) -> ApiResult<String> {
    let account_id = account_id.trim();
    if account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }
    let row = sqlx::query("SELECT shamell_user_id FROM auth_accounts WHERE account_id=$1 LIMIT 1")
        .bind(account_id)
        .fetch_optional(&auth.pool)
        .await
        .map_err(|e| {
            tracing::error!(error = %e, "auth_accounts shamell_id lookup failed");
            ApiError::internal("failed to load Shamell ID")
        })?
        .ok_or_else(|| ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"))?;
    let id: String = require_auth_text_column(
        row.try_get("shamell_user_id"),
        "shamell_user_id",
        "ensure_shamell_user_id_for_account",
        "failed to load Shamell ID",
    )?;
    let id = id.trim().to_string();
    if id.is_empty() {
        return Err(ApiError::internal("failed to load Shamell ID"));
    }
    Ok(id)
}

fn sha256_hex(value: &str) -> String {
    let mut hasher = Sha256::new();
    hasher.update(value.as_bytes());
    let digest = hasher.finalize();
    digest
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect::<String>()
}

pub(crate) fn hash_prefix(value: &str) -> String {
    let digest = sha256_hex(value);
    digest.chars().take(12).collect()
}

fn hash_i64_prefix(value: i64) -> String {
    hash_prefix(&value.to_string())
}

fn token_hash_prefix(token_hash: &str) -> String {
    token_hash.chars().take(12).collect()
}

fn upstream_error_key_is_sensitive(key: &str) -> bool {
    let normalized = key
        .trim()
        .chars()
        .filter(|c| c.is_ascii_alphanumeric())
        .flat_map(|c| c.to_lowercase())
        .collect::<String>();
    if normalized.contains("authorization")
        || normalized.contains("cookie")
        || normalized.contains("token")
        || normalized.contains("secret")
        || normalized.contains("password")
        || normalized.contains("session")
    {
        return true;
    }
    matches!(
        normalized.as_str(),
        "setcookie"
            | "xinternalsecret"
            | "xinternalidentitysig"
            | "xinternalidentitysigv2"
            | "xinternalidentitynonce"
            | "internalapisecret"
            | "challengetoken"
            | "xchatdevicetoken"
            | "xshamellpaymentattestationchallenge"
            | "xshamellpaymentplayintegrity"
            | "xshamellpaymentappledevicecheck"
            | "xshamellbiometricattestationchallenge"
            | "xshamellbiometricplayintegrity"
            | "xshamellbiometricappledevicecheck"
            | "xshamellbiometricloginattestationchallenge"
            | "xshamellbiometricloginplayintegrity"
            | "xshamellbiometricloginappledevicecheck"
    )
}

fn redact_sensitive_upstream_error_value(value: Value) -> Value {
    match value {
        Value::Object(map) => Value::Object(
            map.into_iter()
                .map(|(key, value)| {
                    if upstream_error_key_is_sensitive(&key) {
                        (key, Value::String("[redacted]".to_string()))
                    } else {
                        (key, redact_sensitive_upstream_error_value(value))
                    }
                })
                .collect(),
        ),
        Value::Array(items) => Value::Array(
            items
                .into_iter()
                .map(redact_sensitive_upstream_error_value)
                .collect(),
        ),
        other => other,
    }
}

pub(crate) fn redact_sensitive_upstream_error_detail(raw: &str) -> String {
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return raw.to_string();
    }
    if let Ok(value) = serde_json::from_str::<Value>(trimmed) {
        return serde_json::to_string(&redact_sensitive_upstream_error_value(value))
            .unwrap_or_else(|_| "[redacted upstream detail]".to_string());
    }

    static ASSIGNMENT_RE: OnceLock<Result<Regex, regex::Error>> = OnceLock::new();
    let re = match ASSIGNMENT_RE
        .get_or_init(|| Regex::new(r"(?i)\b([a-z0-9_.-]+)\b(\s*[:=]\s*)([^\r\n,;]+)"))
    {
        Ok(re) => re,
        Err(_) => return "[redacted upstream detail]".to_string(),
    };
    re.replace_all(raw, |captures: &regex::Captures<'_>| {
        let key = captures.get(1).map(|m| m.as_str()).unwrap_or_default();
        if upstream_error_key_is_sensitive(key) {
            format!("{}{}[redacted]", &captures[1], &captures[2])
        } else {
            captures
                .get(0)
                .map(|m| m.as_str())
                .unwrap_or_default()
                .to_string()
        }
    })
    .into_owned()
}

fn account_create_challenge_token_hash(challenge_token: &str) -> String {
    sha256_hex(challenge_token)
}

fn payment_mutation_attestation_challenge_token_hash(challenge_token: &str) -> String {
    sha256_hex(&format!("pay_att:{challenge_token}"))
}

async fn record_account_create_challenge(
    auth: &AuthRuntime,
    device_id: &str,
    challenge_token: &str,
    expires_at_epoch_secs: i64,
) -> ApiResult<()> {
    let token_hash = account_create_challenge_token_hash(challenge_token);
    let result = sqlx::query(
        "INSERT INTO auth_account_create_challenges \
         (token_hash, device_id, expires_at) \
         VALUES ($1, $2, to_timestamp($3)) \
         ON CONFLICT (token_hash) DO NOTHING",
    )
    .bind(&token_hash)
    .bind(device_id)
    .bind(expires_at_epoch_secs)
    .execute(&auth.pool)
    .await
    .map_err(|e| {
        tracing::error!(
            error = %e,
            challenge_hash = %token_hash_prefix(&token_hash),
            device_id_hash = %hash_prefix(device_id),
            "account create challenge insert failed"
        );
        ApiError::internal("account create unavailable")
    })?;
    if result.rows_affected() != 1 {
        tracing::error!(
            challenge_hash = %token_hash_prefix(&token_hash),
            device_id_hash = %hash_prefix(device_id),
            "account create challenge collision detected"
        );
        return Err(ApiError::internal("account create unavailable"));
    }
    Ok(())
}

struct PaymentMutationAttestationChallengeRecord<'a> {
    account_id: &'a str,
    device_id: &'a str,
    operation: &'a str,
    resource_id: &'a str,
    challenge_token: &'a str,
    expires_at_epoch_secs: i64,
    failure_detail: &'static str,
}

async fn record_payment_mutation_attestation_challenge(
    auth: &AuthRuntime,
    record: PaymentMutationAttestationChallengeRecord<'_>,
) -> ApiResult<()> {
    let PaymentMutationAttestationChallengeRecord {
        account_id,
        device_id,
        operation,
        resource_id,
        challenge_token,
        expires_at_epoch_secs,
        failure_detail,
    } = record;
    let token_hash = payment_mutation_attestation_challenge_token_hash(challenge_token);
    let result = sqlx::query(
        "INSERT INTO auth_payment_attestation_challenges \
         (token_hash, account_id, device_id, operation, resource_id, expires_at) \
         VALUES ($1, $2, $3, $4, $5, to_timestamp($6)) \
         ON CONFLICT (token_hash) DO NOTHING",
    )
    .bind(&token_hash)
    .bind(account_id)
    .bind(device_id)
    .bind(operation)
    .bind(resource_id)
    .bind(expires_at_epoch_secs)
    .execute(&auth.pool)
    .await
    .map_err(|e| {
        tracing::error!(
            error = %e,
            challenge_hash = %token_hash_prefix(&token_hash),
            account_hash = %hash_prefix(account_id),
            device_id_hash = %hash_prefix(device_id),
            operation,
            "payment mutation attestation challenge insert failed"
        );
        ApiError::internal(failure_detail)
    })?;
    if result.rows_affected() != 1 {
        tracing::error!(
            challenge_hash = %token_hash_prefix(&token_hash),
            account_hash = %hash_prefix(account_id),
            device_id_hash = %hash_prefix(device_id),
            operation,
            "payment mutation attestation challenge collision detected"
        );
        return Err(ApiError::internal(failure_detail));
    }
    Ok(())
}

async fn consume_account_create_challenge(
    auth: &AuthRuntime,
    device_id: &str,
    challenge_token: &str,
    client_ip: &str,
) -> ApiResult<()> {
    let token_hash = account_create_challenge_token_hash(challenge_token);
    let result = sqlx::query(
        "UPDATE auth_account_create_challenges \
         SET consumed_at = NOW() \
         WHERE token_hash = $1 \
           AND device_id = $2 \
           AND consumed_at IS NULL \
           AND expires_at > NOW()",
    )
    .bind(&token_hash)
    .bind(device_id)
    .execute(&auth.pool)
    .await
    .map_err(|e| {
        tracing::error!(
            error = %e,
            challenge_hash = %token_hash_prefix(&token_hash),
            device_id_hash = %hash_prefix(device_id),
            "account create challenge consume failed"
        );
        ApiError::internal("account create unavailable")
    })?;
    if result.rows_affected() != 1 {
        tracing::warn!(
            security_event = "account_create_attestation",
            outcome = "replayed_or_unknown_challenge",
            client_ip_hash = %hash_prefix(client_ip),
            challenge_hash = %token_hash_prefix(&token_hash),
            device_id_hash = %hash_prefix(device_id),
            "account create rejected replayed or unknown challenge token"
        );
        return Err(ApiError::new(
            StatusCode::UNAUTHORIZED,
            "attestation required",
        ));
    }
    Ok(())
}

fn audit_device_login_event(
    event: &'static str,
    outcome: &'static str,
    client_ip: Option<&str>,
    phone: Option<&str>,
    token_hash: Option<&str>,
    reason: Option<&str>,
) {
    let client_ip_hash = client_ip.map(hash_prefix).unwrap_or_default();
    let phone_hash = phone.map(hash_prefix).unwrap_or_default();
    let token_hash = token_hash.map(token_hash_prefix).unwrap_or_default();
    let reason = reason.unwrap_or("");
    if matches!(outcome, "blocked" | "revoked" | "failed") {
        tracing::warn!(
            security_event = event,
            outcome,
            reason,
            client_ip_hash,
            phone_hash,
            token_hash,
            "auth device login security event"
        );
    } else {
        tracing::info!(
            security_event = event,
            outcome,
            client_ip_hash,
            phone_hash,
            token_hash,
            "auth device login security event"
        );
    }
}

pub(crate) fn audit_admin_role_mutation_event(
    operation: &'static str,
    outcome: &'static str,
    principal: Option<&AuthPrincipal>,
    target_role: Option<&str>,
    target_account_id: Option<&str>,
    target_phone: Option<&str>,
    reason: Option<&str>,
) {
    let actor_account_hash = principal
        .map(|principal| hash_prefix(principal.account_id.trim()))
        .unwrap_or_default();
    let actor_phone_hash = principal
        .and_then(|principal| principal.phone.as_deref())
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(hash_prefix)
        .unwrap_or_default();
    let target_role = target_role.unwrap_or("").trim().to_ascii_lowercase();
    let target_account_hash = target_account_id
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(hash_prefix)
        .unwrap_or_default();
    let target_phone_hash = target_phone
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(hash_prefix)
        .unwrap_or_default();
    let reason = reason.unwrap_or("");
    if matches!(outcome, "blocked" | "failed") {
        tracing::warn!(
            security_event = "admin_role_mutation",
            operation,
            outcome,
            reason,
            actor_account_hash,
            actor_phone_hash,
            target_role,
            target_account_hash,
            target_phone_hash,
            "admin role mutation security event"
        );
    } else {
        tracing::info!(
            security_event = "admin_role_mutation",
            operation,
            outcome,
            actor_account_hash,
            actor_phone_hash,
            target_role,
            target_account_hash,
            target_phone_hash,
            "admin role mutation security event"
        );
    }
}

