pub(crate) async fn enforce_admin_role_read_rate_limit(
    state: &AppState,
    headers: &HeaderMap,
    principal: &AuthPrincipal,
    operation: &'static str,
) -> ApiResult<()> {
    let Some(auth) = state.auth.as_ref() else {
        return Ok(());
    };
    let client_ip = rate_limit_client_ip(state, headers)?;
    let account_id = principal.account_id.trim();
    if account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }
    consume_rate_limit(
        auth,
        &format!("admin_role_read_ip:{operation}:{}", sha256_hex(&client_ip)),
        ADMIN_ROLE_READ_WINDOW_SECS,
        ADMIN_ROLE_READ_MAX_PER_IP,
    )
    .await?;
    consume_rate_limit(
        auth,
        &format!(
            "admin_role_read_account:{operation}:{}",
            hash_prefix(account_id)
        ),
        ADMIN_ROLE_READ_WINDOW_SECS,
        ADMIN_ROLE_READ_MAX_PER_ACCOUNT,
    )
    .await?;
    Ok(())
}

