fn security_alert_ingest_rate_limit_client_ip(
    state: &AppState,
    headers: &HeaderMap,
) -> Option<String> {
    let env_lower = state.env_name.trim().to_ascii_lowercase();
    let ip_attested =
        header_value(headers, TRUSTED_CLIENT_IP_ATTESTED_HEADER).is_some_and(|value| value == "1");

    if let Some(ip) =
        header_value(headers, TRUSTED_CLIENT_IP_HEADER).and_then(|value| parse_ip(&value))
    {
        if ip_attested || matches!(env_lower.as_str(), "dev" | "test") {
            return Some(ip);
        }
    }

    if !matches!(env_lower.as_str(), "dev" | "test") {
        return None;
    }

    header_value(headers, "x-forwarded-for").and_then(|value| {
        value
            .split(',')
            .next()
            .map(str::trim)
            .filter(|ip| !ip.is_empty())
            .and_then(parse_ip)
    })
}

pub(crate) async fn enforce_security_alert_ingest_rate_limit(
    state: &AppState,
    headers: &HeaderMap,
    source: &str,
) -> ApiResult<()> {
    enforce_security_alert_ingest_rate_limit_inner(
        state,
        headers,
        source,
        SECURITY_ALERT_INGEST_WINDOW_SECS,
        SECURITY_ALERT_INGEST_MAX_PER_CALLER,
        SECURITY_ALERT_INGEST_MAX_PER_SOURCE,
        SECURITY_ALERT_INGEST_MAX_PER_IP,
    )
    .await
}

async fn enforce_security_alert_ingest_rate_limit_inner(
    state: &AppState,
    headers: &HeaderMap,
    source: &str,
    window_secs: i64,
    max_per_caller: i64,
    max_per_source: i64,
    max_per_ip: i64,
) -> ApiResult<()> {
    let Some(auth) = state.auth.as_ref() else {
        return Ok(());
    };

    let caller = normalize_small(
        header_value(headers, "x-internal-service-id").as_deref(),
        64,
    )
    .unwrap_or_else(|| "unknown".to_string());
    let normalized_source =
        normalize_small(Some(source), 128).unwrap_or_else(|| "missing".to_string());
    let caller_hash = hash_prefix(&caller);

    consume_rate_limit(
        auth,
        &format!("security_alert_ingest_caller:{caller_hash}"),
        window_secs,
        max_per_caller,
    )
    .await?;
    consume_rate_limit(
        auth,
        &format!(
            "security_alert_ingest_source:{caller_hash}:{}",
            hash_prefix(&normalized_source)
        ),
        window_secs,
        max_per_source,
    )
    .await?;
    if let Some(client_ip) = security_alert_ingest_rate_limit_client_ip(state, headers) {
        consume_rate_limit(
            auth,
            &format!(
                "security_alert_ingest_ip:{caller_hash}:{}",
                sha256_hex(&client_ip)
            ),
            window_secs,
            max_per_ip,
        )
        .await?;
    }
    Ok(())
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct RateLimitDecision {
    window_start_epoch: i64,
    request_count: i64,
    allowed: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum MutationReplayDecision {
    Fresh,
    Replay,
}

fn next_rate_limit_decision(
    now_epoch: i64,
    window_start_epoch: i64,
    request_count: i64,
    window_secs: i64,
    max_per_window: i64,
) -> RateLimitDecision {
    let mut window_start_epoch = window_start_epoch;
    let mut request_count = request_count.max(0);

    // Repair future windows caused by clock skew or legacy bad state so users do not
    // remain blocked longer than the configured rate-limit window.
    if window_start_epoch > now_epoch {
        window_start_epoch = now_epoch;
        request_count = 0;
    }

    let elapsed = now_epoch.saturating_sub(window_start_epoch);
    let allowed = if elapsed >= window_secs {
        window_start_epoch = now_epoch;
        request_count = 1;
        true
    } else if request_count < max_per_window {
        request_count = request_count.saturating_add(1);
        true
    } else {
        false
    };

    RateLimitDecision {
        window_start_epoch,
        request_count,
        allowed,
    }
}

fn rate_limit_retry_after_secs(now_epoch: i64, window_start_epoch: i64, window_secs: i64) -> i64 {
    let elapsed = now_epoch.saturating_sub(window_start_epoch).max(0);
    window_secs.saturating_sub(elapsed).max(1)
}

fn session_last_seen_refresh_secs(idle_ttl_secs: i64) -> i64 {
    idle_ttl_secs.saturating_div(4).clamp(
        AUTH_SESSION_LAST_SEEN_REFRESH_MIN_SECS,
        AUTH_SESSION_LAST_SEEN_REFRESH_MAX_SECS,
    )
}

fn require_rate_limit_i64_column(
    value: Result<i64, sqlx::Error>,
    column: &'static str,
    key: &str,
    context: &'static str,
) -> ApiResult<i64> {
    value.map_err(|e| {
        tracing::error!(
            error = %e,
            limit_key_hash = hash_prefix(key),
            column,
            context,
            "rate-limit column decode failed"
        );
        ApiError::internal("rate-limit unavailable")
    })
}

fn require_auth_db_column<T>(
    value: Result<T, sqlx::Error>,
    column: &'static str,
    context: &'static str,
    failure_detail: &'static str,
) -> ApiResult<T> {
    value.map_err(|e| {
        tracing::error!(error = %e, column, context, "auth column decode failed");
        ApiError::internal(failure_detail)
    })
}

fn require_auth_optional_text_column(
    value: Result<Option<String>, sqlx::Error>,
    column: &'static str,
    context: &'static str,
    failure_detail: &'static str,
) -> ApiResult<Option<String>> {
    require_auth_db_column(value, column, context, failure_detail)
}

fn require_auth_text_column(
    value: Result<String, sqlx::Error>,
    column: &'static str,
    context: &'static str,
    failure_detail: &'static str,
) -> ApiResult<String> {
    require_auth_db_column(value, column, context, failure_detail)
}

async fn consume_rate_limit(
    auth: &AuthRuntime,
    key: &str,
    window_secs: i64,
    max_per_window: i64,
) -> ApiResult<()> {
    let mut tx = auth.pool.begin().await.map_err(|e| {
        tracing::error!(
            error = %e,
            limit_key_hash = hash_prefix(key),
            "rate-limit tx begin failed"
        );
        ApiError::internal("rate-limit unavailable")
    })?;
    let now_row = sqlx::query("SELECT FLOOR(EXTRACT(EPOCH FROM NOW()))::BIGINT AS now_epoch")
        .fetch_one(&mut *tx)
        .await
        .map_err(|e| {
            tracing::error!(
                error = %e,
                limit_key_hash = hash_prefix(key),
                "rate-limit clock read failed"
            );
            ApiError::internal("rate-limit unavailable")
        })?;
    let now: i64 = require_rate_limit_i64_column(
        now_row.try_get("now_epoch"),
        "now_epoch",
        key,
        "consume_rate_limit_clock_read",
    )?;
    sqlx::query(
        r#"
        INSERT INTO auth_rate_limits (limit_key, window_start_at, request_count, updated_at)
        VALUES ($1, TO_TIMESTAMP($2), 0, NOW())
        ON CONFLICT (limit_key) DO NOTHING
        "#,
    )
    .bind(key)
    .bind(now)
    .execute(&mut *tx)
    .await
    .map_err(|e| {
        tracing::error!(
            error = %e,
            limit_key_hash = hash_prefix(key),
            "rate-limit insert failed"
        );
        ApiError::internal("rate-limit unavailable")
    })?;

    let row = sqlx::query(
        "SELECT FLOOR(EXTRACT(EPOCH FROM window_start_at))::BIGINT AS window_start_epoch, request_count \
         FROM auth_rate_limits WHERE limit_key=$1 FOR UPDATE",
    )
    .bind(key)
    .fetch_one(&mut *tx)
    .await
    .map_err(|e| {
        tracing::error!(
            error = %e,
            limit_key_hash = hash_prefix(key),
            "rate-limit select failed"
        );
        ApiError::internal("rate-limit unavailable")
    })?;
    let mut window_start: i64 = require_rate_limit_i64_column(
        row.try_get("window_start_epoch"),
        "window_start_epoch",
        key,
        "consume_rate_limit_window_read",
    )?;
    let mut request_count: i64 = require_rate_limit_i64_column(
        row.try_get("request_count"),
        "request_count",
        key,
        "consume_rate_limit_window_read",
    )?;
    if request_count < 0 {
        tracing::error!(
            request_count,
            limit_key_hash = hash_prefix(key),
            "rate-limit request_count invariant violated"
        );
        return Err(ApiError::internal("rate-limit unavailable"));
    }
    let decision = next_rate_limit_decision(
        now,
        window_start,
        request_count,
        window_secs,
        max_per_window,
    );
    window_start = decision.window_start_epoch;
    request_count = decision.request_count;
    sqlx::query(
        "UPDATE auth_rate_limits \
         SET window_start_at=TO_TIMESTAMP($1), request_count=$2, updated_at=NOW() \
         WHERE limit_key=$3",
    )
    .bind(window_start)
    .bind(request_count)
    .bind(key)
    .execute(&mut *tx)
    .await
    .map_err(|e| {
        tracing::error!(
            error = %e,
            limit_key_hash = hash_prefix(key),
            "rate-limit update failed"
        );
        ApiError::internal("rate-limit unavailable")
    })?;
    tx.commit().await.map_err(|e| {
        tracing::error!(
            error = %e,
            limit_key_hash = hash_prefix(key),
            "rate-limit tx commit failed"
        );
        ApiError::internal("rate-limit unavailable")
    })?;

    if !decision.allowed {
        let retry_after_secs = rate_limit_retry_after_secs(now, window_start, window_secs);
        tracing::warn!(
            security_event = "auth_rate_limit_exceeded",
            outcome = "blocked",
            limit_key_hash = hash_prefix(key),
            window_secs,
            max_per_window,
            retry_after_secs,
            "auth rate limit exceeded"
        );
        return Err(ApiError::new(
            StatusCode::TOO_MANY_REQUESTS,
            format!("too many requests; retry_after_secs={retry_after_secs}"),
        ));
    }
    Ok(())
}

async fn consume_rate_limit_once_in_tx(
    tx: &mut Transaction<'_, Postgres>,
    key: &str,
    window_secs: i64,
) -> ApiResult<MutationReplayDecision> {
    let now_row = sqlx::query("SELECT FLOOR(EXTRACT(EPOCH FROM NOW()))::BIGINT AS now_epoch")
        .fetch_one(&mut **tx)
        .await
        .map_err(|e| {
            tracing::error!(
                error = %e,
                limit_key_hash = hash_prefix(key),
                "rate-limit clock read failed"
            );
            ApiError::internal("rate-limit unavailable")
        })?;
    let now: i64 = require_rate_limit_i64_column(
        now_row.try_get("now_epoch"),
        "now_epoch",
        key,
        "consume_rate_limit_once_in_tx_clock_read",
    )?;

    sqlx::query(
        r#"
        INSERT INTO auth_rate_limits (limit_key, window_start_at, request_count, updated_at)
        VALUES ($1, TO_TIMESTAMP($2), 0, NOW())
        ON CONFLICT (limit_key) DO NOTHING
        "#,
    )
    .bind(key)
    .bind(now)
    .execute(&mut **tx)
    .await
    .map_err(|e| {
        tracing::error!(
            error = %e,
            limit_key_hash = hash_prefix(key),
            "rate-limit insert failed"
        );
        ApiError::internal("rate-limit unavailable")
    })?;

    let row = sqlx::query(
        "SELECT FLOOR(EXTRACT(EPOCH FROM window_start_at))::BIGINT AS window_start_epoch, request_count \
         FROM auth_rate_limits WHERE limit_key=$1 FOR UPDATE",
    )
    .bind(key)
    .fetch_one(&mut **tx)
    .await
    .map_err(|e| {
        tracing::error!(
            error = %e,
            limit_key_hash = hash_prefix(key),
            "rate-limit select failed"
        );
        ApiError::internal("rate-limit unavailable")
    })?;
    let window_start: i64 = require_rate_limit_i64_column(
        row.try_get("window_start_epoch"),
        "window_start_epoch",
        key,
        "consume_rate_limit_once_in_tx_window_read",
    )?;
    let request_count: i64 = require_rate_limit_i64_column(
        row.try_get("request_count"),
        "request_count",
        key,
        "consume_rate_limit_once_in_tx_window_read",
    )?;
    if request_count < 0 {
        tracing::error!(
            request_count,
            limit_key_hash = hash_prefix(key),
            "rate-limit request_count invariant violated"
        );
        return Err(ApiError::internal("rate-limit unavailable"));
    }

    let decision = next_rate_limit_decision(now, window_start, request_count, window_secs, 1);
    if !decision.allowed {
        sqlx::query("UPDATE auth_rate_limits SET updated_at=NOW() WHERE limit_key=$1")
            .bind(key)
            .execute(&mut **tx)
            .await
            .map_err(|e| {
                tracing::error!(
                    error = %e,
                    limit_key_hash = hash_prefix(key),
                    "rate-limit touch failed"
                );
                ApiError::internal("rate-limit unavailable")
            })?;
        return Ok(MutationReplayDecision::Replay);
    }

    sqlx::query(
        "UPDATE auth_rate_limits \
         SET window_start_at=TO_TIMESTAMP($1), request_count=$2, updated_at=NOW() \
         WHERE limit_key=$3",
    )
    .bind(decision.window_start_epoch)
    .bind(decision.request_count)
    .bind(key)
    .execute(&mut **tx)
    .await
    .map_err(|e| {
        tracing::error!(
            error = %e,
            limit_key_hash = hash_prefix(key),
            "rate-limit update failed"
        );
        ApiError::internal("rate-limit unavailable")
    })?;

    Ok(MutationReplayDecision::Fresh)
}

fn normalize_hex_32(raw: &str) -> Option<String> {
    let t = raw.trim();
    if t.len() != 32 {
        return None;
    }
    if !t.chars().all(|c| c.is_ascii_hexdigit()) {
        return None;
    }
    Some(t.to_ascii_lowercase())
}

fn normalize_hex_64(raw: &str) -> Option<String> {
    let t = raw.trim();
    if t.len() != 64 {
        return None;
    }
    if !t.chars().all(|c| c.is_ascii_hexdigit()) {
        return None;
    }
    Some(t.to_ascii_lowercase())
}

fn normalize_session_account_id(raw: Option<&str>) -> Option<String> {
    raw.map(str::trim)
        .filter(|value| !value.is_empty())
        .and_then(normalize_hex_64)
}

fn truncate_utf8_safely(s: &mut String, max: usize) {
    if s.len() <= max {
        return;
    }
    let mut boundary = max;
    while boundary > 0 && !s.is_char_boundary(boundary) {
        boundary -= 1;
    }
    s.truncate(boundary);
}

fn normalize_device_id(raw: Option<&str>) -> Option<String> {
    let mut s = raw.unwrap_or_default().trim().to_string();
    if s.is_empty() {
        return None;
    }
    if s.len() > 128 {
        truncate_utf8_safely(&mut s, 128);
    }
    if s.chars().any(|c| c.is_control()) {
        return None;
    }
    Some(s)
}

fn normalize_small(raw: Option<&str>, max: usize) -> Option<String> {
    let mut s = raw.unwrap_or_default().trim().to_string();
    if s.is_empty() {
        return None;
    }
    if s.len() > max {
        truncate_utf8_safely(&mut s, max);
    }
    if s.chars().any(|c| c.is_control()) {
        return None;
    }
    Some(s)
}

fn is_bidi_spoofing_char(ch: char) -> bool {
    matches!(
        ch,
        '\u{061C}' // Arabic letter mark
            | '\u{200E}' // left-to-right mark
            | '\u{200F}' // right-to-left mark
            | '\u{202A}' // left-to-right embedding
            | '\u{202B}' // right-to-left embedding
            | '\u{202C}' // pop directional formatting
            | '\u{202D}' // left-to-right override
            | '\u{202E}' // right-to-left override
            | '\u{2066}' // left-to-right isolate
            | '\u{2067}' // right-to-left isolate
            | '\u{2068}' // first strong isolate
            | '\u{2069}' // pop directional isolate
    )
}

fn normalize_device_login_label(raw: Option<&str>, max: usize) -> Option<String> {
    let mut out = String::new();
    let mut prev_space = false;
    for ch in raw.unwrap_or_default().chars() {
        if ch.is_control() || is_bidi_spoofing_char(ch) {
            continue;
        }
        if ch.is_whitespace() {
            if out.is_empty() || prev_space {
                continue;
            }
            out.push(' ');
            prev_space = true;
            continue;
        }
        out.push(ch);
        prev_space = false;
    }
    let mut normalized = out.trim().to_string();
    if normalized.is_empty() {
        return None;
    }
    if normalized.len() > max {
        truncate_utf8_safely(&mut normalized, max);
        normalized = normalized.trim().to_string();
    }
    if normalized.is_empty() {
        return None;
    }
    Some(normalized)
}

fn normalize_optional_idempotency_key(headers: &HeaderMap) -> ApiResult<Option<String>> {
    let Some(raw) = headers.get("Idempotency-Key") else {
        return Ok(None);
    };
    let raw = raw
        .to_str()
        .map_err(|_| ApiError::bad_request("invalid Idempotency-Key"))?;
    let key = raw.trim();
    if key.is_empty() || key.len() > IDEMPOTENCY_KEY_MAX_LEN {
        return Err(ApiError::bad_request("invalid Idempotency-Key"));
    }
    if key.chars().any(|ch| ch.is_ascii_control()) {
        return Err(ApiError::bad_request("invalid Idempotency-Key"));
    }
    if !key
        .chars()
        .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_' | '.' | ':'))
    {
        return Err(ApiError::bad_request("invalid Idempotency-Key"));
    }
    Ok(Some(key.to_string()))
}

fn official_service_template_message_replay_guard_key(
    headers: &HeaderMap,
    principal: &AuthPrincipal,
    official_id: &str,
    session_id: i64,
    title: &str,
    message_body: &str,
) -> ApiResult<(String, i64, &'static str)> {
    let account_id = principal.account_id.trim();
    if account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }
    let payload_hash = sha256_hex(&format!(
        "{}\n{}\n{}\n{}",
        official_id.trim(),
        session_id,
        title.trim(),
        message_body.trim()
    ));
    let idempotency_key = normalize_optional_idempotency_key(headers)?;
    let out = if let Some(idempotency_key) = idempotency_key {
        (
            format!(
                "admin_role_mutation_idem:official_service_inbox_send_template_message:{}:{}:{}:{}:{}",
                hash_prefix(account_id),
                hash_prefix(official_id),
                hash_i64_prefix(session_id),
                sha256_hex(&idempotency_key),
                payload_hash
            ),
            ADMIN_ROLE_MUTATION_IDEMPOTENCY_WINDOW_SECS,
            "header",
        )
    } else {
        (
            format!(
                "admin_role_mutation_replay:official_service_inbox_send_template_message:{}:{}:{}:{}",
                hash_prefix(account_id),
                hash_prefix(official_id),
                hash_i64_prefix(session_id),
                payload_hash
            ),
            OFFICIAL_SERVICE_TEMPLATE_LEGACY_REPLAY_WINDOW_SECS,
            "legacy_payload",
        )
    };
    Ok(out)
}

