fn official_account_profile_mutation_replay_guard_key(
    headers: &HeaderMap,
    principal: &AuthPrincipal,
    payload: OfficialAccountProfileMutationReplayPayload<'_>,
) -> ApiResult<(String, i64, &'static str)> {
    let OfficialAccountProfileMutationReplayPayload {
        official_id,
        address,
        opening_hours,
        website_url,
        qr_payload,
    } = payload;
    let account_id = principal.account_id.trim();
    if account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }
    let payload_hash = sha256_hex(&format!(
        "{}\n{}\n{}\n{}\n{}",
        official_id.trim(),
        address.unwrap_or_default().trim(),
        opening_hours.unwrap_or_default().trim(),
        website_url.unwrap_or_default().trim(),
        qr_payload.unwrap_or_default().trim(),
    ));
    let idempotency_key = normalize_optional_idempotency_key(headers)?;
    let out = if let Some(idempotency_key) = idempotency_key {
        (
            format!(
                "admin_role_mutation_idem:official_account_profile_mutation:{}:{}:{}:{}",
                hash_prefix(account_id),
                hash_prefix(official_id),
                sha256_hex(&idempotency_key),
                payload_hash
            ),
            ADMIN_ROLE_MUTATION_IDEMPOTENCY_WINDOW_SECS,
            "header",
        )
    } else {
        (
            format!(
                "admin_role_mutation_replay:official_account_profile_mutation:{}:{}:{}",
                hash_prefix(account_id),
                hash_prefix(official_id),
                payload_hash
            ),
            OFFICIAL_ACCOUNT_PROFILE_LEGACY_REPLAY_WINDOW_SECS,
            "legacy_payload",
        )
    };
    Ok(out)
}

fn official_feed_create_replay_guard_key(
    headers: &HeaderMap,
    principal: &AuthPrincipal,
    official_id: &str,
    item_id: &str,
    title: &str,
    snippet: Option<&str>,
    thumb_url: Option<&str>,
) -> ApiResult<(String, i64, &'static str)> {
    let account_id = principal.account_id.trim();
    if account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }
    let payload_hash = sha256_hex(&format!(
        "{}\n{}\n{}\n{}\n{}",
        official_id.trim(),
        item_id.trim(),
        title.trim(),
        snippet.unwrap_or_default().trim(),
        thumb_url.unwrap_or_default().trim(),
    ));
    let idempotency_key = normalize_optional_idempotency_key(headers)?;
    let out = if let Some(idempotency_key) = idempotency_key {
        (
            format!(
                "admin_role_mutation_idem:official_feed_create:{}:{}:{}:{}",
                hash_prefix(account_id),
                hash_prefix(official_id),
                sha256_hex(&idempotency_key),
                payload_hash
            ),
            ADMIN_ROLE_MUTATION_IDEMPOTENCY_WINDOW_SECS,
            "header",
        )
    } else {
        (
            format!(
                "admin_role_mutation_replay:official_feed_create:{}:{}:{}:{}",
                hash_prefix(account_id),
                hash_prefix(official_id),
                hash_prefix(item_id),
                payload_hash
            ),
            OFFICIAL_FEED_CREATE_LEGACY_REPLAY_WINDOW_SECS,
            "legacy_payload",
        )
    };
    Ok(out)
}

fn official_owner_mutation_idempotency_key(
    headers: &HeaderMap,
    principal: &AuthPrincipal,
    official_id: &str,
    operation: &str,
    role: &str,
    account_id: Option<&str>,
    phone: Option<&str>,
) -> ApiResult<(String, &'static str)> {
    if let Some(idempotency_key) = normalize_optional_idempotency_key(headers)? {
        return Ok((idempotency_key, "header"));
    }
    let actor_account_id = principal.account_id.trim();
    if actor_account_id.is_empty() {
        return Err(ApiError::new(StatusCode::UNAUTHORIZED, "unauthorized"));
    }
    let operation = operation.trim().to_ascii_lowercase();
    let role = role.trim().to_ascii_lowercase();
    let subject =
        if let Some(account_id) = account_id.map(str::trim).filter(|value| !value.is_empty()) {
            format!("account:{account_id}")
        } else if let Some(phone) = phone.map(str::trim).filter(|value| !value.is_empty()) {
            format!("phone:{phone}")
        } else {
            "none".to_string()
        };
    let digest = sha256_hex(&format!(
        "{}\n{}\n{}\n{}\n{}",
        actor_account_id,
        official_id.trim().to_ascii_lowercase(),
        operation,
        role,
        subject
    ));
    let fallback = format!(
        "official-owner-{}-{}",
        if operation.is_empty() {
            "mutation"
        } else {
            operation.as_str()
        },
        digest.chars().take(32).collect::<String>()
    );
    Ok((fallback, "derived_payload"))
}

fn header_value(headers: &HeaderMap, name: &str) -> Option<String> {
    headers
        .get(name)
        .and_then(|v| v.to_str().ok())
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(ToString::to_string)
}

fn normalize_app_surface_header_value(raw: Option<&str>) -> &'static str {
    match raw.unwrap_or_default().trim().to_ascii_lowercase().as_str() {
        "ride" | "rides" | "taxi" => "ride",
        "driver" | "ride_driver" | "taxi_driver" => "driver",
        "operator" | "ops" | "ride_operator" | "taxi_operator" => "operator",
        "superapp" => "superapp",
        _ => "superapp",
    }
}

fn rate_limit_client_ip(state: &AppState, headers: &HeaderMap) -> ApiResult<String> {
    if let Some(ip) = client_ip_from_headers(state, headers) {
        return Ok(ip);
    }
    let env_lower = state.env_name.trim().to_ascii_lowercase();
    if matches!(env_lower.as_str(), "prod" | "production" | "staging") {
        tracing::error!("missing trusted client IP header (X-Shamell-Client-IP) on auth path");
        return Err(ApiError::internal("client ip unavailable"));
    }
    Ok("unknown".to_string())
}

fn client_ip_from_headers(state: &AppState, headers: &HeaderMap) -> Option<String> {
    let env_lower = state.env_name.trim().to_ascii_lowercase();
    let ip_attested =
        header_value(headers, TRUSTED_CLIENT_IP_ATTESTED_HEADER).is_some_and(|v| v == "1");
    if let Some(ip) = header_value(headers, "x-shamell-client-ip").and_then(|v| parse_ip(&v)) {
        if ip_attested || matches!(env_lower.as_str(), "dev" | "test") {
            return Some(ip);
        }
    }

    if !matches!(env_lower.as_str(), "dev" | "test") {
        return None;
    }

    if let Some(first) = header_value(headers, "x-forwarded-for")
        .and_then(|v| v.split(',').next().map(str::trim).map(str::to_string))
    {
        if let Some(ip) = parse_ip(&first) {
            return Some(ip);
        }
    }
    header_value(headers, "x-real-ip").and_then(|v| parse_ip(&v))
}

fn parse_ip(raw: &str) -> Option<String> {
    let token = raw.trim();
    if token.is_empty() {
        return None;
    }
    let token = token
        .strip_prefix("for=")
        .or_else(|| token.strip_prefix("For="))
        .unwrap_or(token)
        .trim()
        .trim_matches('"');

    if let Ok(ip) = token.parse::<IpAddr>() {
        return Some(ip.to_string());
    }
    if let Ok(sock) = token.parse::<SocketAddr>() {
        return Some(sock.ip().to_string());
    }
    if token.starts_with('[') {
        if let Some(end) = token.find(']') {
            let inner = &token[1..end];
            if let Ok(ip) = inner.parse::<IpAddr>() {
                return Some(ip.to_string());
            }
        }
    }
    let trimmed = token.trim_matches('[').trim_matches(']');
    if let Ok(ip) = trimmed.parse::<IpAddr>() {
        return Some(ip.to_string());
    }
    None
}

fn append_set_cookie(resp: &mut Response, value: &str) {
    if let Ok(v) = HeaderValue::from_str(value) {
        resp.headers_mut().append(header::SET_COOKIE, v);
    }
}

fn append_no_store(resp: &mut Response) {
    resp.headers_mut()
        .insert(header::CACHE_CONTROL, HeaderValue::from_static("no-store"));
}

fn json_no_store(value: Value) -> Response {
    let mut resp = Json(value).into_response();
    append_no_store(&mut resp);
    resp
}

fn json_no_store_payload<T: Serialize>(value: T) -> Response {
    let mut resp = Json(value).into_response();
    append_no_store(&mut resp);
    resp
}

