struct AuthDeviceDeleteResponsePayload<'a> {
    status: &'a str,
    deleted_device_record: u64,
    revoked_sessions: u64,
    revoked_biometric_tokens: u64,
    revoked_contact_invites: u64,
    revoked_device_login_challenges: u64,
    revoked_chat_devices: u64,
    revoked_chat_contacts: u64,
    clear_current_session: bool,
}

fn auth_device_delete_response(payload: AuthDeviceDeleteResponsePayload<'_>) -> Response {
    let AuthDeviceDeleteResponsePayload {
        status,
        deleted_device_record,
        revoked_sessions,
        revoked_biometric_tokens,
        revoked_contact_invites,
        revoked_device_login_challenges,
        revoked_chat_devices,
        revoked_chat_contacts,
        clear_current_session,
    } = payload;
    let mut resp = if status == "ignored" {
        json_no_store(json!({ "status": "ignored" }))
    } else {
        json_no_store(json!({
            "status": status,
            "deleted_device_record": deleted_device_record,
            "revoked_sessions": revoked_sessions,
            "revoked_biometric_tokens": revoked_biometric_tokens,
            "revoked_contact_invites": revoked_contact_invites,
            "revoked_device_login_challenges": revoked_device_login_challenges,
            "revoked_chat_devices": revoked_chat_devices,
            "revoked_chat_contacts": revoked_chat_contacts
        }))
    };
    if clear_current_session {
        append_set_cookie(&mut resp, &clear_session_cookie_value());
        append_set_cookie(&mut resp, &clear_legacy_session_cookie_value());
    }
    resp
}

