fn strict_html_page_csp(style_nonce: &str, script_nonce: Option<&str>) -> String {
    let script_src = match script_nonce {
        Some(nonce) => format!("script-src 'nonce-{nonce}'"),
        None => "script-src 'none'".to_string(),
    };
    format!(
        "default-src 'none'; base-uri 'none'; frame-ancestors 'none'; object-src 'none'; form-action 'self'; img-src 'self' data:; style-src 'nonce-{style_nonce}'; {script_src}; connect-src 'self'; manifest-src 'self'; frame-src 'none'"
    )
}

fn html_response_with_csp(body: String, csp_value: &str) -> Response {
    let mut resp = Html(body).into_response();
    if let Ok(value) = HeaderValue::from_str(csp_value) {
        resp.headers_mut().insert("content-security-policy", value);
    }
    resp
}

