pub(crate) fn url_escape_component(raw: &str) -> String {
    fn hex(b: u8) -> char {
        match b {
            0..=9 => (b'0' + b) as char,
            10..=15 => (b'A' + (b - 10)) as char,
            _ => '0',
        }
    }

    let mut out = String::with_capacity(raw.len());
    for &b in raw.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(hex(b >> 4));
                out.push(hex(b & 0x0F));
            }
        }
    }
    out
}

fn build_device_login_app_link(token: &str, label: &str) -> String {
    let mut payload = format!(
        "{SHAMELL_APP_LINK_ORIGIN}{SHAMELL_APP_LINK_PATH_PREFIX}/device_login#token={}",
        url_escape_component(token.trim())
    );
    let normalized_label = normalize_device_login_label(Some(label), 64).unwrap_or_default();
    if !normalized_label.is_empty() {
        payload.push_str("&label=");
        payload.push_str(&url_escape_component(&normalized_label));
    }
    payload
}

fn row_to_device_json(row: &sqlx::postgres::PgRow) -> ApiResult<Value> {
    let id = require_auth_i64_compatible_column(
        row,
        "id",
        "auth_devices_list_row_decode",
        "failed to list devices",
    )?;
    let device_id: String = require_auth_text_column(
        row.try_get("device_id"),
        "device_id",
        "auth_devices_list_row_decode",
        "failed to list devices",
    )?;
    let device_type: Option<String> = require_auth_optional_text_column(
        row.try_get("device_type"),
        "device_type",
        "auth_devices_list_row_decode",
        "failed to list devices",
    )?;
    let device_name: Option<String> = require_auth_optional_text_column(
        row.try_get("device_name"),
        "device_name",
        "auth_devices_list_row_decode",
        "failed to list devices",
    )?;
    let platform: Option<String> = require_auth_optional_text_column(
        row.try_get("platform"),
        "platform",
        "auth_devices_list_row_decode",
        "failed to list devices",
    )?;
    let app_version: Option<String> = require_auth_optional_text_column(
        row.try_get("app_version"),
        "app_version",
        "auth_devices_list_row_decode",
        "failed to list devices",
    )?;
    let last_ip: Option<String> = require_auth_optional_text_column(
        row.try_get("last_ip"),
        "last_ip",
        "auth_devices_list_row_decode",
        "failed to list devices",
    )?;
    let user_agent: Option<String> = require_auth_optional_text_column(
        row.try_get("user_agent"),
        "user_agent",
        "auth_devices_list_row_decode",
        "failed to list devices",
    )?;
    let created_at: Option<String> = require_auth_optional_text_column(
        row.try_get("created_at"),
        "created_at",
        "auth_devices_list_row_decode",
        "failed to list devices",
    )?;
    let last_seen_at: Option<String> = require_auth_optional_text_column(
        row.try_get("last_seen_at"),
        "last_seen_at",
        "auth_devices_list_row_decode",
        "failed to list devices",
    )?;

    Ok(json!({
        "id": id,
        "device_id": device_id,
        "device_type": device_type,
        "device_name": device_name,
        "platform": platform,
        "app_version": app_version,
        "last_ip": last_ip,
        "user_agent": user_agent,
        "created_at": created_at,
        "last_seen_at": last_seen_at,
    }))
}

fn require_auth_i64_compatible_column(
    row: &sqlx::postgres::PgRow,
    column: &'static str,
    context: &'static str,
    failure_detail: &'static str,
) -> ApiResult<i64> {
    match row.try_get::<i64, _>(column) {
        Ok(value) => Ok(value),
        Err(err_i64) => match row.try_get::<i32, _>(column) {
            Ok(value) => Ok(i64::from(value)),
            Err(err_i32) => {
                tracing::error!(
                    error = %err_i64,
                    fallback_error = %err_i32,
                    column,
                    context,
                    "auth integer column decode failed"
                );
                Err(ApiError::internal(failure_detail))
            }
        },
    }
}

fn redact_device_response_json(device: Value) -> Value {
    let mut device = match device {
        Value::Object(map) => map,
        other => return other,
    };
    device.remove("phone");
    device.remove("account_id");
    Value::Object(device)
}

