async fn assert_auth_schema_ready(pool: &PgPool) -> Result<(), sqlx::Error> {
    schema_contract::ensure_contracts(
        required_auth_tables(),
        |spec| async move { table_exists(pool, spec.qualified_name.as_ref()).await },
        |spec| {
            format!(
                "required auth table missing after ensure_auth_schema: {}",
                spec.qualified_name
            )
        },
    )
    .await?;

    schema_contract::ensure_contracts(
        required_auth_columns(),
        |spec| column_exists(pool, spec.table, spec.column),
        |spec| {
            format!(
                "required auth column missing after ensure_auth_schema: {}.{}",
                spec.table, spec.column
            )
        },
    )
    .await?;

    schema_contract::ensure_contracts(
        required_auth_nullable_columns(),
        |spec| column_matches_nullability(pool, *spec),
        |spec| {
            format!(
                "required auth nullable column missing after ensure_auth_schema: {}.{}",
                spec.table, spec.column
            )
        },
    )
    .await?;

    schema_contract::ensure_contracts(
        required_auth_not_null_columns(),
        |spec| column_matches_nullability(pool, *spec),
        |spec| {
            format!(
                "required auth NOT NULL column missing after ensure_auth_schema: {}.{}",
                spec.table, spec.column
            )
        },
    )
    .await?;

    schema_contract::ensure_contracts(
        required_auth_primary_keys(),
        |spec| has_single_column_primary_key(pool, spec.table, spec.column),
        |spec| {
            format!(
                "required auth primary key missing after ensure_auth_schema: {}.{}",
                spec.table, spec.column
            )
        },
    )
    .await?;

    schema_contract::ensure_contracts(
        required_auth_single_column_unique_constraints(),
        |spec| has_single_column_unique_constraint(pool, spec.table, spec.column),
        |spec| {
            format!(
                "required auth unique constraint missing after ensure_auth_schema: {}.{}",
                spec.table, spec.column
            )
        },
    )
    .await?;

    schema_contract::ensure_contracts(
        required_auth_pair_unique_constraints(),
        |spec| {
            has_two_column_unique_constraint(
                pool,
                spec.table,
                spec.first_column,
                spec.second_column,
            )
        },
        |spec| {
            format!(
                "required auth unique constraint missing after ensure_auth_schema: {}.{},{}",
                spec.table, spec.first_column, spec.second_column
            )
        },
    )
    .await?;

    schema_contract::ensure_contracts(
        required_auth_pair_unique_indexes(),
        |spec| {
            has_named_two_column_unique_index(
                pool,
                spec.index_name,
                spec.table,
                spec.first_column,
                spec.second_column,
            )
        },
        |spec| {
            format!(
                "required auth unique index missing after ensure_auth_schema: {} on {}({},{})",
                spec.index_name, spec.table, spec.first_column, spec.second_column
            )
        },
    )
    .await?;

    schema_contract::ensure_contracts(
        required_auth_pair_partial_indexes(),
        |spec| {
            has_named_two_column_partial_index(
                pool,
                spec.index_name,
                spec.table,
                spec.first_column,
                spec.second_column,
                spec.predicate,
            )
        },
        |spec| {
            format!(
                "required auth partial index missing after ensure_auth_schema: {} on {}({},{}) WHERE {}",
                spec.index_name, spec.table, spec.first_column, spec.second_column, spec.predicate
            )
        },
    )
    .await?;

    schema_contract::ensure_contracts(
        required_auth_ordered_indexes(),
        |spec| {
            has_named_index_with_columns_fragment(
                pool,
                spec.index_name,
                spec.table,
                spec.columns_fragment,
            )
        },
        |spec| {
            format!(
                "required auth ordered index missing after ensure_auth_schema: {} on {}({})",
                spec.index_name, spec.table, spec.columns_fragment
            )
        },
    )
    .await?;

    schema_contract::ensure_contracts(
        required_auth_lookup_indexes(),
        |spec| {
            has_named_index_with_columns_fragment(
                pool,
                spec.index_name,
                spec.table,
                spec.columns_fragment,
            )
        },
        |spec| {
            format!(
                "required auth lookup index missing after ensure_auth_schema: {} on {}({})",
                spec.index_name, spec.table, spec.columns_fragment
            )
        },
    )
    .await?;

    schema_contract::ensure_contracts(
        required_auth_cleanup_indexes(),
        |spec| {
            has_named_index_with_columns_fragment(
                pool,
                spec.index_name,
                spec.table,
                spec.columns_fragment,
            )
        },
        |spec| {
            format!(
                "required auth cleanup index missing after ensure_auth_schema: {} on {}({})",
                spec.index_name, spec.table, spec.columns_fragment
            )
        },
    )
    .await?;

    schema_contract::ensure_contracts(
        required_auth_ordered_partial_indexes(),
        |spec| {
            has_named_partial_index_with_columns_and_predicate(
                pool,
                spec.index_name,
                spec.table,
                spec.columns_fragment,
                spec.predicate,
            )
        },
        |spec| {
            format!(
                "required auth ordered partial index missing after ensure_auth_schema: {} on {}({}) WHERE {}",
                spec.index_name, spec.table, spec.columns_fragment, spec.predicate
            )
        },
    )
    .await?;

    schema_contract::ensure_contracts(
        required_auth_unique_partial_indexes(),
        |spec| {
            has_named_unique_partial_index_with_columns_and_predicate(
                pool,
                spec.index_name,
                spec.table,
                spec.columns_fragment,
                spec.predicate,
            )
        },
        |spec| {
            format!(
                "required auth unique partial index missing after ensure_auth_schema: {} on {}({}) WHERE {}",
                spec.index_name, spec.table, spec.columns_fragment, spec.predicate
            )
        },
    )
    .await?;

    schema_contract::ensure_contracts(
        required_auth_foreign_key_constraints(),
        |spec| {
            has_named_single_column_foreign_key_with_delete_action(
                pool,
                spec.table,
                spec.constraint,
                spec.column,
                spec.referenced_table,
                spec.referenced_column,
                spec.delete_action,
            )
        },
        |spec| {
            format!(
                "required auth foreign key constraint missing after ensure_auth_schema: {}.{} ({} -> {}.{} ON DELETE {})",
                spec.table,
                spec.constraint,
                spec.column,
                spec.referenced_table,
                spec.referenced_column,
                spec.delete_action
            )
        },
    )
    .await?;

    schema_contract::ensure_contracts(
        required_auth_check_constraints(),
        |spec| async move {
            has_named_check_constraint_with_predicate(
                pool,
                spec.table,
                spec.constraint,
                spec.predicate.as_ref(),
            )
            .await
        },
        |spec| {
            format!(
                "required auth check constraint missing after ensure_auth_schema: {}.{} CHECK ({})",
                spec.table, spec.constraint, spec.predicate
            )
        },
    )
    .await?;

    schema_contract::ensure_contracts(
        required_auth_name_only_indexes(),
        |spec| async move { index_exists(pool, spec.qualified_name.as_ref()).await },
        |spec| {
            format!(
                "required auth index missing after ensure_auth_schema: {}",
                spec.qualified_name
            )
        },
    )
    .await?;

    schema_contract::ensure_contracts(
        required_auth_name_only_constraints(),
        |spec| constraint_exists(pool, spec.table, spec.constraint),
        |spec| {
            format!(
                "required auth constraint missing after ensure_auth_schema: {}.{}",
                spec.table, spec.constraint
            )
        },
    )
    .await?;

    Ok(())
}

pub async fn ensure_auth_schema(pool: &PgPool) -> Result<(), sqlx::Error> {
    assert_auth_schema_ready(pool).await
}

