    #[derive(Clone, Debug, Default)]
    struct CapturedTracingEvent {
        fields: BTreeMap<String, String>,
    }

    #[derive(Clone, Default)]
    struct SharedEventBuffer(Arc<Mutex<Vec<CapturedTracingEvent>>>);

    impl SharedEventBuffer {
        fn push(&self, event: CapturedTracingEvent) {
            let mut guard = self.0.lock().expect("event buffer lock");
            guard.push(event);
        }

        fn contains_field_value(&self, field: &str, expected: &str) -> bool {
            let guard = self.0.lock().expect("event buffer lock");
            guard
                .iter()
                .any(|event| event.fields.get(field).map(String::as_str) == Some(expected))
        }

        fn snapshot(&self) -> Vec<CapturedTracingEvent> {
            let guard = self.0.lock().expect("event buffer lock");
            guard.clone()
        }
    }

    #[derive(Default)]
    struct CapturedTracingEventVisitor {
        fields: BTreeMap<String, String>,
    }

    impl Visit for CapturedTracingEventVisitor {
        fn record_bool(&mut self, field: &Field, value: bool) {
            self.fields
                .insert(field.name().to_string(), value.to_string());
        }

        fn record_i64(&mut self, field: &Field, value: i64) {
            self.fields
                .insert(field.name().to_string(), value.to_string());
        }

        fn record_u64(&mut self, field: &Field, value: u64) {
            self.fields
                .insert(field.name().to_string(), value.to_string());
        }

        fn record_str(&mut self, field: &Field, value: &str) {
            self.fields
                .insert(field.name().to_string(), value.to_string());
        }

        fn record_error(&mut self, field: &Field, value: &(dyn std::error::Error + 'static)) {
            self.fields
                .insert(field.name().to_string(), value.to_string());
        }

        fn record_debug(&mut self, field: &Field, value: &dyn std::fmt::Debug) {
            self.fields
                .insert(field.name().to_string(), format!("{value:?}"));
        }
    }

    #[derive(Clone)]
    struct EventCaptureLayer(SharedEventBuffer);

    impl EventCaptureLayer {
        fn new(events: SharedEventBuffer) -> Self {
            Self(events)
        }
    }

    impl<S> Layer<S> for EventCaptureLayer
    where
        S: Subscriber,
    {
        fn on_event(&self, event: &Event<'_>, _ctx: Context<'_, S>) {
            let mut visitor = CapturedTracingEventVisitor::default();
            event.record(&mut visitor);
            self.0.push(CapturedTracingEvent {
                fields: visitor.fields,
            });
        }
    }

    fn assert_sql_contains_all(sql: &str, expected_fragments: &[&str]) {
        for fragment in expected_fragments {
            assert!(
                sql.contains(fragment),
                "missing SQL fragment `{fragment}` in `{sql}`"
            );
        }
    }

    fn assert_unknown_field_error(err: &impl std::fmt::Display, field: &str) {
        let expected = format!("unknown field `{field}`");
        let msg = err.to_string();
        assert!(
            msg.contains(&expected),
            "expected `{expected}` in error `{msg}`"
        );
    }

    fn assert_value_omits_fields(value: &Value, fields: &[&str]) {
        for field in fields {
            assert!(
                value.get(field).is_none(),
                "expected field `{field}` to be omitted in `{value}`"
            );
        }
    }

    fn assert_some_str(actual: Option<&str>, expected: &str) {
        assert_eq!(actual, Some(expected));
    }

    fn assert_some_str_with_context(actual: Option<&str>, expected: &str, context: &str) {
        assert_eq!(actual, Some(expected), "{context}");
    }

    fn assert_some_eq<T: PartialEq + std::fmt::Debug>(actual: Option<T>, expected: T) {
        assert_eq!(actual, Some(expected));
    }

    fn assert_ok_eq<T: PartialEq + std::fmt::Debug, E: std::fmt::Debug>(
        actual: Result<T, E>,
        expected: T,
    ) {
        assert_eq!(actual.expect("expected Ok result"), expected);
    }

    fn assert_some_string(actual: Option<String>, expected: &str) {
        assert_some_str(actual.as_deref(), expected);
    }

    fn assert_str_eq(actual: &str, expected: &str, context: &str) {
        assert_eq!(actual, expected, "unexpected {context}");
    }

    fn assert_str_contains(actual: &str, expected_fragment: &str, context: &str) {
        assert!(
            actual.contains(expected_fragment),
            "unexpected {context}: {actual}"
        );
    }

    fn assert_bool_eq(actual: bool, expected: bool, context: &str) {
        assert_eq!(actual, expected, "unexpected {context}");
    }

    fn assert_not_equal<T: PartialEq + std::fmt::Debug>(actual: &T, unexpected: &T, context: &str) {
        assert_ne!(actual, unexpected, "unexpected {context}");
    }

    fn assert_none_option<T: std::fmt::Debug>(actual: Option<T>) {
        assert!(actual.is_none(), "expected None, got {actual:?}");
    }

    fn assert_err_result<T, E: std::fmt::Debug>(actual: Result<T, E>) {
        assert!(actual.is_err(), "expected Err result");
    }

