    async fn assert_no_store_json_response_eq(resp: Response, expected: Value) -> Value {
        assert_no_store_cache_control(resp.headers());
        let body = to_bytes(resp.into_body(), usize::MAX)
            .await
            .expect("read response body");
        let value: Value = serde_json::from_slice(&body).expect("json body");
        assert_eq!(value, expected);
        value
    }

    fn assert_contains_two_column_constraints(
        constraints: &[TwoColumnConstraintSpec<'_>],
        expected: &[(&str, &str, &str)],
        contract_label: &str,
    ) {
        for (table, first_column, second_column) in expected {
            assert!(
                constraints.iter().any(|spec| {
                    spec.table == *table
                        && spec.first_column == *first_column
                        && spec.second_column == *second_column
                }),
                "missing {contract_label}: ({table}, {first_column}, {second_column})"
            );
        }
    }

    fn assert_lacks_two_column_constraint(
        constraints: &[TwoColumnConstraintSpec<'_>],
        table: &str,
        first_column: &str,
        second_column: &str,
        contract_label: &str,
    ) {
        assert!(
            !constraints.iter().any(|spec| {
                spec.table == table
                    && spec.first_column == first_column
                    && spec.second_column == second_column
            }),
            "unexpected {contract_label}: ({table}, {first_column}, {second_column})"
        );
    }

    fn auth_runtime_from_env_error(env_name: &str) -> String {
        let rt = tokio::runtime::Builder::new_current_thread()
            .enable_all()
            .build()
            .expect("tokio runtime");
        match rt.block_on(AuthRuntime::from_env(env_name)) {
            Ok(_) => panic!("expected auth runtime init to fail"),
            Err(err) => err,
        }
    }

    struct OptionalLimitClampCase<T> {
        default_value: T,
        zero_input: T,
        min_value: T,
        high_input: T,
        capped_value: T,
        passthrough_input: T,
        passthrough_value: T,
    }

    fn assert_optional_limit_clamps<T, F>(normalize: F, case: OptionalLimitClampCase<T>)
    where
        T: Copy + std::fmt::Debug + PartialEq,
        F: Fn(Option<T>) -> T,
    {
        assert_eq!(normalize(None), case.default_value);
        assert_eq!(normalize(Some(case.zero_input)), case.min_value);
        assert_eq!(normalize(Some(case.high_input)), case.capped_value);
        assert_eq!(
            normalize(Some(case.passthrough_input)),
            case.passthrough_value
        );
    }

    fn assert_rate_limit_decision(
        decision: RateLimitDecision,
        window_start_epoch: i64,
        request_count: i64,
        allowed: bool,
    ) {
        assert_eq!(
            decision,
            RateLimitDecision {
                window_start_epoch,
                request_count,
                allowed,
            }
        );
    }

    #[test]
    fn next_rate_limit_decision_repairs_future_window_start() {
        let decision = next_rate_limit_decision(100, 130, 5, 60, 3);

        assert_rate_limit_decision(decision, 100, 1, true);
    }

    #[test]
    fn next_rate_limit_decision_blocks_when_active_window_is_full() {
        let decision = next_rate_limit_decision(120, 100, 3, 60, 3);

        assert_rate_limit_decision(decision, 100, 3, false);
    }

    #[test]
    fn next_rate_limit_decision_rolls_expired_window_forward() {
        let decision = next_rate_limit_decision(170, 100, 3, 60, 3);

        assert_rate_limit_decision(decision, 170, 1, true);
    }

    #[test]
    fn rate_limit_retry_after_secs_returns_remaining_window() {
        assert_eq!(rate_limit_retry_after_secs(120, 100, 60), 40);
    }

    #[test]
    fn rate_limit_retry_after_secs_clamps_to_one() {
        assert_eq!(rate_limit_retry_after_secs(170, 100, 60), 1);
    }

    #[test]
    fn normalize_app_surface_header_value_collapses_aliases() {
        assert_eq!(normalize_app_surface_header_value(Some("ride")), "ride");
        assert_eq!(normalize_app_surface_header_value(Some("rides")), "ride");
        assert_eq!(normalize_app_surface_header_value(Some("taxi")), "ride");
        assert_eq!(normalize_app_surface_header_value(Some("driver")), "driver");
        assert_eq!(
            normalize_app_surface_header_value(Some("ride_driver")),
            "driver"
        );
        assert_eq!(normalize_app_surface_header_value(Some("ops")), "operator");
        assert_eq!(
            normalize_app_surface_header_value(Some("taxi_operator")),
            "operator"
        );
        assert_eq!(
            normalize_app_surface_header_value(Some("superapp")),
            "superapp"
        );
        assert_eq!(
            normalize_app_surface_header_value(Some("unknown-surface")),
            "superapp"
        );
        assert_eq!(normalize_app_surface_header_value(None), "superapp");
    }

