    #[test]
    fn required_auth_indices_cover_runtime_device_paths() {
        let ordered_indices = required_auth_ordered_indexes();
        let partial_indices = required_auth_pair_partial_indexes();
        let ordered_partial_indices = required_auth_ordered_partial_indexes();

        assert_sql_contains_all(
            AUTH_SESSIONS_DEVICE_REVOKE_SQL,
            &[
                "FROM auth_sessions",
                "account_id=$1",
                "device_id=$2",
                "revoked_at IS NULL",
            ],
        );
        assert_contains_two_column_partial_index(
            partial_indices,
            "idx_auth_sessions_account_device_active",
            "auth_sessions",
            "account_id",
            "device_id",
            "revoked_at IS NULL",
            "device partial index contracts",
        );

        assert_sql_contains_all(
            AUTH_CHAT_DEVICES_CLIENT_DEVICE_REVOKE_SQL,
            &[
                "UPDATE auth_chat_devices",
                "account_id=$1",
                "client_device_id=$2",
                "revoked_at IS NULL",
            ],
        );
        assert_sql_contains_all(
            AUTH_CHAT_DEVICES_CLIENT_DEVICE_SIBLINGS_REVOKE_SQL,
            &[
                "UPDATE auth_chat_devices",
                "account_id=$1",
                "client_device_id=$2",
                "chat_device_id <> $3",
                "revoked_at IS NULL",
            ],
        );
        assert_contains_two_column_partial_index(
            partial_indices,
            "idx_auth_chat_devices_account_client_device_active",
            "auth_chat_devices",
            "account_id",
            "client_device_id",
            "revoked_at IS NULL",
            "device partial index contracts",
        );

        assert_sql_contains_all(
            AUTH_CHAT_DEVICES_ACCOUNT_ACTIVE_LAST_SEEN_LOOKUP_SQL,
            &[
                "FROM auth_chat_devices",
                "account_id=$1",
                "revoked_at IS NULL",
                "ORDER BY last_seen_at DESC, id DESC",
            ],
        );
        assert_contains_partial_index_fragment(
            ordered_partial_indices,
            "idx_auth_chat_devices_account_active_last_seen",
            "auth_chat_devices",
            "auth_chat_devices using btree account_id, last_seen_at desc, id desc",
            "revoked_at IS NULL",
            "device ordered partial index contracts",
        );

        assert_sql_contains_all(
            AUTH_CHAT_DEVICES_PHONE_ACTIVE_LAST_SEEN_LOOKUP_SQL,
            &[
                "FROM auth_chat_devices",
                "phone=$1",
                "revoked_at IS NULL",
                "ORDER BY last_seen_at DESC, id DESC",
            ],
        );
        assert_contains_partial_index_fragment(
            ordered_partial_indices,
            "idx_auth_chat_devices_phone_active_last_seen",
            "auth_chat_devices",
            "auth_chat_devices using btree phone, last_seen_at desc, id desc",
            "revoked_at IS NULL",
            "device ordered partial index contracts",
        );

        let before_sql = auth_devices_list_sql(true);
        assert_sql_contains_all(
            before_sql,
            &[
                "FROM device_sessions",
                "WHERE account_id=$1",
                "last_seen_at < $2",
                "last_seen_at = $2 AND id < $3",
                "ORDER BY last_seen_at DESC, id DESC",
            ],
        );
        assert_contains_index_fragment(
            ordered_indices,
            "idx_device_sessions_account_last_seen",
            "device_sessions",
            "device_sessions using btree account_id, last_seen_at desc, id desc",
            "device ordered index contracts",
        );

        let initial_sql = auth_devices_list_sql(false);
        assert_sql_contains_all(
            initial_sql,
            &[
                "FROM device_sessions",
                "WHERE account_id=$1",
                "ORDER BY last_seen_at DESC, id DESC",
            ],
        );
        assert_contains_index_fragment(
            ordered_indices,
            "idx_device_sessions_account_last_seen",
            "device_sessions",
            "device_sessions using btree account_id, last_seen_at desc, id desc",
            "device ordered index contracts",
        );
    }

    #[test]
    fn required_auth_indices_cover_runtime_official_content_paths() {
        let ordered_indices = required_auth_ordered_indexes();
        let lookup_indices = required_auth_lookup_indexes();
        let ordered_partial_indices = required_auth_ordered_partial_indexes();

        let unread_paged_sql = official_template_messages_sql(true, true);
        assert_sql_contains_all(
            unread_paged_sql,
            &[
                "FROM auth_official_template_messages",
                "account_id=$1",
                "read_at IS NULL",
                "ORDER BY created_at DESC, id DESC",
            ],
        );
        assert_contains_index_fragment(
            ordered_indices,
            "idx_auth_official_template_messages_unread_order",
            "auth_official_template_messages",
            "auth_official_template_messages using btree account_id, read_at, created_at desc, id desc",
            "official ordered index contracts",
        );

        let default_paged_sql = official_template_messages_sql(false, true);
        assert_sql_contains_all(
            default_paged_sql,
            &[
                "FROM auth_official_template_messages",
                "account_id=$1",
                "ORDER BY created_at DESC, id DESC",
            ],
        );
        assert_contains_index_fragment(
            ordered_indices,
            "idx_auth_official_template_messages_account_created",
            "auth_official_template_messages",
            "auth_official_template_messages using btree account_id, created_at desc, id desc",
            "official ordered index contracts",
        );

        let auto_replies_cursor_sql = official_auto_replies_list_sql(true);
        assert_sql_contains_all(
            auto_replies_cursor_sql,
            &[
                "FROM auth_official_auto_replies",
                "account_id=$1",
                "id > $2",
                "ORDER BY id ASC",
            ],
        );
        assert_contains_index_fragment(
            ordered_indices,
            "idx_auth_official_auto_replies_account_id_order",
            "auth_official_auto_replies",
            "auth_official_auto_replies using btree account_id, id",
            "official ordered index contracts",
        );

        assert_sql_contains_all(
            AUTH_OFFICIAL_AUTO_REPLIES_PUBLIC_WELCOME_LOOKUP_SQL,
            &[
                "FROM auth_official_auto_replies",
                "account_id=$1",
                "enabled=TRUE",
                "lower(kind)='welcome'",
                "ORDER BY id ASC",
            ],
        );
        assert_contains_partial_index_fragment(
            ordered_partial_indices,
            "idx_auth_official_auto_replies_public_welcome",
            "auth_official_auto_replies",
            "auth_official_auto_replies using btree account_id, id",
            "enabled = TRUE AND lower(kind) = 'welcome'",
            "official ordered partial index contracts",
        );

        let accounts_sql = official_accounts_list_sql();
        assert_sql_contains_all(
            accounts_sql,
            &[
                "FROM auth_official_accounts a",
                "($3::text IS NULL OR a.chat_peer_id=$3)",
                "ORDER BY a.featured DESC, a.name ASC, a.id ASC",
            ],
        );
        assert_contains_index_fragment(
            lookup_indices,
            "idx_auth_official_accounts_chat_peer_id",
            "auth_official_accounts",
            "auth_official_accounts using btree chat_peer_id",
            "official lookup index contracts",
        );
        assert_contains_index_fragment(
            ordered_indices,
            "idx_auth_official_accounts_featured_name_id",
            "auth_official_accounts",
            "auth_official_accounts using btree featured desc, name, id",
            "official ordered index contracts",
        );

        let account_feed_sql = official_admin_feeds_sql(OfficialAdminFeedsScope::Account, true);
        assert_sql_contains_all(
            account_feed_sql,
            &[
                "FROM auth_official_feed_items",
                "WHERE account_id=$1",
                "ORDER BY ts DESC, id DESC",
            ],
        );
        assert_contains_index_fragment(
            ordered_indices,
            "idx_auth_official_feed_items_account_ts_id",
            "auth_official_feed_items",
            "auth_official_feed_items using btree account_id, ts desc, id desc",
            "official ordered index contracts",
        );

        let global_feed_sql = official_admin_feeds_sql(OfficialAdminFeedsScope::All, true);
        assert_sql_contains_all(
            global_feed_sql,
            &[
                "FROM auth_official_feed_items",
                "WHERE ts < $1::timestamptz",
                "ORDER BY ts DESC, id DESC",
            ],
        );
        assert_contains_index_fragment(
            ordered_indices,
            "idx_auth_official_feed_items_ts_id",
            "auth_official_feed_items",
            "auth_official_feed_items using btree ts desc, id desc",
            "official ordered index contracts",
        );

        let service_inbox_sql = official_service_inbox_sql(true);
        assert_sql_contains_all(
            service_inbox_sql,
            &[
                "FROM auth_official_service_sessions",
                "WHERE account_id=$1",
                "COALESCE(last_message_ts, created_at) < $2::timestamptz",
                "ORDER BY COALESCE(last_message_ts, created_at) DESC, id DESC",
            ],
        );
        assert_contains_index_fragment(
            ordered_indices,
            "idx_auth_official_service_sessions_inbox_sort",
            "auth_official_service_sessions",
            "auth_official_service_sessions using btree account_id, coalesce(last_message_ts, created_at) desc, id desc",
            "official ordered index contracts",
        );

        assert_sql_contains_all(
            AUTH_OFFICIAL_FOLLOWS_COUNT_SQL,
            &["FROM auth_official_follows", "official_id=$1"],
        );
        assert_contains_index_fragment(
            lookup_indices,
            "idx_auth_official_follows_official_id",
            "auth_official_follows",
            "auth_official_follows using btree official_id",
            "official lookup index contracts",
        );
    }

    #[test]
    fn auth_auto_apply_schema_defaults_true_in_dev() {
        let _g = ENV_LOCK.get_or_init(|| Mutex::new(())).lock().unwrap();
        let _env = EnvGuard::new(&["AUTH_AUTO_APPLY_SCHEMA"]);
        env::remove_var("AUTH_AUTO_APPLY_SCHEMA");

        assert_auth_auto_apply_schema_cases(
            &["dev", "local"],
            true,
            "auth_auto_apply_schema default allow",
        );
    }

    #[test]
    fn auth_auto_apply_schema_defaults_fail_closed_in_prod_and_staging() {
        let _g = ENV_LOCK.get_or_init(|| Mutex::new(())).lock().unwrap();
        let _env = EnvGuard::new(&["AUTH_AUTO_APPLY_SCHEMA"]);
        env::remove_var("AUTH_AUTO_APPLY_SCHEMA");

        assert_auth_auto_apply_schema_cases(
            &["prod", "production", "staging"],
            false,
            "auth_auto_apply_schema default fail-closed",
        );
    }

    #[test]
    fn auth_auto_apply_schema_honors_explicit_override() {
        let _g = ENV_LOCK.get_or_init(|| Mutex::new(())).lock().unwrap();
        let _env = EnvGuard::new(&["AUTH_AUTO_APPLY_SCHEMA"]);

        env::set_var("AUTH_AUTO_APPLY_SCHEMA", "true");
        assert_auth_auto_apply_schema_cases(
            &["prod"],
            true,
            "auth_auto_apply_schema explicit true override",
        );

        env::set_var("AUTH_AUTO_APPLY_SCHEMA", "false");
        assert_auth_auto_apply_schema_cases(
            &["dev"],
            false,
            "auth_auto_apply_schema explicit false override",
        );
    }

    #[test]
    fn auth_auto_apply_schema_invalid_override_falls_back_to_env_default() {
        let _g = ENV_LOCK.get_or_init(|| Mutex::new(())).lock().unwrap();
        let _env = EnvGuard::new(&["AUTH_AUTO_APPLY_SCHEMA"]);

        env::set_var("AUTH_AUTO_APPLY_SCHEMA", "truthy-ish");
        assert_auth_auto_apply_schema_cases(
            &["prod", "production", "staging"],
            false,
            "auth_auto_apply_schema invalid override should stay fail-closed in prod-like envs",
        );
        assert_auth_auto_apply_schema_cases(
            &["dev", "local"],
            true,
            "auth_auto_apply_schema invalid override should keep dev default behavior",
        );
    }

