    #[tokio::test]
    async fn auth_device_delete_response_clears_session_cookies_for_current_device() {
        let resp = auth_device_delete_response(AuthDeviceDeleteResponsePayload {
            status: "ok",
            deleted_device_record: 1,
            revoked_sessions: 2,
            revoked_biometric_tokens: 3,
            revoked_contact_invites: 4,
            revoked_device_login_challenges: 5,
            revoked_chat_devices: 6,
            revoked_chat_contacts: 7,
            clear_current_session: true,
        });
        let headers = resp.headers().clone();
        assert_set_cookie_count(&headers, 2);
        let set_cookie_values = headers
            .get_all(header::SET_COOKIE)
            .iter()
            .map(|value| value.to_str().expect("cookie header"))
            .collect::<Vec<_>>();
        assert!(
            set_cookie_values
                .iter()
                .any(|value| value.starts_with("__Host-sa_session=;")),
            "expected host session cookie clear header, got {set_cookie_values:?}"
        );
        assert!(
            set_cookie_values
                .iter()
                .any(|value| value.starts_with("sa_session=;")),
            "expected legacy session cookie clear header, got {set_cookie_values:?}"
        );
        assert_no_store_json_response_eq(
            resp,
            json!({
                "status": "ok",
                "deleted_device_record": 1,
                "revoked_sessions": 2,
                "revoked_biometric_tokens": 3,
                "revoked_contact_invites": 4,
                "revoked_device_login_challenges": 5,
                "revoked_chat_devices": 6,
                "revoked_chat_contacts": 7
            }),
        )
        .await;
    }

