    #[tokio::test]
    async fn account_create_hw_attestation_policy_bypasses_trusted_device() {
        let pool = PgPoolOptions::new()
            .acquire_timeout(StdDuration::from_millis(20))
            .connect_lazy("postgresql://127.0.0.1:1/shamell_auth_test")
            .expect("lazy postgres pool");
        let mut auth = test_auth_runtime(pool);
        auth.account_create_hw_attestation_enabled = true;
        auth.account_create_hw_attestation_required = true;
        auth.account_create_play_integrity = Some(test_play_integrity_config());
        auth.account_create_trusted_device_ids
            .insert("android-dev-trusted-71a05a7e9af77a62".to_string());

        let (trusted_device, trusted_providers, trusted_enabled, trusted_required) =
            account_create_hw_attestation_policy(&auth, "android-dev-trusted-71a05a7e9af77a62");
        assert_bool_eq(
            trusted_device,
            true,
            "trusted device should be detected by allowlist",
        );
        assert_eq!(
            trusted_providers,
            vec!["google_play_integrity"],
            "configured providers should still be discoverable for observability",
        );
        assert_bool_eq(
            trusted_enabled,
            false,
            "trusted device should bypass hardware attestation enablement",
        );
        assert_bool_eq(
            trusted_required,
            false,
            "trusted device should bypass hardware attestation enforcement",
        );

        let (untrusted_device, untrusted_providers, untrusted_enabled, untrusted_required) =
            account_create_hw_attestation_policy(&auth, "android-dev-untrusted-1");
        assert_bool_eq(
            untrusted_device,
            false,
            "untrusted device must not match the allowlist",
        );
        assert_eq!(
            untrusted_providers,
            vec!["google_play_integrity"],
            "provider discovery should stay stable for untrusted devices",
        );
        assert_bool_eq(
            untrusted_enabled,
            true,
            "untrusted device should still keep hardware attestation enabled",
        );
        assert_bool_eq(
            untrusted_required,
            true,
            "untrusted device should still require hardware attestation",
        );
    }

