    #[test]
    fn remote_media_url_validation_allows_https_and_loopback_http_only() {
        assert_ok_eq(
            normalize_remote_media_url(Some("https://cdn.shamell.test/a.png"), "thumb_url")
                .map(|value| value.map(|s| s.to_string())),
            Some("https://cdn.shamell.test/a.png".to_string()),
        );
        assert_ok_eq(
            normalize_remote_media_url(Some("http://127.0.0.1:8080/a.png"), "thumb_url")
                .map(|value| value.map(|s| s.to_string())),
            Some("http://127.0.0.1:8080/a.png".to_string()),
        );
        assert_err_result(normalize_remote_media_url(
            Some("http://cdn.shamell.test/a.png"),
            "thumb_url",
        ));
        assert_err_result(normalize_remote_media_url(
            Some("data:image/png;base64,AAAA"),
            "thumb_url",
        ));
        assert_err_result(normalize_remote_media_url(
            Some("file:///tmp/x.png"),
            "thumb_url",
        ));
    }

