    #[test]
    fn device_login_redeem_replay_allowed_requires_matching_client_fingerprint() {
        let client_ip_hash = sha256_hex("203.0.113.10");
        let user_agent_hash = sha256_hex("Mozilla/5.0");

        assert_bool_eq(
            device_login_redeem_replay_allowed(
                Some(client_ip_hash.as_str()),
                Some(user_agent_hash.as_str()),
                &client_ip_hash,
                &user_agent_hash,
            ),
            true,
            "same client fingerprint may replay redeemed device-login challenge",
        );
        assert_bool_eq(
            device_login_redeem_replay_allowed(
                Some(client_ip_hash.as_str()),
                Some(user_agent_hash.as_str()),
                &sha256_hex("203.0.113.11"),
                &user_agent_hash,
            ),
            false,
            "ip drift must block replay on redeemed device-login challenge",
        );
        assert_bool_eq(
            device_login_redeem_replay_allowed(
                Some(client_ip_hash.as_str()),
                Some(user_agent_hash.as_str()),
                &client_ip_hash,
                &sha256_hex("Different-UA"),
            ),
            false,
            "user-agent drift must block replay on redeemed device-login challenge",
        );
    }

    #[test]
    fn device_login_redeem_replay_allowed_rejects_missing_stored_fingerprint() {
        let client_ip_hash = sha256_hex("203.0.113.10");
        let user_agent_hash = sha256_hex("Mozilla/5.0");
        assert_bool_eq(
            device_login_redeem_replay_allowed(
                None,
                Some(user_agent_hash.as_str()),
                &client_ip_hash,
                &user_agent_hash,
            ),
            false,
            "missing stored ip fingerprint must fail closed",
        );
        assert_bool_eq(
            device_login_redeem_replay_allowed(
                Some(client_ip_hash.as_str()),
                None,
                &client_ip_hash,
                &user_agent_hash,
            ),
            false,
            "missing stored user-agent fingerprint must fail closed",
        );
    }

