    #[test]
    fn official_admin_feeds_sql_uses_stable_ts_id_cursor() {
        let scoped_sql = official_admin_feeds_sql(OfficialAdminFeedsScope::Account, true);
        assert_sql_contains_all(
            scoped_sql,
            &[
                "WHERE account_id=$1",
                "ts < $2::timestamptz",
                "ts = $2::timestamptz AND id < $3",
                "ORDER BY ts DESC, id DESC",
                "LIMIT $4",
            ],
        );

        let global_sql = official_admin_feeds_sql(OfficialAdminFeedsScope::All, true);
        assert_sql_contains_all(
            global_sql,
            &[
                "WHERE ts < $1::timestamptz",
                "ts = $1::timestamptz AND id < $2",
                "ORDER BY ts DESC, id DESC",
                "LIMIT $3",
            ],
        );

        let owned_sql = official_admin_feeds_sql(OfficialAdminFeedsScope::OwnedSubset, true);
        assert_sql_contains_all(
            owned_sql,
            &[
                "WHERE account_id = ANY($1)",
                "ts < $2::timestamptz",
                "ts = $2::timestamptz AND id < $3",
                "ORDER BY ts DESC, id DESC",
                "LIMIT $4",
            ],
        );
    }

