    fn payment_mutation_rate_limit_operation_whitelist_is_strict() {
        assert_bool_eq(
            is_payment_mutation_rate_limit_operation("payments_create_user"),
            true,
            "payments create-user op must be allowed",
        );
        assert_bool_eq(
            is_payment_mutation_rate_limit_operation("payments_transfer"),
            true,
            "payments transfer op must be allowed",
        );
        assert_bool_eq(
            is_payment_mutation_rate_limit_operation("payments_topup"),
            true,
            "payments topup op must be allowed",
        );
        assert_bool_eq(
            is_payment_mutation_rate_limit_operation("payments_favorites_create"),
            true,
            "payments favorites create op must be allowed",
        );
        assert_bool_eq(
            is_payment_mutation_rate_limit_operation("payments_favorites_delete"),
            true,
            "payments favorites delete op must be allowed",
        );
        assert_bool_eq(
            is_payment_mutation_rate_limit_operation("payments_requests_create"),
            true,
            "payments requests create op must be allowed",
        );
        assert_bool_eq(
            is_payment_mutation_rate_limit_operation("payments_requests_accept"),
            true,
            "payments requests accept op must be allowed",
        );
        assert_bool_eq(
            is_payment_mutation_rate_limit_operation("payments_requests_cancel"),
            true,
            "payments requests cancel op must be allowed",
        );
        assert_bool_eq(
            is_payment_mutation_rate_limit_operation("payments_requests_delete"),
            false,
            "unknown payments op must be rejected",
        );
    }

