    #[test]
    fn rotated_biometric_login_token_derivation_is_stable_and_distinct() {
        let current = "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef";
        let next = derive_rotated_biometric_login_token("device-1", current);
        assert_lower_hex_string(&next, 64, "rotated biometric token");
        assert_eq!(
            next,
            derive_rotated_biometric_login_token("device-1", current),
            "rotated biometric token must be stable for retry safety"
        );
        assert_ne!(next, current, "rotated biometric token must differ");
        assert_ne!(
            next,
            derive_rotated_biometric_login_token("device-2", current),
            "rotated biometric token must differ across devices"
        );
    }

    #[test]
    fn biometric_token_match_kind_accepts_current_or_pending_next_only() {
        assert_eq!(
            biometric_token_match_kind(true, false),
            Some(BiometricTokenMatchKind::Current)
        );
        assert_eq!(
            biometric_token_match_kind(false, true),
            Some(BiometricTokenMatchKind::PendingNext)
        );
        assert_eq!(biometric_token_match_kind(false, false), None);
        assert_eq!(biometric_token_match_kind(true, true), None);
    }

