    #[test]
    fn contact_invite_create_legacy_fallback_logs_allowed_security_event() {
        let _guard = LOG_CAPTURE_LOCK
            .get_or_init(|| Mutex::new(()))
            .lock()
            .expect("log capture lock");
        let events = SharedEventBuffer::default();
        let subscriber =
            tracing_subscriber::registry().with(EventCaptureLayer::new(events.clone()));
        let sub_guard = tracing::subscriber::set_default(subscriber);

        log_contact_invite_create_legacy_chat_device_fallback("account-1", "chat-dev-1");

        drop(sub_guard);
        assert!(
            events.contains_field_value(
                "security_event",
                "contact_invite_create_legacy_chat_device_fallback"
            ),
            "missing security_event log: {:?}",
            events.snapshot()
        );
        assert!(
            events.contains_field_value("outcome", "allowed"),
            "missing allowed outcome log: {:?}",
            events.snapshot()
        );
    }

