    #[tokio::test]
    async fn device_login_page_allows_when_web_enabled() {
        let state = test_state("prod", true);
        let resp = device_login_page(State(state)).await.unwrap();
        let csp = resp
            .headers()
            .get("content-security-policy")
            .and_then(|v| v.to_str().ok())
            .expect("device login csp header");
        assert_str_contains(csp, "style-src 'nonce-", "device login csp style nonce");
        assert_str_contains(csp, "script-src 'nonce-", "device login csp script nonce");
        assert!(!csp.contains("'unsafe-inline'"));
        let body = response_body_text(resp).await;
        assert_str_contains(&body, "Device login", "device login page html");
        assert_str_contains(
            &body,
            "/me/roles",
            "device login page session recovery probe",
        );
        assert_str_contains(
            &body,
            "dlProbeSignedIn",
            "device login page session recovery helper",
        );
        assert_str_contains(&body, "nonce=\"", "device login page nonce attributes");
    }

