    #[derive(Clone, Default)]
    struct UpstreamCapture {
        headers: Arc<Mutex<Option<HeaderMap>>>,
        body: Arc<Mutex<Option<Vec<u8>>>>,
    }

    #[derive(Clone, Default)]
    struct WalletUserCapture {
        get_calls: Arc<Mutex<usize>>,
        post_calls: Arc<Mutex<usize>>,
        lookup_miss: bool,
        headers: Arc<Mutex<Option<HeaderMap>>>,
    }

    async fn capture_payments_request(
        AxumState(state): AxumState<UpstreamCapture>,
        headers: HeaderMap,
        body: axum::body::Bytes,
    ) -> impl IntoResponse {
        *state.headers.lock().expect("headers lock") = Some(headers);
        *state.body.lock().expect("body lock") = Some(body.to_vec());
        (StatusCode::OK, Json(json!({"ok": true})))
    }

    async fn capture_wallet_user_lookup(
        AxumState(state): AxumState<WalletUserCapture>,
        headers: HeaderMap,
    ) -> impl IntoResponse {
        let mut calls = state.get_calls.lock().expect("wallet lookup calls lock");
        *calls += 1;
        *state.headers.lock().expect("headers lock") = Some(headers);
        if state.lookup_miss {
            return (
                StatusCode::NOT_FOUND,
                Json(json!({"detail": "User not found"})),
            )
                .into_response();
        }
        Json(json!({
            "user_id": "user-1",
            "wallet_id": "wallet_cached_1",
            "account_id": "a".repeat(64),
            "phone": "+963111111111",
            "balance_cents": 0,
            "currency": "SYP",
        }))
        .into_response()
    }

    async fn capture_wallet_user_provision(
        AxumState(state): AxumState<WalletUserCapture>,
        headers: HeaderMap,
    ) -> impl IntoResponse {
        let mut calls = state
            .post_calls
            .lock()
            .expect("wallet provision calls lock");
        *calls += 1;
        *state.headers.lock().expect("headers lock") = Some(headers);
        Json(json!({
            "user_id": "user-1",
            "wallet_id": "wallet_cached_1",
            "account_id": "a".repeat(64),
            "phone": "+963111111111",
            "balance_cents": 0,
            "currency": "SYP",
        }))
    }

    #[tokio::test]
    async fn call_upstream_json_signs_internal_identity_headers() {
        let capture = UpstreamCapture::default();
        let app = Router::new()
            .route("/admin/roles", any(capture_payments_request))
            .with_state(capture.clone());
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind");
        let addr = listener.local_addr().expect("addr");
        let server = tokio::spawn(async move {
            let _ = axum::serve(listener, app).await;
        });

        let signer = InternalRequestSigner::from_seed_bytes("bff", [7u8; 32]).expect("signer");
        let verifier = InternalIdentityVerifier::from_public_keys_base64(
            vec![("bff".to_string(), signer.public_key_base64())],
            30,
        )
        .expect("verifier");
        let mut state = test_state("dev", true);
        state.payments_base_url = format!("http://{addr}");
        state.internal_request_signer = Some(signer);
        state.payments_internal_secret = Some("legacy-secret".to_string());
        let mut headers = HeaderMap::new();
        headers.insert(
            TRUSTED_CLIENT_IP_HEADER,
            HeaderValue::from_static("203.0.113.9"),
        );
        headers.insert(
            TRUSTED_CLIENT_IP_ATTESTED_HEADER,
            HeaderValue::from_static("1"),
        );
        headers.insert(
            "Idempotency-Key",
            HeaderValue::from_static("owner-add-req-123"),
        );

        let value = call_upstream_json(
            &state,
            Upstream::Payments,
            Method::POST,
            "/admin/roles",
            Vec::new(),
            Some(json!({"role":"official_owner:shamell_pay"})),
            &headers,
        )
        .await
        .expect("upstream call");
        assert_some_eq(value.get("ok").and_then(|v| v.as_bool()), true);

        let captured_headers = capture
            .headers
            .lock()
            .expect("headers lock")
            .clone()
            .expect("captured headers");
        let captured_body = capture
            .body
            .lock()
            .expect("body lock")
            .clone()
            .expect("captured body");
        let caller = header_str(&captured_headers, INTERNAL_SERVICE_ID_HEADER);
        let client_ip = captured_headers
            .get(TRUSTED_CLIENT_IP_HEADER)
            .and_then(|v| v.to_str().ok());
        let client_ip_attested = captured_headers
            .get(TRUSTED_CLIENT_IP_ATTESTED_HEADER)
            .and_then(|v| v.to_str().ok());
        let forwarded_idempotency_key = captured_headers
            .get("Idempotency-Key")
            .or_else(|| captured_headers.get("idempotency-key"))
            .and_then(|v| v.to_str().ok());
        let timestamp = header_str(&captured_headers, INTERNAL_IDENTITY_TS_HEADER)
            .parse::<i64>()
            .expect("timestamp");
        let legacy_signature = header_str(&captured_headers, INTERNAL_IDENTITY_SIG_HEADER);
        let signature_v2 = header_str(&captured_headers, INTERNAL_IDENTITY_SIG_V2_HEADER);
        let nonce = header_str(&captured_headers, INTERNAL_IDENTITY_NONCE_HEADER);
        let audience = header_str(&captured_headers, INTERNAL_IDENTITY_AUDIENCE_HEADER);
        assert_some_str(Some(audience), "payments");
        let captured_header_names = captured_headers
            .keys()
            .map(|name| name.as_str().to_string())
            .collect::<Vec<_>>();
        assert_some_str_with_context(
            client_ip,
            "203.0.113.9",
            &format!("captured headers: {captured_header_names:?}"),
        );
        assert_some_str_with_context(
            client_ip_attested,
            "1",
            &format!("captured headers: {captured_header_names:?}"),
        );
        assert_header_absent(&captured_headers, "x-internal-secret");
        assert_some_str(forwarded_idempotency_key, "owner-add-req-123");
        verifier
            .verify_legacy(
                shamell_common::internal_identity::LegacyInternalIdentityVerification {
                    service_id: caller,
                    timestamp,
                    nonce,
                    signature_b64: legacy_signature,
                    method: &Method::POST,
                    path_and_query: "/admin/roles",
                    body: &captured_body,
                },
            )
            .expect("valid legacy internal identity signature");
        verifier
            .verify(
                shamell_common::internal_identity::InternalIdentityVerification {
                    service_id: caller,
                    audience,
                    timestamp,
                    nonce,
                    signature_b64: signature_v2,
                    method: &Method::POST,
                    path_and_query: "/admin/roles",
                    body: &captured_body,
                },
            )
            .expect("valid internal identity signature");

        server.abort();
    }

