    #[tokio::test]
    async fn ensure_wallet_for_account_reuses_existing_user_without_provisioning() {
        let capture = WalletUserCapture::default();
        let app = Router::new()
            .route(
                "/users",
                get(capture_wallet_user_lookup).post(capture_wallet_user_provision),
            )
            .with_state(capture.clone());
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind");
        let addr = listener.local_addr().expect("addr");
        let server = tokio::spawn(async move {
            let _ = axum::serve(listener, app).await;
        });

        let mut state = test_state("dev", true);
        state.payments_base_url = format!("http://{addr}");
        let headers = HeaderMap::new();
        let account_id = "a".repeat(64);

        let wallet =
            ensure_wallet_for_account(&state, &headers, &account_id, Some("+963111111111"), None)
                .await
                .expect("wallet resolution should succeed")
                .expect("wallet payload");

        assert_some_str(
            wallet.get("wallet_id").and_then(Value::as_str),
            "wallet_cached_1",
        );
        assert_locked_usize_eq(&capture.get_calls, 1, "unexpected wallet get calls");
        assert_locked_usize_eq(&capture.post_calls, 0, "unexpected wallet post calls");
        assert_some_string(
            state.cached_wallet_id_for_account(&account_id).await,
            "wallet_cached_1",
        );

        server.abort();
    }

