    #[tokio::test]
    async fn ensure_wallet_for_account_injects_internal_idempotency_for_provision() {
        let capture = WalletUserCapture {
            lookup_miss: true,
            ..WalletUserCapture::default()
        };
        let app = Router::new()
            .route(
                "/users",
                get(capture_wallet_user_lookup).post(capture_wallet_user_provision),
            )
            .with_state(capture.clone());
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind");
        let addr = listener.local_addr().expect("addr");
        let server = tokio::spawn(async move {
            let _ = axum::serve(listener, app).await;
        });

        let mut state = test_state("prod", true);
        state.payments_base_url = format!("http://{addr}");
        let headers = HeaderMap::new();
        let account_id = "a".repeat(64);

        let _wallet =
            ensure_wallet_for_account(&state, &headers, &account_id, Some("+963111111111"), None)
                .await
                .expect("wallet provisioning should succeed")
                .expect("wallet payload");

        assert_locked_usize_eq(&capture.post_calls, 1, "unexpected wallet post calls");

        let captured_headers = capture
            .headers
            .lock()
            .expect("headers lock")
            .clone()
            .expect("captured headers");
        let idempotency = captured_headers
            .get("idempotency-key")
            .or_else(|| captured_headers.get("Idempotency-Key"))
            .and_then(|v| v.to_str().ok())
            .expect("idempotency key should be injected");
        assert_str_eq(
            idempotency,
            &wallet_create_user_idempotency_key(&account_id, None),
            "wallet provision idempotency header",
        );

        server.abort();
    }

