    #[tokio::test]
    #[ignore = "requires SHAMELL_AUTH_TEST_DB_URL"]
    async fn payment_mutation_attestation_challenge_rate_limit_blocks_repeated_live_calls() {
        let live = LiveAuthTestDb::provision_from_env().await;
        let mut state = test_state("test", false);
        state.auth = Some(test_auth_runtime(live.pool.clone()));

        let principal = AuthPrincipal {
            account_id: "account-rate-limit-1".to_string(),
            phone: None,
            device_id: None,
        };
        let mut headers = HeaderMap::new();
        headers.insert(
            "x-shamell-client-ip",
            HeaderValue::from_static("198.51.100.20"),
        );

        enforce_payment_mutation_attestation_challenge_rate_limit_inner(
            &state, &headers, &principal, 60, 10, 1,
        )
        .await
        .expect("first payment attestation challenge request should pass");
        let err = enforce_payment_mutation_attestation_challenge_rate_limit_inner(
            &state, &headers, &principal, 60, 10, 1,
        )
        .await
        .expect_err("second payment attestation challenge request must be rate-limited");
        assert_api_error_status(&err, StatusCode::TOO_MANY_REQUESTS);
        assert_api_error_detail_prefix(&err, "too many requests; retry_after_secs=");

        live.cleanup().await;
    }

