    #[tokio::test]
    #[ignore = "requires SHAMELL_AUTH_TEST_DB_URL"]
    async fn contact_invite_redeem_missing_chat_device_does_not_burn_token_rate_limit() {
        let live = LiveAuthTestDb::provision_from_env().await;
        let mut state = test_state("test", false);
        state.auth = Some(test_auth_runtime(live.pool.clone()));

        let issuer_account_id = "a".repeat(64);
        let redeemer_account_id = "b".repeat(64);
        let issuer_chat_device_id = "chat_dev_issuer_live_1";
        let redeemer_chat_device_id = "chat_dev_redeemer_live_1";
        let invite_token = "c".repeat(64);
        let invite_token_hash = sha256_hex(&invite_token);
        let redeemer_principal = AuthPrincipal {
            account_id: redeemer_account_id.clone(),
            phone: Some("+963111111112".to_string()),
            device_id: None,
        };

        sqlx::query(
            "INSERT INTO auth_accounts (account_id, shamell_user_id, phone) VALUES ($1, $2, $3), ($4, $5, $6)",
        )
        .bind(&issuer_account_id)
        .bind("SA111111")
        .bind("+963111111111")
        .bind(&redeemer_account_id)
        .bind("SA222222")
        .bind("+963111111112")
        .execute(&live.pool)
        .await
        .expect("insert auth accounts");
        sqlx::query(
            "INSERT INTO auth_chat_devices \
             (account_id, phone, chat_device_id, client_device_id, created_at, last_seen_at, revoked_at) \
             VALUES \
             ($1, $2, $3, NULL, NOW(), NOW(), NULL), \
             ($4, $5, $6, NULL, NOW(), NOW(), NULL)",
        )
        .bind(&issuer_account_id)
        .bind("+963111111111")
        .bind(issuer_chat_device_id)
        .bind(&redeemer_account_id)
        .bind("+963111111112")
        .bind(redeemer_chat_device_id)
        .execute(&live.pool)
        .await
        .expect("insert auth chat devices");
        sqlx::query(
            "INSERT INTO auth_contact_invites \
             (token_hash, issuer_account_id, issuer_phone, issuer_chat_device_id, max_uses, use_count, created_at, last_redeemed_at, expires_at, revoked_at) \
             VALUES ($1, $2, NULL, $3, 1, 0, NOW(), NULL, NOW() + INTERVAL '10 minutes', NULL)",
        )
        .bind(&invite_token_hash)
        .bind(&issuer_account_id)
        .bind(issuer_chat_device_id)
        .execute(&live.pool)
        .await
        .expect("insert auth contact invite");

        let missing_device_headers = test_client_headers_with_fingerprint("198.51.100.41", "");
        let missing_device_err = redeem_contact_invite(
            &state,
            &missing_device_headers,
            &redeemer_principal,
            &invite_token,
        )
        .await
        .expect_err("missing chat device header must fail before token-limit burn");
        assert_api_error(
            &missing_device_err,
            StatusCode::CONFLICT,
            "chat device not registered",
        );

        let mut valid_headers = test_client_headers_with_fingerprint("198.51.100.41", "");
        valid_headers.insert(
            HeaderName::from_static("x-chat-device-id"),
            HeaderValue::from_static(redeemer_chat_device_id),
        );
        let redeemed_device =
            redeem_contact_invite(&state, &valid_headers, &redeemer_principal, &invite_token)
                .await
                .expect("valid redeem must still pass after missing-device attempt");
        assert_eq!(redeemed_device, issuer_chat_device_id);

        live.cleanup().await;
    }

