    #[test]
    fn extract_workforce_jwt_assertion_prefers_cf_header_over_body_token() {
        let mut headers = HeaderMap::new();
        headers.insert(
            HeaderName::from_static("cf-access-jwt-assertion"),
            HeaderValue::from_static("edge-token"),
        );
        headers.insert(
            header::AUTHORIZATION,
            HeaderValue::from_static("Bearer auth-token"),
        );
        let body = WorkforceSessionExchangeIn {
            jwt_assertion: Some("body-token".to_string()),
            device_id: None,
        };

        let (token, source) =
            extract_workforce_jwt_assertion(&headers, &body).expect("jwt assertion");
        assert_eq!(token, "edge-token");
        assert_eq!(source, WorkforceTokenSource::CloudflareHeader);
    }

