    #[tokio::test]
    async fn verify_workforce_identity_accepts_valid_oidc_token() {
        let secret_b64 = URL_SAFE_NO_PAD.encode(TEST_WORKFORCE_HMAC_SECRET.as_bytes());
        let jwks = json!({
            "keys": [{
                "kty": "oct",
                "kid": TEST_WORKFORCE_JWK_KID,
                "k": secret_b64,
                "alg": "HS256",
                "use": "sig"
            }]
        });
        let app = Router::new().route(
            "/oidc/keys",
            get(move || {
                let jwks = jwks.clone();
                async move { Json(jwks) }
            }),
        );
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind oidc jwks stub");
        let addr = listener.local_addr().expect("oidc jwks addr");
        let server = tokio::spawn(async move {
            let _ = axum::serve(listener, app).await;
        });

        let mut state = test_state("test", false);
        state.workforce_access = Some(test_workforce_access_config(&format!(
            "http://{addr}/oidc/keys"
        )));

        let mut jwt_header = Header::new(Algorithm::HS256);
        jwt_header.kid = Some(TEST_WORKFORCE_JWK_KID.to_string());
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("unix now")
            .as_secs() as usize;
        let token = jsonwebtoken::encode(
            &jwt_header,
            &json!({
                "iss": "https://iam.test.shamell.online",
                "sub": "zitadel|staff-owner-1",
                "aud": "shamell-workforce-test",
                "exp": now + 3600,
                "email": "Owner@Test.Shamell.Online",
                "name": "Owner Daily Admin"
            }),
            &EncodingKey::from_secret(TEST_WORKFORCE_HMAC_SECRET.as_bytes()),
        )
        .expect("encode workforce token");

        let identity =
            verify_workforce_identity(&state, token.as_str(), WorkforceTokenSource::RequestBody)
                .await
                .expect("verified workforce identity");

        assert_eq!(identity.provider, "oidc");
        assert_eq!(identity.issuer, "https://iam.test.shamell.online");
        assert_eq!(identity.subject, "zitadel|staff-owner-1");
        assert_eq!(identity.email.as_deref(), Some("owner@test.shamell.online"));
        assert_eq!(identity.display_name.as_deref(), Some("Owner Daily Admin"));

        server.abort();
    }

