    #[tokio::test]
    #[ignore = "requires SHAMELL_AUTH_TEST_DB_URL and live postgres"]
    async fn biometric_login_rotation_retry_flow_stays_recoverable_on_live_db() {
        let db = LiveAuthTestDb::provision_from_env().await;
        let capture = WalletUserCapture::default();
        let app = Router::new()
            .route(
                "/users",
                get(capture_wallet_user_lookup).post(capture_wallet_user_provision),
            )
            .with_state(capture.clone());
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind payments stub");
        let addr = listener.local_addr().expect("payments stub addr");
        let server = tokio::spawn(async move {
            let _ = axum::serve(listener, app).await;
        });

        let account_id = "a".repeat(64);
        let shamell_user_id = "SA123456";
        let phone = "+963111111111";
        let device_id = "device_live_bio_1";
        let session_id = generate_token_hex_16();
        let session_id_hash = sha256_hex(&session_id);

        sqlx::query(
            "INSERT INTO auth_accounts (account_id, shamell_user_id, phone) VALUES ($1, $2, $3)",
        )
        .bind(&account_id)
        .bind(shamell_user_id)
        .bind(phone)
        .execute(&db.pool)
        .await
        .expect("insert auth account");
        sqlx::query(
            "INSERT INTO auth_sessions \
             (sid_hash, account_id, phone, device_id, expires_at, created_at, last_seen_at, revoked_at) \
             VALUES ($1, $2, $3, $4, NOW() + INTERVAL '1 hour', NOW(), NOW(), NULL)",
        )
        .bind(&session_id_hash)
        .bind(&account_id)
        .bind(phone)
        .bind(device_id)
        .execute(&db.pool)
        .await
        .expect("insert auth session");

        let mut auth = test_auth_runtime(db.pool.clone());
        auth.biometric_login_max_per_ip = 10;
        auth.biometric_login_max_per_device = 10;
        let mut state = test_state("dev", true);
        state.auth = Some(auth);
        state.payments_base_url = format!("http://{addr}");

        let enroll = auth_biometric_enroll(
            State(state.clone()),
            test_session_cookie_headers(&session_id),
            Json(BiometricEnrollIn {
                device_id: Some(device_id.to_string()),
            }),
        )
        .await
        .expect("biometric enroll");
        let enroll_json = response_json(enroll).await;
        let initial_token = enroll_json
            .get("token")
            .and_then(Value::as_str)
            .expect("enroll token")
            .to_string();

        let first_rotate = auth_biometric_login(
            State(state.clone()),
            test_biometric_login_headers(),
            Json(BiometricLoginIn {
                device_id: Some(device_id.to_string()),
                token: Some(initial_token.clone()),
                rotate: Some(true),
            }),
        )
        .await
        .expect("first biometric rotate");
        let first_rotate_json = response_json(first_rotate).await;
        let first_next = first_rotate_json
            .get("token")
            .and_then(Value::as_str)
            .expect("first rotated token")
            .to_string();

        let retry_rotate = auth_biometric_login(
            State(state.clone()),
            test_biometric_login_headers(),
            Json(BiometricLoginIn {
                device_id: Some(device_id.to_string()),
                token: Some(initial_token.clone()),
                rotate: Some(true),
            }),
        )
        .await
        .expect("retry biometric rotate with original token");
        let retry_rotate_json = response_json(retry_rotate).await;
        let retry_next = retry_rotate_json
            .get("token")
            .and_then(Value::as_str)
            .expect("retry rotated token")
            .to_string();

        assert_eq!(
            retry_next, first_next,
            "retry with the original token must deterministically return the same staged successor"
        );

        let staged_row = sqlx::query(
            "SELECT token_hash, next_token_hash FROM auth_biometric_tokens WHERE account_id=$1 AND device_id=$2",
        )
        .bind(&account_id)
        .bind(device_id)
        .fetch_one(&db.pool)
        .await
        .expect("load staged biometric token row");
        let staged_current_hash: String = staged_row.try_get("token_hash").expect("token_hash");
        let staged_next_hash: Option<String> = staged_row
            .try_get("next_token_hash")
            .expect("next_token_hash");
        assert_eq!(
            staged_current_hash,
            sha256_hex(&format!("bio:{device_id}:{initial_token}")),
            "original token must remain current until the staged token is used"
        );
        assert_eq!(
            staged_next_hash.as_deref(),
            Some(sha256_hex(&format!("bio:{device_id}:{first_next}")).as_str()),
            "staged successor hash must match the returned rotated token"
        );

        let promote_rotate = auth_biometric_login(
            State(state.clone()),
            test_biometric_login_headers(),
            Json(BiometricLoginIn {
                device_id: Some(device_id.to_string()),
                token: Some(first_next.clone()),
                rotate: Some(true),
            }),
        )
        .await
        .expect("promote staged biometric token and rotate again");
        let promote_rotate_json = response_json(promote_rotate).await;
        let second_next = promote_rotate_json
            .get("token")
            .and_then(Value::as_str)
            .expect("second rotated token")
            .to_string();
        assert_ne!(
            second_next, first_next,
            "using the staged token must promote it and mint a new successor"
        );

        let promoted_row = sqlx::query(
            "SELECT token_hash, next_token_hash, (last_used_at IS NOT NULL) AS has_last_used_at FROM auth_biometric_tokens WHERE account_id=$1 AND device_id=$2",
        )
        .bind(&account_id)
        .bind(device_id)
        .fetch_one(&db.pool)
        .await
        .expect("load promoted biometric token row");
        let promoted_current_hash: String = promoted_row
            .try_get("token_hash")
            .expect("promoted token_hash");
        let promoted_next_hash: Option<String> = promoted_row
            .try_get("next_token_hash")
            .expect("promoted next_token_hash");
        let has_last_used_at: bool = promoted_row
            .try_get("has_last_used_at")
            .expect("promoted has_last_used_at");
        assert_eq!(
            promoted_current_hash,
            sha256_hex(&format!("bio:{device_id}:{first_next}")),
            "the staged token must become current once it is used"
        );
        assert_eq!(
            promoted_next_hash.as_deref(),
            Some(sha256_hex(&format!("bio:{device_id}:{second_next}")).as_str()),
            "promotion must stage the next deterministic successor"
        );
        assert!(
            has_last_used_at,
            "live biometric row must record activity after successful sign-in"
        );
        assert!(
            *capture.get_calls.lock().expect("wallet get_calls lock") >= 1,
            "expected at least one wallet lookup during live biometric flow"
        );
        assert_locked_usize_eq(&capture.post_calls, 0, "unexpected wallet provision count");

        server.abort();
        db.cleanup().await;
    }

