    #[tokio::test]
    #[ignore = "requires SHAMELL_AUTH_TEST_DB_URL and live postgres"]
    async fn biometric_login_attestation_repeated_invalid_attempts_revoke_token_on_live_db() {
        let db = LiveAuthTestDb::provision_from_env().await;
        let account_id = "f".repeat(64);
        let shamell_user_id = "SA666666";
        let phone = "+963166666666";
        let device_id = "device_live_bio_login_revoke_1";
        let token = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa".to_string();
        let token_hash = sha256_hex(&format!("bio:{device_id}:{token}"));

        sqlx::query(
            "INSERT INTO auth_accounts (account_id, shamell_user_id, phone) VALUES ($1, $2, $3)",
        )
        .bind(&account_id)
        .bind(shamell_user_id)
        .bind(phone)
        .execute(&db.pool)
        .await
        .expect("insert biometric login revoke auth account");
        sqlx::query(
            "INSERT INTO auth_biometric_tokens \
             (token_hash, account_id, phone, device_id, created_at, last_used_at, expires_at, revoked_at) \
             VALUES ($1, $2, $3, $4, NOW(), NULL, NOW() + INTERVAL '1 hour', NULL)",
        )
        .bind(&token_hash)
        .bind(&account_id)
        .bind(phone)
        .bind(device_id)
        .execute(&db.pool)
        .await
        .expect("insert biometric login revoke token");

        let mut auth = test_auth_runtime(db.pool.clone());
        auth.biometric_login_hw_attestation_enabled = true;
        auth.account_create_apple_devicecheck = Some(AppleDeviceCheckConfig {
            team_id: "AB12CD34EF".to_string(),
            key_id: "AB12CD34EF".to_string(),
            private_key_p8: TEST_APPLE_DEVICECHECK_PRIVATE_KEY_PEM.as_bytes().to_vec(),
        });
        let mut state = test_state("dev", false);
        state.auth = Some(auth);

        let login_headers = test_biometric_login_headers();
        let challenge = auth_biometric_login_attestation_challenge(
            State(state.clone()),
            login_headers.clone(),
            Json(BiometricLoginAttestationChallengeIn {
                device_id: Some(device_id.to_string()),
                token: Some(token.clone()),
            }),
        )
        .await
        .expect("issue biometric login revoke challenge");
        let challenge_json = response_json(challenge).await;
        let challenge_token = challenge_json
            .get("challenge_token")
            .and_then(Value::as_str)
            .expect("biometric login revoke challenge token")
            .to_string();

        let mut attestation_headers = login_headers.clone();
        attestation_headers.insert(
            BIOMETRIC_LOGIN_ATTESTATION_CHALLENGE_HEADER,
            challenge_token.parse().expect("challenge header"),
        );
        attestation_headers.insert(
            BIOMETRIC_LOGIN_ATTESTATION_APPLE_DEVICECHECK_HEADER,
            STANDARD
                .encode(b"live-biometric-login-revoke-test-token")
                .parse()
                .expect("apple devicecheck header"),
        );

        for _ in 0..BIOMETRIC_LOGIN_ATTESTATION_FAILURE_REVOKE_THRESHOLD {
            let err = enforce_biometric_login_attestation_with_test_verdict(
                &state,
                &attestation_headers,
                &account_id,
                device_id,
                &token_hash,
                false,
            )
            .await
            .expect_err("invalid attestation verdict must fail closed");
            assert_api_error(&err, StatusCode::UNAUTHORIZED, "attestation required");
        }

        let row = sqlx::query(
            "SELECT revoked_at IS NOT NULL AS revoked FROM auth_biometric_tokens WHERE account_id=$1 AND device_id=$2",
        )
        .bind(&account_id)
        .bind(device_id)
        .fetch_one(&db.pool)
        .await
        .expect("load revoked biometric login token");
        let revoked: bool = row.try_get("revoked").expect("revoked flag");
        assert!(
            revoked,
            "repeated invalid biometric login attestation attempts must revoke the biometric token"
        );

        db.cleanup().await;
    }

