    #[test]
    fn ride_pricing_roles_allow_only_city_or_admin_controls() {
        assert!(roles_allow_ride_pricing(&["city_manager".to_string()]));
        assert!(roles_allow_ride_pricing(&["admin".to_string()]));
        assert!(roles_allow_ride_pricing(&["ops".to_string()]));
        assert!(!roles_allow_ride_pricing(&["finance".to_string()]));
        assert!(!roles_allow_ride_pricing(&["support_l2".to_string()]));
        assert!(!roles_allow_ride_pricing(&["driver_ops".to_string()]));
    }

    async fn spawn_payments_stub(
        status: StatusCode,
        body: Value,
    ) -> (String, tokio::task::JoinHandle<()>) {
        let app = Router::new().route(
            "/admin/roles",
            any(move || {
                let body = body.clone();
                async move { (status, Json(body)) }
            }),
        );
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind");
        let addr = listener.local_addr().expect("addr");
        let server = tokio::spawn(async move {
            let _ = axum::serve(listener, app).await;
        });
        (format!("http://{addr}"), server)
    }
